package com.bestgearsetup;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonParser;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.config.ConfigManager;

/** Account facts are read on the client thread and remembered only in the RuneScape profile. */
final class AccountFacts
{
	private static final Map<String, List<String>> TARGETS = loadTargets();
	private AccountFacts() {}

	/** Parsed without Gson: this runs at class load, before the client's Gson can be passed in. */
	private static Map<String, List<String>> loadTargets()
	{
		try (InputStreamReader reader = new InputStreamReader(AccountFacts.class.getResourceAsStream("slayer-targets.json"), StandardCharsets.UTF_8))
		{
			Map<String, List<String>> targets = new HashMap<>();
			for (Map.Entry<String, JsonElement> entry : new JsonParser().parse(reader).getAsJsonObject().entrySet())
			{
				List<String> aliases = new ArrayList<>();
				for (JsonElement alias : entry.getValue().getAsJsonArray())
				{
					aliases.add(alias.getAsString());
				}
				targets.put(entry.getKey(), aliases);
			}
			return targets;
		}
		catch (Exception e) { throw new IllegalStateException("Cannot load Slayer target aliases", e); }
	}

	static Boolean diary(Client client, ConfigManager manager)
	{
		String key = "detectedKandarinHard";
		if (ready(client))
		{
			boolean complete = client.getVarbitValue(VarbitID.KANDARIN_DIARY_HARD_COMPLETE) == 1;
			if (!String.valueOf(complete).equals(manager.getRSProfileConfiguration(BestGearSetupConfig.GROUP, key)))
			{
				manager.setRSProfileConfiguration(BestGearSetupConfig.GROUP, key, complete);
			}
			return complete;
		}
		String value = manager.getRSProfileConfiguration(BestGearSetupConfig.GROUP, key);
		return "true".equals(value) ? true : "false".equals(value) ? false : null;
	}

	static boolean ready(Client client)
	{
		return client.getGameState() == GameState.LOGGED_IN && client.getRealSkillLevel(Skill.HITPOINTS) > 0;
	}

	/** @param gson the client's Gson, for the remembered assignment */
	static TaskRecord task(Client client, ConfigManager manager, Gson gson)
	{
		String key = "detectedSlayerTask";
		TaskRecord record = null;
		if (ready(client))
		{
			int remaining = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
			if (remaining == 0) { record = new TaskRecord("", 0, false); }
			else
			{
				try
				{
					int task = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
					int row;
					if (task == 98)
					{
						List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTaskSublist.ID,
							DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID, 0, client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID));
						if (rows.isEmpty()) { return null; }
						row = (Integer) client.getDBTableField(rows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0)[0];
					}
					else
					{
						List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, task);
						if (rows.isEmpty()) { return null; }
						row = rows.get(0);
					}
					String name = (String) client.getDBTableField(row, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0)[0];
					int area = client.getVarpValue(VarPlayerID.SLAYER_AREA);
					String location = null;
					if (area > 0)
					{
						List<Integer> areas = client.getDBRowsByValue(DBTableID.SlayerArea.ID, DBTableID.SlayerArea.COL_AREA_ID, 0, area);
						if (!areas.isEmpty())
						{ location = (String) client.getDBTableField(areas.get(0), DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER, 0)[0]; }
					}
					record = new TaskRecord(name, remaining, area > 0, location);
				}
				catch (RuntimeException e) { return null; }
			}
			String json = gson.toJson(record);
			if (!json.equals(manager.getRSProfileConfiguration(BestGearSetupConfig.GROUP, key)))
			{
				manager.setRSProfileConfiguration(BestGearSetupConfig.GROUP, key, json);
			}
		}
		else
		{
			String value = manager.getRSProfileConfiguration(BestGearSetupConfig.GROUP, key);
			try { record = value == null ? null : gson.fromJson(value, TaskRecord.class); }
			catch (RuntimeException e) { return null; }
		}
		return record;
	}

	static String normalize(String value)
	{
		return value.toLowerCase(Locale.ROOT).replace('\u00a0', ' ').replace('\u2019', '\'')
			.replaceFirst("^the ", "").trim();
	}

	static Boolean matches(TaskRecord record, String target)
	{
		return matches(record, target, null);
	}

	static Boolean matches(TaskRecord record, String target, WorldPoint location)
	{
		if (record == null || record.name == null || record.remaining < 0) { return null; }
		if (record.remaining == 0) { return false; }
		String name = normalize(record.name);
		List<String> aliases = TARGETS.get(name);
		if (aliases == null && name.endsWith("s")) { aliases = TARGETS.get(name.substring(0, name.length() - 1)); }
		if (aliases == null) { return null; }
		String npc = normalize(target);
		boolean matches = aliases.stream().anyMatch(alias -> Pattern.compile("(?:^|\\s)" + Pattern.quote(normalize(alias))
			+ "(?:$|\\s|\\(|-)").matcher(npc).find());
		if (!matches || !record.locationRestricted) { return matches; }
		return atAssignedLocation(record.location, location);
	}

	/**
	 * A search without a live target plans the assigned fight, so a location-restricted assignment counts as
	 * being at its location; only the assigned name has to match.
	 */
	static Boolean matchesAssignment(TaskRecord record, String target)
	{
		return record == null ? null : matches(new TaskRecord(record.name, record.remaining, false), target);
	}

	/** Unknown areas remain unknown rather than granting a location-restricted task bonus. */
	static Boolean atAssignedLocation(String assigned, WorldPoint location)
	{
		if (assigned == null || location == null) { return null; }
		if (normalize(assigned).equals("fremennik slayer dungeon"))
		{
			// RuneLite's Discord area catalog identifies the three regions of this dungeon.
			int region = location.getRegionID();
			return location.getPlane() == 0 && (region == 10907 || region == 10908 || region == 11164);
		}
		if (isKaruulmAssignment(assigned)) { return inKaruulm(location); }
		return null;
	}

	private static boolean isKaruulmAssignment(String assigned)
	{
		return assigned != null && normalize(assigned).equals("karuulm slayer dungeon");
	}

	/** Dungeon regions from RuneLite's Discord area catalog; all dungeon floors are included. */
	static boolean inKaruulm(WorldPoint location)
	{
		if (location == null) { return false; }
		switch (location.getRegionID())
		{
			case 5280: case 5279: case 5023: case 5535: case 5022: case 4766:
			case 4510: case 4511: case 4767: case 4768: case 4512:
				return true;
			default: return false;
		}
	}

	/** A visible target determines its location; otherwise a matching Konar assignment guides planning. */
	static boolean karuulmSearch(TaskRecord record, String target, WorldPoint liveTarget, WorldPoint player)
	{
		if (liveTarget != null) { return inKaruulm(liveTarget); }
		if (record != null && record.locationRestricted && isKaruulmAssignment(record.location)
			&& Boolean.TRUE.equals(matchesAssignment(record, target)))
		{
			return true;
		}
		return inKaruulm(player);
	}

	static String describe(TaskRecord record)
	{
		if (record == null) { return "Slayer assignment unavailable."; }
		if (record.remaining == 0) { return "No remaining Slayer assignment."; }
		return "Slayer assignment: " + record.name + " (" + record.remaining + " remaining)"
			+ (record.locationRestricted ? ", assigned location: " + (record.location == null ? "unavailable" : record.location) : "") + ".";
	}

	static final class TaskRecord
	{
		final String name;
		final int remaining;
		final boolean locationRestricted;
		final String location;
		TaskRecord(String name, int remaining, boolean locationRestricted)
		{
			this(name, remaining, locationRestricted, null);
		}
		TaskRecord(String name, int remaining, boolean locationRestricted, String location)
		{
			this.name = name; this.remaining = remaining; this.locationRestricted = locationRestricted; this.location = location;
		}
	}
}

package com.bestgearsetup;

/** Automatic account detection, or an explicit planning override. */
public enum AutoState
{
	AUTO("Auto"), ON("On"), OFF("Off");
	private final String label;
	AutoState(String label) { this.label = label; }
	@Override public String toString() { return label; }

	boolean resolve(Boolean detected, boolean fallback)
	{
		return this == ON || this == AUTO && (detected == null ? fallback : detected);
	}
}

package com.bestgearsetup;

import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.SoundEffectID;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

/** Bank title-bar control for the selected setup, styled and placed like Quest Helper's title-bar button. */
class BestGearSetupBankButton
{
	// Quest Helper's button geometry: a 25px square at x=408, with its icon inset by 3px.
	private static final int QUEST_HELPER_X = 408;
	private static final int Y = 5;
	private static final int SIZE = 25;
	private static final int ICON_INSET = 3;
	// Keep the gap tight: the bank's Close button sits just right of Quest Helper's.
	private static final int GAP = 1;
	private final Client client;
	private final ClientThread clientThread;
	private final BestGearSetupBankView view;
	private Widget parent;
	private Widget background;
	private Widget icon;
	private boolean enabled;
	private boolean lastSelected;
	private boolean lastAvailable;

	BestGearSetupBankButton(Client client, ClientThread clientThread, BestGearSetupBankView view)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.view = view;
	}

	void start()
	{
		enabled = true;
		clientThread.invokeLater(this::update);
	}

	void stop()
	{
		enabled = false;
		clientThread.invokeLater(this::remove);
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		update();
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			remove();
			clientThread.invokeLater(this::update);
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN && event.isUnload())
		{
			remove();
		}
	}

	private void update()
	{
		if (!enabled)
		{
			return;
		}
		Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		if (bank == null || bank.isHidden())
		{
			return;
		}
		boolean selected = view.isActive();
		boolean available = view.hasSelection();
		if (!available)
		{
			if (background != null)
			{
				background.setHidden(true);
				background.clearActions();
				icon.setHidden(true);
			}
			lastAvailable = false;
			return;
		}
		boolean created = parent != bank || background == null;
		if (created)
		{
			remove();
			parent = bank;
			background = graphic(SIZE, SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL);
			background.setName("<col=ff981f>Best Gear Setup</col>");
			background.setHasListener(true);
			background.setOnOpListener((JavaScriptCallback) event ->
			{
				int op = event.getOp();
				clientThread.invokeLater(() -> activate(op));
			});
			icon = graphic(SIZE - 2 * ICON_INSET, SpriteID.ICON_SWORDS);
		}
		// Take Quest Helper's slot by the Close button, or sit just right of its button while it's shown.
		place(questHelperShown(bank) ? QUEST_HELPER_X + SIZE + GAP : QUEST_HELPER_X);
		if (created || selected != lastSelected || available != lastAvailable)
		{
			background.setSpriteId(selected ? SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL_SELECTED
				: SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL);
			background.setHidden(false);
			icon.setHidden(false);
			background.clearActions();
			background.setAction(0, selected ? "Show all items" : "Gear layout");
			background.revalidate();
			lastSelected = selected;
			lastAvailable = available;
		}
	}

	private boolean questHelperShown(Widget bank)
	{
		Widget[] children = bank.getChildren();
		if (children != null)
		{
			for (Widget child : children)
			{
				if (child != null && "quest-helper".equals(child.getName()) && !child.isSelfHidden())
				{
					return true;
				}
			}
		}
		return false;
	}

	private void place(int x)
	{
		if (background.getOriginalX() == x)
		{
			return;
		}
		background.setOriginalX(x);
		background.setOriginalY(Y);
		background.revalidate();
		icon.setOriginalX(x + ICON_INSET);
		icon.setOriginalY(Y + ICON_INSET);
		icon.revalidate();
	}

	private Widget graphic(int size, int sprite)
	{
		Widget widget = parent.createChild(-1, WidgetType.GRAPHIC);
		widget.setOriginalWidth(size);
		widget.setOriginalHeight(size);
		widget.setSpriteId(sprite);
		widget.revalidate();
		return widget;
	}

	private void activate(int op)
	{
		if (!enabled || background == null || !view.hasSelection())
		{
			return;
		}
		if (op == 1)
		{
			client.playSoundEffect(SoundEffectID.UI_BOOP);
			if (view.isActive())
			{
				view.clear();
			}
			else if (view.isPotionStoreOpen())
			{
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Close the potion store to view the gear setup.", null);
			}
			else
			{
				view.show();
			}
		}
		update();
	}

	private void remove()
	{
		if (background != null)
		{
			background.setHidden(true);
			background.clearActions();
			background.setOnOpListener((Object[]) null);
			icon.setHidden(true);
		}
		parent = background = icon = null;
	}
}

package com.bestgearsetup;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/** Outlines the selected setup's equipment and spell runes in the bank. */
class BestGearSetupBankOverlay extends WidgetItemOverlay
{
	private final BestGearSetupPlugin plugin;
	private final BestGearSetupConfig config;
	private final ItemManager itemManager;

	@Inject
	BestGearSetupBankOverlay(BestGearSetupPlugin plugin, BestGearSetupConfig config, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		showOnBank();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		Set<Integer> ids = plugin.getBankHighlightIds();
		if (!config.highlightBankGear() || itemId <= 0 || widgetItem.getQuantity() <= 0
			|| ids.isEmpty())
		{
			return;
		}
		if (!ids.contains(itemManager.canonicalize(itemId)))
		{
			return;
		}
		Rectangle bounds = widgetItem.getCanvasBounds();
		graphics.drawImage(itemManager.getItemOutline(itemId, widgetItem.getQuantity(), config.bankHighlightColor()),
			bounds.x, bounds.y, null);
	}
}

package com.bestgearsetup;

import com.bestgearsetup.calc.Loadout;
import com.bestgearsetup.calc.SetupResult;
import com.bestgearsetup.calc.SpecialPlan;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Potion;
import com.bestgearsetup.data.Slot;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.vars.InputType;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;
import net.runelite.client.plugins.bank.BankSearch;

/** Temporary equipment tab; never changes the bank's item slots or opens a search input. */
@Singleton
class BestGearSetupBankView
{
	// Equipment silhouette on the bank's eight-column grid, matching the sidebar.
	private static final int[] CELLS = {1, 8, 9, 10, 16, 17, 18, 25, 32, 33, 34};
	// Right of the silhouette: spell runes (and a thrall's Book of the dead), then potions and hearts.
	private static final int[] SPELL_CELLS = {4, 5, 6, 7, 12, 13, 14, 15};
	private static final int[] BOOST_CELLS = {20, 21, 22, 23, 28, 29, 30, 31};
	// Below the runes and boosts: a spec weapon and off-hand to switch to, then its own ammunition or a spec
	// blowpipe's darts (never both).
	private static final int SPEC_WEAPON_CELL = 36;
	private static final int SPEC_OFFHAND_CELL = 37;
	private static final int SPEC_AMMO_CELL = 38;
	// Extra matches go below the layout, each group starting its own row: gear, then spell items, then boosts.
	private static final int EXTRA_ROWS_START = 40;
	private static final int GEAR = 0;
	private static final int SPELL = 1;
	private static final int BOOST = 2;
	private static final int BANKTAB_POTIONSTORE = 15;
	private final Client client;
	private final ItemManager itemManager;
	private final BankSearch bankSearch;
	private final EventBus eventBus;
	private volatile Layout selection = Layout.EMPTY;
	private final Map<Widget, int[]> dragSettings = new IdentityHashMap<>();
	private boolean active;

	@Inject
	BestGearSetupBankView(Client client, ItemManager itemManager, BankSearch bankSearch, EventBus eventBus)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.bankSearch = bankSearch;
		this.eventBus = eventBus;
	}

	/** Publish a selection from the sidebar; the bank reads one immutable snapshot per rebuild. */
	void setSelection(SetupResult setup)
	{
		setSelection(setup, Collections.emptyList());
	}

	void setSelection(SetupResult setup, List<Potion> potions)
	{
		selection = layoutFor(setup, potions);
	}

	static Map<Integer, Integer> cellsFor(SetupResult setup)
	{
		return cellsFor(setup, Collections.emptyList());
	}

	static Map<Integer, Integer> cellsFor(SetupResult setup, List<Potion> potions)
	{
		return Collections.unmodifiableMap(layoutFor(setup, potions).cells);
	}

	static Layout layoutFor(SetupResult setup, List<Potion> potions)
	{
		Layout layout = new Layout();
		if (setup != null)
		{
			Loadout loadout = setup.getLoadout();
			for (Slot slot : Slot.values())
			{
				addItem(layout, loadout.get(slot), CELLS[slot.ordinal()]);
			}
			addItem(layout, loadout.getLoadedAmmo(), loadout.get(Slot.AMMO) == null ? 10 : 40);
			SpecialPlan special = setup.getSpecial();
			if (special != null && special.isSwitch(loadout))
			{
				addItem(layout, special.getWeapon(), SPEC_WEAPON_CELL);
				addItem(layout, special.getOffhand(), SPEC_OFFHAND_CELL);
				addItem(layout, special.getAmmo(), SPEC_AMMO_CELL);
				addItem(layout, special.getLoadedAmmo(), SPEC_AMMO_CELL);
			}
			List<Integer> spellItems = SpellRunes.required(setup);
			for (int i = 0; i < spellItems.size(); i++)
			{
				List<Integer> ids = new ArrayList<>();
				ids.add(spellItems.get(i));
				ids.addAll(SpellRunes.substitutes(spellItems.get(i)));
				layout.add(ids, reservedCell(SPELL_CELLS, i), SPELL);
			}
			int cell = 0;
			for (Potion potion : potions)
			{
				// Raid supplies are handed out inside the raid, never withdrawn.
				if (!potion.isRaidSupply())
				{
					// Each dose of the potion, then its divine version and potions giving the same boost.
					layout.add(BoostAccess.itemIds(potion), reservedCell(BOOST_CELLS, cell++), BOOST);
				}
			}
		}
		return layout;
	}

	private static int reservedCell(int[] reserved, int index)
	{
		// Any beyond the reserved cells join the extra rows below the silhouette.
		return index < reserved.length ? reserved[index] : EXTRA_ROWS_START + index;
	}

	private static void addItem(Layout layout, GearItem item, int cell)
	{
		if (item != null)
		{
			List<Integer> ids = new ArrayList<>();
			ids.add(item.getId());
			ids.addAll(item.getOwnershipVariants());
			layout.add(ids, cell, GEAR);
		}
	}

	/**
	 * Each matching item's cell, extra-row group (gear, spell or boost) and rank, and the items that take their
	 * cell ahead of any alternative. Built once in {@link #layoutFor}, then only read.
	 */
	static final class Layout
	{
		static final Layout EMPTY = new Layout();
		private final Map<Integer, Integer> cells = new HashMap<>();
		private final Map<Integer, Integer> groups = new HashMap<>();
		/** Insertion order: a cell's own item, then its alternatives (doses by type, substitutes) in order. */
		private final Map<Integer, Integer> ranks = new HashMap<>();
		private final Set<Integer> primary = new HashSet<>();

		/** The first id is the cell's own item; the rest (variants, doses, substitutes) only fill it in its absence. */
		private void add(Collection<Integer> ids, int cell, int group)
		{
			boolean first = true;
			for (int id : ids)
			{
				if (cells.putIfAbsent(id, cell) == null)
				{
					groups.put(id, group);
					ranks.put(id, ranks.size());
					if (first)
					{
						primary.add(id);
					}
				}
				first = false;
			}
		}

		boolean isEmpty()
		{
			return cells.isEmpty();
		}
	}

	/** Whether the potion store is open; it must be closed by the player before the layout can show. */
	boolean isPotionStoreOpen()
	{
		return client.getVarbitValue(VarbitID.BANK_CURRENTTAB) == BANKTAB_POTIONSTORE;
	}

	/** Client thread: switch from any bank tab/search into a temporary equipment tab. */
	boolean show()
	{
		Widget bank = client.getWidget(InterfaceID.Bankmain.ITEMS);
		// The store is closed server-side by its button; plugins may not click it, and leaving it open behind
		// the layout would stop deposits working (as in Bank Tags).
		if (bank == null || bank.isHidden() || isPotionStoreOpen() || bank.getOnInvTransmitListener() == null
			|| selection.isEmpty())
		{
			return false;
		}
		clear();
		releaseOtherViews();
		active = true;
		bank.setScrollY(0);
		client.setVarcIntValue(VarClientID.BANK_SCROLLPOS, 0);
		bankSearch.reset(true);
		return true;
	}

	/** Release any Bank Tags or Quest Helper tab so they cannot override this layout. */
	private void releaseOtherViews()
	{
		client.setVarbit(VarbitID.BANK_CURRENTTAB, 0);
		// Bank Tags and Quest Helper both release their tab when the bank search is toggled, so announce one
		// without opening search.
		eventBus.post(new ScriptPreFired(ScriptID.BANKMAIN_SEARCH_TOGGLE));
	}

	/** Client thread: update an existing setup search, without replacing the user's own search. */
	void refreshSelection()
	{
		if (selection.isEmpty())
		{
			clear();
		}
		else if (isActive())
		{
			bankSearch.layoutBank();
		}
	}

	/** Client thread: release our view and restore normal bank search and dragging. */
	void clear()
	{
		boolean reset = isActive();
		active = false;
		restoreDragging();
		if (reset)
		{
			bankSearch.layoutBank();
		}
	}

	boolean hasSelection()
	{
		return !selection.isEmpty();
	}

	boolean isActive()
	{
		return active;
	}

	// Run after the other bank views so this temporary tab owns its results while selected.
	@Subscribe(priority = -1)
	public void onScriptCallbackEvent(ScriptCallbackEvent event)
	{
		if (!isActive() || client.getWidget(InterfaceID.Bankmain.ITEMS) == null)
		{
			return;
		}
		if ("bankSearchFilter".equals(event.getEventName()))
		{
			int[] ints = client.getIntStack();
			int size = client.getIntStackSize();
			int id = ints[size - 1];
			// Placeholders match through their canonical item, so a withdrawn item keeps its cell.
			ints[size - 2] = id > 0 && key(selection, id) != null ? 1 : 0;
		}
		else if ("bankBuildTab".equals(event.getEventName())
			|| "getSearchingTagTab".equals(event.getEventName()))
		{
			client.getIntStack()[client.getIntStackSize() - 1] = 1;
		}
	}

	/** The layout id this bank item matches, directly or through its canonical item; null when none. */
	private Integer key(Layout layout, int id)
	{
		if (layout.cells.containsKey(id))
		{
			return id;
		}
		int canonical = itemManager.canonicalize(id);
		return layout.cells.containsKey(canonical) ? canonical : null;
	}

	@Subscribe(priority = -1)
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() == ScriptID.BANKMAIN_SEARCH_TOGGLE)
		{
			// Let a normal search open on its first click, without rebuilding inside the script VM.
			active = false;
			restoreDragging();
		}
		else if (event.getScriptId() == ScriptID.BANKMAIN_BUILD)
		{
			restoreDragging();
			if (client.getVarbitValue(VarbitID.BANK_CURRENTTAB) != 0
				|| client.getVarcIntValue(VarClientID.MESLAYERMODE) == InputType.SEARCH.getType())
			{
				active = false;
			}
		}
		else if (event.getScriptId() == ScriptID.BANKMAIN_FINISHBUILDING && isActive())
		{
			int height = arrangeItems();
			if (height >= 0)
			{
				// Finishbuilding receives the scroll height as int13 (nine from the end).
				// Update it before the game configures its scrollbar and scroll listeners.
				client.getIntStack()[client.getIntStackSize() - 9] = height;
			}
		}
	}

	@Subscribe(priority = -1)
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() != ScriptID.BANKMAIN_FINISHBUILDING || !isActive())
		{
			return;
		}
		Widget title = client.getWidget(InterfaceID.Bankmain.TITLE);
		if (title != null)
		{
			title.setText("Best Gear Setup - equipment layout");
		}
	}

	private int arrangeItems()
	{
		Widget bank = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (bank == null || bank.getChildren() == null)
		{
			return -1;
		}
		Layout layout = selection;
		Set<Integer> occupied = new HashSet<>();
		Map<Widget, Integer> matches = new IdentityHashMap<>();
		for (Widget item : bank.getChildren())
		{
			if (item == null || item.isSelfHidden())
			{
				continue;
			}
			Integer key = item.getItemId() <= 0 ? null : key(layout, item.getItemId());
			if (key == null)
			{
				// This also hides the tab headings/separators in the bank's scroll container.
				item.setHidden(true);
			}
			else
			{
				matches.put(item, key);
			}
		}
		// Each cell's own item claims it first; the best-ranked alternative fills it in its absence (the
		// highest dose, the first substitute) and the rest join the extra rows in rank order. Placeholders
		// (quantity 0) come after every real item and only fill a cell nothing withdrawable can.
		List<Widget> ordered = new ArrayList<>(matches.keySet());
		ordered.sort(Comparator.comparing(BestGearSetupBankView::isPlaceholder)
			.thenComparing((Widget w) -> !layout.primary.contains(matches.get(w)))
			.thenComparingInt(w -> layout.ranks.get(matches.get(w)))
			.thenComparingInt(Widget::getOriginalY).thenComparingInt(Widget::getOriginalX));
		List<List<Widget>> extras = Arrays.asList(new ArrayList<>(), new ArrayList<>(), new ArrayList<>());
		int lastCell = 34;
		for (Widget item : ordered)
		{
			int key = matches.get(item);
			int cell = layout.cells.get(key);
			if (occupied.add(cell))
			{
				place(item, cell);
				lastCell = Math.max(lastCell, cell);
			}
			else if (isPlaceholder(item))
			{
				// A spare placeholder (e.g. another dose) would only clutter the extra rows.
				item.setHidden(true);
			}
			else
			{
				extras.get(layout.groups.get(key)).add(item);
			}
		}
		// Extra rows start below every placed cell; gear, spell items and boosts each begin a new row,
		// and so does each potion type (every dose of one potion together, highest first).
		int next = Math.max(EXTRA_ROWS_START, (lastCell / 8 + 1) * 8);
		for (int group = 0; group < extras.size(); group++)
		{
			Integer type = null;
			for (Widget item : extras.get(group))
			{
				int itemType = ItemVariationMapping.map(matches.get(item));
				if (group == BOOST && type != null && type != itemType)
				{
					next = (next + 7) / 8 * 8;
				}
				type = itemType;
				place(item, next);
				lastCell = next++;
			}
			next = (next + 7) / 8 * 8;
		}
		bank.setScrollHeight(lastCell < 0 ? 0 : (lastCell / 8 + 1) * 36);
		bank.setScrollY(Math.max(0, Math.min(bank.getScrollY(), bank.getScrollHeight() - bank.getHeight())));
		client.setVarcIntValue(VarClientID.BANK_SCROLLPOS, bank.getScrollY());
		return bank.getScrollHeight();
	}

	private static boolean isPlaceholder(Widget item)
	{
		return item.getItemQuantity() <= 0;
	}

	private void place(Widget item, int cell)
	{
		// Preserve each real widget's index and withdrawal actions; only change its display position.
		// The scroll widget can be wider than its clipped viewport (e.g. stretched mode).
		// Match RuneLite's bank layout spacing: 36px items with 12px horizontal padding.
		item.setOriginalX(51 + (cell % 8) * 48);
		item.setOriginalY((cell / 8) * 36);
		item.revalidate();
		dragSettings.putIfAbsent(item, new int[]{item.getDragDeadZone(), item.getDragDeadTime()});
		// This is a temporary display layout, so dragging must not rearrange actual bank slots.
		item.setDragDeadZone(Integer.MAX_VALUE);
		item.setDragDeadTime(Integer.MAX_VALUE);
	}

	private void restoreDragging()
	{
		for (Map.Entry<Widget, int[]> entry : dragSettings.entrySet())
		{
			entry.getKey().setDragDeadZone(entry.getValue()[0]);
			entry.getKey().setDragDeadTime(entry.getValue()[1]);
		}
		dragSettings.clear();
	}

	@Subscribe(priority = 1)
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		String option = event.getMenuOption();
		if (option.startsWith("View tab") || option.startsWith("View tag tab")
			|| option.equals("View all items") || option.startsWith("Potion store"))
		{
			active = false;
			restoreDragging();
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN && event.isUnload())
		{
			active = false;
			restoreDragging();
		}
	}
}

