/** Tradable components needed to acquire equipment, rather than its resale value. */
public final class ItemCosts
{
	/**
	 * Untradeables bought for coins from a shop, at their full price: the Culinaromancer's Chest gloves after all
	 * Recipe for Disaster subquests, without the Lumbridge diary discount.
	 */
	private static final Map<Integer, Long> SHOP_PRICES = shopPrices();

	/**
	 * Perdu's fee to repair untradeables that break on an unprotected PvP death, by item name, from the OSRS Wiki's
	 * (broken) page. Ancient sceptres also charge the ancient staff's current price, which their acquisition
	 * price already covers.
	 */
	private static final Map<String, Long> REPAIR_COSTS = repairCosts();

	private ItemCosts()
	{
	}

	private static Map<Integer, Long> shopPrices()
	{
		Map<Integer, Long> costs = new HashMap<>();
		costs.put(ItemID.HUNDRED_GAUNTLETS_LEVEL_1, 65L);
		costs.put(ItemID.HUNDRED_GAUNTLETS_LEVEL_2, 130L);
		costs.put(ItemID.HUNDRED_GAUNTLETS_LEVEL_3, 325L);
		costs.put(ItemID.HUNDRED_GAUNTLETS_LEVEL_4, 650L);
		costs.put(ItemID.HUNDRED_GAUNTLETS_LEVEL_5, 1_300L);
		costs.put(ItemID.HUNDRED_GAUNTLETS_LEVEL_6, 1_950L);
		costs.put(ItemID.HUNDRED_GAUNTLETS_LEVEL_7, 3_250L);
		costs.put(ItemID.HUNDRED_GAUNTLETS_LEVEL_8, 6_500L);
		costs.put(ItemID.HUNDRED_GAUNTLETS_LEVEL_9, 130_000L);
		costs.put(ItemID.HUNDRED_GAUNTLETS_LEVEL_10, 130_000L);
		return Collections.unmodifiableMap(costs);
	}

	private static Map<String, Long> repairCosts()
	{
		Map<String, Long> costs = new HashMap<>();
		repair(costs, 150_000, "fire cape", "fire max cape", "fighter torso");
		repair(costs, 225_000, "infernal cape", "infernal max cape");
		repair(costs, 240_000, "ava's assembler", "assembler max cape", "masori assembler",
			"masori assembler max cape", "dragon defender");
		repair(costs, 96_000, "imbued guthix cape", "imbued saradomin cape", "imbued zamorak cape");
		repair(costs, 99_000, "imbued guthix max cape", "imbued saradomin max cape", "imbued zamorak max cape");
		repair(costs, 1_000, "bronze defender");
		repair(costs, 2_000, "iron defender");
		repair(costs, 2_500, "steel defender");
		repair(costs, 5_000, "black defender");
		repair(costs, 15_000, "mithril defender");
		repair(costs, 25_000, "adamant defender");
		repair(costs, 35_000, "rune defender");
		repair(costs, 600_000, "avernic defender");
		repair(costs, 160_000, "void melee helm", "void mage helm", "void ranger helm");
		repair(costs, 180_000, "void knight top", "void knight robe");
		repair(costs, 250_000, "elite void top", "elite void robe");
		repair(costs, 120_000, "void knight gloves");
		repair(costs, 20_000, "void knight mace", "penance skirt");
		repair(costs, 25_000, "guthix halo", "saradomin halo", "zamorak halo", "armadyl halo", "bandos halo",
			"seren halo", "ancient halo", "brassica halo");
		repair(costs, 45_000, "fighter hat", "ranger hat", "healer hat");
		repair(costs, 40_005, "runner hat");
		repair(costs, 10_500, "barronite mace");
		repair(costs, 200_000, "blood ancient sceptre", "smoke ancient sceptre", "ice ancient sceptre",
			"shadow ancient sceptre");
		repair(costs, 270_000, "dizana's quiver");
		repair(costs, 400_000, "blessed dizana's quiver", "dizana's max cape");
		return Collections.unmodifiableMap(costs);
	}

	private static void repair(Map<String, Long> costs, long fee, String... names)
	{
		for (String name : names)
		{
			costs.put(name, fee);
		}
	}

	/**
	 * Coins needed to repair the item after an unprotected PvP death, or 0 if it doesn't break. Variants share
	 * their base item's catalogue name, so a trimmed dragon defender pays the fee as well as losing its kit.
	 */
	public static long pvpRepairCost(GearItem item)
	{
		String name = item.getName() == null ? "" : item.getName().toLowerCase(Locale.ROOT);
		if (name.startsWith("decorative armour"))
		{
			return 5_000;
		}
		return REPAIR_COSTS.getOrDefault(name, 0L);
	}

	/** Component quantities, including consumed upgrades absent from RuneLite's resale mappings. */
	public static Map<Integer, Long> components(int itemId)
	{
		Map<Integer, Long> components = new HashMap<>();
		int base = acquisitionBase(itemId);
		int family = ItemVariationMapping.map(itemId);
		Collection<ItemMapping> mappings = mappings(itemId, base);
		if (mappings == null)
		{
			components.put(base, 1L);
		}
		else
		{
			for (ItemMapping mapping : mappings)
			{
				// Reward currencies have a cash-out value, but cannot be bought to acquire gear.
				if (mapping.getTradeableItem() != ItemID.GRACE
					&& mapping.getTradeableItem() != ItemID.MOTHERLODE_NUGGET)
				{
					components.merge(mapping.getTradeableItem(), mapping.getQuantity(), Long::sum);
				}
			}
		}

		if (family == ItemVariationMapping.map(ItemID.BLOOD_AMULET))
		{
			components.put(ItemID.ENCHANTED_ONYX_AMULET, 1L);
			components.put(ItemID.BLOOD_SHARD, 1L);
		}
		else if (family == ItemVariationMapping.map(ItemID.INFERNAL_DEFENDER)
			|| family == ItemVariationMapping.map(ItemID.INFERNAL_DEFENDER_GHOMMAL_5)
			|| family == ItemVariationMapping.map(ItemID.INFERNAL_DEFENDER_GHOMMAL_6))
		{
			components.remove(base);
			components.put(ItemID.INFERNAL_DEFENDER_HILT, 1L);
		}
		else if (family == ItemVariationMapping.map(ItemID.ABYSSAL_TENTACLE))
		{
			components.put(ItemID.ABYSSAL_WHIP, 1L);
		}
		else if (family == ItemVariationMapping.map(ItemID.ECHO_BOOTS))
		{
			components.put(ItemID.ECHO_CRYSTAL, 1L);
		}
		return Collections.unmodifiableMap(components);
	}

	/** Cosmetic variants sold separately can share a RuneLite family without sharing an acquisition base. */
	private static int acquisitionBase(int itemId)
	{
		return OwnershipRules.identity(itemId);
	}

	/** RuneLite's tradable-component mappings for the item or its variation base; null if it has none. */
	private static Collection<ItemMapping> mappings(int itemId, int base)
	{
		Collection<ItemMapping> mappings = ItemMapping.map(itemId);
		return mappings == null && base != itemId ? ItemMapping.map(base) : mappings;
	}

	/** Price of an item that cannot be bought without a component that has no current quote. */
	public static final long UNKNOWN = -1;

	/**
	 * Current component prices, or {@link #UNKNOWN} if any purchasable component has no quote. RuneLite's mapped
	 * bases (an empty blowpipe, an inactive bow, an uncharged helm) and consumed upgrades are always purchasable.
	 * Only an item RuneLite maps to nothing is bought as its own variation base, and only when that base can be
	 * traded; otherwise it costs its coin shop price, or nothing when it is earned rather than bought.
	 *
	 * @param tradeable whether the game cache marks an item id as tradeable
	 */
	public static long price(GearItem item, IntToLongFunction quote, IntPredicate tradeable)
	{
		int base = acquisitionBase(item.getId());
		boolean unmapped = mappings(item.getId(), base) == null;
		long total = SHOP_PRICES.getOrDefault(base, 0L);
		for (Map.Entry<Integer, Long> component : components(item.getId()).entrySet())
		{
			int id = component.getKey();
			long price = quote.applyAsLong(id);
			if (price > 0)
			{
				total += price * component.getValue();
			}
			else if (!unmapped || id != base || item.isTradeable() || tradeable.test(id))
			{
				return UNKNOWN;
			}
		}
		return total;
	}

	public static boolean isKnown(long price)
	{
		return price >= 0;
	}

	/**
	 * Whether an item is acquired by buying tradable components: RuneLite maps it to a tradable base
	 * (charged Sanguinesti staff, Tumeken's shadow, trident of the swamp; a tormented synapse for the
	 * demonic weapons; imbued rings) or it consumes a tradable upgrade. Earned-only untradeables
	 * such as fire capes have neither.
	 */
	public static boolean hasTradableComponents(int itemId)
	{
		int base = acquisitionBase(itemId);
		boolean mapped = mappings(itemId, base) != null;
		for (int id : components(itemId).keySet())
		{
			if (mapped || id != base)
			{
				return true;
			}
		}
		return false;
	}

	/** Variants with additional paid components must not be granted merely by owning the base. */
	public static boolean equivalent(int first, int second)
	{
		return components(first).equals(components(second));
	}

	/** Whether an owned mapped item already contains everything needed for its base component. */
	public static boolean containsComponents(int ownedItem, int baseItem)
	{
		Map<Integer, Long> owned = components(ownedItem);
		Map<Integer, Long> required = components(baseItem);
		if (required.isEmpty())
		{
			return false;
		}
		for (Map.Entry<Integer, Long> component : required.entrySet())
		{
			if (owned.getOrDefault(component.getKey(), 0L) < component.getValue())
			{
				return false;
			}
		}
		return true;
	}
}

package com.bestgearsetup;

import com.bestgearsetup.calc.RaidScaling;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.MonsterSummary;
import java.util.HashMap;
import java.util.Map;
import java.util.Locale;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;

/** Raid scaling read once from the matching live raid; never written to planning configuration. */
final class LiveRaid
{
	final Map<String, Object> values = new HashMap<>();
	int maxCombat;
	boolean raidDetected;

	static Monster target(MonsterSummary summary)
	{
		Monster target = new Monster();
		target.setId(summary.getId()); target.setName(summary.getName());
		java.util.List<Monster.Attribute> attrs = new java.util.ArrayList<>();
		for (String name : summary.getAttributes())
		{
			Monster.Attribute attribute = new Monster.Attribute(); attribute.setName(name); attrs.add(attribute);
		}
		target.setAttributes(attrs);
		return target;
	}

	static LiveRaid read(Client client, MonsterSummary summary)
	{
		LiveRaid live = new LiveRaid();
		RaidScaling.Raid raid = RaidScaling.raid(target(summary));
		int size = 0;
		if (raid == RaidScaling.Raid.COX && client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1)
		{
			size = client.getVarbitValue(VarbitID.RAIDS_CLIENT_PARTYSIZE_SCALED);
			if (size < 1) { size = client.getVarbitValue(VarbitID.RAIDS_CLIENT_PARTYSIZE); }
			live.values.put("coxChallengeMode", client.getVarbitValue(VarbitID.RAIDS_CHALLENGE_MODE) == 1);
			live.maxCombat = client.getVarbitValue(VarbitID.RAIDS_CLIENT_HIGHESTCOMBAT);
		}
		else if (raid == RaidScaling.Raid.TOA && client.getVarbitValue(VarbitID.TOA_CLIENT_PARTYSTATUS) > 0)
		{
			for (int id : new int[]{VarbitID.TOA_CLIENT_P0, VarbitID.TOA_CLIENT_P1, VarbitID.TOA_CLIENT_P2, VarbitID.TOA_CLIENT_P3,
				VarbitID.TOA_CLIENT_P4, VarbitID.TOA_CLIENT_P5, VarbitID.TOA_CLIENT_P6, VarbitID.TOA_CLIENT_P7})
			{ size += client.getVarbitValue(id) > 0 ? 1 : 0; }
			live.values.put("toaRaidLevel", Math.max(0, Math.min(600, client.getVarbitValue(VarbitID.TOA_CLIENT_RAID_LEVEL))));
			String name = summary.getName().toLowerCase(Locale.ROOT);
			int path = name.contains("zebak") ? VarbitID.TOA_CLIENT_CRONDIS_LEVEL : name.contains("kephri") ? VarbitID.TOA_CLIENT_SCABARAS_LEVEL
				: name.contains("akkha") ? VarbitID.TOA_CLIENT_HET_LEVEL : name.contains("ba-ba") ? VarbitID.TOA_CLIENT_APMEKEN_LEVEL : -1;
			if (path >= 0) { live.values.put("toaPathLevel", Math.max(0, Math.min(6, client.getVarbitValue(path)))); }
		}
		else if ((raid == RaidScaling.Raid.TOB || raid == RaidScaling.Raid.TOB_ENTRY)
			&& client.getVarbitValue(VarbitID.TOB_CLIENT_PARTYSTATUS) > 0)
		{
			for (int id : new int[]{VarbitID.TOB_CLIENT_P0, VarbitID.TOB_CLIENT_P1, VarbitID.TOB_CLIENT_P2, VarbitID.TOB_CLIENT_P3, VarbitID.TOB_CLIENT_P4})
			{ size += client.getVarbitValue(id) > 0 ? 1 : 0; }
		}
		if (size >= 1 && size <= 100)
		{
			live.values.put("raidPartySize", size); live.raidDetected = true;
		}
		else
		{
			live.values.keySet().removeIf(key -> key.startsWith("toa") || key.equals("coxChallengeMode"));
			live.maxCombat = 0;
		}
		return live;
	}
}

package com.bestgearsetup;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Consumer;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameState;
import net.runelite.api.Hitsplat;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.util.Text;

/**
 * Specials that landed on the target being fought. A search of that target uses them in place of the planned
 * pre-fight preparation; saved settings are never changed. Own specials are matched to their hitsplat the way
 * RuneLite's Special Attack Counter does, using only the game API, so they keep working whatever that plugin does;
 * party members' arrive through {@link PartySpecs} when it is available. Client thread only, except {@link #overrides}.
 */
final class LiveSpecs
{
	static final String AUTO_KEY = "autoSpecs";
	/** Preparation keys this tracker fills, with each setting's upper bound. */
	private static final Map<String, Integer> LIMITS = new LinkedHashMap<>();

	static
	{
		LIMITS.put("specElderMaul", 10);
		LIMITS.put("specDwh", 10);
		LIMITS.put("specEmberlight", 20);
		LIMITS.put("specArclight", 20);
		LIMITS.put("specTonalztics", 20);
		LIMITS.put("specBgsDamage", 2000);
		LIMITS.put("specSeercullDamage", 2000);
		LIMITS.put("specAyakDamage", 2000);
	}

	private final Client client;
	private final ClientThread clientThread;
	private final BestGearSetupConfig config;
	/** Called with the tracked target's name whenever what landed on it changes. */
	private final Consumer<String> changed;

	private final Map<String, Integer> landed = new HashMap<>();
	private int targetIndex = -1;
	/** Lower-case name of the tracked target; read by searches off the client thread. */
	private volatile String targetName;
	private volatile Map<String, Object> snapshot = new HashMap<>();

	private int energy = -1;
	private long hitpointsXp = -1;
	private int hitpointsXpCycle = -1;
	private SpecWeapon weapon;
	private NPC specTarget;
	private boolean specXp;
	private int hitsplatTick;
	private final List<Hitsplat> hitsplats = new ArrayList<>();

	LiveSpecs(Client client, ClientThread clientThread, BestGearSetupConfig config, Consumer<String> changed)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.changed = changed;
	}

	/**
	 * The preparation values for a search of this monster: every tracked special, so planned ones that did not
	 * land read zero. Empty when the monster isn't the target being fought.
	 */
	Map<String, Object> overrides(String monsterName)
	{
		String name = targetName;
		return name != null && sameTarget(name, monsterName) ? snapshot : new HashMap<>();
	}

	/** Whether a catalogue name ("verzik vitur (phase 2)") names the live NPC ("verzik vitur"). */
	static boolean sameTarget(String npcName, String monsterName)
	{
		String monster = monsterName.toLowerCase(Locale.ROOT);
		return monster.equals(npcName) || monster.startsWith(npcName + " (");
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarpId() != VarPlayerID.SA_ENERGY)
		{
			return;
		}
		int previous = energy;
		energy = event.getValue();
		if (previous == -1 || energy >= previous)
		{
			return;
		}
		// Player and NPC updates follow this event, so the target is read once they have run.
		int serverTick = client.getTickCount();
		clientThread.invokeLater(() ->
		{
			Player player = client.getLocalPlayer();
			SpecWeapon used = usedWeapon();
			if (player == null || used == null || !(player.getInteracting() instanceof NPC))
			{
				return;
			}
			weapon = used;
			specTarget = (NPC) player.getInteracting();
			specXp = hitpointsXpCycle == client.getGameCycle();
			hitsplats.clear();
			WorldArea area = specTarget.getWorldArea();
			hitsplatTick = serverTick + (area == null ? 1 : used.hitDelay(area.distanceTo(player.getWorldLocation())));
		});
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.HITPOINTS)
		{
			return;
		}
		if (hitpointsXp != -1 && event.getXp() > hitpointsXp)
		{
			hitpointsXpCycle = client.getGameCycle();
		}
		hitpointsXp = event.getXp();
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (event.getHitsplat().isMine() && specTarget != null && event.getActor() == specTarget
			&& hitsplatTick == client.getTickCount())
		{
			hitsplats.add(event.getHitsplat());
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (weapon == null || specTarget == null)
		{
			return;
		}
		int tick = client.getTickCount();
		if (weapon == SpecWeapon.ELDER_MAUL)
		{
			// Its hitsplat comes late; the Hitpoints experience of the spec tick shows whether it landed.
			land(weapon, specXp ? 1 : 0, specTarget);
		}
		else if (tick == hitsplatTick)
		{
			if (weapon == SpecWeapon.TONALZTICS_OF_RALOS)
			{
				if (hitsplats.size() < 2)
				{
					return;
				}
				int count = hitsplats.size();
				land(weapon, Math.min(hitsplats.get(count - 1).getAmount(), 1)
					+ Math.min(hitsplats.get(count - 2).getAmount(), 1), specTarget);
			}
			else
			{
				if (hitsplats.isEmpty())
				{
					return;
				}
				// The weapon's hitsplat comes after same-tick ones such as vengeance or thralls.
				land(weapon, hitsplats.get(hitsplats.size() - 1).getAmount(), specTarget);
			}
		}
		else if (tick < hitsplatTick)
		{
			return;
		}
		weapon = null;
		specTarget = null;
		hitsplats.clear();
	}

	/** A party member's special, reported by its Special Attack Counter weapon name. */
	void partySpec(int npcIndex, String weaponName, int hit)
	{
		SpecWeapon used = SpecWeapon.byName(weaponName);
		NPC target = used == null ? null : client.getTopLevelWorldView().npcs().byIndex(npcIndex);
		if (target != null)
		{
			land(used, hit, target);
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		if (event.getNpc().getIndex() == targetIndex)
		{
			end();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			end();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (BestGearSetupConfig.GROUP.equals(event.getGroup()) && AUTO_KEY.equals(event.getKey()) && !config.autoSpecs())
		{
			end();
		}
	}

	private void land(SpecWeapon used, int hit, NPC target)
	{
		if (!config.autoSpecs() || target.getName() == null)
		{
			return;
		}
		if (target.getIndex() != targetIndex)
		{
			landed.clear();
			targetIndex = target.getIndex();
			targetName = Text.removeTags(target.getName()).toLowerCase(Locale.ROOT).trim();
		}
		landed.merge(used.key, used.amount(hit, target), Integer::sum);
		Map<String, Object> values = new HashMap<>();
		LIMITS.forEach((k, limit) -> values.put(k, Math.min(limit, landed.getOrDefault(k, 0))));
		snapshot = values;
		changed.accept(targetName);
	}

	/** Stop tracking; the next search of the target uses the planned preparation again. */
	void end()
	{
		String name = targetName;
		landed.clear();
		targetIndex = -1;
		targetName = null;
		snapshot = new HashMap<>();
		weapon = null;
		specTarget = null;
		hitsplats.clear();
		if (name != null)
		{
			changed.accept(name);
		}
	}

	private SpecWeapon usedWeapon()
	{
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		Item item = worn == null ? null : worn.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		return item == null ? null : SpecWeapon.byItem(item.getId());
	}
}

package com.bestgearsetup;

import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;

/**
 * Tracks which items the player owns across bank, inventory and worn equipment, with stack sizes so
 * ammunition can be priced by the shortfall. Each container is persisted per RuneScape profile so the
 * bank is remembered after it has been opened once.
 */
@Singleton
public class OwnedItems
{
	private static final String BANK_KEY = "ownedBank";
	private static final String INVENTORY_KEY = "ownedInventory";
	private static final String WORN_KEY = "ownedWorn";
	private static final String MANUAL_KEY = "ownedManual";
	/** The quantity assumed for an item marked owned by hand: enough of any requested stack. */
	public static final long UNLIMITED = Long.MAX_VALUE;

	private final ConfigManager configManager;
	private final ItemManager itemManager;

	/** Quantity held per canonical item id, per container. */
	volatile Map<Integer, Long> bank = Collections.emptyMap();
	volatile Map<Integer, Long> inventory = Collections.emptyMap();
	volatile Map<Integer, Long> worn = Collections.emptyMap();
	/**
	 * Canonical ids equipped right now: set from the live worn container and cleared on logout. Unlike
	 * {@link #worn} it is never persisted, so remembered equipment doesn't show as equipped while logged out.
	 */
	volatile Set<Integer> equipped = Collections.emptySet();
	/** Items the player marked as owned by hand (e.g. stored in the POH costume room); no quantity is known. */
	private volatile Set<Integer> manual = Collections.emptySet();
	/** Owned ids and reviewed equivalent charge states. */
	private volatile Set<Integer> expanded = Collections.emptySet();
	/** Total quantity per id across containers; {@link #UNLIMITED} for items marked owned by hand. */
	private volatile Map<Integer, Long> quantities = Collections.emptyMap();

	@Getter
	private volatile boolean bankKnown;

	@Inject
	OwnedItems(ConfigManager configManager, ItemManager itemManager)
	{
		this.configManager = configManager;
		this.itemManager = itemManager;
	}

	/** Reload the persisted containers for the current profile. */
	public void load()
	{
		bank = readQuantities(BANK_KEY);
		inventory = readQuantities(INVENTORY_KEY);
		worn = readQuantities(WORN_KEY);
		manual = read(MANUAL_KEY);
		bankKnown = configManager.getRSProfileConfiguration(BestGearSetupConfig.GROUP, BANK_KEY) != null;
		rebuild();
	}

	/** Must be called on the client thread (canonicalises item ids). */
	public void onContainerChanged(int containerId, ItemContainer container)
	{
		String key;
		if (containerId == InventoryID.BANK)
		{
			key = BANK_KEY;
		}
		else if (containerId == InventoryID.INV)
		{
			key = INVENTORY_KEY;
		}
		else if (containerId == InventoryID.WORN)
		{
			key = WORN_KEY;
		}
		else
		{
			return;
		}

		Map<Integer, Long> ids = new HashMap<>();
		for (Item item : container.getItems())
		{
			// Quantity 0 is a bank placeholder: not owned.
			if (item.getId() > 0 && item.getQuantity() > 0)
			{
				ids.merge(itemManager.canonicalize(item.getId()), (long) item.getQuantity(), Long::sum);
			}
		}

		if (containerId == InventoryID.WORN)
		{
			equipped = Collections.unmodifiableSet(new HashSet<>(ids.keySet()));
		}

		Map<Integer, Long> previous = containerId == InventoryID.BANK ? bank : containerId == InventoryID.INV ? inventory : worn;
		boolean changed = !ids.equals(previous) || (containerId == InventoryID.BANK && !bankKnown);
		if (!changed)
		{
			return;
		}
		// Firing ammunition only changes stack sizes; the owned set is re-expanded only when items come or go.
		boolean itemsChanged = !ids.keySet().equals(previous.keySet());

		if (containerId == InventoryID.BANK)
		{
			bank = ids;
			bankKnown = true;
		}
		else if (containerId == InventoryID.INV)
		{
			inventory = ids;
		}
		else
		{
			worn = ids;
		}
		configManager.setRSProfileConfiguration(BestGearSetupConfig.GROUP, key, serialize(ids));
		rebuild(itemsChanged);
	}

	public Set<Integer> getManual()
	{
		return Collections.unmodifiableSet(manual);
	}

	public boolean isManual(int itemId)
	{
		return manual.contains(itemId);
	}

	public void setManual(int itemId, boolean owned)
	{
		Set<Integer> next = new HashSet<>(manual);
		if (owned ? !next.add(itemId) : !next.remove(itemId))
		{
			return;
		}
		manual = next;
		configManager.setRSProfileConfiguration(BestGearSetupConfig.GROUP, MANUAL_KEY,
			next.stream().map(String::valueOf).collect(Collectors.joining(",")));
		rebuild();
	}

	public boolean owns(int itemId)
	{
		return expanded.contains(itemId);
	}

	/** Whether the item (canonical id) is equipped right now; always false while logged out. */
	public boolean isWorn(int itemId)
	{
		return equipped.contains(itemId);
	}

	/** Logged out: nothing is equipped until the worn container is seen again. */
	public void clearEquipped()
	{
		equipped = Collections.emptySet();
	}

	/** Immutable view of the owned ids at this moment, unaffected by later container changes. */
	public Set<Integer> snapshot()
	{
		return expanded;
	}

	/** Immutable quantities at this moment: held stacks per id, {@link #UNLIMITED} for manual entries. */
	public Map<Integer, Long> quantitySnapshot()
	{
		return quantities;
	}

	/** Distinct items seen in the bank, inventory and worn equipment, excluding manual entries. */
	public int count()
	{
		Set<Integer> all = new HashSet<>(bank.keySet());
		all.addAll(inventory.keySet());
		all.addAll(worn.keySet());
		return all.size();
	}

	private void rebuild()
	{
		rebuild(true);
	}

	void rebuild(boolean itemsChanged)
	{
		Map<Integer, Long> total = combine(java.util.Arrays.asList(bank, inventory, worn), manual);
		if (itemsChanged)
		{
			expanded = expand(total.keySet());
		}
		quantities = Collections.unmodifiableMap(total);
	}

	/** Sum stacks across containers; a manual entry has no known quantity, so it covers any stack. */
	static Map<Integer, Long> combine(Collection<Map<Integer, Long>> containers, Set<Integer> manual)
	{
		Map<Integer, Long> total = new HashMap<>();
		for (Map<Integer, Long> container : containers)
		{
			container.forEach((id, qty) -> total.merge(id, qty, OwnedItems::saturatedAdd));
		}
		for (int id : manual)
		{
			total.put(id, UNLIMITED);
		}
		return total;
	}

	private static long saturatedAdd(long a, long b)
	{
		long sum = a + b;
		return sum < 0 ? UNLIMITED : sum;
	}

	/** Exact holdings plus reviewed charge states; resale components are not separately held items. */
	static Set<Integer> expand(Set<Integer> actual)
	{
		Set<Integer> all = new HashSet<>(actual);
		for (int id : actual)
		{
			for (int variant : ItemVariationMapping.getVariations(ItemVariationMapping.map(id)))
			{
				if (OwnershipRules.equivalent(id, variant) && ItemCosts.equivalent(id, variant))
				{
					all.add(variant);
				}
			}
		}
		return Collections.unmodifiableSet(all);
	}

	static String serialize(Map<Integer, Long> quantities)
	{
		return quantities.entrySet().stream().map(e -> e.getKey() + ":" + e.getValue()).collect(Collectors.joining(","));
	}

	/** "id:quantity" entries; a bare "id" from older versions counts as one. */
	static Map<Integer, Long> parseQuantities(String value)
	{
		if (value == null || value.isEmpty())
		{
			return Collections.emptyMap();
		}
		Map<Integer, Long> out = new HashMap<>();
		for (String part : value.split(","))
		{
			String[] fields = part.trim().split(":", 2);
			try
			{
				long qty = fields.length > 1 ? Long.parseLong(fields[1].trim()) : 1;
				if (qty > 0)
				{
					out.merge(Integer.parseInt(fields[0].trim()), qty, OwnedItems::saturatedAdd);
				}
			}
			catch (NumberFormatException ignored)
			{
				// skip corrupt entries
			}
		}
		return out;
	}

	private Map<Integer, Long> readQuantities(String key)
	{
		return parseQuantities(configManager.getRSProfileConfiguration(BestGearSetupConfig.GROUP, key));
	}

	private Set<Integer> read(String key)
	{
		String value = configManager.getRSProfileConfiguration(BestGearSetupConfig.GROUP, key);
		if (value == null || value.isEmpty())
		{
			return Collections.emptySet();
		}
		Set<Integer> ids = new HashSet<>();
		for (String part : value.split(","))
		{
			try
			{
				ids.add(Integer.parseInt(part.trim()));
			}
			catch (NumberFormatException ignored)
			{
				// skip corrupt entries
			}
		}
		return ids;
	}
}

package com.bestgearsetup;

import com.bestgearsetup.data.GameData;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Slot;
import com.bestgearsetup.data.WikiGameData;
import com.google.gson.Gson;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemVariationMapping;

/** Ownership identities are separate from RuneLite's resale and broad cosmetic families. */
public final class OwnershipRules
{
	/** RuneLite's injected Gson: plugins may not create their own (Plugin Hub disallowed API). */
	private static volatile Gson gson;
	private static volatile Rules rules;

	/** Built once from the bundled catalogue, on first use rather than at class load, so it can use the client's Gson. */
	private static final class Rules
	{
		private final Map<Integer, Integer> states = new HashMap<>();
		private final Set<Integer> equipmentFamilies = new HashSet<>();
		private final Set<Integer> earned = new HashSet<>();

		Rules()
		{
			try
			{
				// The cached catalogue the plugin also loads: no second parse, monster list or deep copy.
				GameData data = catalogue().getEquipment();
				for (Slot slot : Slot.values())
				{
					for (GearItem item : data.getItems(slot))
					{
						equipmentFamilies.add(ItemVariationMapping.map(item.getId()));
						for (int variant : item.getVariants())
						{
							equipmentFamilies.add(ItemVariationMapping.map(variant));
						}
						// These entries contain charge counts or alternative providers of the same earned imbue.
						String name = item.getName();
						if (name.equals("black mask") || name.equals("black mask (i)")
							|| name.endsWith("ring (i)") || name.equals("ring of the gods (i)")
							|| name.equals("ring of suffering (i)") || name.equals("salve amulet(i)")
							|| name.equals("salve amulet(ei)"))
						{
							states.put(item.getId(), item.getId());
							for (int variant : item.getVariants())
							{
								states.put(variant, item.getId());
							}
						}
						if (name.endsWith("ring (i)") || name.equals("ring of the gods (i)")
							|| name.equals("ring of suffering (i)") || name.equals("black mask (i)")
							|| name.equals("slayer helmet (i)") || name.startsWith("salve amulet")
							|| name.equals("slayer helmet") || name.endsWith("cape (i)"))
						{
							earned.add(item.getId());
							earned.addAll(item.getVariants());
						}
					}
				}
			}
			catch (IOException e)
			{
				throw new UncheckedIOException(e);
			}
			group(ItemID.AMULET_OF_GLORY, ItemID.AMULET_OF_GLORY_1, ItemID.AMULET_OF_GLORY_2, ItemID.AMULET_OF_GLORY_3, ItemID.AMULET_OF_GLORY_4, ItemID.AMULET_OF_GLORY_5, ItemID.AMULET_OF_GLORY_6);
			group(ItemID.TRAIL_AMULET_OF_GLORY, ItemID.TRAIL_AMULET_OF_GLORY_1, ItemID.TRAIL_AMULET_OF_GLORY_2, ItemID.TRAIL_AMULET_OF_GLORY_3, ItemID.TRAIL_AMULET_OF_GLORY_4, ItemID.TRAIL_AMULET_OF_GLORY_5, ItemID.TRAIL_AMULET_OF_GLORY_6);
			group(ItemID.RING_OF_WEALTH, ItemID.RING_OF_WEALTH_5, ItemID.RING_OF_WEALTH_4, ItemID.RING_OF_WEALTH_3, ItemID.RING_OF_WEALTH_2, ItemID.RING_OF_WEALTH_1);
			group(ItemID.RING_OF_WEALTH_I, ItemID.RING_OF_WEALTH_I5, ItemID.RING_OF_WEALTH_I4, ItemID.RING_OF_WEALTH_I3, ItemID.RING_OF_WEALTH_I2, ItemID.RING_OF_WEALTH_I1);
			group(ItemID.TOTS_UNCHARGED, ItemID.TOTS_CHARGED); // Trident of the seas, uncharged/charged.
			group(ItemID.TOXIC_TOTS_UNCHARGED, ItemID.TOXIC_TOTS_CHARGED); // Trident of the swamp, uncharged/charged.
			group(ItemID.TOTS_I_UNCHARGED, ItemID.TOTS_I_CHARGED);
			group(ItemID.TOXIC_TOTS_I_UNCHARGED, ItemID.TOXIC_TOTS_I_CHARGED);
			group(ItemID.TOXIC_BLOWPIPE, ItemID.TOXIC_BLOWPIPE_LOADED); // Blowpipe, empty/loaded; ornaments retain their own identities.
			group(ItemID.TOXIC_SOTD, ItemID.TOXIC_SOTD_CHARGED);
			group(ItemID.SERPENTINE_HELM, ItemID.SERPENTINE_HELM_CHARGED);
			group(ItemID.SERPENTINE_HELM_CYAN, ItemID.SERPENTINE_HELM_CHARGED_CYAN);
			group(ItemID.SERPENTINE_HELM_RED, ItemID.SERPENTINE_HELM_CHARGED_RED);
			group(ItemID.SANGUINESTI_STAFF_UNCHARGED, ItemID.SANGUINESTI_STAFF);
			group(ItemID.SANGUINESTI_STAFF_UNCHARGED_OR, ItemID.SANGUINESTI_STAFF_OR);
			group(ItemID.SCYTHE_OF_VITUR_UNCHARGED, ItemID.SCYTHE_OF_VITUR);
			group(ItemID.SCYTHE_OF_VITUR_UNCHARGED_OR, ItemID.SCYTHE_OF_VITUR_OR);
			group(ItemID.SCYTHE_OF_VITUR_UNCHARGED_BL, ItemID.SCYTHE_OF_VITUR_BL);
			group(ItemID.TUMEKENS_SHADOW_UNCHARGED, ItemID.TUMEKENS_SHADOW);
			group(ItemID.TOXIC_BLOWPIPE_ORNAMENT, ItemID.TOXIC_BLOWPIPE_LOADED_ORNAMENT);
			group(ItemID.WILD_CAVE_CHAINMACE_UNCHARGED, ItemID.WILD_CAVE_CHAINMACE_CHARGED);
			group(ItemID.WILD_CAVE_BOW_UNCHARGED, ItemID.WILD_CAVE_BOW_CHARGED);
			group(ItemID.WILD_CAVE_SCEPTRE_UNCHARGED, ItemID.WILD_CAVE_SCEPTRE_CHARGED);
			group(ItemID.WILD_CAVE_WEBWEAVER_UNCHARGED, ItemID.WILD_CAVE_WEBWEAVER_CHARGED);
			group(ItemID.WILD_CAVE_URSINE_UNCHARGED, ItemID.WILD_CAVE_URSINE_CHARGED);
			group(ItemID.WILD_CAVE_ACCURSED_UNCHARGED, ItemID.WILD_CAVE_ACCURSED_CHARGED);
			group(ItemID.WILD_CAVE_ACCURSED_UNCHARGED_RECOL, ItemID.WILD_CAVE_ACCURSED_CHARGED_RECOL);
			group(ItemID.WILD_CAVE_SCEPTRE_UNCHARGED_RECOL, ItemID.WILD_CAVE_SCEPTRE_CHARGED_RECOL);
			group(ItemID.TOME_OF_FIRE_UNCHARGED, ItemID.TOME_OF_FIRE);
			group(ItemID.TOME_OF_WATER_UNCHARGED, ItemID.TOME_OF_WATER);
			group(ItemID.TOME_OF_EARTH_UNCHARGED, ItemID.TOME_OF_EARTH);
		}

		private void group(int base, int... variants)
		{
			states.put(base, base);
			for (int variant : variants)
			{
				states.put(variant, base);
			}
		}
	}

	private OwnershipRules()
	{
	}

	/** Give the rules the client's Gson; the plugin calls this before anything can query them. */
	public static void init(Gson clientGson)
	{
		gson = clientGson;
	}

	/** Build the rules on a background thread before UI or client-thread code first queries them. */
	public static void load()
	{
		rules();
	}

	private static Rules rules()
	{
		Rules loaded = rules;
		if (loaded == null)
		{
			synchronized (OwnershipRules.class)
			{
				loaded = rules;
				if (loaded == null)
				{
					loaded = new Rules();
					rules = loaded;
				}
			}
		}
		return loaded;
	}

	/** The cached catalogue the plugin also loads: no second parse, monster list or deep copy. */
	private static WikiGameData catalogue() throws IOException
	{
		WikiGameData loaded = WikiGameData.loaded();
		if (loaded != null)
		{
			return loaded;
		}
		Gson client = gson;
		if (client == null)
		{
			throw new IllegalStateException("OwnershipRules.init must be given the client's Gson first");
		}
		return WikiGameData.get(client);
	}

	/** Only reviewed charge states and identical earned tiers share ownership; unknown gear stays exact. */
	public static boolean equivalent(int first, int second)
	{
		return first == second || identity(first) == identity(second);
	}

	/** Acquisition identity for gear; non-equipment such as potion doses keeps its RuneLite family. */
	public static int identity(int id)
	{
		if (DiaryRewards.isReward(id))
		{
			return id;
		}
		Integer state = rules().states.get(id);
		if (state != null)
		{
			return state;
		}
		int base = ItemVariationMapping.map(id);
		return rules().equipmentFamilies.contains(base) ? id : base;
	}

	/** Earned imbues cannot be acquired just by buying the tradable base in a budget search. */
	public static boolean requiresOwnership(int id)
	{
		return DiaryRewards.isReward(id) || rules().earned.contains(id);
	}
}

package com.bestgearsetup;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.plugins.specialcounter.SpecialCounterUpdate;

/**
 * Party members' specials, read from the updates RuneLite's Special Attack Counter shares over RuneLite Party.
 * This is the only class that uses that plugin's classes: if they are missing or have changed, registering or
 * handling an update fails with a {@link LinkageError}, party specials stop, and {@link LiveSpecs} keeps tracking
 * the player's own. Updates only arrive while the Special Attack Counter runs here and for the sender.
 */
@Slf4j
final class PartySpecs
{
	private final Client client;
	private final ClientThread clientThread;
	private final PartyService party;
	private final LiveSpecs specs;
	private boolean broken;

	PartySpecs(Client client, ClientThread clientThread, PartyService party, LiveSpecs specs)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.party = party;
		this.specs = specs;
	}

	@Subscribe
	public void onSpecialCounterUpdate(SpecialCounterUpdate event)
	{
		if (broken)
		{
			return;
		}
		try
		{
			PartyMember local = party.getLocalMember();
			// Own specials are tracked directly.
			if (local == null || local.getMemberId() == event.getMemberId() || event.getWorld() != client.getWorld())
			{
				return;
			}
			int npcIndex = event.getNpcIndex();
			String weapon = event.getWeapon().name();
			int hit = event.getHit();
			clientThread.invoke(() -> specs.partySpec(npcIndex, weapon, hit));
		}
		catch (LinkageError e)
		{
			broken = true;
			log.warn("Special Attack Counter updates changed; party specs are off, own specs are still tracked", e);
		}
	}
}

