package com.bestgearsetup;

import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicIntegerArray;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.IntConsumer;
import java.util.function.LongSupplier;

/**
 * Combines the progress of a search's result tabs, which may run on several threads, into one percentage.
 * Each tab counts equally. A new percentage is published at most once per {@link #INTERVAL_NANOS}, and
 * never one lower than already published, so the panel is not flooded with Swing updates.
 */
final class SearchProgress
{
	/** Shortest gap between two published updates. */
	static final long INTERVAL_NANOS = 100_000_000L;

	/** Per-tab progress in hundredths of a percent, for a smooth average without floating-point atomics. */
	private final AtomicIntegerArray tabs;
	private final AtomicInteger published = new AtomicInteger(-1);
	private final AtomicLong lastPublished;
	private final IntConsumer publish;
	private final LongSupplier clock;

	/**
	 * @param tabs    number of result tabs searched
	 * @param publish receives the overall percentage (0 to 100); may be called from any search thread
	 */
	SearchProgress(int tabs, IntConsumer publish)
	{
		this(tabs, publish, System::nanoTime);
	}

	SearchProgress(int tabs, IntConsumer publish, LongSupplier clock)
	{
		this.tabs = new AtomicIntegerArray(Math.max(1, tabs));
		this.publish = publish;
		this.clock = clock;
		this.lastPublished = new AtomicLong(clock.getAsLong() - INTERVAL_NANOS);
	}

	/** Record one tab's fraction done (0 to 1). */
	void update(int tab, double fraction)
	{
		tabs.set(tab, (int) Math.round(Math.max(0, Math.min(1, fraction)) * 10_000));
		long now = clock.getAsLong();
		long last = lastPublished.get();
		if (now - last >= INTERVAL_NANOS && lastPublished.compareAndSet(last, now))
		{
			offer(percent());
		}
	}

	/** Publish 100%, whatever the throttle; the search is finishing up. */
	void complete()
	{
		offer(100);
	}

	int percent()
	{
		long sum = 0;
		for (int i = 0; i < tabs.length(); i++)
		{
			sum += tabs.get(i);
		}
		return (int) (sum / tabs.length() / 100);
	}

	private void offer(int percent)
	{
		int previous = published.getAndAccumulate(percent, Math::max);
		if (percent > previous)
		{
			publish.accept(percent);
		}
	}
}

package com.bestgearsetup;

import com.bestgearsetup.calc.AttackStyle;
import com.bestgearsetup.calc.LockStatus;
import com.bestgearsetup.calc.SetupResult;
import com.bestgearsetup.calc.Thrall;
import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.OffensivePrayer;
import com.bestgearsetup.data.Potion;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import lombok.AllArgsConstructor;
import lombok.Value;

/**
 * Everything the results view shows for one search.
 */
@Value
@AllArgsConstructor
public class SearchResults
{
	/** The target after any pre-fight stat drains. */
	Monster monster;
	/** Effective starting HP used by the calculator, which may be below the target's maximum. */
	int startingHitpoints;
	/** Best setups per attack type (stab, slash, crush, ranged, magic), best first. */
	Map<AttackStyle.Type, List<SetupResult>> byType;
	List<String> notes;
	Map<CombatClass, OffensivePrayer> prayers;
	/** Potions used per combat class (melee may use one for Attack and another for Strength). */
	Map<CombatClass, List<Potion>> potions;
	boolean assumedLevels;
	/** How each slot lock affected the search; empty when nothing is locked. */
	List<LockStatus> locks;
	/** Mark of Darkness is assumed for demonbane spells. */
	boolean markOfDarkness;
	/** Logged out, using the levels last seen on this account. */
	boolean rememberedLevels;
	/** Assumptions that change the headline estimates and must stay visible beside them (potion overrides...). */
	List<String> warnings;
	/** The thrall added to setups that can cast one, or null when none is. */
	Thrall thrall;
	/** The raid scaling applied, such as "ToB party: 3 (live raid)", or null outside raids. */
	String raidScaling;
	/** The target's Defence level before pre-fight drains. */
	int baseDefence;

	public SearchResults(Monster monster, int startingHitpoints, Map<AttackStyle.Type, List<SetupResult>> byType,
		List<String> notes, Map<CombatClass, OffensivePrayer> prayers, Map<CombatClass, List<Potion>> potions,
		boolean assumedLevels)
	{
		this(monster, startingHitpoints, byType, notes, prayers, potions, assumedLevels, Collections.emptyList(), false, false,
			Collections.emptyList());
	}

	public SearchResults(Monster monster, int startingHitpoints, Map<AttackStyle.Type, List<SetupResult>> byType,
		List<String> notes, Map<CombatClass, OffensivePrayer> prayers, Map<CombatClass, List<Potion>> potions,
		boolean assumedLevels, List<LockStatus> locks, boolean markOfDarkness, boolean rememberedLevels, List<String> warnings)
	{
		this(monster, startingHitpoints, byType, notes, prayers, potions, assumedLevels, locks, markOfDarkness,
			rememberedLevels, warnings, null, null, monster == null ? 0 : monster.getDefenceLevel());
	}

	/** Whether a lock could not be honoured. */
	public boolean hasBlockingLock()
	{
		return locks.stream().anyMatch(LockStatus::isBlocking);
	}

	public boolean isEmpty()
	{
		return byType.isEmpty();
	}
}

package com.bestgearsetup;

import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.NPC;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;

/**
 * Special attack weapons whose landed specs set a pre-fight preparation value. Constant names match RuneLite's
 * Special Attack Counter weapons, so party updates map across by name; timings follow that plugin's measurements.
 */
enum SpecWeapon
{
	DRAGON_WARHAMMER("specDwh", false, 0, 0, ItemID.DRAGON_WARHAMMER, ItemID.BH_DRAGON_WARHAMMER_CORRUPTED),
	ELDER_MAUL("specElderMaul", false, 50, 0, ItemID.ELDER_MAUL, ItemID.ELDER_MAUL_ORNAMENT),
	ARCLIGHT("specArclight", false, 0, 0, ItemID.ARCLIGHT),
	EMBERLIGHT("specEmberlight", false, 0, 0, ItemID.EMBERLIGHT),
	// The hit counts of its double hit, reported as one value like the Special Attack Counter does.
	TONALZTICS_OF_RALOS("specTonalztics", true, 50, 0, ItemID.TONALZTICS_OF_RALOS_CHARGED),
	BANDOS_GODSWORD("specBgsDamage", true, 0, 0, ItemID.BGS, ItemID.BGSG),
	SEERCULL("specSeercullDamage", true, 46, 5, ItemID.DAGANOTH_CAVE_MAGIC_SHORTBOW),
	EYE_OF_AYAK("specAyakDamage", true, 120, 0, ItemID.EYE_OF_AYAK);

	/** Tekton loses Defence even when a Bandos godsword special misses. */
	private static final Set<Integer> TEKTON = new HashSet<>(Arrays.asList(NpcID.RAIDS_TEKTON_WAITING,
		NpcID.RAIDS_TEKTON_WALKING_STANDARD, NpcID.RAIDS_TEKTON_FIGHTING_STANDARD, NpcID.RAIDS_TEKTON_HAMMERING,
		NpcID.RAIDS_TEKTON_WALKING_ENRAGED, NpcID.RAIDS_TEKTON_FIGHTING_ENRAGED));
	private static final Map<Integer, SpecWeapon> BY_ITEM = new HashMap<>();
	private static final Map<String, SpecWeapon> BY_NAME = new HashMap<>();

	static
	{
		for (SpecWeapon weapon : values())
		{
			BY_NAME.put(weapon.name(), weapon);
			for (int id : weapon.items)
			{
				BY_ITEM.put(id, weapon);
			}
		}
	}

	/** The preparation setting the special fills. */
	final String key;
	/** Whether the setting counts damage (or Tonalztics hits) rather than successful specials. */
	final boolean damage;
	private final int baseCycles;
	private final int cyclesPerTile;
	private final int[] items;

	SpecWeapon(String key, boolean damage, int baseCycles, int cyclesPerTile, int... items)
	{
		this.key = key;
		this.damage = damage;
		this.baseCycles = baseCycles;
		this.cyclesPerTile = cyclesPerTile;
		this.items = items;
	}

	static SpecWeapon byItem(int itemId)
	{
		return BY_ITEM.get(itemId);
	}

	/** The weapon a Special Attack Counter weapon name refers to, or null when it isn't modelled. */
	static SpecWeapon byName(String name)
	{
		return BY_NAME.get(name);
	}

	/** Game ticks from the spec energy drop to the hitsplat, at this distance in tiles. */
	int hitDelay(int distance)
	{
		// Projectile travel in client cycles (30 per tick), plus the tick every attack waits.
		return (baseCycles + cyclesPerTile * distance) / 30 + 1;
	}

	/** What one special adds to its setting. */
	int amount(int hit, NPC target)
	{
		if (this == BANDOS_GODSWORD && hit == 0 && target != null && TEKTON.contains(target.getId()))
		{
			return 10;
		}
		return damage ? Math.max(0, hit) : hit > 0 ? 1 : 0;
	}
}

