/**
 * Everything about the fight that does not depend on the gear: target (after any pre-fight
 * drains), boosted levels, the prayer used for each combat class, task and thrall.
 */
@Getter
public class CombatContext
{
	private final Monster monster;
	private final PlayerLevels levels;
	private final boolean onTask;
	private final int attack;
	private final int strength;
	private final int ranged;
	private final int magic;
	private final Map<CombatClass, OffensivePrayer> prayers;
	private final boolean thrall;
	private final int aoeTargets;
	private final int targetDistance;
	private final CombatModifiers modifiers;
	/** Target stats at a given HP (after pre-fight drains), or null when they do not depend on HP. */
	private final IntFunction<Monster> healthStates;

	public CombatContext(Monster monster, PlayerLevels levels, boolean onTask, int attack, int strength, int ranged,
		int magic, Map<CombatClass, OffensivePrayer> prayers, boolean thrall)
	{
		this(monster, levels, onTask, attack, strength, ranged, magic, prayers, thrall, 1, 0);
	}

	private CombatContext(Monster monster, PlayerLevels levels, boolean onTask, int attack, int strength, int ranged,
		int magic, Map<CombatClass, OffensivePrayer> prayers, boolean thrall, int aoeTargets, int targetDistance)
	{
		this(monster, levels, onTask, attack, strength, ranged, magic, prayers, thrall, aoeTargets, targetDistance,
			CombatModifiers.NONE);
	}

	private CombatContext(Monster monster, PlayerLevels levels, boolean onTask, int attack, int strength, int ranged,
		int magic, Map<CombatClass, OffensivePrayer> prayers, boolean thrall, int aoeTargets, int targetDistance,
		CombatModifiers modifiers)
	{
		this(monster, levels, onTask, attack, strength, ranged, magic, prayers, thrall, aoeTargets, targetDistance,
			modifiers, null);
	}

	private CombatContext(Monster monster, PlayerLevels levels, boolean onTask, int attack, int strength, int ranged,
		int magic, Map<CombatClass, OffensivePrayer> prayers, boolean thrall, int aoeTargets, int targetDistance,
		CombatModifiers modifiers, IntFunction<Monster> healthStates)
	{
		this.monster = monster;
		this.levels = levels;
		this.onTask = onTask;
		this.attack = attack;
		this.strength = strength;
		this.ranged = ranged;
		this.magic = magic;
		this.prayers = prayers == null ? new EnumMap<>(CombatClass.class) : new EnumMap<>(prayers);
		this.thrall = thrall;
		this.aoeTargets = Math.max(1, Math.min(12, aoeTargets));
		this.targetDistance = targetDistance;
		this.modifiers = modifiers;
		this.healthStates = healthStates;
	}

	/** Whether thralls were requested; Lombok skips this getter because {@link #getThrall()} shares its name. */
	public boolean isThrall()
	{
		return thrall;
	}

	/** The thrall added to setups that can cast one, or null when thralls are off or Magic is below 38. */
	public Thrall getThrall()
	{
		if (!thrall)
		{
			return null;
		}
		return levels == null ? Thrall.GREATER : Thrall.forLevel(levels.getMagic());
	}

	/** Grouped identical targets in multicombat; one target disables area damage. */
	public CombatContext withFightOptions(int targets, int distance)
	{
		return new CombatContext(monster, levels, onTask, attack, strength, ranged, magic, prayers, thrall,
			targets, distance, modifiers, healthStates);
	}

	/** Change optional buffs without losing distance, group size or boosted levels. */
	public CombatContext withModifiers(CombatModifiers buffs)
	{
		return new CombatContext(monster, levels, onTask, attack, strength, ranged, magic, prayers, thrall,
			aoeTargets, targetDistance, buffs == null ? CombatModifiers.NONE : buffs, healthStates);
	}

	/** Supply target stats that change with its HP, such as Vardorvis's Defence. */
	public CombatContext withHealthStates(IntFunction<Monster> states)
	{
		return new CombatContext(monster, levels, onTask, attack, strength, ranged, magic, prayers, thrall,
			aoeTargets, targetDistance, modifiers, states);
	}

	/** The same fight after further drains land on the target, at every HP state too. */
	CombatContext withDrains(SpecialAttacks drains)
	{
		if (!drains.isAny())
		{
			return this;
		}
		IntFunction<Monster> states = healthStates == null ? null : hp -> drains.apply(healthStates.apply(hp));
		return new CombatContext(drains.apply(monster), levels, onTask, attack, strength, ranged, magic, prayers,
			thrall, aoeTargets, targetDistance, modifiers, states);
	}

	/** The same fight with the target at the given HP. */
	CombatContext atTargetHp(int hp)
	{
		Monster target = healthStates == null ? monster : healthStates.apply(hp);
		return new CombatContext(target, levels, onTask, attack, strength, ranged, magic, prayers, thrall,
			aoeTargets, targetDistance, modifiers.toBuilder().monsterHitpoints(hp).build(), healthStates);
	}

	/**
	 * Convenience constructor: with potions, assumes super combat, ranging potion and saturated heart.
	 */
	public CombatContext(Monster monster, PlayerLevels levels, boolean onTask, boolean usePotions,
		Map<CombatClass, OffensivePrayer> prayers)
	{
		this(monster, levels, onTask,
			usePotions ? levels.getAttack() + 5 + levels.getAttack() * 15 / 100 : levels.getAttack(),
			usePotions ? levels.getStrength() + 5 + levels.getStrength() * 15 / 100 : levels.getStrength(),
			usePotions ? levels.getRanged() + 4 + levels.getRanged() / 10 : levels.getRanged(),
			usePotions ? levels.getMagic() + 4 + levels.getMagic() / 10 : levels.getMagic(),
			prayers, false);
	}

	public OffensivePrayer getPrayer(CombatClass combatClass)
	{
		return prayers.get(combatClass);
	}

	/** Effective target HP at the start of this fight, clamped to its scaled maximum. */
	public int getTargetHitpoints()
	{
		return modifiers.targetHp(monster);
	}
}

package com.bestgearsetup.calc;

import lombok.Builder;
import lombok.Value;

/** Explicit combat snapshots; defaults do not assume optional buffs or missing health. */
@Value
@Builder(toBuilder = true)
public class CombatModifiers
{
	public static final CombatModifiers NONE = CombatModifiers.builder().build();
	/** Zero selects the player's base maximum HP. */
	int currentHitpoints;
	/** Zero selects the monster's supplied maximum HP. */
	int monsterHitpoints;
	boolean wilderness;
	boolean charge;
	boolean markOfDarkness;
	boolean sunfireRunes;
	boolean kandarinDiary;
	/** Forinthry Surge raises the amulet of avarice bonus against revenants. */
	boolean forinthrySurge;
	/** Poison assumed on poisonable weapons and ammunition. */
	@Builder.Default
	WeaponPoison weaponPoison = WeaponPoison.NONE;
	/** Score each weapon's special attack instead of its ordinary attack. */
	boolean specialAttack;
	int soulreaperStacks;
	@Builder.Default
	int miningLevel = 99;

	int playerHp(PlayerLevels levels)
	{
		return currentHitpoints <= 0 ? levels.getHitpoints() : Math.min(currentHitpoints, levels.getHitpoints());
	}

	int targetHp(com.bestgearsetup.data.Monster monster)
	{
		return monsterHitpoints <= 0 ? monster.getHitpoints() : Math.min(monsterHitpoints, monster.getHitpoints());
	}
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.EncounterPhase;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Monster;

/** Static encounter identity rules from the OSRS Wiki calculator; phases remain separate targets. */
final class CombatRules
{
	private CombatRules()
	{
	}

	static boolean toa(Monster m)
	{
		int id = m.getId();
		return id >= 11789 && id <= 11799 || id >= 11778 && id <= 11780
			|| id == 11719 || id == 11721 || id >= 11724 && id <= 11726
			|| id == 11730 || id == 11732 || id == 11733 || id >= 11750 && id <= 11758
			|| id >= 11761 && id <= 11764 || m.hasAttribute("toa") || m.hasAttribute("tombs of amascut");
	}

	/** NPC defence roll, including the Tombs of Amascut raid-level multiplier stored on scaled targets. */
	static long defenceRoll(Monster m, int level, int bonus)
	{
		long roll = (long) (level + 9) * (bonus + 64);
		int raidLevel = m.getToaRaidLevel();
		return raidLevel > 0 ? roll * (250 + raidLevel) / 250 : roll;
	}

	/** Whether the selected temporary phase names this target. */
	static boolean phaseApplies(Monster m, EncounterPhase phase)
	{
		switch (phase)
		{
			case HUEYCOATL_PILLAR:
				return hueycoatlPillarTarget(m);
			case ROYAL_TITANS_OUT_OF_MELEE:
				return titanBoss(m);
			case ABYSSAL_SIRE_TRANSITION:
				return m.getId() == 5886 || m.getId() == 5889 || m.getId() == 5891
					|| EncounterDamage.named(m, "abyssal sire") && !m.getLowerName().contains("stage 2");
			case MOKHAIOTL_SHIELDED:
			case MOKHAIOTL_BURROWING:
				return EncounterDamage.named(m, "doom of mokhaiotl") || m.getId() == 14707;
			case TD_UNSHIELDED:
			case TD_DEFENCELESS:
				// Variants whose names already fix the shield state ignore the phase option.
				return EncounterDamage.tormented(m) && !m.getLowerName().contains("shielded)")
					&& !m.getLowerName().contains("100% accuracy");
			case YAMA_MELEE_TANK:
				return yamaTankDependent(m);
			default:
				return false;
		}
	}

	static boolean phase(Monster m, EncounterPhase phase)
	{
		return m.getPhase() == phase && phaseApplies(m, phase);
	}

	/** Yama's Magic defence depends on the tank's style except in his enraged final phase. */
	static boolean yamaTankDependent(Monster m)
	{
		String name = m.getLowerName();
		return EncounterDamage.named(m, "yama") && !name.contains("enraged") && !name.contains("phase 3")
			&& !name.contains("mage tank") && !name.contains("deadman");
	}

	/** Head and tail receive the pillar damage buff; the body cannot. */
	static boolean hueycoatlPillarTarget(Monster m)
	{
		String name = m.getLowerName();
		int id = m.getId();
		return EncounterDamage.named(m, "the hueycoatl") ? name.contains("(head)") || name.contains("(tail)")
			: id == 14009 || id == 14010 || id == 14013 || id == 14014;
	}

	static boolean titanBoss(Monster m)
	{
		return m.getId() == 12596 || m.getId() == 14147 || EncounterDamage.named(m, "branda the fire queen")
			|| EncounterDamage.named(m, "eldric the ice king");
	}

	static boolean titanElemental(Monster m)
	{
		String name = m.getLowerName();
		return m.getId() == 14150 || m.getId() == 14151
			|| name.endsWith("elemental (royal titans)");
	}

	/** Targets immune to burns in the reference: Tekton, Dusk, Vasa's crystal and the Warriors' Guild cyclopes. */
	static boolean burnImmune(Monster m)
	{
		int id = m.getId();
		return EncounterDamage.tekton(m) || EncounterDamage.crystal(m) || EncounterDamage.named(m, "dusk")
			|| id == 7851 || id == 7854 || id == 7855 || id == 7882 || id == 7883 || id >= 7886 && id <= 7889
			|| id >= 2463 && id <= 2468 || id >= 2137 && id <= 2142;
	}

	static boolean gauntlet(Monster m)
	{
		return m.hasAttribute("crystalline") || m.hasAttribute("corrupted")
			|| m.getId() >= 9021 && m.getId() <= 9048;
	}

	static boolean equipmentAllowed(Monster m, GearItem item)
	{
		return equipmentAllowed(m, gauntlet(m), item);
	}

	/** @param gauntlet {@link #gauntlet(Monster)}, worked out once when checking every slot of a setup */
	static boolean equipmentAllowed(Monster m, boolean gauntlet, GearItem item)
	{
		String name = EncounterDamage.lower(item);
		boolean activity = (name.startsWith("crystal ") || name.startsWith("corrupted "))
			&& (name.contains("(basic)") || name.contains("(attuned)") || name.contains("(perfected)")
			|| name.contains("(gauntlet)") || name.endsWith("sceptre") || name.equals("corrupted axe")
			|| name.equals("corrupted harpoon") || name.equals("corrupted pickaxe"));
		if (gauntlet)
		{
			return activity && name.startsWith(m.hasAttribute("corrupted") || m.getId() >= 9035 ? "corrupted " : "crystal ");
		}
		return !activity && (!name.startsWith("dawnbringer") || EncounterDamage.verzikP1(m))
			&& (!name.contains("(inside toa)") || toa(m)) && (!name.contains("(outside toa)") || !toa(m));
	}

	static int defenceFloor(Monster m)
	{
		if (EncounterDamage.named(m, "vardorvis") || EncounterDamage.named(m, "verzik vitur"))
		{
			return m.getDefenceLevel();
		}
		String name = m.getLowerName();
		int floor = name.startsWith("sotetseg") ? 100 : name.contains("nightmare") && !name.contains("totem") ? 120
			: name.startsWith("akkha") && !name.contains("shadow") ? 70 : name.startsWith("ba-ba") ? 60
			: name.startsWith("kephri") || name.startsWith("obelisk") && toa(m) ? 60
			: name.startsWith("zebak") ? 50 : name.contains("warden") && name.contains("phase 3") ? 120
			: EncounterDamage.named(m, "nex") ? 250 : EncounterDamage.named(m, "araxxor") ? 90
			: EncounterDamage.named(m, "the hueycoatl") ? 120 : EncounterDamage.named(m, "yama") ? 145
			: EncounterDamage.named(m, "doom of mokhaiotl") ? 60 : 0;
		return Math.min(m.getDefenceLevel(), Math.max(floor, m.getDefenceFloor()));
	}

	static boolean wardenCore(Monster m)
	{
		String name = m.getLowerName();
		if (name.contains("warden"))
		{
			// A named variant takes priority over the NPC id.
			return name.contains("core");
		}
		return m.getId() == 11755 || m.getId() == 11758;
	}

	static boolean wardenP2(Monster m)
	{
		String name = m.getLowerName();
		if (name.contains("warden"))
		{
			return name.contains("phase 2");
		}
		return m.getId() == 11753 || m.getId() == 11754 || m.getId() == 11756 || m.getId() == 11757;
	}

	static long[] bounds(Monster m, long attack, long defence, long max)
	{
		if (!wardenP2(m))
		{
			return new long[]{EncounterDamage.named(m, "respiratory system") ? max / 2 : 0, max};
		}
		double modifier = Math.max(15, Math.min(40, 15 + Math.max(0, attack - defence / 3) * 25.0 / 42000));
		return new long[]{(long) (max * modifier / 100), (long) (max * (modifier + 20) / 100)};
	}

	static boolean defenceBasedMagic(Monster m)
	{
		int id = m.getId();
		return id == 7584 || id == 7585 || id >= 8917 && id <= 8920
			|| id >= 8369 && id <= 8374 || id >= 10830 && id <= 10835 || id >= 10847 && id <= 10852
			|| id == 11709 || id == 11712 || id == 9118
			|| EncounterDamage.named(m, "ice demon") || EncounterDamage.named(m, "fragment of seren")
			|| EncounterDamage.named(m, "verzik vitur");
	}

	static int demonVulnerability(Monster m)
	{
		if (m.getDemonbaneVulnerability() != null)
		{
			return Math.max(0, m.getDemonbaneVulnerability());
		}
		if (EncounterDamage.named(m, "duke sucellus"))
		{
			return 70;
		}
		if (EncounterDamage.named(m, "yama"))
		{
			return 120;
		}
		if (m.getId() == 14179)
		{
			return 200;
		}
		return m.getId() == 7584 || m.getId() == 7585 || EncounterDamage.named(m, "ice demon") ? 115 : 100;
	}

	static int demonBonus(Monster m, int percent)
	{
		return percent * demonVulnerability(m) / 100;
	}

	static boolean alwaysMax(Monster m, CombatClass cls)
	{
		int id = m.getId();
		if (id == 14179 || id == 14180)
		{
			return true;
		}
		switch (cls)
		{
			case MELEE:
				return id == 11710 || id == 11713 || id == 12814 || wardenCore(m);
			case RANGED:
				return id == 11711 || id == 11714 || id == 12815 || id == 11717 || id == 11715;
			default:
				return id == 11709 || id == 11712 || id == 12816 || id == 14150 || id == 14151;
		}
	}

	static boolean oneHit(Monster m)
	{
		return m.getId() == 7223 || m.getId() == 8584 || m.getId() == 11193;
	}

	static double accuracy(Monster m, Loadout l, double normal)
	{
		return alwaysMax(m, WeaponRules.classOf(l.getStyle())) || oneHit(m) || m.getId() == 5916 || wardenP2(m)
			|| m.getLowerName().contains("(100% accuracy)")
			|| phase(m, EncounterPhase.MOKHAIOTL_SHIELDED) || phase(m, EncounterPhase.MOKHAIOTL_BURROWING)
			|| phase(m, EncounterPhase.TD_DEFENCELESS)
			|| eclipseClone(m) && l.getStyle().isMelee()
			|| EncounterDamage.unshielded(m) || EncounterDamage.verzikP1(m)
			&& EncounterDamage.lower(l.getWeapon()).equals("dawnbringer") ? 1 : normal;
	}

	static boolean eclipseClone(Monster m)
	{
		// By name: the clone shares no reliable NPC id across data sources.
		return EncounterDamage.named(m, "eclipse moon") && m.getLowerName().contains("clone");
	}

	static boolean araxyteMax(Monster m, Loadout l)
	{
		if (!EncounterDamage.named(m, "acidic araxyte") && !EncounterDamage.named(m, "mirrorback araxyte"))
		{
			return false;
		}
		if (EncounterDamage.lower(l.getWeapon()).equals("noxious halberd"))
		{
			return true;
		}
		DpsCalculator.Bonuses b = DpsCalculator.Bonuses.of(l);
		return l.getStyle().getType() == AttackStyle.Type.CRUSH && b.crush > b.stab && b.crush > b.slash
			&& b.crush >= b.magic && b.crush >= b.ranged
			|| l.getStyle().getType() == AttackStyle.Type.RANGED && l.getWeapon().getSubcategory().equals("crossbow")
			&& b.ranged > b.stab && b.ranged > b.slash && b.ranged > b.crush && b.ranged > b.magic;
	}

	static boolean tormentedBonus(Monster m, Loadout l)
	{
		if (!EncounterDamage.unshielded(m))
		{
			return false;
		}
		String category = l.getWeapon().getSubcategory();
		return l.getStyle().getType() == AttackStyle.Type.CRUSH
			|| l.getStyle().getType() == AttackStyle.Type.MAGIC && l.getSpell() != null
			|| l.getStyle().getType() == AttackStyle.Type.RANGED && (category.equals("chinchompa")
			|| category.equals("crossbow") && !EncounterDamage.lower(l.getWeapon()).startsWith("karil's crossbow"));
	}
}

package com.bestgearsetup.calc;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Which defence bonus to maximise when filling slots.
 */
@Getter
@RequiredArgsConstructor
public enum DefenceFocus
{
	TARGET("Target's attacks"),
	STAB("Stab"),
	SLASH("Slash"),
	CRUSH("Crush"),
	MELEE("All melee"),
	MAGIC("Magic"),
	RANGED("Ranged"),
	TOTAL("Total");

	private final String displayName;

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.EncounterPhase;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.OffensivePrayer;
import com.bestgearsetup.data.Slot;
import com.bestgearsetup.data.StatusImmunities;

/**
 * Expected-DPS calculator following the OSRS Wiki combat formulas. Covers the common gear
 * effects (void, slayer helmet, salve, obsidian, inquisitor, crystal, dragon hunter, arclight,
 * keris, twisted bow, scythe, fang, Tumeken's shadow) and supported encounter hit caps and
 * immunities. Thralls are added separately. "Only special attacks" scores each weapon's special attack
 * instead (see {@link SpecialAttack}); specs mixed into a kill are blended by {@link SpecialRotation}.
 * Overkill is not modelled.
 */
public final class DpsCalculator
{
	private static final double SECONDS_PER_TICK = 0.6;
	/** Slot.values() copies the array on every call, and bonuses are summed for every setup scored. */
	private static final Slot[] SLOTS = Slot.values();

	private DpsCalculator()
	{
	}

	/** Gauss-Legendre nodes and weights on [0, 1]; exact for cubic 1/DPS between breakpoints. */
	private static final double[] NODES = {0.5 - Math.sqrt(0.15), 0.5, 0.5 + Math.sqrt(0.15)};
	private static final double[] WEIGHTS = {5 / 18.0, 8 / 18.0, 5 / 18.0};

	/**
	 * Expected DPS for the fight. When the attack depends on the target's remaining HP (ruby bolts,
	 * the Sun keris in ToA, Vardorvis's Defence), kill time is integrated from the selected HP down to
	 * zero, and DPS is that HP divided by the time. Accuracy and max hit describe the starting state.
	 */
	public static DpsResult calculate(Loadout loadout, CombatContext ctx)
	{
		DpsResult start = snapshot(loadout, ctx);
		if (ctx.getModifiers().isSpecialAttack())
		{
			// A special attack is one hit at the selected HP, not a whole fight.
			return start;
		}
		int startHp = ctx.getModifiers().targetHp(ctx.getMonster());
		int[] breaks = hpBreakpoints(loadout, ctx);
		if (breaks == null || start.getPrimaryDps() <= 0 || startHp <= 1)
		{
			return StatusEffects.apply(loadout, ctx, start);
		}
		double seconds = 0;
		int upper = startHp;
		for (int b = 0; b <= breaks.length; b++)
		{
			int lower = b < breaks.length ? Math.max(0, Math.min(upper, breaks[b])) : 0;
			if (upper <= lower)
			{
				continue;
			}
			for (int i = 0; i < NODES.length; i++)
			{
				// Remaining HP is at least 1 while the target is alive.
				int hp = Math.max(1, (int) Math.ceil(lower + (upper - lower) * NODES[i]));
				DpsResult at = hp == startHp ? start : snapshot(loadout, ctx.atTargetHp(hp));
				if (at.getPrimaryDps() <= 0)
				{
					return StatusEffects.apply(loadout, ctx, start);
				}
				seconds += WEIGHTS[i] * (upper - lower) / at.getPrimaryDps();
			}
			upper = lower;
		}
		return StatusEffects.apply(loadout, ctx, start.withWholeFight(startHp / seconds / start.getPrimaryDps(), startHp));
	}

	/**
	 * HP values below which the attack changes, ordered downwards, or null when it does not depend on
	 * the target's HP. An empty array still integrates smoothly varying stats.
	 */
	static int[] hpBreakpoints(Loadout l, CombatContext ctx)
	{
		Monster m = ctx.getMonster();
		if (CombatRules.oneHit(m) || m.getId() == 14779 || EncounterDamage.named(m, "gemstone crab"))
		{
			return null;
		}
		String weapon = lower(l.getWeapon());
		String ammo = lower(l.get(Slot.AMMO));
		boolean ruby = WeaponRules.classOf(l.getStyle()) == CombatClass.RANGED
			&& l.getWeapon() != null && l.getWeapon().getSubcategory().equals("crossbow")
			&& WeaponRules.firesAmmoSlot(l.getWeapon()) && ammo.startsWith("ruby ");
		boolean sun = weapon.equals("keris partisan of the sun") && l.getStyle().isMelee() && CombatRules.toa(m);
		boolean vardorvis = ctx.getHealthStates() != null && EncounterDamage.named(m, "vardorvis");
		if (!ruby && !sun && !vardorvis)
		{
			return null;
		}
		if (ruby && sun)
		{
			return new int[]{500, m.getHitpoints() / 4};
		}
		// Ruby damage stops at its cap from 500 HP; the Sun keris gains accuracy below a quarter of max HP.
		return ruby ? new int[]{500} : sun ? new int[]{m.getHitpoints() / 4} : new int[0];
	}

	static DpsResult snapshot(Loadout loadout, CombatContext ctx)
	{
		GearItem weapon = loadout.getWeapon();
		AttackStyle style = loadout.getStyle();
		if (weapon == null || style == null || !EncounterImmunities.attackAllowed(ctx.getMonster(), loadout)
			|| !AttackReach.canReach(ctx.getMonster(), weapon, style, ctx.getTargetDistance()))
		{
			return DpsResult.ZERO;
		}
		Bonuses b = Bonuses.of(loadout);
		// Special-attack mode scores only the spec, so weapons without a damaging spec deal nothing.
		SpecialAttack spec = ctx.getModifiers().isSpecialAttack() ? SpecialAttack.of(loadout, ctx) : null;
		if (ctx.getModifiers().isSpecialAttack() && spec == null)
		{
			return DpsResult.ZERO;
		}
		DpsResult r;
		switch (WeaponRules.classOf(style))
		{
			case RANGED:
				r = ranged(loadout, weapon, style, b, ctx, spec);
				break;
			case MAGIC:
				r = magic(loadout, weapon, style, b, ctx, spec);
				break;
			default:
				r = melee(loadout, weapon, style, b, ctx, spec);
				break;
		}
		if (CombatRules.oneHit(ctx.getMonster()) && r.getMaxHit() > 0)
		{
			int hp = ctx.getModifiers().targetHp(ctx.getMonster());
			int speed = EquipmentEffects.ratWeapon(weapon) ? 1 : r.getAttackSpeedTicks();
			r = result(hp, hp, 1, speed).withDetail("Target dies in one successful attack");
		}
		else if (EncounterDamage.named(ctx.getMonster(), "respiratory system") && EncounterDamage.demonbane(loadout))
		{
			int hp = ctx.getMonster().getHitpoints();
			r = result(hp * r.getAccuracy(), hp, r.getAccuracy(), r.getAttackSpeedTicks()).withDetail("Demonbane one-hit kill");
		}
		else if (CombatRules.titanElemental(ctx.getMonster()) && WeaponRules.classOf(style) == CombatClass.MAGIC)
		{
			// Royal Titans elementals: accuracy from the Magic attack bonus alone; successful hits are maximum.
			double accuracy = Math.min(1.0, Math.max(0, b.magic) / 100.0 + 0.3);
			if (hasVoid(loadout, "void mage helm"))
			{
				accuracy = Math.min(1.0, accuracy * 1.45);
			}
			r = result(r.getMaxHit() * accuracy, r.getMaxHit(), accuracy, r.getAttackSpeedTicks())
				.withDetail("Bonus-based accuracy; guaranteed maximum damage");
		}
		else if (CombatRules.alwaysMax(ctx.getMonster(), WeaponRules.classOf(style))
			|| CombatRules.araxyteMax(ctx.getMonster(), loadout))
		{
			r = result(r.getMaxHit(), r.getMaxHit(), 1, r.getAttackSpeedTicks()).withDetail("Guaranteed maximum damage");
		}
		if (CombatRules.tormentedBonus(ctx.getMonster(), loadout))
		{
			r = r.withExpectedSpeed(Math.max(1, r.getExpectedSpeedTicks() - 1));
		}
		if (SupportSpell.thrall(loadout, ctx) && r.getDps() > 0)
		{
			r = r.withExtraDps(ctx.getThrall().getDps());
		}
		return r;
	}

	// ---------------------------------------------------------------- melee

	private static DpsResult melee(Loadout l, GearItem weapon, AttackStyle style, Bonuses b, CombatContext ctx,
		SpecialAttack spec)
	{
		Monster m = ctx.getMonster();
		String stance = style.getStance();
		int attStance = stance.equals("accurate") ? 3 : stance.equals("controlled") ? 1 : 0;
		int strStance = stance.equals("aggressive") ? 3 : stance.equals("controlled") ? 1 : 0;

		OffensivePrayer prayer = ctx.getPrayer(CombatClass.MELEE);
		double pAtt = prayer == null ? 1 : 1 + prayer.getAccuracyPercent() / 100;
		double pStr = prayer == null ? 1 : 1 + prayer.getDamagePercent() / 100;

		int effAtt = (int) Math.floor(ctx.getAttack() * pAtt) + attStance + 8;
		int effStr = (int) Math.floor(ctx.getStrength() * pStr) + strStance + 8;
		String wName = lower(weapon);
		if (wName.startsWith("soulreaper axe") && spec == null)
		{
			effStr += ctx.getStrength() * Math.max(0, Math.min(5, ctx.getModifiers().getSoulreaperStacks())) * 6 / 100;
		}
		if (hasVoid(l, "void melee helm"))
		{
			effAtt = effAtt * 11 / 10;
			effStr = effStr * 11 / 10;
		}

		int attBonus;
		int defBonus;
		switch (style.getType())
		{
			case STAB:
				attBonus = b.stab;
				defBonus = m.getDefStab();
				break;
			case SLASH:
				attBonus = b.slash;
				defBonus = m.getDefSlash();
				break;
			default:
				attBonus = b.crush;
				defBonus = m.getDefCrush();
				break;
		}
		int defLevel = m.getDefenceLevel();
		if (spec != null && spec.getDefence() != null)
		{
			// Many specs roll against a fixed defence style regardless of the selected stance.
			defBonus = specDefenceBonus(m, spec.getDefence());
			if (spec.getDefence().equals("magic") && !CombatRules.defenceBasedMagic(m))
			{
				defLevel = m.getMagicLevel();
			}
		}

		long attRoll = (long) effAtt * (attBonus + 64);
		long maxHit = (effStr * (long) (b.meleeStr + 64) + 320) / 640;
		long baseMax = maxHit;
		if (named(l, Slot.AMMO, "crystal blessing"))
		{
			int pieces = (named(l, Slot.HEAD, "crystal helm") ? 1 : 0)
				+ (named(l, Slot.BODY, "crystal body") ? 3 : 0) + (named(l, Slot.LEGS, "crystal legs") ? 2 : 0);
			maxHit = frac(maxHit, 40 + pieces, 40);
		}

		// Salve and slayer helmet do not stack; salve takes priority.
		int salve = salveTier(l.get(Slot.NECK));
		if (named(l, Slot.NECK, "amulet of avarice") && m.getLowerName().startsWith("revenant"))
		{
			int avarice = ctx.getModifiers().isForinthrySurge() ? 27 : 24;
			attRoll = frac(attRoll, avarice, 20);
			maxHit = frac(maxHit, avarice, 20);
		}
		else if (m.hasAttribute("undead") && salve != SALVE_NONE)
		{
			boolean enchanted = salve == SALVE_E || salve == SALVE_EI;
			attRoll = frac(attRoll, enchanted ? 6 : 7, enchanted ? 5 : 6);
			maxHit = frac(maxHit, enchanted ? 6 : 7, enchanted ? 5 : 6);
		}
		else if (ctx.isOnTask() && isSlayerHelm(l.get(Slot.HEAD)))
		{
			attRoll = frac(attRoll, 7, 6);
			maxHit = frac(maxHit, 7, 6);
		}

		boolean tzhaar = wName.startsWith("toktz-") || wName.startsWith("tzhaar-ket-");
		if (tzhaar && named(l, Slot.HEAD, "obsidian helmet") && named(l, Slot.BODY, "obsidian platebody")
			&& named(l, Slot.LEGS, "obsidian platelegs"))
		{
			attRoll = frac(attRoll, 11, 10);
			maxHit += baseMax / 10;
		}
		if (wName.startsWith("dragon hunter lance") && m.hasAttribute("dragon"))
		{
			attRoll = frac(attRoll, 6, 5);
			maxHit = frac(maxHit, 6, 5);
		}
		if (m.hasAttribute("demon"))
		{
			int bonus = wName.startsWith("arclight") || wName.startsWith("emberlight") ? 70
				: wName.startsWith("silverlight") || wName.startsWith("darklight") ? 60
				: wName.startsWith("burning claws") || wName.startsWith("bone claws") ? 5 : 0;
			bonus = CombatRules.demonBonus(m, bonus);
			attRoll = frac(attRoll, 100 + bonus, 100);
			maxHit = frac(maxHit, 100 + bonus, 100);
		}
		if (wName.startsWith("keris") && m.hasAttribute("kalphite"))
		{
			if (wName.contains("breaching"))
			{
				attRoll = frac(attRoll, 133, 100);
			}
			maxHit = frac(maxHit, wName.contains("amascut") ? 115 : 133, 100);
		}
		if (wName.equals("keris partisan of the sun") && CombatRules.toa(m)
			&& ctx.getModifiers().targetHp(m) < m.getHitpoints() / 4)
		{
			attRoll = frac(attRoll, 5, 4);
		}
		if (EquipmentEffects.vampyre(ctx))
		{
			if (wName.startsWith("blisterwood flail") || wName.startsWith("blisterwood sickle"))
			{
				attRoll = frac(attRoll, 105, 100);
			}
			else if (wName.startsWith("hallowed flail") || wName.equals("sunspear"))
			{
				attRoll = frac(attRoll, 125, 100);
			}
			if (named(l, Slot.RING, "efaritay's aid") && EncounterImmunities.silver(l))
			{
				attRoll = frac(attRoll, 23, 20);
			}
		}
		if (wName.startsWith("dragon hunter wand") && m.hasAttribute("dragon"))
		{
			attRoll = frac(attRoll, 7, 4);
			maxHit = frac(maxHit, 7, 5);
		}
		if (EquipmentEffects.wildernessWeapon(l, ctx))
		{
			attRoll = frac(attRoll, 3, 2);
			maxHit = frac(maxHit, 3, 2);
		}
		if (wName.equals("leaf-bladed battleaxe") && (m.hasAttribute("leafy")
			|| EncounterDamage.named(m, "kurask") || EncounterDamage.named(m, "turoth")))
		{
			maxHit = frac(maxHit, 47, 40);
		}
		if (m.hasAttribute("golem") && wName.equals("barronite mace"))
		{
			maxHit = frac(maxHit, 23, 20);
		}
		if (m.hasAttribute("golem") && wName.equals("granite hammer"))
		{
			attRoll = frac(attRoll, 13, 10);
			maxHit = frac(maxHit, 13, 10);
		}
		if (wName.equals("colossal blade"))
		{
			maxHit += Math.min(10, Math.max(1, m.getSize()) * 2);
		}
		if (EquipmentEffects.ratWeapon(weapon) && m.hasAttribute("rat"))
		{
			maxHit += 10;
		}
		if (style.getType() == AttackStyle.Type.CRUSH)
		{
			int pieces = (named(l, Slot.HEAD, "inquisitor's great helm") ? 1 : 0)
				+ (named(l, Slot.BODY, "inquisitor's hauberk") ? 2 : 0)
				+ (named(l, Slot.LEGS, "inquisitor's plateskirt") ? 2 : 0);
			if (pieces > 0)
			{
				int perMille = pieces * 5;
				attRoll = frac(attRoll, 1000 + perMille, 1000);
				maxHit = frac(maxHit, 1000 + perMille, 1000);
			}
		}
		long specMin = 0;
		if (spec != null)
		{
			attRoll = spec.scaleAccuracy(attRoll);
			specMin = spec.minimum(maxHit);
			maxHit = spec.scaleMax(maxHit);
			switch (spec.getKind())
			{
				case VOIDWAKER:
					specMin = maxHit / 2;
					maxHit += specMin;
					break;
				case BLOOD_MOON:
					specMin = maxHit / 4;
					maxHit += specMin;
					break;
				case SOULREAPER:
				{
					int stacks = Math.max(0, Math.min(5, ctx.getModifiers().getSoulreaperStacks()));
					specMin = maxHit * 6 * stacks / 100;
					maxHit = maxHit * (100 + 6 * stacks) / 100;
					break;
				}
				case FANG:
					specMin = maxHit * 3 / 20;
					break;
				default:
					break;
			}
		}

		if (maxHit <= 0)
		{
			return DpsResult.ZERO;
		}
		long defRoll = CombatRules.defenceRoll(m, defLevel, defBonus);
		boolean fang = wName.startsWith("osmumten's fang");
		double accuracy = HitChance.single(attRoll, defRoll);
		if (fang && style.getType() == AttackStyle.Type.STAB)
		{
			accuracy = CombatRules.toa(m) ? 1 - (1 - accuracy) * (1 - accuracy) : HitChance.twoAttackRolls(attRoll, defRoll);
		}
		accuracy = CombatRules.accuracy(m, l, accuracy);
		int speed = weapon.getAttackSpeed();
		EncounterDamage.Rule rule = EncounterDamage.rule(m, l);
		long minimum = EncounterDamage.named(m, "respiratory system") ? maxHit / 2 : 0;
		if (spec != null)
		{
			return SpecialDamage.melee(spec, l, ctx, rule, spec.isGuaranteed() ? 1 : accuracy, minimum + specMin, maxHit,
				attRoll, defRoll, speed);
		}

		double avgDamage;
		int displayMax = (int) maxHit;
		String detail = null;
		boolean scythe = wName.contains("scythe of vitur");
		if (scythe)
		{
			// Up to three hits at 100%, 50% and 25% damage depending on target size.
			int hits = m.getSize() >= 3 ? 3 : m.getSize() == 2 ? 2 : 1;
			avgDamage = 0;
			displayMax = 0;
			StringBuilder sb = new StringBuilder();
			for (int i = 0; i < hits; i++)
			{
				avgDamage += accuracy * EquipmentEffects.average(rule, l, ctx, i == 0 ? minimum : 0, maxHit >> i)
					+ (1 - accuracy) * rule.missDamage();
				int hitMax = EquipmentEffects.maximum(rule, l, ctx, maxHit >> i);
				displayMax += hitMax;
				sb.append(i == 0 ? "" : " + ").append(hitMax);
			}
			detail = hits > 1 ? sb.toString() : null;
		}
		else
		{
			avgDamage = accuracy * EquipmentEffects.average(rule, l, ctx, minimum, maxHit) + (1 - accuracy) * rule.missDamage();
			displayMax = EquipmentEffects.maximum(rule, l, ctx, maxHit);
			if (fang)
			{
				// Rolls between 15% and 85% of the max hit: same mean, lower max.
				displayMax = (int) (maxHit - maxHit * 15 / 100);
				detail = (maxHit * 15 / 100) + "-" + displayMax;
				long fangMin = maxHit * 15 / 100 + (minimum > 0 ? displayMax / 2 : 0);
				avgDamage = accuracy * EquipmentEffects.average(rule, l, ctx, fangMin, displayMax);
				displayMax = EquipmentEffects.maximum(rule, l, ctx, displayMax);
			}
		}
		if (EquipmentEffects.twoHit(weapon) || wName.equals("dual macuahuitl"))
		{
			long first = maxHit / 2;
			long second = maxHit - first;
			double secondAccuracy = wName.equals("dual macuahuitl") ? accuracy * accuracy : accuracy;
			avgDamage = accuracy * EquipmentEffects.average(rule, l, ctx, 0, first)
				+ (1 - accuracy) * rule.missDamage() + secondAccuracy * EquipmentEffects.average(rule, l, ctx, 0, second)
				+ (1 - secondAccuracy) * rule.missDamage();
			displayMax = EquipmentEffects.maximum(rule, l, ctx, first) + EquipmentEffects.maximum(rule, l, ctx, second);
			detail = EquipmentEffects.maximum(rule, l, ctx, first) + " + " + EquipmentEffects.maximum(rule, l, ctx, second);
		}
		if (wName.startsWith("keris") && m.hasAttribute("kalphite"))
		{
			avgDamage = (50 * avgDamage + accuracy * HitDamage.average(rule, 0, maxHit,
				h -> EquipmentEffects.damage(l, ctx, h * 3))) / 51;
			displayMax = EquipmentEffects.maximum(rule, l, ctx, maxHit * 3);
			detail = "1/51 triple-damage roll";
		}
		if (wName.equals("gadderhammer") && m.hasAttribute("shade"))
		{
			avgDamage = accuracy * (0.95 * HitDamage.average(rule, 0, maxHit,
				h -> EquipmentEffects.damage(l, ctx, h * 5 / 4)) + 0.05 * HitDamage.average(rule, 0, maxHit,
				h -> EquipmentEffects.damage(l, ctx, h * 2)));
			displayMax = EquipmentEffects.maximum(rule, l, ctx, maxHit * 2);
		}
		if (EquipmentEffects.verac(l))
		{
			avgDamage = 0.75 * avgDamage + 0.25 * EquipmentEffects.average(rule, l, ctx, 1, maxHit + 1);
			displayMax = EquipmentEffects.maximum(rule, l, ctx, maxHit + 1);
			accuracy = 0.75 * accuracy + 0.25;
			detail = "25% defence-bypassing roll";
		}
		if (rule.detail != null)
		{
			detail = (detail == null ? "" : detail + "; ") + rule.detail;
		}
		DpsResult r = result(avgDamage, displayMax, accuracy, speed).withDetail(detail);
		if (EquipmentEffects.bloodMoon(l))
		{
			// Bloodrager rolls 0..99 and triggers at <=32: exactly 33%, not one third.
			// The second hit requires the first to land; either proc saves only one tick.
			double procChance = 0.33 * accuracy + 0.33 * 0.67 * accuracy * accuracy;
			r = r.withExpectedSpeed(speed - procChance);
		}
		if (wName.equals("hallowfell") && ctx.getAoeTargets() > 1 && r.getDps() > 0)
		{
			// Two distinct secondary enemies, each at half max; no repeated hits on large enemies.
			int targets = Math.min(3, ctx.getAoeTargets());
			double cleave = accuracy * EquipmentEffects.average(rule, l, ctx, 0, maxHit / 2);
			r = r.withAreaDamage(cleave * (targets - 1), 0, targets);
		}
		else if (scythe && ctx.getAoeTargets() > 1 && r.getDps() > 0)
		{
			int primaryHits = Math.max(1, Math.min(3, m.getSize()));
			int extraTargets = Math.min(ctx.getAoeTargets() - 1, 3 - primaryHits);
			double extra = 0;
			for (int i = primaryHits; i < primaryHits + extraTargets; i++)
			{
				extra += accuracy * EquipmentEffects.average(rule, l, ctx, 0, maxHit >> i);
			}
			if (extraTargets > 0)
			{
				r = r.withAreaDamage(extra, 0, 1 + extraTargets);
			}
		}
		return r;
	}

	// ---------------------------------------------------------------- ranged

	private static DpsResult ranged(Loadout l, GearItem weapon, AttackStyle style, Bonuses b, CombatContext ctx,
		SpecialAttack spec)
	{
		Monster m = ctx.getMonster();
		String stance = style.getStance();
		int stanceBonus = stance.equals("accurate") ? 3 : 0;

		OffensivePrayer prayer = ctx.getPrayer(CombatClass.RANGED);
		double pAcc = prayer == null ? 1 : 1 + prayer.getAccuracyPercent() / 100;
		double pDmg = prayer == null ? 1 : 1 + prayer.getDamagePercent() / 100;

		// The eclipse atlatl and Hunter's spear hit with the (visible, potion-boosted) Strength level and melee strength bonus;
		// ranged prayers and the void ranger helm still boost it. Accuracy is ordinary ranged accuracy.
		boolean atlatl = WeaponRules.scalesWithStrength(weapon);
		int effAcc = (int) Math.floor(ctx.getRanged() * pAcc) + stanceBonus + 8;
		int effStr = (int) Math.floor((atlatl ? ctx.getStrength() : ctx.getRanged()) * pDmg) + stanceBonus + 8;
		if (hasVoid(l, "void ranger helm"))
		{
			effAcc = effAcc * 11 / 10;
			effStr = isEliteVoid(l) ? effStr * 1125 / 1000 : effStr * 11 / 10;
		}

		long attRoll = (long) effAcc * (b.ranged + 64);
		long maxHit = (effStr * (long) ((atlatl ? b.meleeStr : b.rangedStr) + 64) + 320) / 640;
		String wName = lower(weapon);
		boolean crystal = wName.startsWith("bow of faerdhinen") || wName.startsWith("crystal bow")
			&& !wName.contains("basic") && !wName.contains("attuned") && !wName.contains("perfected");
		if (crystal)
		{
			int pieces = (named(l, Slot.HEAD, "crystal helm") ? 1 : 0)
				+ (named(l, Slot.BODY, "crystal body") ? 3 : 0) + (named(l, Slot.LEGS, "crystal legs") ? 2 : 0);
			attRoll = frac(attRoll, 100 + pieces * 5, 100);
			maxHit = frac(maxHit, 1000 + pieces * 25, 1000);
		}
		boolean taskDamage = false;

		int salve = salveTier(l.get(Slot.NECK));
		boolean avarice = named(l, Slot.NECK, "amulet of avarice")
			&& m.getLowerName().startsWith("revenant");
		int avariceFactor = ctx.getModifiers().isForinthrySurge() ? 27 : 24;
		if (avarice)
		{
			attRoll = frac(attRoll, avariceFactor, 20);
		}
		else if (m.hasAttribute("undead") && (salve == SALVE_I || salve == SALVE_EI))
		{
			attRoll = frac(attRoll, salve == SALVE_EI ? 6 : 7, salve == SALVE_EI ? 5 : 6);
		}
		else if (ctx.isOnTask() && isImbuedSlayerHelm(l.get(Slot.HEAD)))
		{
			attRoll = frac(attRoll, 23, 20);
		}
		if (avarice)
		{
			maxHit = frac(maxHit, avariceFactor, 20);
		}
		else if (m.hasAttribute("undead") && (salve == SALVE_I || salve == SALVE_EI || atlatl && salve != SALVE_NONE))
		{
			boolean enchanted = salve == SALVE_E || salve == SALVE_EI;
			maxHit = frac(maxHit, enchanted ? 6 : 7, enchanted ? 5 : 6);
		}
		else if (ctx.isOnTask() && (atlatl ? isSlayerHelm(l.get(Slot.HEAD)) : isImbuedSlayerHelm(l.get(Slot.HEAD))))
		{
			if (atlatl)
			{
				maxHit = frac(maxHit, 7, 6);
			}
			else
			{
				taskDamage = true;
			}
		}
		if (wName.startsWith("twisted bow"))
		{
			if (taskDamage)
			{
				maxHit = frac(maxHit, 23, 20);
				taskDamage = false;
			}
			int magic = Math.min(m.hasAttribute("xerician") ? 350 : 250,
				Math.max(m.getMagicLevel(), m.getMagicAttackBonus()));
			int t = 3 * magic / 10;
			int accPct = Math.max(0, Math.min(140, 140 + (3 * magic - 10) / 100 - (t - 100) * (t - 100) / 100));
			int dmgPct = Math.max(0, Math.min(250, 250 + (3 * magic - 14) / 100 - (t - 140) * (t - 140) / 100));
			attRoll = frac(attRoll, accPct, 100);
			if (CombatRules.wardenP2(m))
			{
				attRoll = frac(attRoll, accPct, 100);
			}
			maxHit = frac(maxHit, dmgPct, 100);
		}
		int extraDamage = taskDamage ? 15 : 0;
		if (wName.startsWith("dragon hunter crossbow") && m.hasAttribute("dragon"))
		{
			attRoll = frac(attRoll, 13, 10);
			extraDamage += 25;
		}
		if (wName.startsWith("scorching bow") && m.hasAttribute("demon"))
		{
			int bonus = CombatRules.demonBonus(m, 30);
			attRoll = frac(attRoll, 100 + bonus, 100);
			extraDamage += bonus;
		}
		if (EquipmentEffects.wildernessWeapon(l, ctx))
		{
			attRoll = frac(attRoll, 3, 2);
			extraDamage += 50;
		}
		maxHit = frac(maxHit, 100 + extraDamage, 100);
		if (wName.equals("ogre bow") || wName.equals("comp ogre bow"))
		{
			GearItem ammo = l.get(Slot.AMMO);
			maxHit = ((ctx.getRanged() + 10L) * (64 + (ammo == null ? 0 : ammo.getRangedStr())) + 320) / 640;
		}
		if (wName.equals("holy water"))
		{
			maxHit = ((ctx.getRanged() + 10L) * (64 + weapon.getRangedStr()) + 320) / 640;
			maxHit = frac(maxHit, 100 + CombatRules.demonBonus(m, 60), 100);
			if (EncounterDamage.named(m, "nezikchened"))
			{
				maxHit += 5;
			}
		}
		if (EquipmentEffects.ratWeapon(weapon) && m.hasAttribute("rat"))
		{
			maxHit += 10;
		}
		if (wName.startsWith("tonalztics of ralos"))
		{
			maxHit = frac(maxHit, 3, 4);
		}
		long specMin = 0;
		if (spec != null)
		{
			switch (spec.getKind())
			{
				case ARROW_FORMULA:
					// The bows' specials ignore every other damage bonus.
					maxHit = SpecialDamage.arrowFormula(l, ctx);
					break;
				case WEBWEAVER:
					maxHit -= maxHit * 6 / 10;
					break;
				case DARK_BOW:
				{
					boolean dragonArrows = lower(l.get(Slot.AMMO)).startsWith("dragon arrow");
					specMin = dragonArrows ? 8 : 5;
					maxHit = maxHit * (dragonArrows ? 15 : 13) / 10;
					break;
				}
				default:
					specMin = spec.minimum(maxHit);
					maxHit = spec.scaleMax(maxHit);
					break;
			}
		}

		int defBonus;
		String sub = weapon.getSubcategory();
		if (sub.equals("salamander"))
		{
			defBonus = (m.getDefLightOrStandard() + m.getDefRanged() + m.getDefHeavyOrStandard()) / 3;
		}
		else if (sub.equals("crossbow") && !wName.startsWith("karil's crossbow"))
		{
			defBonus = m.getDefHeavyOrStandard();
		}
		else if (sub.equals("chinchompa"))
		{
			defBonus = m.getDefHeavyOrStandard();
			int distance = AttackReach.distance(m, ctx.getTargetDistance());
			int band = distance <= 3 ? 0 : distance <= 6 ? 1 : 2;
			int preferred = stance.equals("accurate") ? 0 : stance.equals("rapid") ? 1 : 2;
			int percent = preferred == band ? 100 : preferred == 1 || band == 1 ? 75 : 50;
			attRoll = frac(attRoll, percent, 100);
		}
		else if (sub.equals("thrown"))
		{
			defBonus = m.getDefLightOrStandard();
		}
		else
		{
			defBonus = m.getDefRanged();
		}
		if (spec != null)
		{
			attRoll = spec.scaleAccuracy(attRoll);
		}
		if (maxHit <= 0)
		{
			return DpsResult.ZERO;
		}
		if (CombatRules.phase(m, EncounterPhase.ROYAL_TITANS_OUT_OF_MELEE))
		{
			// Ranged attacks are six times as accurate while the titan is out of melee range.
			attRoll *= 6;
		}
		long defRoll = CombatRules.defenceRoll(m, m.getDefenceLevel(), defBonus);
		double accuracy = HitChance.single(attRoll, defRoll);
		accuracy = CombatRules.accuracy(m, l, accuracy);
		int speed = weapon.getAttackSpeed() - (stance.equals("rapid") ? 1 : 0);
		long[] bounds = CombatRules.bounds(m, attRoll, defRoll, maxHit);
		long minimum = bounds[0];
		maxHit = bounds[1];
		EncounterDamage.Rule rule = EncounterDamage.rule(m, l);
		if (spec != null)
		{
			return SpecialDamage.ranged(spec, l, ctx, rule, spec.isGuaranteed() ? 1 : accuracy,
				Math.max(minimum, specMin), maxHit, attRoll, defBonus, speed);
		}
		double avgDamage = accuracy * EquipmentEffects.average(rule, l, ctx, minimum, maxHit);
		long rawMax = maxHit;
		maxHit = EquipmentEffects.maximum(rule, l, ctx, maxHit);
		String detail = rule.detail;
		if (wName.startsWith("dark bow") || wName.startsWith("tonalztics of ralos") && !wName.contains("uncharged"))
		{
			avgDamage *= 2;
			detail = maxHit + " + " + maxHit + (detail == null ? "" : "; " + detail);
			maxHit *= 2;
		}
		if (EquipmentEffects.karil(l))
		{
			avgDamage += accuracy * 0.25 * HitDamage.average(rule, 0, rawMax, h -> h / 2);
			maxHit += rule.maximum(rawMax / 2);
			detail = "25% second hitsplat at half the first damage";
		}
		if (sub.equals("crossbow") && WeaponRules.firesAmmoSlot(weapon))
		{
			EnchantedBolts.Result bolts = EnchantedBolts.calculate(l, ctx, rule, accuracy, minimum, rawMax);
			if (bolts != null)
			{
				avgDamage = bolts.getAverage();
				maxHit = bolts.getMaximum();
				accuracy = bolts.getAccuracy();
				detail = bolts.getDetail() + (detail == null ? "" : "; " + detail);
			}
		}
		DpsResult r = result(avgDamage, (int) maxHit, accuracy, speed).withDetail(detail);
		if (ctx.getAoeTargets() > 1 && r.getDps() > 0)
		{
			if (sub.equals("chinchompa"))
			{
				int targets = Math.min(wName.startsWith("black chinchompa") ? 12 : 11, ctx.getAoeTargets());
				r = r.withAreaDamage(avgDamage * (targets - 1), 0, targets);
			}
			else if (wName.startsWith("venator bow") && !wName.contains("uncharged"))
			{
				double bounce = accuracy * EquipmentEffects.average(rule, l, ctx, 0, rawMax * 2 / 3);
				int targets = Math.min(3, ctx.getAoeTargets());
				r = r.withAreaDamage(2 * bounce, targets == 2 ? bounce : 0, targets,
					targets == 2 ? rule.maximum(rawMax * 2 / 3) : 0);
			}
		}
		return r;
	}

	// ---------------------------------------------------------------- magic

	private static DpsResult magic(Loadout l, GearItem weapon, AttackStyle style, Bonuses b, CombatContext ctx,
		SpecialAttack spec)
	{
		Monster m = ctx.getMonster();
		if (spec != null && style.isAutocast() && SpecialDamage.builtInSpell(weapon))
		{
			// These staves' specials cast their own built-in spell, as a powered staff on its accurate stance.
			l = l.copy();
			l.setSpell(null);
			l.setStyle(AttackStyle.parse("accurate,magic,accurate"));
			style = l.getStyle();
		}
		int baseMax;
		int speed;
		int stanceBonus;
		if (weapon.getSubcategory().equals("salamander"))
		{
			baseMax = WeaponRules.salamanderMaxHit(weapon, ctx.getMagic());
			speed = weapon.getAttackSpeed();
			stanceBonus = 0;
		}
		else if (style.isAutocast())
		{
			if (l.getSpell() == null)
			{
				return DpsResult.ZERO;
			}
			baseMax = SpellRules.maxHit(l, ctx);
			speed = l.getSpell().getAttackSpeed();
			if (lower(weapon).startsWith("harmonised nightmare staff")
				&& "standard".equalsIgnoreCase(l.getSpell().getSpellbook()))
			{
				speed = 4;
			}
			if (lower(weapon).startsWith("twinflame staff"))
			{
				speed = 6;
			}
			stanceBonus = 0;
		}
		else
		{
			baseMax = spec != null ? SpecialDamage.builtInMax(weapon, ctx.getMagic())
				: WeaponRules.poweredStaffMaxHit(weapon, ctx.getMagic());
			if (baseMax <= 0)
			{
				return DpsResult.ZERO;
			}
			speed = weapon.getAttackSpeed();
			stanceBonus = style.getStance().equals("accurate") ? 2 : 0;
		}
		String wName = lower(weapon);
		if (spec != null && spec.getName().equals("Eye of Ayak"))
		{
			// Eye of Ayak's special raises the base damage and attacks every five ticks.
			baseMax = (int) spec.scaleMax(baseMax);
			speed = 5;
		}
		String spell = EncounterDamage.spell(l);
		String element = SpellRules.element(l.getSpell());
		boolean standard = l.getSpell() != null && "standard".equalsIgnoreCase(l.getSpell().getSpellbook());
		boolean ancient = l.getSpell() != null && "ancient".equalsIgnoreCase(l.getSpell().getSpellbook());
		if (standard && spell.endsWith(" bolt") && named(l, Slot.HANDS, "chaos gauntlets"))
		{
			baseMax += 3;
		}
		if (!element.isEmpty() && (named(l, Slot.NECK, "elemental amulet") || named(l, Slot.NECK, "amulet of " + element)))
		{
			baseMax += 2;
		}
		if (SupportSpell.charge(l, ctx))
		{
			baseMax += 10;
		}

		OffensivePrayer prayer = ctx.getPrayer(CombatClass.MAGIC);
		double pAcc = prayer == null ? 1 : 1 + prayer.getAccuracyPercent() / 100;
		double dmgPct = prayer == null ? 0 : prayer.getDamagePercent();

		int effMagic = (int) Math.floor(ctx.getMagic() * pAcc) + stanceBonus + 9;
		boolean voidMage = hasVoid(l, "void mage helm");
		if (voidMage)
		{
			effMagic = effMagic * 29 / 20;
			if (isEliteVoid(l))
			{
				dmgPct += 5;
			}
		}

		int magicBonus = b.magic;
		double gearDmg = b.magicStr;
		if (ancient)
		{
			gearDmg += (named(l, Slot.HEAD, "virtus mask") ? 3 : 0)
				+ (named(l, Slot.BODY, "virtus robe top") ? 3 : 0) + (named(l, Slot.LEGS, "virtus robe bottom") ? 3 : 0);
		}
		if (WeaponRules.isShadow(weapon) && !style.isAutocast())
		{
			int factor = CombatRules.toa(m) ? 4 : 3;
			magicBonus *= factor;
			gearDmg = Math.min(100, gearDmg * factor);
		}
		dmgPct += gearDmg;

		long attRoll = (long) effMagic * (magicBonus + 64);
		long baseRoll = attRoll;
		int additiveAccuracy = 0;
		boolean smoke = standard && (wName.startsWith("smoke battlestaff") || wName.startsWith("mystic smoke staff"));
		if (smoke)
		{
			dmgPct += 10;
			additiveAccuracy += 10;
		}
		boolean task = false;

		int salve = salveTier(l.get(Slot.NECK));
		if (m.hasAttribute("undead") && (salve == SALVE_I || salve == SALVE_EI))
		{
			int bonus = salve == SALVE_EI ? 20 : 15;
			additiveAccuracy += bonus;
			dmgPct += bonus;
		}
		else if (named(l, Slot.NECK, "amulet of avarice") && m.getLowerName().startsWith("revenant"))
		{
			int bonus = ctx.getModifiers().isForinthrySurge() ? 35 : 20;
			additiveAccuracy += bonus;
			dmgPct += bonus;
		}
		else if (ctx.isOnTask() && isImbuedSlayerHelm(l.get(Slot.HEAD)))
		{
			task = true;
		}
		if (EquipmentEffects.vampyre(ctx) && named(l, Slot.RING, "efaritay's aid") && EncounterImmunities.silver(l))
		{
			additiveAccuracy += 15;
		}
		attRoll = frac(attRoll, 100 + additiveAccuracy, 100);
		long maxHit = (long) Math.floor(baseMax * (1 + dmgPct / 100));
		if (task)
		{
			attRoll = frac(attRoll, 23, 20);
			maxHit = frac(maxHit, 23, 20);
		}
		if (m.hasAttribute("dragon") && wName.startsWith("dragon hunter wand"))
		{
			attRoll = frac(attRoll, 7, 4);
			maxHit = frac(maxHit, 7, 5);
		}
		boolean demonbane = SupportSpell.demonbane(l, ctx);
		if (demonbane)
		{
			int bonus = ctx.getModifiers().isMarkOfDarkness() ? 40 : 20;
			if (wName.startsWith("purging staff"))
			{
				bonus *= 2;
			}
			attRoll = frac(attRoll, 100 + CombatRules.demonBonus(m, bonus), 100);
		}
		if (EquipmentEffects.wildernessWeapon(l, ctx))
		{
			attRoll = frac(attRoll, 3, 2);
			maxHit = frac(maxHit, 3, 2);
		}
		if (standard && named(l, Slot.SHIELD, "tome of water")
			&& !lower(l.get(Slot.SHIELD)).contains("empty") && element.equals("water"))
		{
			attRoll = frac(attRoll, 6, 5);
		}
		if (spec != null)
		{
			attRoll = spec.scaleAccuracy(attRoll);
			if (!spec.getName().equals("Eye of Ayak"))
			{
				maxHit = spec.scaleMax(maxHit);
			}
		}
		if (!element.isEmpty() && element.equalsIgnoreCase(m.getWeaknessType()))
		{
			attRoll += frac(baseRoll, Math.max(0, m.getWeakness()), 100);
			maxHit += frac(baseMax, Math.max(0, m.getWeakness()), 100);
		}
		long minimum = ctx.getModifiers().isSunfireRunes() && element.equals("fire") ? maxHit / 10 : 0;
		String shield = lower(l.get(Slot.SHIELD));
		if (standard && !shield.contains("empty") && !shield.contains("uncharged")
			&& (shield.startsWith("tome of fire") && element.equals("fire")
			|| shield.startsWith("tome of water") && element.equals("water")
			|| shield.startsWith("tome of earth") && element.equals("earth")))
		{
			maxHit = frac(maxHit, 11, 10);
			minimum = frac(minimum, 11, 10);
		}
		if (wName.equals("dawnbringer"))
		{
			maxHit = Math.max(2, maxHit / 2);
		}
		int defenceLevel = CombatRules.defenceBasedMagic(m) ? m.getDefenceLevel() : m.getMagicLevel();
		if (maxHit <= 0)
		{
			return DpsResult.ZERO;
		}
		long defRoll = CombatRules.defenceRoll(m, defenceLevel, m.getDefMagic());
		boolean confliction = named(l, Slot.HANDS, "confliction gauntlets") && !weapon.isTwoHanded();
		double accuracy = magicAccuracy(attRoll, defRoll, confliction);
		if (named(l, Slot.RING, "brimstone ring"))
		{
			accuracy = 0.75 * accuracy + 0.25 * magicAccuracy(attRoll, defRoll * 9 / 10, confliction);
		}
		if (wName.startsWith("ice ancient sceptre") && spell.startsWith("ice "))
		{
			accuracy = iceSceptreAccuracy(m, l, attRoll, defRoll, confliction, accuracy, spell, speed);
		}
		accuracy = CombatRules.accuracy(m, l, accuracy);
		long[] bounds = CombatRules.bounds(m, attRoll, defRoll, maxHit);
		if (CombatRules.wardenP2(m) || EncounterDamage.named(m, "respiratory system"))
		{
			minimum = bounds[0];
			maxHit = bounds[1];
		}
		EncounterDamage.Rule rule = EncounterDamage.rule(m, l);
		if (spec != null)
		{
			boolean dawnbringer = spec.getKind() == SpecialAttack.Kind.DAWNBRINGER;
			// Dawnbringer's special always hits for 75-150, ignoring bonuses.
			long low = dawnbringer ? 75 : minimum;
			long high = dawnbringer ? 150 : maxHit;
			double hit = spec.isGuaranteed() ? 1 : accuracy;
			return result(hit * EquipmentEffects.average(rule, l, ctx, low, high) + (1 - hit) * rule.missDamage(),
				EquipmentEffects.maximum(rule, l, ctx, high), hit, speed)
				.withDetail(spec.describe() + (rule.detail == null ? "" : "; " + rule.detail));
		}
		double average = accuracy * EquipmentEffects.average(rule, l, ctx, minimum, maxHit);
		int displayMax = EquipmentEffects.maximum(rule, l, ctx, maxHit);
		if (wName.startsWith("sanguinesti staff") || wName.startsWith("holy sanguinesti staff"))
		{
			average = 0.8 * average + 0.2 * accuracy * HitDamage.average(rule, minimum, maxHit, h -> h + 8);
			displayMax = rule.maximum(maxHit + 8);
		}
		if (EquipmentEffects.ahrim(l))
		{
			average = 0.75 * average + 0.25 * accuracy * HitDamage.average(rule, minimum, maxHit, h -> h * 13 / 10);
			displayMax = rule.maximum(maxHit * 13 / 10);
		}
		if (SupportSpell.markOfDarkness(l, ctx))
		{
			int percent = wName.startsWith("purging staff") ? 50 : 25;
			average = accuracy * HitDamage.average(rule, minimum, maxHit,
				h -> h + h * percent / 100 * CombatRules.demonVulnerability(m) / 100);
			displayMax = rule.maximum(maxHit + maxHit * percent / 100 * CombatRules.demonVulnerability(m) / 100);
		}
		if (wName.startsWith("twinflame staff") && standard
			&& (spell.endsWith(" bolt") || spell.endsWith(" blast") || spell.endsWith(" wave")))
		{
			average += accuracy * HitDamage.averageTransformed(rule, minimum, maxHit, h -> Math.max(1, h) * 4 / 10);
			displayMax += rule.maximum(maxHit * 4 / 10);
		}
		DpsResult r = result(average, displayMax, accuracy, speed).withDetail(rule.detail);
		if (style.isAutocast() && l.getSpell() != null && "ancient".equalsIgnoreCase(l.getSpell().getSpellbook())
			&& (spell.endsWith(" burst") || spell.endsWith(" barrage")) && ctx.getAoeTargets() > 1 && r.getDps() > 0)
		{
			int targets = Math.min(9, ctx.getAoeTargets());
			r = r.withAreaDamage(average * (targets - 1), 0, targets);
		}
		return r;
	}

	// ---------------------------------------------------------------- helpers

	/**
	 * Ice ancient sceptre: ice spells gain 10% accuracy against freezable targets that are not frozen.
	 * A landed cast freezes for the spell's duration (+10% from the sceptre, less any freeze resistance),
	 * then five ticks of immunity; casts in that window get no bonus, and every cast after it does until
	 * one lands. Returns the mean accuracy over that cycle.
	 */
	private static double iceSceptreAccuracy(Monster m, Loadout l, long attRoll, long defRoll, boolean confliction,
		double accuracy, String spell, int speed)
	{
		StatusImmunities.Immunity immunity = StatusImmunities.of(m);
		int resistance = immunity.getFreezeResistance();
		boolean freezable = resistance >= 0 ? resistance < 100 : !m.hasAttribute("boss");
		if (!freezable)
		{
			return accuracy;
		}
		double bonus = magicAccuracy(attRoll * 11 / 10, defRoll, confliction);
		if (named(l, Slot.RING, "brimstone ring"))
		{
			bonus = 0.75 * bonus + 0.25 * magicAccuracy(attRoll * 11 / 10, defRoll * 9 / 10, confliction);
		}
		if (bonus <= 0)
		{
			return accuracy;
		}
		int freeze = spell.endsWith("rush") ? 8 : spell.endsWith("burst") ? 17 : spell.endsWith("blitz") ? 26 : 35;
		freeze = freeze * (100 - Math.max(0, resistance)) / 100;
		int unbonused = Math.max(0, (int) Math.ceil((freeze + 5.0) / speed) - 1);
		double bonusCasts = 1 / bonus;
		double share = bonusCasts / (bonusCasts + unbonused);
		return share * bonus + (1 - share) * accuracy;
	}

	private static int specDefenceBonus(Monster m, String defence)
	{
		switch (defence)
		{
			case "stab":
				return m.getDefStab();
			case "slash":
				return m.getDefSlash();
			case "crush":
				return m.getDefCrush();
			case "ranged":
				return m.getDefRanged();
			default:
				return m.getDefMagic();
		}
	}

	/** Magic accuracy; with one-handed confliction gauntlets, the attack after a miss rolls accuracy twice. */
	private static double magicAccuracy(long attack, long defence, boolean confliction)
	{
		double single = HitChance.single(attack, defence);
		return confliction ? HitChance.withRetryAfterMiss(single, HitChance.twoAttackRolls(attack, defence)) : single;
	}

	static DpsResult result(double avgDamage, int maxHit, double accuracy, int speed)
	{
		if (speed <= 0 || maxHit <= 0)
		{
			return new DpsResult(0, Math.max(0, maxHit), accuracy, speed, 0, null);
		}
		return new DpsResult(avgDamage / (speed * SECONDS_PER_TICK), maxHit, accuracy, speed, avgDamage, null);
	}

	private static long frac(long value, long num, long den)
	{
		return value * num / den;
	}

	private static final int SALVE_NONE = 0;
	private static final int SALVE = 1;
	private static final int SALVE_I = 2;
	private static final int SALVE_E = 3;
	private static final int SALVE_EI = 4;

	private static int salveTier(GearItem neck)
	{
		String n = lower(neck);
		if (!n.startsWith("salve amulet"))
		{
			return SALVE_NONE;
		}
		String rest = n.substring("salve amulet".length()).replace(" ", "");
		switch (rest)
		{
			case "(ei)":
				return SALVE_EI;
			case "(e)":
				return SALVE_E;
			case "(i)":
				return SALVE_I;
			default:
				return SALVE;
		}
	}

	static boolean isSlayerHelm(GearItem head)
	{
		String n = lower(head);
		return n.startsWith("slayer helmet") || n.startsWith("black mask")
			|| (n.endsWith("slayer helmet") || n.endsWith("slayer helmet (i)"));
	}

	static boolean isImbuedSlayerHelm(GearItem head)
	{
		return isSlayerHelm(head) && lower(head).contains("(i)");
	}

	private static boolean hasVoid(Loadout l, String helm)
	{
		String body = lower(l.get(Slot.BODY));
		String legs = lower(l.get(Slot.LEGS));
		return named(l, Slot.HEAD, helm)
			&& lower(l.get(Slot.HANDS)).startsWith("void knight gloves")
			&& (body.startsWith("void knight top") || body.startsWith("elite void top"))
			&& (legs.startsWith("void knight robe") || legs.startsWith("elite void robe"));
	}

	private static boolean isEliteVoid(Loadout l)
	{
		return lower(l.get(Slot.BODY)).startsWith("elite void top") && lower(l.get(Slot.LEGS)).startsWith("elite void robe");
	}

	private static boolean named(Loadout l, Slot slot, String prefix)
	{
		return EquipmentEffects.named(l, slot, prefix);
	}

	private static String lower(GearItem item)
	{
		return EncounterDamage.lower(item);
	}

	/**
	 * Summed equipment bonuses. Ranged stats of the ammo slot only count when the weapon fires it.
	 */
	static final class Bonuses
	{
		private static final java.util.Set<String> QUIVERS = new java.util.HashSet<>(java.util.Arrays.asList(
			"dizana's quiver", "blessed dizana's quiver", "dizana's max cape"));

		int stab;
		int slash;
		int crush;
		int ranged;
		int magic;
		int meleeStr;
		int rangedStr;
		double magicStr;

		static Bonuses of(Loadout l)
		{
			Bonuses b = new Bonuses();
			GearItem weapon = l.getWeapon();
			boolean firesAmmo = WeaponRules.firesAmmoSlot(weapon);
			for (Slot slot : SLOTS)
			{
				GearItem item = l.get(slot);
				if (item == null)
				{
					continue;
				}
				b.stab += item.getStabBonus();
				b.slash += item.getSlashBonus();
				b.crush += item.getCrushBonus();
				b.magic += item.getMagicBonus();
				b.meleeStr += item.getMeleeStr();
				b.magicStr += item.getMagicStr();
				if (slot != Slot.AMMO || firesAmmo)
				{
					b.ranged += item.getRangedBonus();
					b.rangedStr += item.getRangedStr();
				}
			}
			GearItem loaded = l.getLoadedAmmo();
			if (loaded != null && WeaponRules.loadsAmmo(weapon))
			{
				b.rangedStr += loaded.getRangedStr();
			}
			// A charged Dizana's quiver adds +10 ranged accuracy and +1 ranged strength to fired arrows and bolts.
			GearItem ammo = l.get(Slot.AMMO);
			if (firesAmmo && ammo != null && weapon.getAmmunition().contains(ammo.getId())
				&& QUIVERS.contains(lower(l.get(Slot.CAPE))))
			{
				b.ranged += 10;
				b.rangedStr += 1;
			}
			if (lower(weapon).contains("bulwark"))
			{
				int defence = 0;
				for (Slot slot : SLOTS)
				{
					GearItem item = l.get(slot);
					if (item != null)
					{
						defence += item.getStabDef() + item.getSlashDef() + item.getCrushDef() + item.getRangedDef();
					}
				}
				b.meleeStr += Math.max(0, (defence - 800) / 12 - 38);
			}
			return b;
		}
	}
}

package com.bestgearsetup.calc;

import lombok.AllArgsConstructor;
import lombok.Value;

@Value
@AllArgsConstructor
public class DpsResult
{
	public static final DpsResult ZERO = new DpsResult(0, 0, 0, 0, 0, null);

	double dps;
	int maxHit;
	/** Probability of a successful hit, 0..1. */
	double accuracy;
	int attackSpeedTicks;
	/** Expected damage per attack, including misses. */
	double averageHit;
	/** How the max hit is made up when it is not a single hit, e.g. "26 + 26" or "7-44"; otherwise null. */
	String maxHitDetail;
	/** DPS on the selected enemy, including any returning venator bounce. */
	double primaryDps;
	/** Distinct enemies hit by this attack. */
	int targetsHit;
	/** Mean attack interval when a set effect shortens some attacks. */
	double expectedSpeedTicks;

	public DpsResult(double dps, int maxHit, double accuracy, int speed, double averageHit, String detail,
		double primaryDps, int targetsHit)
	{
		this(dps, maxHit, accuracy, speed, averageHit, detail, primaryDps, targetsHit, speed);
	}

	public DpsResult(double dps, int maxHit, double accuracy, int speed, double averageHit, String detail)
	{
		this(dps, maxHit, accuracy, speed, averageHit, detail, dps, 1);
	}

	public DpsResult withAreaDamage(double extraAverage, double returningAverage, int targets)
	{
		return withAreaDamage(extraAverage, returningAverage, targets, 0);
	}

	public DpsResult withAreaDamage(double extraAverage, double returningAverage, int targets, int returningMax)
	{
		double seconds = expectedSpeedTicks * 0.6;
		String detail = returningMax > 0 ? maxHit + " + " + returningMax + " returning bounce"
			+ (maxHitDetail == null ? "" : "; " + maxHitDetail) : maxHitDetail;
		return new DpsResult(dps + extraAverage / seconds, maxHit + returningMax, accuracy, attackSpeedTicks,
			averageHit + extraAverage, detail, primaryDps + returningAverage / seconds, targets, expectedSpeedTicks);
	}

	public DpsResult withExtraDps(double extra)
	{
		return new DpsResult(dps + extra, maxHit, accuracy, attackSpeedTicks, averageHit, maxHitDetail,
			primaryDps + extra, targetsHit, expectedSpeedTicks);
	}

	public DpsResult withDetail(String detail)
	{
		return new DpsResult(dps, maxHit, accuracy, attackSpeedTicks, averageHit, detail,
			primaryDps, targetsHit, expectedSpeedTicks);
	}

	/**
	 * Scale damage to the whole-fight average when the attack changes with the target's HP. Max hit and
	 * accuracy keep their starting values.
	 */
	public DpsResult withWholeFight(double factor, int fromHp)
	{
		String note = "whole-fight average from " + fromHp + " HP";
		return new DpsResult(dps * factor, maxHit, accuracy, attackSpeedTicks, averageHit * factor,
			maxHitDetail == null ? note : maxHitDetail + "; " + note, primaryDps * factor, targetsHit, expectedSpeedTicks);
	}

	/** Replace the damage rates, keeping this attack's max hit, accuracy and speed (special attacks mixed in). */
	public DpsResult withDamageRates(double totalDps, double primary)
	{
		return new DpsResult(totalDps, maxHit, accuracy, attackSpeedTicks, averageHit, maxHitDetail, primary,
			targetsHit, expectedSpeedTicks);
	}

	/** Apply a mean interval before adding independent thrall damage. */
	public DpsResult withExpectedSpeed(double speed)
	{
		double interval = Math.max(1, speed);
		return new DpsResult(dps * expectedSpeedTicks / interval, maxHit, accuracy, attackSpeedTicks, averageHit,
			maxHitDetail, primaryDps * expectedSpeedTicks / interval, targetsHit, interval);
	}
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.Slot;
import java.util.regex.Pattern;

/** Equipment requirements for dragonfire, independent of ordinary defence bonuses. */
public final class DragonfireProtection
{
	// Compiled once: the search checks protection for every setup it scores.
	private static final Pattern METAL_DRAGON = Pattern.compile("(bronze|iron|steel|mithril|adamant|rune) dragon.*");
	private static final Pattern CHROMATIC_DRAGON = Pattern.compile("(green|blue|red|black|lava|frost|reanimated) dragon.*");

	private DragonfireProtection()
	{
	}

	private static String name(Monster monster)
	{
		return monster.getLowerName();
	}

	static boolean isProtectiveShield(GearItem item)
	{
		String n = item == null ? "" : item.getLowerCombatName();
		return n.startsWith("anti-dragon shield") || n.startsWith("dragonfire shield")
			|| n.startsWith("dragonfire ward") || n.startsWith("ancient wyvern shield")
			|| n.equals("elemental shield") || n.equals("mind shield");
	}

	private static boolean wyvern(Monster monster)
	{
		return name(monster).contains("wyvern");
	}

	private static boolean metal(Monster monster)
	{
		return METAL_DRAGON.matcher(name(monster)).matches() || name(monster).startsWith("drake");
	}

	/** Whether this encounter requires dragonfire or wyvern breath protection. */
	public static boolean applies(Monster monster)
	{
		String n = name(monster);
		return !n.contains("baby") && (wyvern(monster) || metal(monster)
			|| n.contains("brutal") && n.contains("dragon")
			|| CHROMATIC_DRAGON.matcher(n).matches()
			|| n.startsWith("vorkath") || n.startsWith("king black dragon") || n.startsWith("galvek")
			|| n.startsWith("elvarg"));
	}

	/** Meets normal protection requirements; boss chip damage and avoidable specials may remain. */
	public static boolean allowed(Monster monster, Loadout loadout, OptimizerSettings settings, PlayerLevels levels)
	{
		return !required(monster, settings) || protects(monster, loadout, settings, levels);
	}

	/** Whether this lookup makes the setup carry dragonfire protection at all; fixed for one search. */
	static boolean required(Monster monster, OptimizerSettings settings)
	{
		return settings.isRequireFireProtection() && applies(monster);
	}

	/** {@link #allowed} once {@link #required} holds. */
	static boolean protects(Monster monster, Loadout loadout, OptimizerSettings settings, PlayerLevels levels)
	{
		GearItem item = loadout.getWeapon() == null || loadout.getWeapon().isTwoHanded() ? null : loadout.get(Slot.SHIELD);
		String shieldName = item == null ? "" : item.getLowerCombatName();
		boolean shield = isProtectiveShield(item);
		if (wyvern(monster))
		{
			return shield && !shieldName.startsWith("anti-dragon shield");
		}
		shield &= !shieldName.equals("elemental shield") && !shieldName.equals("mind shield");
		boolean magic = settings.isProtectMagic() && levels.getPrayer() >= 37;
		boolean potion = settings.getAntifire() != Antifire.NONE;
		boolean superPotion = settings.getAntifire() == Antifire.SUPER;
		String n = name(monster);
		if (n.startsWith("vorkath"))
		{
			return potion && shield || superPotion && magic;
		}
		if (n.startsWith("galvek") || n.startsWith("elvarg"))
		{
			return potion && shield;
		}
		if (n.startsWith("king black dragon"))
		{
			return potion && shield || superPotion && magic;
		}
		return superPotion || potion && (shield || magic && !metal(monster));
	}

	/** Summary of the active protection assumptions for the lookup. */
	public static String note(Monster monster, OptimizerSettings settings)
	{
		if (!applies(monster))
		{
			return null;
		}
		if (!settings.isRequireFireProtection())
		{
			return "Dragonfire / icy breath protection is not required by this lookup.";
		}
		String base = "Fire protection required: " + settings.getAntifire()
			+ (settings.isProtectMagic() ? " + Protect from Magic (requires 37 Prayer). " : ". ");
		if (wyvern(monster))
		{
			return base + "Wyverns need an icy breath shield; antifire and anti-dragon shields do not work. "
				+ "Icy breath can still hit 10; only the ancient wyvern shield prevents freezing.";
		}
		String n = name(monster);
		if (n.startsWith("vorkath"))
		{
			return base + "Requires potion + fire shield, or super antifire + Protect from Magic. "
				+ "Standard fire can still hit 10 without super antifire + shield; avoidable specials remain.";
		}
		if (n.startsWith("king black dragon"))
		{
			return base + "Requires antifire + shield or super antifire + Protect from Magic. "
				+ "Special breaths can still hit 10 with a shield, or 15 with super antifire + prayer.";
		}
		if (n.startsWith("galvek") || n.startsWith("elvarg"))
		{
			return base + "Requires antifire + fire shield; quest boss chip damage and special attacks may remain.";
		}
		return base + (metal(monster) ? "Metal dragons and drakes ignore Protect from Magic. " : "")
			+ (n.contains("brutal") ? "Brutal dragons also have a separate magic attack. " : "")
			+ "Protection constrains gear; eating and movement downtime are not simulated.";
	}
}

package com.bestgearsetup.calc;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/** How the stat drains of specs used during a kill (dragon warhammer, elder maul...) count towards ranking. */
@Getter
@RequiredArgsConstructor
public enum DrainSpecs
{
	/** Every hit/miss sequence weighted by its chance: the average kill. */
	EXPECTED("Expected"),
	/** Drains ignored; the spec is scored by its damage alone. */
	DAMAGE_ONLY("Ignore drain"),
	/** Worst case: every opening drain spec misses, costing its attack and leaving the target undrained. */
	ALL_MISS("Worst case");

	private final String displayName;

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.Slot;
import lombok.Value;

/** Sustained damaging enchanted-bolt effects, including miss procs and per-hit encounter caps. */
final class EnchantedBolts
{
	private EnchantedBolts()
	{
	}

	static Result calculate(Loadout l, CombatContext ctx, EncounterDamage.Rule rule, double accuracy, long min, long max)
	{
		String ammo = EncounterDamage.lower(l.get(Slot.AMMO));
		if (!ammo.endsWith("(e)"))
		{
			return null;
		}
		Monster monster = ctx.getMonster();
		boolean zaryte = EncounterDamage.lower(l.getWeapon()).startsWith("zaryte crossbow");
		// The Zaryte crossbow special guarantees the effect on every accurate hit; misses keep the usual chance.
		boolean guaranteed = zaryte && ctx.getModifiers().isSpecialAttack();
		double diary = ctx.getModifiers().isKandarinDiary() ? 1.1 : 1;
		double normal = EquipmentEffects.average(rule, l, ctx, min, max);
		int normalMax = EquipmentEffects.maximum(rule, l, ctx, max);
		double chance;
		double effectHit;
		// Expected effect damage when it procs on a miss; negative when misses cannot proc.
		double effectMiss;
		boolean missBecomesAccurate = false;
		int effectMax;
		if (ammo.startsWith("ruby ") && ctx.getModifiers().playerHp(ctx.getLevels()) >= 10
			&& ctx.getModifiers().targetHp(monster) > 0)
		{
			chance = 0.06 * diary;
			boolean infinite = monster.getId() == 14779 || EncounterDamage.named(monster, "gemstone crab");
			int cap = infinite ? zaryte ? 66 : 60 : zaryte ? 110 : 100;
			int damage = Math.min(cap, ctx.getModifiers().targetHp(monster) * (zaryte ? 22 : 20) / 100);
			// Corp's reduction precedes ruby replacement, so ruby effect damage bypasses it.
			EncounterDamage.Rule rubyRule = EncounterDamage.named(monster, "corporeal beast")
				|| monster.getId() == 319 ? EncounterDamage.unmitigated() : rule;
			effectHit = rubyRule.mean(Math.max(1, damage));
			effectMiss = effectHit;
			missBecomesAccurate = true;
			effectMax = rubyRule.maximum(Math.max(1, damage));
		}
		else if (ammo.startsWith("diamond "))
		{
			chance = 0.10 * diary;
			long effectRoll = max * (zaryte ? 126 : 115) / 100;
			effectHit = HitDamage.average(rule, 0, effectRoll);
			effectMiss = effectHit;
			missBecomesAccurate = true;
			effectMax = rule.maximum(effectRoll);
		}
		else if (ammo.startsWith("onyx ") && !monster.hasAttribute("undead"))
		{
			chance = 0.11 * diary;
			long effectRoll = max * (zaryte ? 132 : 120) / 100;
			effectHit = HitDamage.average(rule, 0, effectRoll);
			effectMiss = -1;
			effectMax = rule.maximum(effectRoll);
		}
		else
		{
			int bonus;
			boolean missProc;
			if (ammo.startsWith("opal "))
			{
				chance = 0.05 * diary;
				bonus = ctx.getRanged() / (zaryte ? 9 : 10);
				missProc = true;
			}
			else if (ammo.startsWith("pearl "))
			{
				chance = 0.06 * diary;
				int divisor = monster.hasAttribute("fiery") ? 15 : 20;
				bonus = ctx.getRanged() / (zaryte ? divisor - 2 : divisor);
				missProc = true;
			}
			else if (ammo.startsWith("dragonstone ") && !monster.hasAttribute("dragon")
				&& !monster.hasAttribute("fiery") && !monster.hasAttribute("dragonfire immune"))
			{
				chance = 0.06 * diary;
				bonus = ctx.getRanged() * 2 / (zaryte ? 9 : 10);
				missProc = false;
			}
			else
			{
				return null;
			}
			effectHit = HitDamage.average(rule, min, max, h -> EquipmentEffects.damage(l, ctx, h) + bonus);
			// A miss that procs stays inaccurate, so flat armour does not reduce it.
			effectMiss = missProc ? rule.meanInaccurate(bonus) : -1;
			effectMax = rule.maximum(EquipmentEffects.damage(l, ctx, max) + bonus);
		}
		double onHit = guaranteed ? 1 : chance;
		double average = accuracy * (onHit * effectHit + (1 - onHit) * normal)
			+ (effectMiss >= 0 ? (1 - accuracy) * chance * effectMiss : 0);
		double accurate = missBecomesAccurate ? accuracy + (1 - accuracy) * chance : accuracy;
		return new Result(average, Math.max(normalMax, effectMax), accurate,
			String.format(java.util.Locale.ROOT, "%s: %s proc; target HP %d", ammo,
				guaranteed ? "guaranteed on hit" : String.format(java.util.Locale.ROOT, "%.1f%%", chance * 100),
				ctx.getModifiers().targetHp(monster)));
	}

	@Value
	static class Result
	{
		double average;
		int maximum;
		double accuracy;
		String detail;
	}
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.EncounterPhase;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.Slot;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/** Per-hit encounter mitigation, applied after player damage bonuses and before thralls. */
final class EncounterDamage
{
	private static final Rule NONE = new Rule(1, 1, false, -1, 0, false, null);
	private static final Rule THIRD = new Rule(1, 3, false, -1, 0, false, "Damage / 3, rounded per hit");
	private static final Rule HALF = new Rule(1, 2, false, -1, 0, false, "Damage / 2, rounded per hit");
	private static final Rule QUARTER = new Rule(1, 4, false, -1, 0, false, "Damage / 4, rounded per hit");
	private static final Rule KRAKEN = new Rule(1, 7, true, -1, 0, false, "Ranged damage / 7; positive hits stay at least 1");
	private static final Rule TEKTON = new Rule(1, 5, true, -1, 0, false, "Magic damage / 5; positive hits stay at least 1");
	private static final Rule TD_SHIELD = new Rule(4, 5, true, -1, 0, false, "Fire shield: damage reduced by 20%");
	private static final Rule ZULRAH = new Rule(1, 1, false, 50, 45, true, "Hits above 50 rerolled to 45-50");
	private static final Rule SEREN = new Rule(1, 1, false, 2, 22, false, "Each hit limited by a random 22-24 cap");
	private static final Rule VERZIK_MELEE = new Rule(1, 1, false, 10, 0, false, "P1: each hit limited by a random 0-10 cap");
	private static final Rule VERZIK_OTHER = new Rule(1, 1, false, 3, 0, false, "P1: each hit limited by a random 0-3 cap");
	private static final Rule SILVER_CAP = new Rule(1, 1, false, 0, 10, false, "Silver weapon damage capped at 10");
	private static final Rule TOTEM = new Rule(2, 1, false, -1, 0, false, "Nightmare totem: double Magic damage");
	private static final Rule SIRE_TRANSITION = new Rule(1, 2, false, -1, 0, false, "Transition: damage / 2 per hit");
	private static final Rule HUEY_OTHER = new Rule(1, 1, false, 4, 0, false, "Tail: random 0-4 damage cap");
	private static final Rule HUEY_EARTH = new Rule(1, 1, false, 9, 0, false, "Tail: random 0-9 earth spell cap");
	private static final Rule HUEY_CRUSH = new Rule(1, 1, false, 9, 0, false,
		"Tail: random 0-9 crush cap, minimum 1 including misses", 0, true);

	private EncounterDamage()
	{
	}

	static CombatClass olmPreferredClass(Monster monster)
	{
		if (AttackReach.isOlmHead(monster))
		{
			return CombatClass.RANGED;
		}
		int id = monster.getId();
		String name = monster.getLowerName();
		boolean olm = name.startsWith("great olm");
		if (id == 7550 || id == 7553 || olm && name.contains("mage hand"))
		{
			return CombatClass.MAGIC;
		}
		if (id == 7552 || id == 7555 || olm && name.contains("melee hand"))
		{
			return CombatClass.MELEE;
		}
		return null;
	}

	static int divisor(Monster monster, CombatClass combatClass)
	{
		CombatClass preferred = olmPreferredClass(monster);
		if (preferred != null && preferred != combatClass)
		{
			return 3;
		}
		return combatClass == CombatClass.RANGED && AttackReach.isKraken(monster) ? 7 : 1;
	}

	static boolean named(Monster monster, String target)
	{
		return versionOf(monster.getLowerName(), target);
	}

	/** The name equals the base or is the base followed by a parenthesised version, without building strings. */
	static boolean versionOf(String name, String base)
	{
		return name.startsWith(base) && (name.length() == base.length() || name.startsWith(" (", base.length()));
	}

	static boolean tekton(Monster monster)
	{
		int id = monster.getId();
		return id == 7540 || id >= 7543 && id <= 7545 || named(monster, "tekton");
	}

	static boolean crystal(Monster monster)
	{
		return monster.getId() == 7568 || named(monster, "glowing crystal");
	}

	static boolean guardian(Monster monster)
	{
		return monster.getId() >= 7569 && monster.getId() <= 7572;
	}

	static boolean verzikP1(Monster monster)
	{
		int id = monster.getId();
		return id >= 8369 && id <= 8371 || id >= 10830 && id <= 10832 || id >= 10847 && id <= 10849
			|| named(monster, "verzik vitur") && monster.getLowerName().contains("(phase 1)");
	}

	static boolean tormented(Monster monster)
	{
		return monster.getId() >= 13599 && monster.getId() <= 13606 || named(monster, "tormented demon");
	}

	/** An "(unshielded)" variant, or the Boss phase option on the spawn variants the Wiki lists. */
	static boolean unshielded(Monster monster)
	{
		return tormented(monster) && (monster.getLowerName().contains("(unshielded)")
			|| CombatRules.phase(monster, EncounterPhase.TD_UNSHIELDED));
	}

	static boolean demonbane(Loadout loadout)
	{
		String weapon = lower(loadout.getWeapon());
		if (loadout.getStyle().getType() == AttackStyle.Type.MAGIC)
		{
			return spell(loadout).contains("demonbane");
		}
		if (loadout.getStyle().getType() == AttackStyle.Type.RANGED)
		{
			return weapon.startsWith("scorching bow");
		}
		return weapon.startsWith("silverlight") || weapon.startsWith("darklight") || weapon.startsWith("arclight")
			|| weapon.startsWith("emberlight") || weapon.startsWith("bone claws") || weapon.startsWith("burning claws");
	}

	static boolean abyssal(Loadout loadout)
	{
		String weapon = lower(loadout.getWeapon());
		return loadout.getStyle().isMelee() && (weapon.startsWith("abyssal whip") || weapon.startsWith("abyssal tentacle")
			|| weapon.startsWith("abyssal dagger") || weapon.startsWith("abyssal bludgeon"));
	}

	static String lower(GearItem item)
	{
		if (item == null)
		{
			return "";
		}
		String name = item.getLowerCombatName();
		return item.isDmmEquipment() && name.startsWith("corrupted ") ? name.substring(10) : name;
	}

	static String spell(Loadout loadout)
	{
		return loadout.getSpell() == null ? "" : loadout.getSpell().getName().toLowerCase(Locale.ROOT);
	}

	static Rule rule(Monster monster, Loadout loadout)
	{
		return rule(monster, loadout, WeaponRules.classOf(loadout.getStyle()));
	}

	/** Mitigation for a hit of the given class, such as Voidwaker's magical special attack. */
	static Rule rule(Monster monster, Loadout loadout, CombatClass cls)
	{
		Rule base = baseRule(monster, loadout, cls);
		int armour = monster.getFlatArmour() == null ? monster.getId() == 13011 ? -2
			: monster.getId() == 13013 ? -5 : monster.getId() == 13012
			? monster.getLowerName().contains("clone") ? 4 : 6 : CombatRules.eclipseClone(monster)
			? 4 : 0 : monster.getFlatArmour();
		if (cls == CombatClass.MAGIC)
		{
			armour = 0;
		}
		boolean pillar = CombatRules.phase(monster, EncounterPhase.HUEYCOATL_PILLAR);
		if (armour == 0 && !pillar)
		{
			return base;
		}
		int flat = armour;
		// Distinct keys for each armour value with and without the pillar buff.
		return base.derived.computeIfAbsent(flat * 2 + (pillar ? 1 : 0), key ->
		{
			String detail = base.detail;
			if (pillar)
			{
				detail = (detail == null ? "" : detail + "; ") + "Pillar: damage x1.3 per hit";
			}
			if (flat != 0)
			{
				detail = (detail == null ? "" : detail + "; ") + "Flat armour: " + flat + " per hit";
			}
			return new Rule(base.numerator, base.divisor, base.positiveMinimum, base.limit, base.offset,
				base.reroll, detail, flat, base.outputMinimum, pillar ? 13 : 1, pillar ? 10 : 1);
		});
	}

	private static Rule baseRule(Monster monster, Loadout loadout, CombatClass cls)
	{
		String weapon = lower(loadout.getWeapon());
		int id = monster.getId();
		if (id == 14014 || named(monster, "the hueycoatl") && monster.getLowerName().contains("tail"))
		{
			DpsCalculator.Bonuses bonuses = DpsCalculator.Bonuses.of(loadout);
			boolean crush = loadout.getStyle().getType() == AttackStyle.Type.CRUSH
				&& bonuses.crush > bonuses.stab && bonuses.crush > bonuses.slash;
			return crush ? HUEY_CRUSH : SpellRules.element(loadout.getSpell()).equals("earth") ? HUEY_EARTH : HUEY_OTHER;
		}
		if (cls == CombatClass.MAGIC && (id == 9434 || id == 9435 || id == 9437 || id == 9438
			|| id == 9440 || id == 9441 || id == 9443 || id == 9444 || named(monster, "nightmare totem")
			|| named(monster, "phosani's nightmare totem")))
		{
			return TOTEM;
		}
		if (id >= 2042 && id <= 2044 || named(monster, "zulrah"))
		{
			return ZULRAH;
		}
		if (id >= 8917 && id <= 8920 || named(monster, "fragment of seren"))
		{
			return SEREN;
		}
		if (verzikP1(monster) && !weapon.equals("dawnbringer"))
		{
			return cls == CombatClass.MELEE ? VERZIK_MELEE : VERZIK_OTHER;
		}
		if (tekton(monster) && cls == CombatClass.MAGIC)
		{
			return TEKTON;
		}
		if (crystal(monster) && cls == CombatClass.MAGIC)
		{
			return THIRD;
		}
		if ((id == 7584 || id == 7585 || named(monster, "ice demon"))
			&& !(cls == CombatClass.MAGIC && spell(loadout).startsWith("fire ")) && !demonbane(loadout))
		{
			return THIRD;
		}
		if (tormented(monster) && !unshielded(monster) && !demonbane(loadout) && !abyssal(loadout))
		{
			return TD_SHIELD;
		}
		if (CombatRules.phase(monster, EncounterPhase.ABYSSAL_SIRE_TRANSITION))
		{
			return SIRE_TRANSITION;
		}
		if (id == 319 || named(monster, "corporeal beast"))
		{
			boolean stab = loadout.getStyle().getType() == AttackStyle.Type.STAB;
			boolean suitable = cls == CombatClass.MAGIC || stab && (weapon.startsWith("osmumten's fang")
				|| loadout.getWeapon().getSubcategory().equals("polearm")
				|| weapon.contains("spear") && !weapon.startsWith("blue moon spear"));
			return suitable ? NONE : HALF;
		}
		if (named(monster, "slagilith") && !loadout.getWeapon().getSubcategory().equals("pickaxe"))
		{
			return THIRD;
		}
		if (named(monster, "zogre") || named(monster, "skogre") || named(monster, "slash bash"))
		{
			if (spell(loadout).equals("crumble undead"))
			{
				return HALF;
			}
			return cls == CombatClass.RANGED && weapon.equals("comp ogre bow")
				&& lower(loadout.get(Slot.AMMO)).contains(" brutal") ? NONE : QUARTER;
		}
		if (monster.hasAttribute("vampyre (t2)") && !EncounterImmunities.vampyrebane(loadout, false))
		{
			return lower(loadout.get(Slot.RING)).equals("efaritay's aid") ? HALF : SILVER_CAP;
		}
		int divisor = divisor(monster, cls);
		return divisor == 7 ? KRAKEN : divisor == 3 ? THIRD : NONE;
	}

	static Rule unmitigated()
	{
		return NONE;
	}

	static String encounterNote(Monster monster)
	{
		int id = monster.getId();
		if (id >= 2042 && id <= 2044 || named(monster, "zulrah"))
		{
			return "Zulrah: hits above 50 reroll to 45-50; the reroll is included in expected DPS.";
		}
		if (id >= 8917 && id <= 8920 || named(monster, "fragment of seren"))
		{
			return "Seren: each hit is limited by a random 22-24 cap.";
		}
		if (verzikP1(monster))
		{
			return "Verzik P1: random per-hit caps of 0-10 for melee and 0-3 otherwise; Dawnbringer bypasses them.";
		}
		if (tekton(monster))
		{
			return "Tekton: ranged immune; Magic damage divided by 5 with positive hits kept at 1.";
		}
		if (crystal(monster))
		{
			return "Vasa crystal: ranged immune; Magic damage divided by 3.";
		}
		if (id == 7584 || id == 7585 || named(monster, "ice demon"))
		{
			return "Ice Demon: damage divided by 3 except fire spells and demonbane attacks.";
		}
		if (tormented(monster))
		{
			return unshielded(monster) ? "Tormented Demon: unshielded target; no fire-shield reduction."
				: "Tormented Demon: fire shield reduces damage by 20%; demonbane and abyssal attacks bypass it.";
		}
		if (id == 319 || named(monster, "corporeal beast"))
		{
			return "Corp: half damage except Magic and qualifying stab weapons.";
		}
		if (guardian(monster))
		{
			return "CoX guardian: only melee attacks with a pickaxe can deal damage.";
		}
		if (monster.hasAttribute("leafy"))
		{
			return "Requires leaf-bladed melee, broad ammunition, or Magic Dart.";
		}
		if (monster.hasAttribute("vampyre (t2)") || monster.hasAttribute("vampyre (t3)"))
		{
			return "Vampyre weapon requirements apply; tier 2 silver hits cap at 10, or half damage with Efaritay's aid.";
		}
		return null;
	}

	/**
	 * A uniform raw hit is transformed before its mean is calculated: division, then a random cap or
	 * reroll, then a phase multiplier, then flat armour. Prefix sums keep searches fast.
	 */
	static final class Rule
	{
		private final int numerator;
		private final int divisor;
		private final boolean positiveMinimum;
		private final int limit;
		private final int offset;
		private final boolean reroll;
		private final int flatArmour;
		private final boolean outputMinimum;
		private final int postNumerator;
		private final int postDivisor;
		private final Map<Integer, Rule> derived = new ConcurrentHashMap<>();
		final String detail;
		private final double[] sums = new double[513];

		private Rule(int numerator, int divisor, boolean positiveMinimum, int limit, int offset,
			boolean reroll, String detail)
		{
			this(numerator, divisor, positiveMinimum, limit, offset, reroll, detail, 0, false, 1, 1);
		}

		private Rule(int numerator, int divisor, boolean positiveMinimum, int limit, int offset,
			boolean reroll, String detail, int flatArmour, boolean outputMinimum)
		{
			this(numerator, divisor, positiveMinimum, limit, offset, reroll, detail, flatArmour, outputMinimum, 1, 1);
		}

		private Rule(int numerator, int divisor, boolean positiveMinimum, int limit, int offset,
			boolean reroll, String detail, int flatArmour, boolean outputMinimum, int postNumerator, int postDivisor)
		{
			this.numerator = numerator;
			this.divisor = divisor;
			this.positiveMinimum = positiveMinimum;
			this.limit = limit;
			this.offset = offset;
			this.reroll = reroll;
			this.flatArmour = flatArmour;
			this.outputMinimum = outputMinimum;
			this.postNumerator = postNumerator;
			this.postDivisor = postDivisor;
			this.detail = detail;
			for (int hit = 0; hit < sums.length - 1; hit++)
			{
				sums[hit + 1] = sums[hit] + mean(hit);
			}
		}

		private long scaled(long hit)
		{
			return positiveMinimum && hit > 0 ? Math.max(1, hit * numerator / divisor) : hit * numerator / divisor;
		}

		/** Phase multiplier and armour for one capped outcome. Flat armour applies per outcome, not to a mean. */
		private double finish(long hit, boolean armour)
		{
			long value = hit * postNumerator / postDivisor;
			return outputMinimum ? Math.max(1, value) : Math.max(0, value - (armour ? flatArmour : 0));
		}

		private double finish(long hit)
		{
			return finish(hit, true);
		}

		/** Mean for an inaccurate hitsplat that still deals damage: flat armour only reduces accurate hits. */
		double meanInaccurate(long raw)
		{
			if (flatArmour == 0)
			{
				return mean(raw);
			}
			long hit = scaled(raw);
			if (limit < 0 || reroll && hit <= limit)
			{
				return finish(hit, false);
			}
			double sum = 0;
			if (reroll)
			{
				for (long rerolled = offset; rerolled <= limit; rerolled++)
				{
					sum += finish(rerolled, false);
				}
				return sum / (limit - offset + 1.0);
			}
			for (long cap = offset; cap <= offset + limit; cap++)
			{
				sum += finish(Math.min(hit, cap), false);
			}
			return sum / (limit + 1.0);
		}

		double mean(long raw)
		{
			long hit = scaled(raw);
			if (limit < 0 || reroll && hit <= limit)
			{
				return finish(hit);
			}
			if (reroll)
			{
				double sum = 0;
				for (long rerolled = offset; rerolled <= limit; rerolled++)
				{
					sum += finish(rerolled);
				}
				return sum / (limit - offset + 1.0);
			}
			if (!outputMinimum && flatArmour == 0 && postNumerator == postDivisor)
			{
				return cappedMean(hit);
			}
			double sum = 0;
			for (long cap = offset; cap <= offset + limit; cap++)
			{
				sum += finish(Math.min(hit, cap));
			}
			return sum / (limit + 1.0);
		}

		/** Closed form of min(hit, cap) averaged over a uniform cap in [offset, offset + limit]. */
		private double cappedMean(long hit)
		{
			long upper = offset + limit;
			if (hit >= upper)
			{
				return (offset + upper) / 2.0;
			}
			if (hit <= offset)
			{
				return hit;
			}
			long smaller = hit - offset;
			return (smaller * (offset + hit - 1) / 2.0 + (upper - hit + 1) * hit) / (limit + 1.0);
		}

		int maximum(long raw)
		{
			long hit = scaled(raw);
			long capped = limit < 0 ? hit : Math.min(hit, reroll ? limit : offset + limit);
			return (int) finish(capped);
		}

		double missDamage()
		{
			return outputMinimum ? finish(1) : 0;
		}

		double average(long minimum, long maximum)
		{
			if (this == NONE)
			{
				return (minimum + maximum) / 2.0;
			}
			if (minimum >= 0 && maximum < sums.length - 1)
			{
				return (sums[(int) maximum + 1] - sums[(int) minimum]) / (maximum - minimum + 1.0);
			}
			double sum = 0;
			for (long hit = minimum; hit <= maximum; hit++)
			{
				sum += mean(hit);
			}
			return sum / (maximum - minimum + 1.0);
		}
	}

}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.EncounterPhase;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.Slot;

/** Combat-class and equipment requirements shared by search filtering and direct DPS scoring. */
final class EncounterImmunities
{
	/** Slot.values() copies the array on every call, and every scored setup is checked. */
	private static final Slot[] SLOTS = Slot.values();

	private EncounterImmunities()
	{
	}

	static boolean classAllowed(Monster monster, CombatClass cls)
	{
		int id = monster.getId();
		if (CombatRules.eclipseClone(monster))
		{
			return cls == CombatClass.MELEE;
		}
		boolean dusk = id == 7851 || id == 7854 || id == 7855 || id == 7882 || id == 7883
			|| id >= 7886 && id <= 7889 || EncounterDamage.named(monster, "dusk");
		if (dusk || EncounterDamage.guardian(monster))
		{
			return cls == CombatClass.MELEE;
		}
		if (id == 2463 || id == 2464 || id == 2465 || id == 2466 || id == 2467 || id == 2468
			|| id >= 2137 && id <= 2142)
		{
			return cls == CombatClass.MELEE;
		}
		if (EncounterDamage.tekton(monster) || EncounterDamage.crystal(monster))
		{
			// Crystals can take reduced Magic damage even where a broader "melee only" tag says otherwise.
			return cls != CombatClass.RANGED;
		}
		if (cls == CombatClass.MELEE && (AttackReach.isMeleeBlocked(monster)
			|| AttackReach.isVespula(monster) || AttackReach.isAbyssalPortal(monster)
			|| id == 12214 || id == 12215 || id == 12219 || EncounterDamage.named(monster, "the leviathan")))
		{
			return false;
		}
		if (cls == CombatClass.MELEE && monster.hasAttribute("melee immune")
			|| cls == CombatClass.RANGED && monster.hasAttribute("ranged immune")
			|| cls == CombatClass.MAGIC && monster.hasAttribute("magic immune"))
		{
			return false;
		}
		return (!monster.hasAttribute("melee only") || cls == CombatClass.MELEE)
			&& (!monster.hasAttribute("ranged only") || cls == CombatClass.RANGED)
			&& (!monster.hasAttribute("magic only") || cls == CombatClass.MAGIC);
	}

	static boolean attackAllowed(Monster monster, Loadout loadout)
	{
		CombatClass cls = WeaponRules.classOf(loadout.getStyle());
		if (!classAllowed(monster, cls)
			|| loadout.getStyle().isMelee() && !AttackReach.meleeAllowed(monster, loadout.getWeapon()))
		{
			return false;
		}
		String weapon = EncounterDamage.lower(loadout.getWeapon());
		String ammo = EncounterDamage.lower(loadout.get(Slot.AMMO));
		boolean gauntlet = CombatRules.gauntlet(monster);
		for (Slot slot : SLOTS)
		{
			if (loadout.get(slot) != null && !CombatRules.equipmentAllowed(monster, gauntlet, loadout.get(slot)))
			{
				return false;
			}
		}
		if (cls == CombatClass.RANGED && (weapon.equals("holy water") && !monster.hasAttribute("demon")
			|| weapon.contains("(u)") || weapon.contains("uncharged")))
		{
			return false;
		}
		if (EquipmentEffects.ratWeapon(loadout.getWeapon()) && !monster.hasAttribute("rat"))
		{
			return false;
		}
		if (CombatRules.phase(monster, EncounterPhase.MOKHAIOTL_SHIELDED) && !EncounterDamage.demonbane(loadout))
		{
			// The shield blocks everything except demonbane attacks.
			return false;
		}
		if (EncounterDamage.named(monster, "fire warrior of lesarkus")
			&& (cls != CombatClass.RANGED || !ammo.equals("ice arrows")))
		{
			return false;
		}
		if (EncounterDamage.named(monster, "fareed") && (cls == CombatClass.MAGIC
			&& !SpellRules.element(loadout.getSpell()).equals("water") || cls == CombatClass.RANGED && !ammo.contains("arrow")))
		{
			return false;
		}
		if (EncounterDamage.guardian(monster)
			&& !loadout.getWeapon().getSubcategory().equals("pickaxe"))
		{
			return false;
		}
		if (monster.hasAttribute("leafy") || EncounterDamage.named(monster, "kurask")
			|| EncounterDamage.named(monster, "turoth"))
		{
			boolean leaf = cls == CombatClass.MELEE && weapon.startsWith("leaf-bladed ")
				|| cls == CombatClass.MAGIC && EncounterDamage.spell(loadout).equals("magic dart")
				|| cls == CombatClass.RANGED && WeaponRules.firesAmmoSlot(loadout.getWeapon())
				&& (ammo.startsWith("broad ") || ammo.startsWith("amethyst broad ") || ammo.startsWith("seeking broad "));
			if (!leaf)
			{
				return false;
			}
		}
		if (monster.hasAttribute("vampyre (t3)") && !vampyrebane(loadout, true))
		{
			return false;
		}
		if (monster.hasAttribute("vampyre (t2)") && !vampyrebane(loadout, false)
			&& !EncounterDamage.lower(loadout.get(Slot.RING)).equals("efaritay's aid") && !silver(loadout))
		{
			return false;
		}
		return true;
	}

	static boolean vampyrebane(Loadout loadout, boolean tierThree)
	{
		String weapon = EncounterDamage.lower(loadout.getWeapon());
		if (loadout.getStyle().getType() == AttackStyle.Type.RANGED && weapon.startsWith("blisterwood stake"))
		{
			return true;
		}
		return (!tierThree || loadout.getStyle().isMelee()) && (weapon.startsWith("ivandis flail")
			|| weapon.startsWith("blisterwood sickle") || weapon.startsWith("blisterwood flail")
			|| weapon.startsWith("hallowed flail") || weapon.equals("sunspear")
			|| !tierThree && weapon.startsWith("rod of ivandis"));
	}

	static boolean silver(Loadout loadout)
	{
		if (loadout.getStyle().getType() == AttackStyle.Type.RANGED)
		{
			return EncounterDamage.lower(loadout.getWeapon()).startsWith("blisterwood stake")
				|| WeaponRules.firesAmmoSlot(loadout.getWeapon())
				&& EncounterDamage.lower(loadout.get(Slot.AMMO)).startsWith("silver bolts");
		}
		String weapon = EncounterDamage.lower(loadout.getWeapon());
		return loadout.getStyle().isMelee() && (weapon.startsWith("silver sickle") || weapon.contains("emerald sickle")
			|| weapon.contains("ruby sickle") || weapon.equals("blessed axe") || weapon.equals("wolfbane")
			|| weapon.startsWith("silverlight") || weapon.startsWith("darklight") || weapon.startsWith("arclight")
			|| weapon.startsWith("ivandis flail") || weapon.startsWith("rod of ivandis")
			|| weapon.startsWith("blisterwood") || weapon.startsWith("hallowed flail"));
	}
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.EncounterPhase;
import com.bestgearsetup.data.Monster;

/** Describes how the selected temporary boss phase changes the calculation. */
public final class EncounterPhases
{
	private EncounterPhases()
	{
	}

	public static boolean applies(Monster monster, EncounterPhase phase)
	{
		return CombatRules.phaseApplies(monster, phase);
	}

	/**
	 * Apply phase-dependent target stats. Yama's Magic defence bonus is +60 while his primary target uses
	 * Magic and -30 while they use Melee (Wiki), except in his enraged phase. Only magic attacks read it, so
	 * when the player is his target a magic setup always faces +60; -30 applies only when a partner tanks
	 * with Melee while the player casts.
	 */
	public static void applyStats(Monster monster)
	{
		if (CombatRules.yamaTankDependent(monster))
		{
			monster.setDefMagic(monster.getPhase() == EncounterPhase.YAMA_MELEE_TANK ? -30 : 60);
		}
	}

	/** A summary for the search notes, or null when the standard state is selected. */
	public static String describe(Monster monster)
	{
		EncounterPhase phase = monster.getPhase();
		if (phase == EncounterPhase.STANDARD)
		{
			return CombatRules.yamaTankDependent(monster)
				? "Yama: you are his target, so magic setups face +60 Magic defence (\"Partner tanks with Melee\": -30)."
				: null;
		}
		if (!applies(monster, phase))
		{
			return "Boss phase \"" + phase + "\" does not apply to this target and is ignored.";
		}
		switch (phase)
		{
			case HUEYCOATL_PILLAR:
				return "Hueycoatl pillar: each hit deals 30% more damage after the tail caps.";
			case ROYAL_TITANS_OUT_OF_MELEE:
				return "Royal Titans out of melee range: ranged attack rolls are multiplied by 6.";
			case ABYSSAL_SIRE_TRANSITION:
				return "Abyssal Sire transition: each hit is halved.";
			case MOKHAIOTL_SHIELDED:
				return "Mokhaiotl shielded: only demonbane attacks deal damage; they always hit.";
			case MOKHAIOTL_BURROWING:
				return "Mokhaiotl burrowing: every attack hits.";
			case TD_UNSHIELDED:
				return "Tormented Demon unshielded: always hit, no fire-shield reduction, heavy-hitting attacks gain damage.";
			case TD_DEFENCELESS:
				return "Tormented Demon defenceless: attacks always hit but the fire shield still reduces damage.";
			case YAMA_MELEE_TANK:
				return "Yama: your partner tanks with Melee, so his Magic defence is -30.";
			default:
				return null;
		}
	}
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Slot;

/** Equipment predicates shared by calculation and optimizer set seeds. */
final class EquipmentEffects
{
	private EquipmentEffects()
	{
	}

	static boolean named(Loadout l, Slot slot, String name)
	{
		return namedWeapon(l.get(slot), name);
	}

	static boolean namedWeapon(GearItem item, String name)
	{
		String actual = EncounterDamage.lower(item);
		// "name (" is a case of "name ": test the prefix first, without building strings.
		return actual.startsWith(name) && (actual.length() == name.length() || actual.charAt(name.length()) == ' ')
			&& !actual.contains("uncharged") && !actual.contains("inactive") && !actual.contains("broken");
	}

	static boolean set(Loadout l, String head, String body, String legs, String weapon)
	{
		return named(l, Slot.HEAD, head) && named(l, Slot.BODY, body) && named(l, Slot.LEGS, legs)
			&& named(l, Slot.WEAPON, weapon);
	}

	static boolean damned(Loadout l)
	{
		return named(l, Slot.NECK, "amulet of the damned");
	}

	static boolean verac(Loadout l)
	{
		return set(l, "verac's helm", "verac's brassard", "verac's plateskirt", "verac's flail");
	}

	static boolean dharok(Loadout l)
	{
		return set(l, "dharok's helm", "dharok's platebody", "dharok's platelegs", "dharok's greataxe");
	}

	static boolean ahrim(Loadout l)
	{
		return damned(l) && set(l, "ahrim's hood", "ahrim's robetop", "ahrim's robeskirt", "ahrim's staff");
	}

	static boolean karil(Loadout l)
	{
		return damned(l) && set(l, "karil's coif", "karil's leathertop", "karil's leatherskirt", "karil's crossbow");
	}

	static boolean bloodMoon(Loadout l)
	{
		return set(l, "blood moon helm", "blood moon chestplate", "blood moon tassets", "dual macuahuitl");
	}

	static boolean twoHit(GearItem w)
	{
		String name = EncounterDamage.lower(w);
		return name.startsWith("torag's hammers") || name.equals("sulphur blades")
			|| name.equals("glacial temotli") || name.equals("earthbound tecpatl");
	}

	static boolean ratWeapon(GearItem w)
	{
		String name = EncounterDamage.lower(w);
		return name.equals("bone mace") || name.equals("bone shortbow") || name.equals("bone staff");
	}

	static boolean wildernessWeapon(Loadout l, CombatContext ctx)
	{
		String name = EncounterDamage.lower(l.getWeapon());
		if (!ctx.getModifiers().isWilderness() || name.contains("uncharged") || name.endsWith("(u)"))
		{
			return false;
		}
		CombatClass cls = WeaponRules.classOf(l.getStyle());
		switch (cls)
		{
			case MELEE:
				return name.startsWith("ursine chainmace") || name.startsWith("viggora's chainmace");
			case RANGED:
				return name.startsWith("craw's bow") || name.startsWith("webweaver bow");
			default:
				return name.startsWith("thammaron's sceptre") || name.startsWith("accursed sceptre");
		}
	}

	static boolean vampyre(CombatContext ctx)
	{
		return ctx.getMonster().hasAttribute("vampyre (t1)") || ctx.getMonster().hasAttribute("vampyre (t2)")
			|| ctx.getMonster().hasAttribute("vampyre (t3)");
	}

	/** Effects that scale each rolled hit, rather than increasing the roll's maximum. */
	static long damage(Loadout l, CombatContext ctx, long hit)
	{
		String weapon = EncounterDamage.lower(l.getWeapon());
		if (l.getStyle().isMelee())
		{
			if (dharok(l))
			{
				int hp = ctx.getLevels().getHitpoints();
				hit = hit * (10000L + (hp - ctx.getModifiers().playerHp(ctx.getLevels())) * hp) / 10000;
			}
			if ((weapon.startsWith("toktz-") || weapon.startsWith("tzhaar-ket-"))
				&& named(l, Slot.NECK, "berserker necklace"))
			{
				hit = hit * 6 / 5;
			}
			if (EncounterDamage.guardian(ctx.getMonster()))
			{
				int pick = weapon.startsWith("bronze") || weapon.startsWith("iron") ? 1
					: weapon.startsWith("steel") ? 6 : weapon.startsWith("black") ? 11
					: weapon.startsWith("mithril") ? 21 : weapon.startsWith("adamant") ? 31
					: weapon.startsWith("rune") || weapon.startsWith("gilded") ? 41 : 61;
				hit = hit * (50 + Math.max(1, Math.min(99, ctx.getModifiers().getMiningLevel())) + pick) / 150;
			}
		}
		if (vampyre(ctx))
		{
			int percent = weapon.startsWith("blisterwood flail") || weapon.startsWith("hallowed flail")
				|| weapon.startsWith("blisterwood stake") ? 125 : weapon.equals("sunspear") ? 150
				: weapon.startsWith("blisterwood sickle") ? 115 : weapon.startsWith("ivandis flail") ? 120
				: weapon.startsWith("rod of ivandis") ? 110
				: ctx.getMonster().hasAttribute("vampyre (t1)") && EncounterImmunities.silver(l) ? 110 : 100;
			if (percent != 100)
			{
				if (named(l, Slot.RING, "efaritay's aid"))
				{
					hit = hit * 11 / 10;
				}
				hit = hit * percent / 100;
			}
		}
		if (CombatRules.tormentedBonus(ctx.getMonster(), l))
		{
			int speed = l.getSpell() != null ? l.getSpell().getAttackSpeed() : l.getWeapon().getAttackSpeed()
				- (l.getStyle().getStance().equals("rapid") ? 1 : 0);
			if (l.getSpell() != null && weapon.startsWith("harmonised nightmare staff")
				&& "standard".equalsIgnoreCase(l.getSpell().getSpellbook()))
			{
				speed = 4;
			}
			else if (l.getSpell() != null && weapon.startsWith("twinflame staff"))
			{
				speed = 6;
			}
			hit += Math.max(0, speed * speed - 16);
		}
		if (seeking(l))
		{
			// Seeking broad arrows raise successful hits to at least 3.
			hit = Math.max(3, hit);
		}
		return hit;
	}

	static boolean seeking(Loadout l)
	{
		return l.getStyle().getType() == AttackStyle.Type.RANGED && WeaponRules.firesAmmoSlot(l.getWeapon())
			&& EncounterDamage.lower(l.get(Slot.AMMO)).startsWith("seeking broad");
	}

	static boolean rolledEffect(Loadout l, CombatContext ctx)
	{
		String weapon = EncounterDamage.lower(l.getWeapon());
		return vampyre(ctx) || CombatRules.tormentedBonus(ctx.getMonster(), l) || seeking(l)
			|| l.getStyle().isMelee() && (dharok(l) || EncounterDamage.guardian(ctx.getMonster())
			|| (weapon.startsWith("toktz-") || weapon.startsWith("tzhaar-ket-"))
			&& named(l, Slot.NECK, "berserker necklace"));
	}

	static double average(EncounterDamage.Rule rule, Loadout l, CombatContext ctx, long min, long max)
	{
		return rolledEffect(l, ctx) ? HitDamage.average(rule, min, max, h -> damage(l, ctx, h))
			: HitDamage.average(rule, min, max);
	}

	static int maximum(EncounterDamage.Rule rule, Loadout l, CombatContext ctx, long max)
	{
		return rule.maximum(Math.max(1, damage(l, ctx, max)));
	}
}

