package com.bestgearsetup.calc;

/**
 * Chance that an attack hits, counted exactly from the rolls the game makes.
 *
 * <p>An attack hits when the attack roll is strictly higher than the defence roll. A roll with maximum
 * {@code max >= 0} is uniform on {@code 0..max}. The game draws a roll as {@code (int) (random() * (max + 1))},
 * so a negative maximum (a bonus below -64) truncates towards zero and is uniform on {@code max + 2..0}
 * (just {@code 0} when {@code max} is -1).
 *
 * <p>The miss chance is the average, over every defence roll {@code y}, of the chance that every attack roll
 * is at most {@code y}. With the attack roll uniform on {@code lo..hi}, that chance is
 * {@code clamp(y - lo + 1, 0, n) / n} for {@code n = hi - lo + 1}, so summing it over the defence rolls
 * needs only sums of consecutive integers or squares.
 */
public final class HitChance
{
	private HitChance()
	{
	}

	/** One attack roll against one defence roll (Wiki: "Damage per second/Melee", hit chance). */
	public static double single(long maxAttackRoll, long maxDefenceRoll)
	{
		return hitWithAttackRolls(maxAttackRoll, maxDefenceRoll, 1);
	}

	/**
	 * Two independent attack rolls against one defence roll; either may beat it. Used by Osmumten's fang outside
	 * the Tombs of Amascut and the confliction gauntlets' second roll (Wiki: their item pages).
	 */
	public static double twoAttackRolls(long maxAttackRoll, long maxDefenceRoll)
	{
		return hitWithAttackRolls(maxAttackRoll, maxDefenceRoll, 2);
	}

	/**
	 * Long-run hit rate when every attack after a miss gets {@code retry} instead of {@code normal} (confliction
	 * gauntlets). Attacks alternate between a normal state and a retry state: a hit returns to the normal state
	 * and a miss moves to the retry state. In the steady state, entering the retry state (a normal miss) is as
	 * likely as leaving it (a retry hit): {@code pNormal * (1 - normal) = pRetry * retry}.
	 */
	public static double withRetryAfterMiss(double normal, double retry)
	{
		double total = (1 - normal) + retry;
		if (total <= 0)
		{
			return normal;
		}
		double pNormal = retry / total;
		double pRetry = (1 - normal) / total;
		return pNormal * normal + pRetry * retry;
	}

	/** Chance that the best of {@code attackRolls} (1 or 2) attack rolls beats one defence roll. */
	private static double hitWithAttackRolls(long maxAttackRoll, long maxDefenceRoll, int attackRolls)
	{
		long attackLow = lowest(maxAttackRoll);
		long attackCount = Math.max(0, maxAttackRoll) - attackLow + 1;
		long defenceLow = lowest(maxDefenceRoll);
		long defenceCount = Math.max(0, maxDefenceRoll) - defenceLow + 1;
		// For defence roll y, the number of attack rolls at most y is clamp(y - attackLow + 1, 0, attackCount).
		long from = defenceLow - attackLow + 1;
		long to = from + defenceCount - 1;
		double missWeight = sumClampedPowers(from, to, attackCount, attackRolls);
		return 1 - missWeight / (defenceCount * Math.pow(attackCount, attackRolls));
	}

	private static long lowest(long maxRoll)
	{
		return maxRoll >= 0 ? 0 : Math.min(0, maxRoll + 2);
	}

	/** The sum of {@code clamp(s, 0, cap)^power} for {@code s} from {@code from} to {@code to}; power is 1 or 2. */
	private static double sumClampedPowers(long from, long to, long cap, int power)
	{
		double total = 0;
		long rising = Math.max(from, 1);
		long top = Math.min(to, cap);
		if (rising <= top)
		{
			total += powerSum(top, power) - powerSum(rising - 1, power);
		}
		long saturated = to - Math.max(from, cap + 1) + 1;
		if (saturated > 0)
		{
			total += saturated * Math.pow(cap, power);
		}
		return total;
	}

	/** 1 + 2 + ... + n, or 1 + 4 + ... + n^2. */
	private static double powerSum(long n, int power)
	{
		double x = n;
		return power == 1 ? x * (x + 1) / 2 : x * (x + 1) * (2 * x + 1) / 6;
	}
}

package com.bestgearsetup.calc;

import java.util.function.LongUnaryOperator;

/** Per-hitsplat damage operations. Misses are separate from successful zero rolls. */
final class HitDamage
{
	private HitDamage()
	{
	}

	static double average(EncounterDamage.Rule rule, long min, long max)
	{
		if (min == 0 && max == 0)
		{
			return rule.mean(1);
		}
		return rule.average(min, max) + (min == 0 && max > 0 ? (rule.mean(1) - rule.mean(0)) / (max + 1.0) : 0);
	}

	static double average(EncounterDamage.Rule rule, long min, long max, LongUnaryOperator transform)
	{
		return averageTransformed(rule, min, max, h -> Math.max(1, transform.applyAsLong(h)));
	}

	static double averageTransformed(EncounterDamage.Rule rule, long min, long max, LongUnaryOperator transform)
	{
		double sum = 0;
		for (long hit = min; hit <= max; hit++)
		{
			sum += rule.mean(transform.applyAsLong(hit));
		}
		return sum / (max - min + 1.0);
	}
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Slot;
import com.bestgearsetup.data.Spell;
import java.util.Arrays;
import lombok.Getter;
import lombok.Setter;

/**
 * A candidate setup: one item per slot, the chosen attack style, and optionally a spell
 * (autocast) or darts loaded into a blowpipe. Mutable for the optimiser's hot loop; use
 * {@link #copy()} before storing.
 */
public class Loadout
{
	private final GearItem[] items = new GearItem[Slot.values().length];

	@Getter
	@Setter
	private AttackStyle style;

	@Getter
	@Setter
	private Spell spell;

	/** Darts loaded into a blowpipe-type weapon (they do not occupy the ammo slot). */
	@Getter
	@Setter
	private GearItem loadedAmmo;

	public GearItem get(Slot slot)
	{
		return items[slot.ordinal()];
	}

	public void set(Slot slot, GearItem item)
	{
		items[slot.ordinal()] = item;
	}

	public GearItem getWeapon()
	{
		return items[Slot.WEAPON.ordinal()];
	}

	public Loadout copy()
	{
		Loadout l = new Loadout();
		System.arraycopy(items, 0, l.items, 0, items.length);
		l.style = style;
		l.spell = spell;
		l.loadedAmmo = loadedAmmo;
		return l;
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof Loadout))
		{
			return false;
		}
		Loadout other = (Loadout) o;
		return Arrays.equals(items, other.items) && java.util.Objects.equals(style, other.style)
			&& spell == other.spell && loadedAmmo == other.loadedAmmo;
	}

	@Override
	public int hashCode()
	{
		return Arrays.hashCode(items);
	}
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.GameData;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Slot;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import lombok.Value;

/** How one slot lock affected a search, in plain words, for the results view. */
@Value
public class LockStatus
{
	Slot slot;
	SlotLock lock;
	/** The locked item; null for empty and fill locks, or an id missing from the bundled data. */
	GearItem item;
	/** Why the lock could not be honoured, or null when it was applied. */
	String problem;
	/** What the lock does to the search, or null when it only fixes the slot. */
	String effect;

	public boolean isBlocking()
	{
		return problem != null;
	}

	/** Check every lock against the search the optimizer was built for. */
	public static List<LockStatus> check(GameData data, Optimizer optimizer, Map<Slot, SlotLock> locks)
	{
		List<LockStatus> out = new ArrayList<>();
		for (Map.Entry<Slot, SlotLock> e : locks.entrySet())
		{
			out.add(check(data, optimizer, e.getKey(), e.getValue()));
		}
		return out;
	}

	private static LockStatus check(GameData data, Optimizer optimizer, Slot slot, SlotLock lock)
	{
		String slotName = slot.getDisplayName().toLowerCase(Locale.ROOT);
		GearItem locked = lock.getKind() == SlotLock.Kind.ITEM ? data.getItem(slot, lock.getItemId()) : null;
		String unprotected = optimizer.protectionLockReason(slot, locked);
		if (unprotected != null)
		{
			return new LockStatus(slot, lock, locked, unprotected, "No setup can be found while this lock is set.");
		}
		switch (lock.getKind())
		{
			case EMPTY:
				return new LockStatus(slot, lock, null, null, slot == Slot.AMMO
					? "Weapons that fire arrows, bolts or other ammunition are excluded." : null);
			case FILL:
				return new LockStatus(slot, lock, null, null, "Always filled with the best defence or prayer item."
					+ (slot == Slot.SHIELD ? " Two-handed weapons are excluded." : ""));
			default:
				break;
		}
		GearItem item = locked;
		String blocked = slot == Slot.WEAPON ? "No setup can be found while this lock is set."
			: slot == Slot.AMMO ? "The ammo slot is left empty, so weapons that fire ammunition are excluded."
			: "The " + slotName + " slot is left empty.";
		if (item == null)
		{
			return new LockStatus(slot, lock, null, "this item is not in the bundled data", blocked);
		}
		String problem = slot == Slot.WEAPON ? optimizer.weaponLockReason(item) : optimizer.unusableReason(item);
		if (problem != null)
		{
			return new LockStatus(slot, lock, item, problem, blocked);
		}
		String name = GameData.titleCase(item.getName());
		switch (slot)
		{
			case WEAPON:
				return new LockStatus(slot, lock, item, null, "Only " + name + " is searched.");
			case SHIELD:
				return new LockStatus(slot, lock, item, null, "Two-handed weapons are excluded.");
			case AMMO:
				return new LockStatus(slot, lock, item, null,
					"Weapons that fire ammunition are searched only if they can fire " + name + ".");
			default:
				return new LockStatus(slot, lock, item, null, null);
		}
	}
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.Monster;

/** Apply supported health-dependent target stats before pre-fight stat drains. */
public final class MonsterStates
{
	private MonsterStates()
	{
	}

	/** Vardorvis's selected health snapshot; unknown modes keep the supplied reference stats. */
	public static Monster atHealth(Monster base, int currentHp)
	{
		Monster result = base.copy();
		if (!EncounterDamage.named(base, "vardorvis"))
		{
			return result;
		}
		String name = base.getLowerName();
		boolean awakened = name.contains("awakened");
		boolean quest = name.contains("(quest)");
		int maximum = awakened ? 1400 : quest ? 500 : 700;
		if (base.getHitpoints() != maximum || name.contains("echo"))
		{
			return result;
		}
		int hp = currentHp <= 0 ? maximum : Math.min(maximum, currentHp);
		int startDef = awakened ? 268 : quest ? 180 : 215;
		int endDef = awakened ? 181 : quest ? 130 : 145;
		int startStr = awakened ? 391 : quest ? 210 : 270;
		int endStr = awakened ? 522 : quest ? 280 : 360;
		result.setDefenceLevel((int) (startDef - (maximum - hp) * (double) (startDef - endDef) / maximum));
		result.setStrengthLevel((int) (startStr + (maximum - hp) * (double) (endStr - startStr) / maximum));
		result.setDefenceFloor(result.getDefenceLevel());
		return result;
	}
}

