@Value
@Builder(toBuilder = true)
public class OptimizerSettings
{
	SearchMode mode;
	/** Maximum GP to spend on items not already owned (BUDGET mode only). */
	long budget;
	/** Limit all equipped expensive items for a Wilderness search, including owned gear. */
	@Builder.Default
	boolean wildernessRiskLimited = false;
	@Builder.Default
	int maxExpensiveItems = 3;
	/** An item at or above this acquisition value plus PvP repair fee is expensive; unknown values count too. */
	@Builder.Default
	long expensiveItemThreshold = 1_000_000;
	/** Lower-case spellbook names the player may autocast from: standard, ancient, arceuus. */
	Set<String> spellbooks;
	/** How many setups to return per combat class. */
	@Builder.Default
	int resultsPerClass = 3;

	/** Attack types that may be used. */
	@Builder.Default
	Set<AttackStyle.Type> styles = EnumSet.allOf(AttackStyle.Type.class);
	@Builder.Default
	WeaponHands weaponHands = WeaponHands.ANY;
	@Builder.Default
	CalcMode calcMode = CalcMode.DPS;
	@Builder.Default
	SearchDepth depth = SearchDepth.NORMAL;

	/** Experience filter: styles granting a disallowed experience type are never used. */
	@Builder.Default
	boolean attackXp = true;
	@Builder.Default
	boolean strengthXp = true;
	@Builder.Default
	boolean defenceXp = true;

	/** False restricts to free-to-play items. */
	@Builder.Default
	boolean membersItems = true;
	/** Optional world-specific equipment is excluded unless explicitly enabled. */
	@Builder.Default
	boolean dmmItems = false;
	@Builder.Default
	boolean betaItems = false;
	@Builder.Default
	boolean bountyHunterItems = false;
	/** Eclipse atlatl setups must wear an Ava's device or quiver to recover ammunition. */
	@Builder.Default
	boolean requireAtlatlAmmoRecovery = false;

	@Builder.Default
	FillMode fillMode = FillMode.NONE;
	@Builder.Default
	DefenceFocus defenceFocus = DefenceFocus.TARGET;
	/** How much DPS (percent) may be given up to fit fill items. */
	@Builder.Default
	double fillMarginPercent = 0;

	/** Use special attacks during the kill, switching to the best spec weapon in the same combat class. */
	@Builder.Default
	boolean killSpecials = false;
	@Builder.Default
	SpecEnergy specEnergy = SpecEnergy.REGENERATION;
	/** How landed stat drains from those specs count. */
	@Builder.Default
	DrainSpecs drainSpecs = DrainSpecs.EXPECTED;

	/** Number of arrows / bolts / darts to price in the budget; 0 ignores ammo cost. */
	@Builder.Default
	int ammoCount = 0;

	/** Distance from the nearest monster tile; 0 uses the encounter's minimum reach. */
	@Builder.Default
	int targetDistance = 0;

	@Builder.Default
	boolean requireFireProtection = true;
	@Builder.Default
	Antifire antifire = Antifire.SUPER;
	@Builder.Default
	boolean protectMagic = true;
	/** The Elite Kourend & Kebos Diary removes the Karuulm Slayer Dungeon's heat-protection boots requirement. */
	@Builder.Default
	boolean kourendEliteDiary = false;
	/** The selected target is in Karuulm, or the search plans a matching Karuulm assignment. */
	@Builder.Default
	boolean karuulmDungeon = false;

	@Builder.Default
	Map<Slot, SlotLock> locks = Collections.emptyMap();
	@Builder.Default
	Set<Integer> excluded = Collections.emptySet();
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.GearItem;
import java.util.ArrayList;
import java.util.List;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Value;

/**
 * The player's base (unboosted) combat levels.
 */
@Value
@Builder
@AllArgsConstructor
public class PlayerLevels
{
	int attack;
	int strength;
	int defence;
	int ranged;
	int magic;
	int prayer;
	int hitpoints;
	int slayer;

	public static PlayerLevels maxed()
	{
		return new PlayerLevels(99, 99, 99, 99, 99, 99, 99, 99);
	}

	/** Standard combat level from the base levels. */
	public int combatLevel()
	{
		double base = (defence + hitpoints + prayer / 2) / 4.0;
		double melee = 13 * (attack + strength) / 40.0;
		double range = 13 * (ranged * 3 / 2) / 40.0;
		double mage = 13 * (magic * 3 / 2) / 40.0;
		return (int) (base + Math.max(melee, Math.max(range, mage)));
	}

	/** Wear requirements use base levels, never potion boosts; ownership and locks do not bypass them. */
	public boolean canEquip(GearItem item)
	{
		return item.getAttackReq() <= attack && item.getStrengthReq() <= strength
			&& item.getDefenceReq() <= defence && item.getRangedReq() <= ranged
			&& item.getMagicReq() <= magic && item.getPrayerReq() <= prayer
			&& item.getHitpointsReq() <= hitpoints && item.getSlayerReq() <= slayer
			&& item.getCombatReq() <= combatLevel();
	}

	/** The wear requirements these levels miss, e.g. "75 Ranged (you have 70)", or null if none. */
	public String missingRequirements(GearItem item)
	{
		List<String> missing = new ArrayList<>();
		missing(missing, item.getAttackReq(), attack, "Attack");
		missing(missing, item.getStrengthReq(), strength, "Strength");
		missing(missing, item.getDefenceReq(), defence, "Defence");
		missing(missing, item.getRangedReq(), ranged, "Ranged");
		missing(missing, item.getMagicReq(), magic, "Magic");
		missing(missing, item.getPrayerReq(), prayer, "Prayer");
		missing(missing, item.getHitpointsReq(), hitpoints, "Hitpoints");
		missing(missing, item.getSlayerReq(), slayer, "Slayer");
		missing(missing, item.getCombatReq(), combatLevel(), "combat");
		return missing.isEmpty() ? null : String.join(", ", missing);
	}

	private static void missing(List<String> out, int required, int level, String skill)
	{
		if (required > level)
		{
			out.add(required + " " + skill + " (you have " + level + ")");
		}
	}
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.GameData;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.Potion;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.function.Predicate;

/**
 * Resolves the user's potion choice for a combat class into boosted levels.
 * A choice is "best" (strongest potion usable anywhere, plus the raid's own supplies such as overloads and
 * smelling salts when the target is in that raid; never NMZ / Deadman only), "none", or a potion name from the
 * potion table. "Best" can be narrowed further, e.g. to owned
 * boosts; a potion chosen by name is always used.
 */
public final class PotionChoice
{
	public static final String BEST = "best";
	public static final String NONE = "none";

	private PotionChoice()
	{
	}

	/** Skills each combat class boosts. */
	public static List<String> skillsFor(com.bestgearsetup.data.CombatClass cls)
	{
		switch (cls)
		{
			case RANGED:
				return Arrays.asList("ranged");
			case MAGIC:
				return Arrays.asList("magic");
			default:
				return Arrays.asList("attack", "strength");
		}
	}

	/** Potion names selectable for a combat class, in data order. */
	public static List<String> namesFor(GameData data, com.bestgearsetup.data.CombatClass cls)
	{
		Set<String> names = new LinkedHashSet<>();
		for (String skill : skillsFor(cls))
		{
			for (Potion p : data.getPotions(skill))
			{
				if (p.getPercentageIncrease() >= 0 && p.getBaseIncrease() >= 0)
				{
					names.add(p.getName());
				}
			}
		}
		return new ArrayList<>(names);
	}

	/** Boosted level for one skill under the given choice. */
	public static int boostedLevel(GameData data, String skill, int level, String choice)
	{
		return boostedLevel(data, skill, level, choice, p -> true);
	}

	/** Boosted level for one skill; "best" only considers potions {@code available} accepts. */
	public static int boostedLevel(GameData data, String skill, int level, String choice, Predicate<Potion> available)
	{
		return boostedLevel(data, skill, level, choice, available, null);
	}

	/** As above; "best" also considers raid supplies usable against {@code target} (null for none). */
	public static int boostedLevel(GameData data, String skill, int level, String choice, Predicate<Potion> available,
		Monster target)
	{
		Potion p = resolve(data, skill, level, choice, available, target);
		return p == null ? level : p.boost(level);
	}

	/** The potion a choice resolves to for a skill, or null for none / no boost. */
	public static Potion resolve(GameData data, String skill, int level, String choice)
	{
		return resolve(data, skill, level, choice, p -> true);
	}

	/** As {@link #resolve(GameData, String, int, String)}; "best" only considers potions {@code available} accepts. */
	public static Potion resolve(GameData data, String skill, int level, String choice, Predicate<Potion> available)
	{
		return resolve(data, skill, level, choice, available, null);
	}

	/**
	 * As {@link #resolve(GameData, String, int, String, Predicate)}; "best" also considers raid supplies usable
	 * against {@code target} (null for none).
	 */
	public static Potion resolve(GameData data, String skill, int level, String choice, Predicate<Potion> available,
		Monster target)
	{
		String c = choice == null ? BEST : choice.trim().toLowerCase(Locale.ROOT);
		if (c.equals(NONE))
		{
			return null;
		}
		Potion best = null;
		int bestLevel = level;
		for (Potion p : data.getPotions(skill))
		{
			boolean match = c.equals(BEST) ? bestCandidate(p, target) && available.test(p) : p.getName().equalsIgnoreCase(c);
			if (match && p.boost(level) > bestLevel)
			{
				best = p;
				bestLevel = p.boost(level);
			}
		}
		return best;
	}

	private static boolean bestCandidate(Potion p, Monster target)
	{
		return p.isUnrestricted() || target != null && p.isRaidSupply() && restriction(p, target) == null;
	}

	/** Whether the choice names a potion rather than "best" or "none". */
	public static boolean isExplicit(String choice)
	{
		String c = choice == null ? BEST : choice.trim().toLowerCase(Locale.ROOT);
		return !c.equals(BEST) && !c.equals(NONE);
	}

	/**
	 * Where a restricted potion can be used, if the target isn't there (e.g. smelling salts outside the Tombs of
	 * Amascut), or null when it applies to this fight.
	 */
	public static String restriction(Potion potion, Monster target)
	{
		for (String attribute : potion.getAttributes())
		{
			switch (attribute.toLowerCase(Locale.ROOT))
			{
				case "tombs of amascut":
					if (!CombatRules.toa(target))
					{
						return "only usable in the Tombs of Amascut";
					}
					break;
				case "xerician":
					if (!target.hasAttribute("xerician"))
					{
						return "only usable in the Chambers of Xeric";
					}
					break;
				case "nmz":
					return "only usable in Nightmare Zone";
				case "deadman":
					return "only usable in Deadman mode";
				default:
					return "restricted (" + attribute + ")";
			}
		}
		return null;
	}

	/** Display name of the potion a choice resolves to for a skill, or null. */
	public static String describe(GameData data, String skill, int level, String choice)
	{
		Potion p = resolve(data, skill, level, choice);
		return p == null ? null : GameData.titleCase(p.getName());
	}
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.Monster;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import lombok.Builder;
import lombok.Value;

/**
 * Raid stat scaling, applied to the solo, unscaled raid records before health states and pre-fight drains.
 * Theatre of Blood and Tombs of Amascut follow their Wiki pages; the Chambers of Xeric values follow the
 * OSRS Wiki DPS calculator (lib/scaling at the audited revision), as the Wiki pages do not state them.
 * Chambers of Xeric scales levels and HP, Theatre of Blood scales HP, and Tombs of Amascut scales HP
 * and multiplies the target's defence roll by its raid level.
 */
public final class RaidScaling
{
	private static final int COX_CM_PERCENT = 50;

	private RaidScaling()
	{
	}

	/** Party inputs. CoX uses the highest party combat and HP levels, normally the player's own. */
	@Value
	@Builder(toBuilder = true)
	public static class Settings
	{
		public static final Settings SOLO = Settings.builder().build();

		@Builder.Default
		int partySize = 1;
		int toaRaidLevel;
		int toaPathLevel;
		boolean coxChallengeMode;
		@Builder.Default
		int partyMaxCombat = 126;
		@Builder.Default
		int partyMaxHitpoints = 99;
		/** Average party Mining level, used for CoX guardian HP. */
		@Builder.Default
		int partyAverageMining = 99;
	}

	public enum Raid
	{
		NONE, COX, TOB, TOB_ENTRY, TOA
	}

	public static Raid raid(Monster m)
	{
		if (m.hasAttribute("xerician"))
		{
			return Raid.COX;
		}
		String name = m.getLowerName();
		int id = m.getId();
		if (m.hasAttribute("theatre of blood"))
		{
			// Names take priority: some ToB variant IDs are shared between modes.
			boolean entry = name.contains("entry") || name.contains("story")
				|| !name.contains("normal") && !name.contains("hard") && TOB_ENTRY_IDS.contains(id);
			return entry ? Raid.TOB_ENTRY : Raid.TOB;
		}
		return toaScaled(m) ? Raid.TOA : Raid.NONE;
	}

	/** Returns a scaled copy; the cached API monster is never changed. */
	public static Monster apply(Monster base, Settings s)
	{
		Monster m = base.copy();
		switch (raid(base))
		{
			case COX:
				cox(m, s);
				break;
			case TOB:
				m.setHitpoints(m.getHitpoints() * tobHitpointsPerMille(s.getPartySize()) / 1000);
				break;
			case TOB_ENTRY:
				m.setHitpoints(m.getHitpoints() * ENTRY_FORTIETHS[clamp(s.getPartySize(), 1, 5)] / 40);
				break;
			case TOA:
				toa(m, s);
				break;
			default:
				break;
		}
		return m;
	}

	/**
	 * Theatre of Blood (Wiki "Theatre of Blood"): bosses have 75% of their hitpoints with three or fewer
	 * players, 87.5% with four and 100% with five.
	 */
	private static int tobHitpointsPerMille(int party)
	{
		return party >= 5 ? 1000 : party == 4 ? 875 : 750;
	}

	/** Entry mode hitpoints in fortieths for one to five players (game values; the Wiki gives no table). */
	private static final int[] ENTRY_FORTIETHS = {0, 10, 19, 27, 34, 40};

	// ------------------------------------------------------------------ Tombs of Amascut

	/**
	 * Tombs of Amascut hitpoints (Wiki "Tombs of Amascut"), applied in order: +2% per 5 raid levels; +8% for
	 * the first path level and +5% per further level; +90% of the base for each of the 2nd and 3rd party
	 * members and +60% for each member after that. The ejected Wardens' core (4,500 hitpoints, +0.1% per raid
	 * level) and the final rounding (to 5 above 100 hitpoints, to 10 above 300) are game values the Wiki pages
	 * do not state.
	 */
	private static void toa(Monster m, Settings s)
	{
		boolean core = CombatRules.wardenCore(m);
		int hp = core ? 4500 : m.getHitpoints();
		int raidLevel = clamp(s.getToaRaidLevel(), 0, 600);
		int raidPercent = core ? raidLevel / 10 : raidLevel * 2 / 5;
		hp += hp * raidPercent / 100;
		int path = clamp(s.getToaPathLevel(), 0, 6);
		if (toaPath(m) && path >= 1)
		{
			int pathPercent = 8 + 5 * (path - 1);
			hp = hp * (100 + pathPercent) / 100;
		}
		int party = clamp(s.getPartySize(), 1, 8);
		int partyPercent = 90 * Math.min(party - 1, 2) + 60 * Math.max(party - 3, 0);
		hp = hp * (100 + partyPercent) / 100;
		if (hp > 100)
		{
			hp = roundToNearest(hp, hp > 300 ? 10 : 5);
		}
		m.setHitpoints(hp);
		// Kephri's overlord scarabs keep their HP scaling but not the defence-roll multiplier.
		m.setToaRaidLevel(overlord(m) ? 0 : raidLevel);
	}

	/** The reference scales ToA bosses and their path minions, not puzzle-room NPCs such as baboons. */
	static boolean toaScaled(Monster m)
	{
		String name = m.getLowerName();
		int id = m.getId();
		if (!CombatRules.toa(m) && !(id >= 11719 && id <= 11764 || id >= 11778 && id <= 11797))
		{
			return false;
		}
		return toaPath(m) || name.contains("warden") || name.startsWith("obelisk")
			|| id >= 11750 && id <= 11764 && !name.contains("baboon");
	}

	/** Whether this ToA target is affected by path levels. */
	public static boolean toaPath(Monster m)
	{
		String name = m.getLowerName();
		return name.startsWith("akkha") || name.startsWith("ba-ba") || name.startsWith("kephri")
			|| name.startsWith("zebak") || overlord(m);
	}

	static boolean overlord(Monster m)
	{
		String name = m.getLowerName();
		return name.startsWith("soldier scarab") || name.startsWith("spitting scarab")
			|| name.startsWith("arcane scarab");
	}

	// ------------------------------------------------------------------ Theatre of Blood

	/** Entry-mode IDs from the reference calculator, used only when the name does not identify the mode. */
	private static final Set<Integer> TOB_ENTRY_IDS = new HashSet<>(Arrays.asList(
		10814, 10815, 10816, 10817, 10818, 10819, 10820, 10821, 10812, 10774, 10775, 10776, 10777, 10778, 10779,
		10780, 10781, 10782, 10783, 10784, 10785, 10787, 10788, 10789, 10864, 10865, 10767, 10768, 10833, 10834,
		10835, 10837, 10841, 10842, 10843, 10844, 10845));

	// ------------------------------------------------------------------ Chambers of Xeric

	/*
	 * Chambers of Xeric. The Wiki pages say only that monsters scale with the party; these are the game's values
	 * as implemented by the OSRS Wiki DPS calculator at the audited revision. Each target has two linked level
	 * groups that scale as one: offence (Attack, Strength, Ranged, and Magic unless Magic counts as defence) and
	 * defence (Defence, plus Magic where it is defensive). A level of 1 never scales. Every step truncates.
	 */

	/** Party-scaled offence, as a percentage, by the number of extra party members. */
	private static int coxOffencePercent(int extraMembers)
	{
		return 100 + 7 * isqrt(extraMembers) + extraMembers;
	}

	/** Party-scaled defence, as a percentage, by the number of extra party members. */
	private static int coxDefencePercent(int extraMembers)
	{
		return 100 + isqrt(extraMembers) + extraMembers * 7 / 10;
	}

	private static void cox(Monster m, Settings s)
	{
		boolean magicDefends = coxMagicIsDefensive(m);
		int offence = highestScalingLevel(m.getAttackLevel(), m.getStrengthLevel(), m.getRangedLevel(),
			magicDefends ? 1 : m.getMagicLevel());
		int defence = highestScalingLevel(m.getDefenceLevel(), magicDefends ? m.getMagicLevel() : 1);
		boolean guardian = EncounterDamage.guardian(m) || EncounterDamage.named(m, "guardian");
		int hp = guardian ? 151 + clamp(s.getPartyAverageMining(), 1, 99) : m.getHitpoints();

		int[] scaled = coxScaledAlone(m) ? coxSolo(offence, defence, hp, s) : coxParty(m, offence, defence, hp, s);
		offence = scaled[0];
		defence = scaled[1];
		m.setHitpoints(scaled[2]);
		m.setAttackLevel(m.getAttackLevel() == 1 ? 1 : offence);
		m.setStrengthLevel(m.getStrengthLevel() == 1 ? 1 : offence);
		m.setRangedLevel(m.getRangedLevel() == 1 ? 1 : offence);
		m.setDefenceLevel(m.getDefenceLevel() == 1 ? 1 : defence);
		m.setMagicLevel(m.getMagicLevel() == 1 ? 1 : magicDefends ? defence : offence);

		if (olm(m))
		{
			// Olm's hitpoints replace the scaled value: a base per part plus a share per member, less three
			// members' worth for each extra phase (one per eight players). The mage hand's Magic is halved.
			int party = clamp(s.getPartySize(), 1, 100);
			int members = Math.min(party - 1, 50) - 3 * (Math.min(party, 50) / 8);
			m.setHitpoints(olmHand(m) ? 600 + 300 * members : 800 + 400 * members);
			if (olmMageHand(m))
			{
				m.setMagicLevel(m.getMagicLevel() / 2);
			}
		}
	}

	/** Scavenger beasts and vespine soldiers scale with the party's levels only, not its size. */
	private static int[] coxSolo(int offence, int defence, int hp, Settings s)
	{
		int levelScale = clamp(s.getPartyMaxHitpoints(), 55, 99);
		int hpScale = clamp(s.getPartyMaxCombat(), 60, 126);
		if (s.isCoxChallengeMode())
		{
			levelScale = addPercent(levelScale, COX_CM_PERCENT);
			hpScale = addPercent(hpScale, COX_CM_PERCENT);
		}
		return new int[]{
			Math.max(1, offence * levelScale / 99),
			Math.max(1, defence * levelScale / 99),
			Math.max(5, hp * hpScale / 126),
		};
	}

	/** Everything else scales with the party's highest levels and its size. */
	private static int[] coxParty(Monster m, int offence, int defence, int hp, Settings s)
	{
		int party = clamp(s.getPartySize(), 1, 100);
		int extra = party - 1;
		// The highest Hitpoints level maps onto 55-99 for levels; the highest combat level (60-126) scales HP.
		int levelScale = clamp(55 + 44 * s.getPartyMaxHitpoints() / 99, 55, 99);
		int hpScale = clamp(s.getPartyMaxCombat(), 60, 126);

		offence = (offence * levelScale / 99) * coxOffencePercent(extra) / 100;
		defence = (defence * levelScale / 99) * coxDefencePercent(extra) / 100;
		hp = hp * hpScale / 126;
		hp += hp * (party / 2);

		if (s.isCoxChallengeMode())
		{
			// Challenge Mode: +50% to everything, except that Tekton's defence gains 20% (35% from four players)
			// and the glowing crystal keeps its hitpoints and defence.
			boolean crystal = EncounterDamage.crystal(m);
			offence = addPercent(offence, COX_CM_PERCENT);
			if (!crystal)
			{
				hp = addPercent(hp, COX_CM_PERCENT);
				defence = addPercent(defence, EncounterDamage.tekton(m) ? party < 4 ? 20 : 35 : COX_CM_PERCENT);
			}
		}
		return new int[]{clamp(offence, 50, 5_000), clamp(defence, 50, 20_000), clamp(hp, 50, 30_000)};
	}

	/** The highest of the linked levels that are not 1, or 1 if all are. */
	private static int highestScalingLevel(int... levels)
	{
		int highest = 1;
		for (int level : levels)
		{
			if (level != 1)
			{
				highest = Math.max(highest, level);
			}
		}
		return highest;
	}

	/** Targets whose Magic level counts as a defensive level. */
	private static boolean coxMagicIsDefensive(Monster m)
	{
		String name = m.getLowerName();
		int id = m.getId();
		return EncounterDamage.tekton(m) || olmHand(m) || id == 7533 || id == 7559
			|| id >= 7530 && id <= 7532 || id == 7538 || id == 7539 || name.startsWith("abyssal portal")
			|| name.startsWith("deathly ranger") || EncounterDamage.named(m, "vespula")
			|| name.startsWith("vespine soldier");
	}

	private static boolean coxScaledAlone(Monster m)
	{
		String name = m.getLowerName();
		int id = m.getId();
		return id == 7548 || id == 7549 || id == 7538 || id == 7539
			|| name.startsWith("scavenger beast") || name.startsWith("vespine soldier");
	}

	private static int isqrt(int value)
	{
		return (int) Math.sqrt(value);
	}

	private static boolean olm(Monster m)
	{
		int id = m.getId();
		return id >= 7550 && id <= 7555 || m.getLowerName().startsWith("great olm");
	}

	private static boolean olmHand(Monster m)
	{
		String name = m.getLowerName();
		int id = m.getId();
		return olm(m) && (name.contains("hand") || !name.startsWith("great olm") && id != 7551 && id != 7554);
	}

	private static boolean olmMageHand(Monster m)
	{
		String name = m.getLowerName();
		int id = m.getId();
		return name.contains("mage hand") || !name.startsWith("great olm") && (id == 7550 || id == 7553);
	}

	// ------------------------------------------------------------------ helpers

	/** One-line summary of the applied scaling, or null for non-raid targets. */
	public static String describe(Monster base, Monster scaled, Settings s)
	{
		switch (raid(base))
		{
			case COX:
				return String.format("CoX scaling: party %d, highest combat %d, highest HP %d%s; HP %d -> %d, Defence %d -> %d.",
					clamp(s.getPartySize(), 1, 100), clamp(s.getPartyMaxCombat(), 3, 126), s.getPartyMaxHitpoints(),
					s.isCoxChallengeMode() ? ", Challenge Mode" : "", base.getHitpoints(), scaled.getHitpoints(),
					base.getDefenceLevel(), scaled.getDefenceLevel());
			case TOB:
			case TOB_ENTRY:
				return String.format("ToB %sHP scaling: party %d (%s); HP %d -> %d.",
					raid(base) == Raid.TOB_ENTRY ? "entry-mode " : "", s.getPartySize(),
					raid(base) == Raid.TOB_ENTRY ? "1-5" : "below 3 counts as 3",
					base.getHitpoints(), scaled.getHitpoints());
			case TOA:
				return String.format("ToA scaling: raid level %d, path level %d, party %d; HP %d -> %d%s.",
					clamp(s.getToaRaidLevel(), 0, 600), clamp(s.getToaPathLevel(), 0, 6), clamp(s.getPartySize(), 1, 8),
					base.getHitpoints(), scaled.getHitpoints(),
					scaled.getToaRaidLevel() > 0 ? ", defence roll x" + (250 + scaled.getToaRaidLevel()) + "/250" : "");
			default:
				if (CombatRules.toa(base))
				{
					return "ToA: this puzzle-room target uses its unscaled stats.";
				}
				return null;
		}
	}

	private static int roundToNearest(int value, int step)
	{
		return (value + step / 2) / step * step;
	}

	private static int addPercent(int value, int percent)
	{
		return value + value * percent / 100;
	}

	private static int clamp(int value, int min, int max)
	{
		return Math.max(min, Math.min(max, value));
	}
}

package com.bestgearsetup.calc;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Speed / thoroughness trade-off for the optimiser.
 */
@Getter
@RequiredArgsConstructor
public enum SearchDepth
{
	FAST("Fast"),
	NORMAL("Normal"),
	BEST("Best (slowest)");

	private final String displayName;

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.bestgearsetup.calc;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum SearchMode
{
	OWNED_ONLY("Owned items only"),
	BUDGET("Owned + budget"),
	UNLIMITED("Best in slot (no limit)");

	private final String displayName;

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.Slot;
import java.util.Collections;
import java.util.Set;
import lombok.Value;

@Value
public class SetupResult
{
	CombatClass combatClass;
	Loadout loadout;
	DpsResult dps;
	/** GP needed to buy the items in this setup that the player does not own. */
	long buyCost;
	/** Items to buy that have no current price; when positive, {@link #buyCost} is a lower bound. */
	int unpricedItems;
	/** Slots filled for prayer / defence rather than DPS. */
	Set<Slot> filledSlots;
	/** Thrall, Mark of Darkness or Charge spells this setup's DPS assumes are cast. */
	Set<SupportSpell> supportSpells;
	/** Special attack used during the kill and already counted in {@link #dps}; null when none helps. */
	SpecialPlan special;

	/** Stab / slash / crush / ranged / magic / atlatl: the result tab this setup belongs to. */
	public AttackStyle.Type getAttackType()
	{
		return loadout.getStyle() == null ? null : WeaponRules.tabType(loadout.getWeapon(), loadout.getStyle());
	}

	public SetupResult(CombatClass combatClass, Loadout loadout, DpsResult dps, long buyCost)
	{
		this(combatClass, loadout, dps, buyCost, 0, Collections.emptySet());
	}

	public SetupResult(CombatClass combatClass, Loadout loadout, DpsResult dps, long buyCost, int unpricedItems,
		Set<Slot> filledSlots)
	{
		this(combatClass, loadout, dps, buyCost, unpricedItems, filledSlots, Collections.emptySet());
	}

	public SetupResult(CombatClass combatClass, Loadout loadout, DpsResult dps, long buyCost, int unpricedItems,
		Set<Slot> filledSlots, Set<SupportSpell> supportSpells)
	{
		this(combatClass, loadout, dps, buyCost, unpricedItems, filledSlots, supportSpells, null);
	}

	public SetupResult(CombatClass combatClass, Loadout loadout, DpsResult dps, long buyCost, int unpricedItems,
		Set<Slot> filledSlots, Set<SupportSpell> supportSpells, SpecialPlan special)
	{
		this.combatClass = combatClass;
		this.loadout = loadout;
		this.dps = dps;
		this.buyCost = buyCost;
		this.unpricedItems = unpricedItems;
		this.filledSlots = filledSlots;
		this.supportSpells = supportSpells;
		this.special = special;
	}
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.Slot;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.function.Predicate;

/**
 * Protective equipment some Slayer monsters require, on or off task: without it they drain stats and hit
 * constantly, or can't be damaged at all, so no unprotected setup is usable. Each rule follows the monster's
 * OSRS Wiki page; superior variants share their base monster's rule. Requirements that are only recommended
 * (insulated boots, slayer gloves, witchwood icon) or only needed to start a fight (wall beasts) are notes.
 */
public final class SlayerEquipment
{
	private static final Predicate<String> SLAYER_HELMET = n -> n.contains("slayer helmet");
	private static final Predicate<String> KARUULM_ONLY = names(
		"hydra", "colossal hydra", "alchemical hydra", "drake", "guardian drake", "sulphur lizard");
	private static final Predicate<String> WYRMS = names("wyrm", "shadow wyrm");
	private static final List<Rule> RULES = Collections.unmodifiableList(Arrays.asList(
		new Rule(Slot.HEAD, "a facemask or slayer helmet", false,
			names("dust devil", "choke devil", "smoke devil", "nuclear smoke devil", "thermonuclear smoke devil"),
			SLAYER_HELMET.or(n -> n.equals("facemask"))),
		new Rule(Slot.HEAD, "earmuffs or a slayer helmet", false,
			names("banshee", "twisted banshee", "screaming banshee", "screaming twisted banshee"),
			SLAYER_HELMET.or(n -> n.equals("earmuffs"))),
		new Rule(Slot.HEAD, "a nose peg or slayer helmet", false,
			names("aberrant spectre", "deviant spectre", "abhorrent spectre", "repugnant spectre"),
			SLAYER_HELMET.or(n -> n.equals("nose peg"))),
		new Rule(Slot.HEAD, "reinforced goggles or a slayer helmet", false, n -> n.equals("sourhog"),
			SLAYER_HELMET.or(n -> n.equals("reinforced goggles"))),
		// During A Porcine of Interest Spria hands over the goggles first; slayer helmets only gain their
		// protection when the quest is complete, so the quest's sourhog needs the goggles themselves.
		new Rule(Slot.HEAD, "reinforced goggles", false, n -> n.equals("sourhog (a porcine of interest)"),
			n -> n.equals("reinforced goggles")),
		new Rule(Slot.SHIELD, "a mirror shield or V's shield", false,
			names("basilisk", "basilisk knight", "basilisk sentinel", "monstrous basilisk", "cockatrice", "cockathrice"),
			n -> n.equals("mirror shield") || n.equals("v's shield")),
		// The Wiki names only the mirror shield for younglings.
		new Rule(Slot.SHIELD, "a mirror shield", false, names("basilisk youngling"), n -> n.equals("mirror shield")),
		new Rule(Slot.SHIELD, "a lit bug lantern", false, names("harpie bug swarm"), n -> n.equals("lit bug lantern")),
		// Wyrms share this rule only when the search location is Karuulm.
		new Rule(Slot.FEET, "boots of stone, boots of brimstone or granite boots", true,
			KARUULM_ONLY.or(WYRMS),
			n -> n.equals("boots of stone") || n.equals("boots of brimstone") || n.equals("granite boots"))));

	private SlayerEquipment()
	{
	}

	/** Names equal to one of the bases or a base followed by a parenthesised version. */
	private static Predicate<String> names(String... bases)
	{
		return n ->
		{
			for (String base : bases)
			{
				if (EncounterDamage.versionOf(n, base))
				{
					return true;
				}
			}
			return false;
		};
	}

	/** The rules this target imposes under these settings. */
	private static List<Rule> rules(Monster monster, OptimizerSettings settings)
	{
		String name = monster.getLowerName();
		List<Rule> out = new ArrayList<>();
		for (Rule rule : RULES)
		{
			if (rule.monster.test(name)
				&& !(rule.karuulm && (settings.isKourendEliteDiary() || !inKaruulm(monster, settings))))
			{
				out.add(rule);
			}
		}
		return out;
	}

	/** Whether the target lives only inside the Karuulm Slayer Dungeon, where heat-protection boots apply. */
	public static boolean inKaruulm(Monster monster)
	{
		String name = monster.getLowerName();
		return KARUULM_ONLY.test(name);
	}

	/** Whether heat-protection boots apply at this search's target location, before the diary exemption. */
	public static boolean inKaruulm(Monster monster, OptimizerSettings settings)
	{
		return inKaruulm(monster) || settings.isKaruulmDungeon() && WYRMS.test(monster.getLowerName());
	}

	/** Whether the target requires protective equipment in any slot. */
	public static boolean applies(Monster monster, OptimizerSettings settings)
	{
		return !rules(monster, settings).isEmpty();
	}

	/** Whether the item satisfies one of this target's requirements, so it must stay a search candidate. */
	static boolean isRequired(Monster monster, OptimizerSettings settings, GearItem item)
	{
		for (Rule rule : rules(monster, settings))
		{
			if (rule.satisfiedBy(item))
			{
				return true;
			}
		}
		return false;
	}

	static boolean allowed(Monster monster, OptimizerSettings settings, Loadout loadout)
	{
		for (Rule rule : rules(monster, settings))
		{
			GearItem worn = loadout.get(rule.slot);
			if (rule.slot == Slot.SHIELD && loadout.getWeapon() != null && loadout.getWeapon().isTwoHanded())
			{
				worn = null;
			}
			if (!rule.satisfiedBy(worn))
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * Why a slot lock leaves out required equipment, or null if it doesn't.
	 *
	 * @param item the locked item, or null for an empty / fill lock
	 */
	static String lockConflict(Monster monster, OptimizerSettings settings, Slot slot, GearItem item)
	{
		for (Rule rule : rules(monster, settings))
		{
			if (rule.slot == slot && !rule.satisfiedBy(item))
			{
				return monster.getDisplayName() + " requires " + rule.items + " in the "
					+ slot.getDisplayName().toLowerCase(Locale.ROOT) + " slot";
			}
		}
		return null;
	}

	/** Summaries for the search details: enforced requirements plus related mechanics that are not enforced. */
	public static List<String> notes(Monster monster, OptimizerSettings settings)
	{
		String name = monster.getLowerName();
		List<String> notes = new ArrayList<>();
		for (Rule rule : rules(monster, settings))
		{
			notes.add("Required equipment: every setup wears " + rule.items + " ("
				+ rule.slot.getDisplayName().toLowerCase(Locale.ROOT) + "), on or off task"
				+ (rule.slot == Slot.SHIELD ? ", so two-handed weapons are excluded." : ".")
				+ (rule.karuulm ? " The Elite Kourend & Kebos Diary removes the boots requirement." : ""));
		}
		if (inKaruulm(monster, settings) && settings.isKourendEliteDiary())
		{
			notes.add("Karuulm Slayer Dungeon: no heat-protection boots needed (Elite Kourend & Kebos Diary complete).");
		}
		if (WYRMS.test(name) && !inKaruulm(monster, settings))
		{
			notes.add("Wyrms in the Karuulm Slayer Dungeon need boots of stone, boots of brimstone or granite boots"
				+ " (unless the Elite Kourend & Kebos Diary is complete); Wyrmscraig wyrms don't, so boots are not enforced.");
		}
		if (names("wall beast").test(name))
		{
			notes.add("Wall beasts: a spiny helmet or slayer helmet is needed only to start the fight, so the head slot"
				+ " is not restricted.");
		}
		return notes;
	}

	private static final class Rule
	{
		private final Slot slot;
		private final String items;
		/** Waived by the Elite Kourend & Kebos Diary. */
		private final boolean karuulm;
		private final Predicate<String> monster;
		private final Predicate<String> item;

		private Rule(Slot slot, String items, boolean karuulm, Predicate<String> monster, Predicate<String> item)
		{
			this.slot = slot;
			this.items = items;
			this.karuulm = karuulm;
			this.monster = monster;
			this.item = item;
		}

		private boolean satisfiedBy(GearItem worn)
		{
			return worn != null && (worn.getSlot() == null || worn.getSlot() == slot) && item.test(worn.getLowerCombatName());
		}
	}
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.Slot;
import java.util.EnumMap;
import java.util.Map;
import lombok.Value;

/**
 * A user constraint on one equipment slot: a specific item, always empty, or always filled with
 * the fill-mode item (prayer / defence) even when that costs DPS.
 */
@Value
public class SlotLock
{
	public enum Kind
	{
		ITEM, EMPTY, FILL
	}

	Kind kind;
	/** Item id for {@link Kind#ITEM}, otherwise 0. */
	int itemId;

	public static SlotLock item(int id)
	{
		return new SlotLock(Kind.ITEM, id);
	}

	public static SlotLock empty()
	{
		return new SlotLock(Kind.EMPTY, 0);
	}

	public static SlotLock fill()
	{
		return new SlotLock(Kind.FILL, 0);
	}

	/** Serialise as "WEAPON:4151,SHIELD:empty,BODY:fill". */
	public static String format(Map<Slot, SlotLock> locks)
	{
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<Slot, SlotLock> e : locks.entrySet())
		{
			if (sb.length() > 0)
			{
				sb.append(',');
			}
			SlotLock l = e.getValue();
			sb.append(e.getKey().name()).append(':')
				.append(l.kind == Kind.ITEM ? String.valueOf(l.itemId) : l.kind.name().toLowerCase());
		}
		return sb.toString();
	}

	public static Map<Slot, SlotLock> parse(String text)
	{
		Map<Slot, SlotLock> out = new EnumMap<>(Slot.class);
		if (text == null || text.trim().isEmpty())
		{
			return out;
		}
		for (String part : text.split(","))
		{
			String[] kv = part.trim().split(":");
			if (kv.length != 2)
			{
				continue;
			}
			try
			{
				Slot slot = Slot.valueOf(kv[0].trim());
				String v = kv[1].trim();
				if (v.equalsIgnoreCase("empty"))
				{
					out.put(slot, empty());
				}
				else if (v.equalsIgnoreCase("fill"))
				{
					out.put(slot, fill());
				}
				else
				{
					out.put(slot, item(Integer.parseInt(v)));
				}
			}
			catch (IllegalArgumentException ignored)
			{
				// skip malformed entries (NumberFormatException is an IllegalArgumentException)
			}
		}
		return out;
	}
}

package com.bestgearsetup.calc;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

