package com.bestgearsetup.calc;

import com.bestgearsetup.data.GameData;
import com.bestgearsetup.data.GearItem;
import java.util.Locale;
import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.Getter;

/**
 * A weapon's damaging special attack. Formulas follow the OSRS Wiki calculator (PlayerVsNPCCalc,
 * dists/claws and dists/bolts at the audited revision); specials it does not implement follow each
 * weapon's Wiki page.
 * Specs without a damage effect return null.
 */
@Getter
@AllArgsConstructor(access = AccessLevel.PRIVATE)
public final class SpecialAttack
{
	/** How the spec's hits are built from the accuracy and min/max roll. */
	public enum Kind
	{
		/** One ordinary roll. */
		SINGLE,
		/** Several independent ordinary rolls. */
		MULTI,
		/** Second hit always lands when the first does. */
		ABYSSAL_DAGGER,
		DRAGON_CLAWS,
		BURNING_CLAWS,
		/** Four accuracy rolls; successes raise a single hit's range. */
		CRIMSON_KISTEN,
		/** Second hit on larger targets at three-quarters attack roll. */
		HALBERD,
		/** Extra 1-16 magic hit when the melee hit lands. */
		SARADOMIN_SWORD,
		/** +5 damage, including on misses. */
		GRANITE_HAMMER,
		/** One hit of 70% of the maximum. */
		SUNSPEAR,
		/** Two arrows with minimum damage on misses, each capped at 48. */
		DARK_BOW,
		/** Built-in ammunition-only max hit. */
		ARROW_FORMULA,
		/** Second hit against the Defence lowered by the first. */
		TONALZTICS,
		/** Two conditional hits with a raised minimum, and an attack-speed proc. */
		BLOOD_MOON,
		/** Damage range fixed at 75-150. */
		DAWNBRINGER,
		/** 50-150% of the maximum, always accurate, mitigated as Magic. */
		VOIDWAKER,
		/** Four hits at 40% of the maximum. */
		WEBWEAVER,
		/** Minimum and maximum raised by 6% per stack. */
		SOULREAPER,
		/** Fang's minimum without its reduced maximum; accuracy still rolls twice. */
		FANG,
	}

	/** Stat drain a landed special leaves on the target, matching the pre-fight drain options. */
	public enum Drain
	{
		NONE,
		/** -30% of current Defence (also Statius's warhammer). */
		DRAGON_WARHAMMER,
		/** -35% of current Defence. */
		ELDER_MAUL,
		ARCLIGHT,
		EMBERLIGHT,
		/** Defence lowered by an eighth of the target's Magic level; counted once per landed special. */
		TONALZTICS,
		/** Drains by the damage dealt: Defence, then Strength, Attack and Magic. */
		BANDOS_GODSWORD,
		/** Drains Magic by the damage dealt. */
		SEERCULL,
		/** Drains magic defence by the damage dealt. */
		EYE_OF_AYAK,
	}

	private final String name;
	private final int energy;
	private final Kind kind;
	private final int hits;
	private final int accuracyNumerator;
	private final int accuracyDenominator;
	/** Maximum-hit multipliers applied in order, each truncated: numerator, denominator pairs. */
	private final int[] damage;
	/** Defence rolled against: stab, slash, crush, ranged or magic; null keeps the active style. */
	private final String defence;
	/** Always accurate. */
	private final boolean guaranteed;
	/** Minimum hit as a percentage of the unscaled maximum (Statius's warhammer: 25-125%). */
	private final int minimumPercent;
	/** Ticks the special adds before the next attack (rune claws). */
	private final int extraTicks;
	private final Drain drain;

	private static SpecialAttack spec(String name, int energy, Kind kind, int hits, int accNum, int accDen,
		String defence, int... damage)
	{
		return new SpecialAttack(name, energy, kind, hits, accNum, accDen, damage, defence, false, 0, 0, Drain.NONE);
	}

	private SpecialAttack withMinimum(int percent)
	{
		return new SpecialAttack(name, energy, kind, hits, accuracyNumerator, accuracyDenominator, damage,
			defence, guaranteed, percent, extraTicks, drain);
	}

	private SpecialAttack withDelay(int ticks)
	{
		return new SpecialAttack(name, energy, kind, hits, accuracyNumerator, accuracyDenominator, damage,
			defence, guaranteed, minimumPercent, ticks, drain);
	}

	/** The minimum hit for a maximum before this special's damage multipliers. */
	long minimum(long unscaledMax)
	{
		return unscaledMax * minimumPercent / 100;
	}

	private static SpecialAttack single(String name, int energy, int accNum, int accDen, String defence, int... damage)
	{
		return spec(name, energy, Kind.SINGLE, 1, accNum, accDen, defence, damage);
	}

	private SpecialAttack alwaysHits()
	{
		return new SpecialAttack(name, energy, kind, hits, accuracyNumerator, accuracyDenominator, damage,
			defence, true, minimumPercent, extraTicks, drain);
	}

	private SpecialAttack draining(Drain effect)
	{
		return new SpecialAttack(name, energy, kind, hits, accuracyNumerator, accuracyDenominator, damage,
			defence, guaranteed, minimumPercent, extraTicks, effect);
	}

	/** Apply the maximum-hit multipliers in order. */
	long scaleMax(long max)
	{
		for (int i = 0; i + 1 < damage.length; i += 2)
		{
			max = max * damage[i] / damage[i + 1];
		}
		return max;
	}

	long scaleAccuracy(long roll)
	{
		return roll * accuracyNumerator / accuracyDenominator;
	}

	/** Spec for the loadout's weapon and attack class, or null when it has no damaging special attack. */
	public static SpecialAttack of(Loadout l, CombatContext ctx)
	{
		GearItem weapon = l.getWeapon();
		if (weapon == null || l.getStyle() == null)
		{
			return null;
		}
		String n = EncounterDamage.lower(weapon);
		AttackStyle.Type type = l.getStyle().getType();
		boolean melee = l.getStyle().isMelee();
		boolean ranged = type == AttackStyle.Type.RANGED;
		if (ranged && n.startsWith("scorching bow") && !ctx.getMonster().hasAttribute("demon"))
		{
			// Scorching shackles fail against non-demons.
			return null;
		}
		return melee ? melee(n, l, ctx) : ranged ? ranged(n, weapon) : magic(n);
	}

	private static SpecialAttack melee(String n, Loadout l, CombatContext ctx)
	{
		if (n.startsWith("abyssal dagger"))
		{
			return spec("Abyssal dagger", 25, Kind.ABYSSAL_DAGGER, 2, 5, 4, "slash", 17, 20);
		}
		if (n.startsWith("dragon dagger"))
		{
			return spec("Dragon dagger", 25, Kind.MULTI, 2, 23, 20, "slash", 23, 20);
		}
		if (n.startsWith("dragon longsword"))
		{
			return single("Dragon longsword", 25, 1, 1, "slash", 5, 4);
		}
		if (n.startsWith("dragon mace"))
		{
			return single("Dragon mace", 25, 5, 4, "crush", 3, 2);
		}
		if (n.startsWith("osmumten's fang"))
		{
			// The ordinary 15% minimum remains but the maximum is not reduced; accuracy still rolls twice.
			return spec("Osmumten's fang", 25, Kind.FANG, 1, 3, 2, null);
		}
		if (n.equals("dual macuahuitl") && EquipmentEffects.bloodMoon(l))
		{
			return spec("Dual macuahuitl", 25, Kind.BLOOD_MOON, 2, 1, 1, null, 1, 1);
		}
		if (n.startsWith("dragon halberd") || n.startsWith("crystal halberd"))
		{
			return spec(n.startsWith("dragon") ? "Dragon halberd" : "Crystal halberd", 30, Kind.HALBERD, 2, 1, 1,
				"slash", 11, 10);
		}
		if (n.startsWith("burning claws") || n.startsWith("bone claws"))
		{
			return spec("Burning claws", 35, Kind.BURNING_CLAWS, 3, 1, 1, "slash", 1, 1);
		}
		if (n.startsWith("arkan blade"))
		{
			return single("Arkan blade", 30, 3, 2, "slash", 3, 2);
		}
		if (n.startsWith("dragon sword"))
		{
			return single("Dragon sword", 40, 5, 4, "stab", 5, 4);
		}
		if (n.startsWith("elder maul"))
		{
			return single("Elder maul", 50, 5, 4, null, 1, 1).draining(Drain.ELDER_MAUL);
		}
		if (n.startsWith("dragon warhammer"))
		{
			return single("Dragon warhammer", 50, 1, 1, null, 3, 2).draining(Drain.DRAGON_WARHAMMER);
		}
		if (n.startsWith("bandos godsword"))
		{
			return single("Bandos godsword", 50, 2, 1, "slash", 11, 10, 11, 10).draining(Drain.BANDOS_GODSWORD);
		}
		if (n.startsWith("armadyl godsword"))
		{
			return single("Armadyl godsword", 50, 2, 1, "slash", 11, 10, 5, 4);
		}
		if (n.startsWith("saradomin godsword") || n.startsWith("zamorak godsword") || n.startsWith("ancient godsword"))
		{
			// Ancient godsword's delayed blood sacrifice damage is not included, as in the reference.
			return single(n.startsWith("saradomin") ? "Saradomin godsword" : n.startsWith("zamorak")
				? "Zamorak godsword" : "Ancient godsword", 50, 2, 1, "slash", 11, 10);
		}
		if (n.startsWith("arclight") || n.startsWith("emberlight"))
		{
			return single(n.startsWith("arclight") ? "Arclight" : "Emberlight", 50, 1, 1, "stab", 1, 1)
				.draining(n.startsWith("arclight") ? Drain.ARCLIGHT : Drain.EMBERLIGHT);
		}
		if (n.startsWith("dragon claws"))
		{
			return spec("Dragon claws", 50, Kind.DRAGON_CLAWS, 4, 1, 1, "slash", 1, 1);
		}
		if (n.startsWith("voidwaker"))
		{
			// 50-150% of the maximum; the hit is magical and always accurate.
			return spec("Voidwaker", 50, Kind.VOIDWAKER, 1, 1, 1, "magic").alwaysHits();
		}
		if (n.startsWith("abyssal bludgeon"))
		{
			// Damage rises with missing Prayer points, which are not tracked: full Prayer is assumed.
			return single("Abyssal bludgeon", 50, 1, 1, null, 1, 1);
		}
		if (n.startsWith("abyssal whip"))
		{
			return single("Abyssal whip", 50, 5, 4, null, 1, 1);
		}
		if (n.startsWith("barrelchest anchor"))
		{
			return single("Barrelchest anchor", 50, 2, 1, null, 110, 100);
		}
		if (n.startsWith("crimson kisten"))
		{
			return spec("Crimson kisten", 50, Kind.CRIMSON_KISTEN, 1, 1, 1, "crush", 1, 1);
		}
		if (n.equals("sunspear"))
		{
			return spec("Sunspear", 50, Kind.SUNSPEAR, 1, 1, 1, null, 7, 10);
		}
		if (n.startsWith("dragon scimitar"))
		{
			return single("Dragon scimitar", 55, 5, 4, "slash", 1, 1);
		}
		if (n.startsWith("granite hammer"))
		{
			return spec("Granite hammer", 60, Kind.GRANITE_HAMMER, 1, 3, 2, null, 1, 1);
		}
		if (n.startsWith("saradomin's blessed sword") || n.startsWith("sara's blessed sword"))
		{
			return single("Saradomin's blessed sword", 65, 1, 1, "magic", 5, 4);
		}
		if (n.startsWith("saradomin sword"))
		{
			return spec("Saradomin sword", 100, Kind.SARADOMIN_SWORD, 2, 1, 1, "slash", 11, 10);
		}
		if (n.startsWith("abyssal tentacle"))
		{
			// Binding Tentacle: an ordinary hit that also binds and may poison (not scored).
			return single("Abyssal tentacle", 50, 1, 1, null, 1, 1);
		}
		if (n.startsWith("ursine chainmace"))
		{
			// Bear Down: doubled accuracy against slash; the 20-damage bleed on a hit is not scored.
			return single("Ursine chainmace", 50, 2, 1, "slash", 1, 1);
		}
		if (n.startsWith("rune claws"))
		{
			// Impale: +10% damage, and the next attack comes one tick later.
			return single("Rune claws", 25, 1, 1, null, 11, 10).withDelay(1);
		}
		if (n.startsWith("dinh's bulwark") || n.startsWith("dinh's blazing bulwark"))
		{
			// Shield Bash: +20% accuracy against crush; extra targets in multicombat are not scored.
			return single("Dinh's bulwark", 50, 6, 5, "crush", 1, 1);
		}
		if (n.startsWith("statius's warhammer"))
		{
			// Smash: 25-125% of the maximum, and a hit lowers Defence by 30%.
			return single("Statius's warhammer", 35, 1, 1, null, 125, 100).withMinimum(25)
				.draining(Drain.DRAGON_WARHAMMER);
		}
		if (n.startsWith("vesta's longsword"))
		{
			// Feint: 20-120% of the maximum. Its accuracy against a quarter of the target's Defence is not modelled.
			return single("Vesta's longsword", 25, 1, 1, "stab", 120, 100).withMinimum(20);
		}
		if (n.startsWith("soulreaper axe"))
		{
			int stacks = Math.max(0, Math.min(5, ctx.getModifiers().getSoulreaperStacks()));
			// Uses the current stacks; with none it is not a damaging spec.
			return stacks == 0 ? null : spec("Soulreaper axe", 0, Kind.SOULREAPER, 1, 100 + 12 * stacks, 100,
				null);
		}
		return null;
	}

	private static SpecialAttack ranged(String n, GearItem weapon)
	{
		if (n.startsWith("armadyl crossbow"))
		{
			// Armadyl Eye doubles accuracy; its doubled enchanted-bolt chance is not modelled.
			return single("Armadyl crossbow", 50, 2, 1, null, 1, 1);
		}
		if (n.startsWith("morrigan's throwing axe"))
		{
			// Hamstring: 150% accuracy and 50-150% of the maximum.
			return single("Morrigan's throwing axe", 50, 3, 2, null, 150, 100).withMinimum(50);
		}
		if (n.startsWith("morrigan's javelin"))
		{
			// Phantom Strike: 150% accuracy; its bleed affects players only.
			return single("Morrigan's javelin", 50, 3, 2, null, 1, 1);
		}
		if (n.startsWith("zaryte crossbow"))
		{
			return single("Zaryte crossbow", 75, 2, 1, null, 1, 1);
		}
		if (n.startsWith("webweaver bow"))
		{
			return spec("Webweaver bow", 50, Kind.WEBWEAVER, 4, 2, 1, null);
		}
		if (n.startsWith("toxic blowpipe") || n.startsWith("blazing blowpipe"))
		{
			return single(n.startsWith("toxic") ? "Toxic blowpipe" : "Blazing blowpipe", 50, 2, 1, null, 3, 2);
		}
		if (n.startsWith("magic shortbow"))
		{
			return spec("Magic shortbow", n.contains("(i)") ? 50 : 55, Kind.ARROW_FORMULA, 2, 10, 7, null);
		}
		if (n.startsWith("magic longbow") || n.startsWith("magic comp bow") || n.equals("seercull"))
		{
			return spec(n.equals("seercull") ? "Seercull" : n.startsWith("magic comp") ? "Magic comp bow"
				: "Magic longbow", n.equals("seercull") ? 100 : 35, Kind.ARROW_FORMULA, 1, 1, 1, null).alwaysHits()
				.draining(n.equals("seercull") ? Drain.SEERCULL : Drain.NONE);
		}
		if (n.startsWith("heavy ballista") || n.startsWith("light ballista"))
		{
			return single(n.startsWith("heavy") ? "Heavy ballista" : "Light ballista", 65, 5, 4, null, 5, 4);
		}
		if (n.startsWith("dark bow"))
		{
			return spec("Dark bow", 55, Kind.DARK_BOW, 2, 1, 1, null, 1, 1);
		}
		if (n.startsWith("dragon knife") || n.startsWith("rosewood blowpipe"))
		{
			return spec(n.startsWith("dragon") ? "Dragon knife" : "Rosewood blowpipe", 25, Kind.MULTI, 2, 1, 1,
				null);
		}
		if (n.startsWith("scorching bow"))
		{
			return single("Scorching bow", 25, 1, 1, null, 1, 1);
		}
		if (n.startsWith("tonalztics of ralos"))
		{
			boolean charged = !n.contains("uncharged");
			return spec("Tonalztics of Ralos", 50, charged ? Kind.TONALZTICS : Kind.SINGLE, charged ? 2 : 1, 3, 2,
				null).draining(Drain.TONALZTICS);
		}
		return null;
	}

	private static SpecialAttack magic(String n)
	{
		if (n.startsWith("accursed sceptre"))
		{
			return single("Accursed sceptre", 50, 3, 2, null, 3, 2);
		}
		if (n.startsWith("volatile nightmare staff"))
		{
			return single("Volatile nightmare staff", 55, 3, 2, null, 1, 1);
		}
		if (n.startsWith("eldritch nightmare staff"))
		{
			return single("Eldritch nightmare staff", 55, 1, 1, null, 1, 1);
		}
		if (n.startsWith("eye of ayak"))
		{
			return single("Eye of Ayak", 50, 2, 1, null, 13, 10).draining(Drain.EYE_OF_AYAK);
		}
		if (n.equals("dawnbringer"))
		{
			return spec("Dawnbringer", 30, Kind.DAWNBRINGER, 1, 1, 1, null, 1, 1).alwaysHits();
		}
		return null;
	}

	/** Spec energy needed per attack; zero for Soulreaper, which spends stacks instead. */
	public String describe()
	{
		return name + " special" + (energy > 0 ? " (" + energy + "% energy)" : " (spends stacks)");
	}
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.Monster;
import lombok.Builder;
import lombok.Value;

/**
 * Stat-draining special attacks landed before the fight, applied in the following order
 * (vulnerability, elder maul, dragon warhammer, emberlight, arclight, tonalztics, seercull,
 * eye of ayak, bandos godsword). Counts are successful hits; the godsword, seercull and ayak
 * values are total damage dealt, since they drain by the damage.
 */
@Value
@Builder(toBuilder = true)
public class SpecialAttacks
{
	public static final SpecialAttacks NONE = SpecialAttacks.builder().build();

	/** Vulnerability (-10% Defence) or, with the tome of water, -15%. */
	boolean vulnerability;
	boolean tomeOfWater;
	int elderMaul;
	int dragonWarhammer;
	int emberlight;
	int arclight;
	int tonalztics;
	/** Damage dealt with seercull specials: drains Magic level. */
	int seercullDamage;
	/** Damage dealt with eye of ayak specials: drains magic defence. */
	int ayakDamage;
	/** Damage dealt with bandos godsword specials: drains Defence, then Strength, Attack, Magic. */
	int bandosGodswordDamage;

	/** These drains plus one more landed special that dealt the given damage. */
	public SpecialAttacks landed(SpecialAttack.Drain drain, int damage)
	{
		switch (drain)
		{
			case DRAGON_WARHAMMER:
				return toBuilder().dragonWarhammer(dragonWarhammer + 1).build();
			case ELDER_MAUL:
				return toBuilder().elderMaul(elderMaul + 1).build();
			case ARCLIGHT:
				return toBuilder().arclight(arclight + 1).build();
			case EMBERLIGHT:
				return toBuilder().emberlight(emberlight + 1).build();
			case TONALZTICS:
				return toBuilder().tonalztics(tonalztics + 1).build();
			case BANDOS_GODSWORD:
				return toBuilder().bandosGodswordDamage(bandosGodswordDamage + damage).build();
			case SEERCULL:
				return toBuilder().seercullDamage(seercullDamage + damage).build();
			case EYE_OF_AYAK:
				return toBuilder().ayakDamage(ayakDamage + damage).build();
			default:
				return this;
		}
	}

	public boolean isAny()
	{
		return vulnerability || elderMaul > 0 || dragonWarhammer > 0 || emberlight > 0 || arclight > 0
			|| tonalztics > 0 || seercullDamage > 0 || ayakDamage > 0 || bandosGodswordDamage > 0;
	}

	/**
	 * A copy of the monster with these drains applied. Defence never drops below the monster's
	 * defence floor. Wiki effects:
	 * dragon warhammer -30% current Defence, elder maul -35% (both multiplicative);
 * arclight -5% + 1 of base Attack/Strength/Defence (10% + 1 vs demons), emberlight 5% + 1 (15% vs demons),
	 * both additive; tonalztics -1/8 of the target's Magic level from Defence per hit.
	 */
	public Monster apply(Monster base)
	{
		Monster m = base.copy();
		if (!isAny() || base.hasAttribute("absorption") && !CombatRules.toa(base))
		{
			return m;
		}
		boolean demon = base.hasAttribute("demon");
		int floor = Math.max(0, CombatRules.defenceFloor(base));
		int def = base.getDefenceLevel();

		if (vulnerability)
		{
			def = Math.max(floor, def * (tomeOfWater ? 85 : 90) / 100);
		}
		for (int i = 0; i < elderMaul; i++)
		{
			def = Math.max(floor, def - def * 35 / 100);
		}
		for (int i = 0; i < dragonWarhammer; i++)
		{
			def = Math.max(floor, def - def * 30 / 100);
		}
		int baseDef = base.getDefenceLevel();
		int att = base.getAttackLevel();
		int str = base.getStrengthLevel();
		for (int i = 0; i < emberlight; i++)
		{
			def -= baseDef * (demon ? 15 : 5) / 100 + 1;
			att -= base.getAttackLevel() * (demon ? 15 : 5) / 100 + 1;
			str -= base.getStrengthLevel() * (demon ? 15 : 5) / 100 + 1;
		}
		for (int i = 0; i < arclight; i++)
		{
			def -= baseDef * (demon ? 10 : 5) / 100 + 1;
			att -= base.getAttackLevel() * (demon ? 10 : 5) / 100 + 1;
			str -= base.getStrengthLevel() * (demon ? 10 : 5) / 100 + 1;
		}
		for (int i = 0; i < tonalztics; i++)
		{
			def -= base.getMagicLevel() / 8;
		}
		def = Math.max(floor, def);

		int magic = Math.max(0, base.getMagicLevel() - seercullDamage);
		int magicDef = base.getDefMagic() > 0 ? Math.max(0, base.getDefMagic() - ayakDamage) : base.getDefMagic();

		// Bandos godsword: Defence first, then Strength, (Prayer, not tracked), Attack, Magic.
		int bgs = bandosGodswordDamage;
		int d = Math.min(bgs, Math.max(0, def - floor));
		def -= d;
		bgs = def > 0 ? 0 : bgs - d;
		int s = Math.min(bgs, Math.max(0, str));
		str -= s;
		bgs -= s;
		int a = Math.min(bgs, Math.max(0, att));
		att -= a;
		bgs -= a;
		magic = Math.max(0, magic - bgs);

		m.setDefenceLevel(def);
		m.setAttackLevel(Math.max(0, att));
		m.setStrengthLevel(Math.max(0, str));
		m.setMagicLevel(magic);
		m.setDefMagic(Math.max(-64, magicDef));
		return m;
	}
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.Slot;
import com.bestgearsetup.data.StatusImmunities;
import java.util.function.LongFunction;

/**
 * Expected damage of one special attack, from its accuracy and min/max roll. Hit structures follow each
 * weapon's Wiki page; encounter mitigation is applied to each hitsplat.
 */
final class SpecialDamage
{
	private SpecialDamage()
	{
	}

	/** One ordinary roll: accurate damage with equipment effects, or a miss. */
	private static double single(EncounterDamage.Rule rule, Loadout l, CombatContext ctx, double acc, long min, long max)
	{
		return acc * EquipmentEffects.average(rule, l, ctx, min, max) + (1 - acc) * rule.missDamage();
	}

	static DpsResult melee(SpecialAttack s, Loadout l, CombatContext ctx, EncounterDamage.Rule rule, double acc,
		long min, long max, long attRoll, long defRoll, int speed)
	{
		Monster m = ctx.getMonster();
		double average;
		int shown = EquipmentEffects.maximum(rule, l, ctx, max);
		double shownAccuracy = acc;
		double interval = speed;
		switch (s.getKind())
		{
			case MULTI:
				average = s.getHits() * single(rule, l, ctx, acc, min, max);
				shown *= s.getHits();
				break;
			case ABYSSAL_DAGGER:
				// The second hit always lands when the first does.
				average = acc * 2 * EquipmentEffects.average(rule, l, ctx, min, max) + (1 - acc) * rule.missDamage();
				shown *= 2;
				break;
			case DRAGON_CLAWS:
			case BURNING_CLAWS:
			{
				boolean dragon = s.getKind() == SpecialAttack.Kind.DRAGON_CLAWS;
				double[] claws = claws(rule, acc, max, dragon);
				average = claws[0];
				shown = (int) claws[1];
				shownAccuracy = 1 - Math.pow(1 - acc, dragon ? 4 : 3);
				if (!dragon)
				{
					average += burningClawDot(acc) * StatusEffects.burnFactor(l, ctx, StatusImmunities.BURN_NORMAL);
				}
				break;
			}
			case CRIMSON_KISTEN:
				average = 0;
				for (int passes = 1; passes <= 4; passes++)
				{
					int i = passes - 1;
					average += binomial(acc, passes, 4) * EquipmentEffects.average(rule, l, ctx,
						max * (70 + 20 * i) / 100, max * (110 + 20 * i) / 100);
				}
				shown = EquipmentEffects.maximum(rule, l, ctx, max * 170 / 100);
				shownAccuracy = 1 - Math.pow(1 - acc, 4);
				break;
			case HALBERD:
				average = single(rule, l, ctx, acc, min, max);
				if (m.getSize() > 1)
				{
					double second = CombatRules.accuracy(m, l, HitChance.single(attRoll * 3 / 4, defRoll));
					average += single(rule, l, ctx, second, min, max);
					shown *= 2;
				}
				break;
			case SARADOMIN_SWORD:
			{
				average = single(rule, l, ctx, acc, min, max);
				if (EncounterImmunities.classAllowed(m, CombatClass.MAGIC))
				{
					// A guaranteed 1-16 magic hit follows a successful melee hit.
					double magic = 0;
					for (int hit = 1; hit <= 16; hit++)
					{
						magic += rule.mean(hit);
					}
					average += acc * magic / 16;
					shown += rule.maximum(16);
				}
				break;
			}
			case GRANITE_HAMMER:
				average = acc * HitDamage.averageTransformed(rule, min, max, h -> EquipmentEffects.damage(l, ctx, h) + 5)
					+ (1 - acc) * rule.meanInaccurate(5);
				shown = rule.maximum(EquipmentEffects.damage(l, ctx, max) + 5);
				break;
			case SUNSPEAR:
				average = acc * rule.mean(Math.max(1, EquipmentEffects.damage(l, ctx, max)));
				break;
			case VOIDWAKER:
			{
				EncounterDamage.Rule magic = EncounterDamage.rule(m, l, CombatClass.MAGIC);
				average = EquipmentEffects.average(magic, l, ctx, min, max);
				shown = EquipmentEffects.maximum(magic, l, ctx, max);
				shownAccuracy = 1;
				break;
			}
			case BLOOD_MOON:
			{
				// Dual macuahuitl: the second half lands only after the first; the set shortens the attack.
				long first = max / 2;
				long second = max - first;
				average = acc * EquipmentEffects.average(rule, l, ctx, min, Math.max(min, first))
					+ (1 - acc) * rule.missDamage() + acc * single(rule, l, ctx, acc, min, Math.max(min, second));
				shown = EquipmentEffects.maximum(rule, l, ctx, first) + EquipmentEffects.maximum(rule, l, ctx, second);
				interval = speed - (1 - (1 - acc) * (1 - acc));
				break;
			}
			default:
				average = single(rule, l, ctx, acc, min, max);
				break;
		}
		if (s.getName().equals("Arkan blade"))
		{
			average += 10 * acc * StatusEffects.burnFactor(l, ctx, StatusImmunities.BURN_STRONG);
		}
		return finish(s, average, shown, shownAccuracy, speed, interval, rule, null);
	}

	static DpsResult ranged(SpecialAttack s, Loadout l, CombatContext ctx, EncounterDamage.Rule rule, double acc,
		long min, long max, long attRoll, int defBonus, int speed)
	{
		Monster m = ctx.getMonster();
		double average;
		int shown;
		double shownAccuracy = acc;
		String extra = null;
		switch (s.getKind())
		{
			case DARK_BOW:
			{
				// Each arrow deals at least the minimum even on a miss, and at most 48.
				long low = min;
				double hit = acc * HitDamage.averageTransformed(rule, min, max,
					h -> Math.max(low, Math.min(48, EquipmentEffects.damage(l, ctx, h))))
					+ (1 - acc) * rule.meanInaccurate(min);
				average = 2 * hit;
				shown = 2 * rule.maximum(Math.max(min, Math.min(48, max)));
				break;
			}
			case TONALZTICS:
			{
				// The second throw uses the Defence lowered by a successful first throw.
				Monster lowered = SpecialAttacks.builder().tonalztics(1).build().apply(m);
				long defence = CombatRules.defenceRoll(lowered, lowered.getDefenceLevel(), defBonus);
				double afterHit = CombatRules.accuracy(m, l, HitChance.single(attRoll, defence));
				double first = single(rule, l, ctx, acc, min, max);
				average = first + acc * single(rule, l, ctx, afterHit, min, max) + (1 - acc) * first;
				shown = 2 * EquipmentEffects.maximum(rule, l, ctx, max);
				break;
			}
			default:
			{
				double hit = single(rule, l, ctx, acc, min, max);
				int hitMax = EquipmentEffects.maximum(rule, l, ctx, max);
				if (l.getWeapon().getSubcategory().equals("crossbow") && WeaponRules.firesAmmoSlot(l.getWeapon()))
				{
					EnchantedBolts.Result bolts = EnchantedBolts.calculate(l, ctx, rule, acc, min, max);
					if (bolts != null)
					{
						hit = bolts.getAverage();
						hitMax = bolts.getMaximum();
						shownAccuracy = bolts.getAccuracy();
						extra = bolts.getDetail();
					}
				}
				average = s.getHits() * hit;
				shown = s.getHits() * hitMax;
				break;
			}
		}
		if (s.getName().equals("Scorching bow"))
		{
			// Scorching shackles burn demons for 5 whether or not the arrow lands.
			average += 5 * StatusEffects.burnFactor(l, ctx, StatusImmunities.BURN_NORMAL);
		}
		return finish(s, average, shown, shownAccuracy, speed, speed, rule, extra);
	}

	private static DpsResult finish(SpecialAttack s, double average, int shown, double accuracy, int speed,
		double interval, EncounterDamage.Rule rule, String extra)
	{
		String detail = s.describe() + (extra == null ? "" : "; " + extra) + (rule.detail == null ? "" : "; " + rule.detail);
		DpsResult r = DpsCalculator.result(average, shown, accuracy, speed).withDetail(detail);
		double next = interval + s.getExtraTicks();
		return next == speed ? r : r.withExpectedSpeed(next);
	}

	/**
	 * What a claws special does when one of its accuracy rolls is the first to succeed: it rolls a total
	 * between {@code quarters / 4} of the max hit and that plus the max hit ({@code + extra}), then splits the
	 * total into hitsplats. Later rolls start lower, so a late success deals less.
	 */
	private static final class ClawRoll
	{
		private final int quarters;
		private final int extra;
		private final LongFunction<long[]> split;

		private ClawRoll(int quarters, int extra, LongFunction<long[]> split)
		{
			this.quarters = quarters;
			this.extra = extra;
			this.split = split;
		}
	}

	/**
	 * Dragon claws, Slice and Dice (Wiki "Dragon claws"): up to four rolls; the hits after the first success
	 * halve in turn ("4-2-1-1", "0-4-2-2", "0-0-3-3", "0-0-0-5"), and the last splat gains 1 damage.
	 */
	private static final ClawRoll[] DRAGON_CLAWS = {
		new ClawRoll(4, -1, t -> new long[]{t / 2, t / 4, t / 8, t / 8 + 1}),
		new ClawRoll(3, -1, t -> new long[]{t / 2, t / 4, t / 4 + 1}),
		new ClawRoll(2, -1, t -> new long[]{t / 2, t / 2 + 1}),
		new ClawRoll(1, -1, t -> new long[]{t + 1}),
	};

	/**
	 * Burning claws, Burning barrage (Wiki "Burning claws"): 75-175% split 25/25/50, then 50-150% split 50/50/0
	 * moving 1 from each of the first two splats to the third, then 25-125% split 0/0/100 moving 2 from the
	 * third splat to the first two.
	 */
	private static final ClawRoll[] BURNING_CLAWS = {
		new ClawRoll(3, 0, t -> new long[]{t / 4, t / 4, t / 2}),
		new ClawRoll(2, 0, t -> new long[]{t / 2 - 1, t / 2 - 1, 2}),
		new ClawRoll(1, 0, t -> new long[]{1, 1, t - 2}),
	};

	/** Expected damage and maximum of a claws special, with encounter rules per splat. Returns {mean, maximum}. */
	static double[] claws(EncounterDamage.Rule rule, double acc, long max, boolean dragon)
	{
		double total = 0;
		long best = 0;
		// Chance that every accuracy roll so far has missed.
		double allMissed = 1;
		for (ClawRoll roll : dragon ? DRAGON_CLAWS : BURNING_CLAWS)
		{
			double firstSuccess = allMissed * acc;
			allMissed *= 1 - acc;
			long low = max * roll.quarters / 4;
			long high = low + max + roll.extra;
			if (high < low)
			{
				continue;
			}
			double perTotal = firstSuccess / (high - low + 1);
			for (long t = low; t <= high; t++)
			{
				double mean = 0;
				long top = 0;
				for (long splat : roll.split.apply(t))
				{
					mean += rule.mean(Math.max(0, splat));
					top += rule.maximum(Math.max(0, splat));
				}
				total += perTotal * mean;
				best = Math.max(best, top);
			}
		}
		// Every roll missed. Dragon claws: about 2/3 of the time two 1-damage splats. Burning claws: 40% one
		// 1-damage splat, 40% two. These splats are inaccurate.
		double missSplats = dragon ? 2.0 / 3 * 2 : 0.4 + 0.4 * 2;
		total += allMissed * missSplats * rule.meanInaccurate(1);
		return new double[]{total, best};
	}

	/**
	 * Expected burn damage of Burning barrage: each of the three splats burns for 10 with a chance of 15%, 30% or
	 * 45%, by the roll that succeeded (Wiki "Burning claws"). By linearity that is 30 x the chance, less 1 damage
	 * when the first two burns overlap (both burn: the chance squared), as the Wiki DPS calculator's authors observed.
	 */
	static double burningClawDot(double acc)
	{
		double total = 0;
		double allMissed = 1;
		for (int roll = 1; roll <= 3; roll++)
		{
			double chance = 0.15 * roll;
			total += allMissed * acc * (30 * chance - chance * chance);
			allMissed *= 1 - acc;
		}
		return total;
	}

	private static double binomial(double p, int k, int n)
	{
		double ways = 1;
		for (int i = 1; i <= k; i++)
		{
			ways = ways * (n - i + 1) / i;
		}
		return ways * Math.pow(p, k) * Math.pow(1 - p, n - k);
	}

	/** Ammunition-only max hit of the magic shortbow, magic longbow and Seercull specials. */
	static long arrowFormula(Loadout l, CombatContext ctx)
	{
		int ammo = l.get(Slot.AMMO) == null ? 0 : l.get(Slot.AMMO).getRangedStr();
		return ((ctx.getRanged() + 10L) * (ammo + 64) + 320) / 640;
	}

	/** Staves whose specials cast a built-in spell even when the staff normally autocasts. */
	static boolean builtInSpell(com.bestgearsetup.data.GearItem weapon)
	{
		String n = EncounterDamage.lower(weapon);
		return n.startsWith("accursed sceptre") || n.startsWith("volatile nightmare staff")
			|| n.startsWith("eldritch nightmare staff");
	}

	/** Built-in spec max hits of the nightmare staves; other staves use their powered formula. */
	static int builtInMax(com.bestgearsetup.data.GearItem weapon, int magic)
	{
		String n = EncounterDamage.lower(weapon);
		if (n.startsWith("volatile nightmare staff"))
		{
			return Math.max(1, Math.min(58, (99 + 58 * magic) / 99));
		}
		if (n.startsWith("eldritch nightmare staff"))
		{
			return Math.max(1, Math.min(44, (99 + 44 * magic) / 99));
		}
		return WeaponRules.poweredStaffMaxHit(weapon, magic);
	}
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Spell;
import lombok.Value;

/** The special attack a setup uses during the kill: its weapon, the spec itself and how often it is used. */
@Value
public class SpecialPlan
{
	/** The spec weapon; the setup's own weapon when no switch is needed. */
	GearItem weapon;
	/** An off-hand switched in with a one-handed spec weapon when the worn shield slot is empty; else null. */
	GearItem offhand;
	/** Ammunition equipped with an ammo-slot spec weapon when it differs from the worn ammunition; else null. */
	GearItem ammo;
	AttackStyle style;
	Spell spell;
	/** Darts loaded into a blowpipe spec weapon. */
	GearItem loadedAmmo;
	SpecialAttack special;
	/** One special attack at the start of the kill: its max hit, accuracy, average and interval. */
	DpsResult spec;
	/** The setup's ordinary attacks alone. */
	DpsResult ordinary;
	/** Ordinary attacks after one landed draining spec of average damage; null for specs that don't drain. */
	DpsResult drained;
	/** Expected specs per kill of the selected target HP. */
	double specsPerKill;
	/** GP to buy the spec weapon (with its off-hand, ammunition and darts) on top of the worn setup. */
	long extraCost;
	/** Items to buy for the spec that have no current price. */
	int unpricedItems;

	/** Whether the spec needs a weapon, off-hand or ammunition switch from the worn setup. */
	public boolean isSwitch(Loadout worn)
	{
		return weapon != worn.getWeapon() || offhand != null || ammo != null;
	}
}

package com.bestgearsetup.calc;

import lombok.Value;

/**
 * Special attacks spent during a kill. Energy regenerates 10% every 30 seconds (twice as fast with
 * lightbearer); a full bar adds the whole specs it holds at the start of the kill (its remainder is not
 * carried over). Weapon-switch timing and overkill are not modelled.
 *
 * <p>A damage special replaces one ordinary attack for the spec weapon's attack interval, and is used only
 * when it out-damages the ordinary attacks over that interval. A draining special (dragon warhammer,
 * Bandos godsword...) opens each kill instead, so its drain helps the rest of the fight: each opening spec
 * hits or misses at the target's current stats, and the kill finishes with ordinary attacks at the drained
 * stats. With regeneration only, the opening uses the energy regenerated over one kill.
 */
public final class SpecialRotation
{
	/** Percent of special attack energy regenerated per second. */
	public static final double REGEN_PER_SECOND = 10.0 / 30;
	static final int FULL_ENERGY = 100;
	private static final double SECONDS_PER_TICK = 0.6;
	/** Iterations of the regenerated-opening fixed point (specs per kill depend on the kill time). */
	private static final int REGEN_ITERATIONS = 8;

	private SpecialRotation()
	{
	}

	/** Whole-kill damage rates with specs, and the specs used per kill. */
	@Value
	public static class Blend
	{
		DpsResult result;
		double specsPerKill;
	}

	/** The fight's ordinary attacks and special attack once some drains have landed. */
	public interface Fight
	{
		DpsResult ordinary(SpecialAttacks drains);

		DpsResult spec(SpecialAttacks drains);
	}

	public static Blend blend(DpsResult ordinary, DpsResult spec, int energy, int targetHp, SpecEnergy mode)
	{
		return blend(ordinary, spec, energy, targetHp, mode, REGEN_PER_SECOND);
	}

	/**
	 * Blend ordinary attacks with damage specs over a kill of the target's HP, or null when the spec never helps.
	 *
	 * @param ordinary the setup's ordinary attacks over the whole fight
	 * @param spec     one special attack, repeated at its interval
	 * @param energy   energy each spec costs, in percent
	 * @param regen    energy regenerated per second, in percent
	 */
	public static Blend blend(DpsResult ordinary, DpsResult spec, int energy, int targetHp, SpecEnergy mode,
		double regen)
	{
		double ordinaryRate = ordinary.getPrimaryDps();
		double specRate = spec.getPrimaryDps();
		double specSeconds = spec.getExpectedSpeedTicks() * SECONDS_PER_TICK;
		if (energy <= 0 || targetHp <= 0 || specSeconds <= 0 || specRate <= ordinaryRate)
		{
			return null;
		}
		// Share of fight time spent speccing on regenerated energy alone.
		double regenShare = Math.min(1, regen * specSeconds / energy);
		double sustainedRate = regenShare * specRate + (1 - regenShare) * ordinaryRate;
		int opening = mode == SpecEnergy.FULL_BAR ? FULL_ENERGY / energy : 0;
		double specDamage = specRate * specSeconds;

		double seconds;
		double specs;
		if (opening * specDamage >= targetHp)
		{
			// The opening specs kill the target alone.
			seconds = targetHp / specRate;
			specs = targetHp / specDamage;
		}
		else
		{
			double openingSeconds = opening * specSeconds;
			seconds = openingSeconds + (targetHp - opening * specDamage) / sustainedRate;
			specs = opening + regenShare * (seconds - openingSeconds) / specSeconds;
		}
		double specSecondsTotal = specs * specSeconds;
		double dps = (specSecondsTotal * spec.getDps() + (seconds - specSecondsTotal) * ordinary.getDps()) / seconds;
		return new Blend(ordinary.withDamageRates(dps, targetHp / seconds), specs);
	}

	/**
	 * Open each kill with draining specs and finish at the drained stats, or null when the target can't be
	 * killed. The result keeps the undrained ordinary attack's max hit and accuracy.
	 */
	public static Blend draining(Fight fight, SpecialAttack.Drain drain, int energy, int targetHp, SpecEnergy mode,
		double regen)
	{
		return draining(fight, drain, energy, targetHp, mode, regen, false);
	}

	/**
	 * As {@link #draining(Fight, SpecialAttack.Drain, int, int, SpecEnergy, double)}.
	 *
	 * @param allMiss the worst case: every opening spec misses, costing its attack and draining nothing
	 */
	public static Blend draining(Fight fight, SpecialAttack.Drain drain, int energy, int targetHp, SpecEnergy mode,
		double regen, boolean allMiss)
	{
		DpsResult start = fight.ordinary(SpecialAttacks.NONE);
		if (energy <= 0 || targetHp <= 0 || start.getPrimaryDps() <= 0)
		{
			return null;
		}
		int barSpecs = FULL_ENERGY / energy;
		double[] r;
		if (mode == SpecEnergy.FULL_BAR)
		{
			r = new DrainKill(fight, drain, energy, regen, allMiss).path(barSpecs, SpecialAttacks.NONE, targetHp);
		}
		else
		{
			// The regenerated energy banked over one kill opens the next; a fraction is a spec on some kills. A
			// bar holds only so many specs, so energy regenerated beyond it is spent during the kill instead.
			double specSeconds = fight.spec(SpecialAttacks.NONE).getExpectedSpeedTicks() * SECONDS_PER_TICK;
			r = new double[]{targetHp / start.getPrimaryDps(), 0};
			for (int i = 0; i < REGEN_ITERATIONS; i++)
			{
				double regenerated = regen * r[0];
				double opening = Math.min(barSpecs, regenerated / energy);
				double excess = Math.max(0, regenerated - barSpecs * energy);
				double midFight = excess / Math.max(specSeconds, r[0] - barSpecs * specSeconds);
				DrainKill kill = new DrainKill(fight, drain, energy, midFight, allMiss);
				int whole = (int) opening;
				double fraction = opening - whole;
				r = kill.path(whole, SpecialAttacks.NONE, targetHp);
				if (fraction > 0)
				{
					double[] more = kill.path(whole + 1, SpecialAttacks.NONE, targetHp);
					r = new double[]{r[0] + fraction * (more[0] - r[0]), r[1] + fraction * (more[1] - r[1])};
				}
			}
		}
		double seconds = r[0];
		if (!(seconds > 0) || Double.isInfinite(seconds))
		{
			return null;
		}
		double primary = targetHp / seconds;
		double total = primary * start.getDps() / start.getPrimaryDps();
		return new Blend(start.withDamageRates(total, primary), r[1]);
	}

	/** Expected kill time and specs used from a point in the opening. */
	private static final class DrainKill
	{
		private final Fight fight;
		private final SpecialAttack.Drain drain;
		private final int energy;
		/** Energy per second that can be spent after the opening specs. */
		private final double midFightRegen;
		private final boolean allMiss;

		DrainKill(Fight fight, SpecialAttack.Drain drain, int energy, double midFightRegen, boolean allMiss)
		{
			this.fight = fight;
			this.drain = drain;
			this.energy = energy;
			this.midFightRegen = midFightRegen;
			this.allMiss = allMiss;
		}

		/** {seconds, specs} with the given opening specs still to throw and HP left. */
		double[] path(int left, SpecialAttacks drains, double hp)
		{
			if (left <= 0)
			{
				return remainder(drains, hp);
			}
			DpsResult spec = fight.spec(drains);
			double seconds = spec.getExpectedSpeedTicks() * SECONDS_PER_TICK;
			double perSpec = spec.getPrimaryDps() * seconds;
			double accuracy = Math.max(0, Math.min(1, spec.getAccuracy()));
			if (seconds <= 0 || perSpec <= 0 || accuracy <= 0)
			{
				return remainder(drains, hp);
			}
			if (allMiss)
			{
				double[] after = path(left - 1, drains, hp);
				return new double[]{seconds + after[0], 1 + after[1]};
			}
			// A landed spec deals its expected damage given a hit; a miss deals nothing.
			double hitDamage = perSpec / accuracy;
			double[] hit;
			if (hitDamage >= hp)
			{
				hit = new double[]{seconds * hp / hitDamage, 1};
			}
			else
			{
				double[] after = path(left - 1, drains.landed(drain, (int) Math.round(hitDamage)), hp - hitDamage);
				hit = new double[]{seconds + after[0], 1 + after[1]};
			}
			if (accuracy >= 1)
			{
				return hit;
			}
			double[] after = path(left - 1, drains, hp);
			return new double[]{
				accuracy * hit[0] + (1 - accuracy) * (seconds + after[0]),
				accuracy * hit[1] + (1 - accuracy) * (1 + after[1]),
			};
		}

		/**
		 * The rest of the kill at the drained stats, speccing for damage on any energy regenerated meanwhile
		 * (drains from those specs are not applied).
		 */
		private double[] remainder(SpecialAttacks drains, double hp)
		{
			double ordinary = fight.ordinary(drains).getPrimaryDps();
			if (midFightRegen > 0)
			{
				DpsResult spec = fight.spec(drains);
				double seconds = spec.getExpectedSpeedTicks() * SECONDS_PER_TICK;
				if (seconds > 0 && spec.getPrimaryDps() > ordinary)
				{
					double share = Math.min(1, midFightRegen * seconds / energy);
					double time = hp / (share * spec.getPrimaryDps() + (1 - share) * ordinary);
					return new double[]{time, share * time / seconds};
				}
			}
			return new double[]{ordinary > 0 ? hp / ordinary : Double.POSITIVE_INFINITY, 0};
		}
	}
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.Spell;
import java.util.Locale;

/** Elemental spell scaling and equipment compatibility, independent of API max-hit snapshots. */
final class SpellRules
{
	private SpellRules()
	{
	}

	static String element(Spell spell)
	{
		String name = spell == null ? "" : spell.getName().toLowerCase(Locale.ROOT);
		if (name.startsWith("wind "))
		{
			return "air";
		}
		for (String element : new String[]{"water", "earth", "fire"})
		{
			if (name.startsWith(element + " "))
			{
				return element;
			}
		}
		return "";
	}

	static int maxHit(Loadout l, CombatContext ctx)
	{
		Spell spell = l.getSpell();
		String name = EncounterDamage.spell(l);
		int magic = ctx.getMagic();
		if (name.equals("magic dart"))
		{
			return EncounterDamage.lower(l.getWeapon()).startsWith("slayer's staff (e)") && ctx.isOnTask()
				? 13 + magic / 6 : 10 + magic / 10;
		}
		if (element(spell).isEmpty())
		{
			return spell.getMaxHit();
		}
		String tier = name.substring(name.indexOf(' ') + 1);
		int[] thresholds;
		int[] maxima;
		switch (tier)
		{
			case "strike":
				thresholds = new int[]{5, 9, 13};
				maxima = new int[]{2, 4, 6, 8};
				break;
			case "bolt":
				thresholds = new int[]{23, 29, 35};
				maxima = new int[]{9, 10, 11, 12};
				break;
			case "blast":
				thresholds = new int[]{47, 53, 59};
				maxima = new int[]{13, 14, 15, 16};
				break;
			case "wave":
				thresholds = new int[]{65, 70, 75};
				maxima = new int[]{17, 18, 19, 20};
				break;
			case "surge":
				thresholds = new int[]{85, 90, 95};
				maxima = new int[]{21, 22, 23, 24};
				break;
			default:
				return spell.getMaxHit();
		}
		int index = 0;
		while (index < thresholds.length && magic >= thresholds[index])
		{
			index++;
		}
		return maxima[index];
	}
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.Slot;
import com.bestgearsetup.data.StatusImmunities;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;
import lombok.Value;

/**
 * Damage over time from poison, venom and burns, integrated over the kill (OSRS Wiki Poison, Venom and
 * Burn pages). Poison and venom hit every 30 ticks on the target's own timer (random phase); poison
 * deals floor((severity + 4) / 5) and loses one severity per hit, and each landed hit may reset it;
 * venom starts at 6 and rises by 2 per hit to 20 and never resets. Burns deal 1 per stack every 4 ticks
 * for 10 hits, up to 5 stacks, and are mitigated as ranged damage. The kill time T solves
 * direct damage x T + expected damage over time by T = HP, so short kills gain little.
 */
public final class StatusEffects
{
	static final int POISON_INTERVAL = 30;
	static final int BURN_INTERVAL = 4;
	static final int BURN_HITS = 10;
	static final int BURN_STACKS = 5;
	private static final double SECONDS_PER_TICK = 0.6;
	private static final int VENOM_AS_POISON = 26;
	private static final Pattern POISONABLE_MELEE = Pattern.compile(
		"(bronze|iron|steel|black|white|mithril|adamant|rune|dragon) (dagger|spear|hasta)|abyssal dagger|bone dagger");
	private static final Pattern POISONABLE_AMMO = Pattern.compile(
		"(bronze|iron|steel|black|mithril|adamant|rune|amethyst|dragon) (arrows?|dart|knife|javelin)"
			+ "|(bronze|iron|steel|mithril|adamant|runite|dragon|silver|blurite|bone) bolts");

	private StatusEffects()
	{
	}

	/** Chances per attack (already multiplied by accuracy), severities, and the burn mitigation factor. */
	@Value
	static class Sources
	{
		double poisonChance;
		int poisonSeverity;
		double venomChance;
		double burnChance;
		/** Fraction of burn damage left after the target's ranged mitigation. */
		double burnFactor;
		List<String> notes;

		boolean any()
		{
			return poisonChance > 0 && poisonSeverity > 0 || venomChance > 0 || burnChance > 0 && burnFactor > 0;
		}
	}

	static boolean serpentineHelm(Loadout l)
	{
		String head = EncounterDamage.lower(l.get(Slot.HEAD));
		return (head.startsWith("serpentine helm") || head.startsWith("tanzanite helm") || head.startsWith("magma helm"))
			&& !head.contains("uncharged");
	}

	/** Whether the weapon option poisons this weapon or its ammunition. */
	static boolean poisonable(Loadout l)
	{
		GearItem weapon = l.getWeapon();
		if (weapon == null)
		{
			return false;
		}
		String w = EncounterDamage.lower(weapon);
		if (l.getStyle().isMelee())
		{
			return POISONABLE_MELEE.matcher(w).matches();
		}
		if (l.getStyle().getType() != AttackStyle.Type.RANGED)
		{
			return false;
		}
		if (WeaponRules.firesAmmoSlot(weapon))
		{
			return POISONABLE_AMMO.matcher(EncounterDamage.lower(l.get(Slot.AMMO))).matches();
		}
		return weapon.getSubcategory().equals("thrown") && POISONABLE_AMMO.matcher(w).matches();
	}

	static Sources sources(Loadout l, CombatContext ctx, double accuracy)
	{
		Monster m = ctx.getMonster();
		List<String> notes = new ArrayList<>();
		GearItem weapon = l.getWeapon();
		String w = EncounterDamage.lower(weapon);
		CombatClass cls = WeaponRules.classOf(l.getStyle());
		boolean serpentine = serpentineHelm(l);
		WeaponPoison option = ctx.getModifiers().getWeaponPoison();
		double poisonMiss = 1;
		int severity = 0;
		double venom = 0;
		boolean poisoned = option != WeaponPoison.NONE && poisonable(l);
		boolean toxic = false;
		switch (cls)
		{
			case MELEE:
				if (poisoned)
				{
					poisonMiss *= 1 - accuracy / 4;
					severity = Math.max(severity, option.getSeverity());
				}
				if (w.startsWith("abyssal tentacle"))
				{
					poisonMiss *= 1 - accuracy / 4;
					severity = Math.max(severity, 20);
				}
				if (w.equals("swamp lizard"))
				{
					poisonMiss *= 1 - accuracy / 4;
					severity = Math.max(severity, 30);
				}
				if (w.startsWith("toxic staff of the dead"))
				{
					venom = serpentine ? 1 : 0.25;
					toxic = true;
				}
				else if (w.startsWith("noxious halberd"))
				{
					venom = serpentine ? 0.5 : 1 / 3.0;
					toxic = true;
				}
				break;
			case RANGED:
				if (poisoned)
				{
					poisonMiss *= 1 - accuracy / 8;
					severity = Math.max(severity, option.getSeverity() - 14);
				}
				String ammo = EncounterDamage.lower(l.get(Slot.AMMO));
				if (weapon.getSubcategory().equals("crossbow") && WeaponRules.firesAmmoSlot(weapon)
					&& (ammo.equals("emerald bolts (e)") || ammo.equals("emerald dragon bolts (e)")))
				{
					// Magical Poison: 55% of successful hits, not reduced like other ranged poison.
					double chance = Math.min(1, 0.55 * (ctx.getModifiers().isKandarinDiary() ? 1.1 : 1));
					poisonMiss *= 1 - accuracy * chance;
					severity = Math.max(severity, w.startsWith("zaryte crossbow") ? 27 : 25);
				}
				if (w.startsWith("toxic blowpipe"))
				{
					venom = serpentine ? 1 : 0.25;
					toxic = true;
				}
				break;
			default:
			{
				String spell = EncounterDamage.spell(l);
				if (spell.startsWith("smoke "))
				{
					int base = spell.endsWith("rush") || spell.endsWith("burst") ? 10 : 20;
					// Every ancient sceptre raises Ancient Magicks effects by 10%.
					poisonMiss *= 1 - accuracy / 8;
					severity = Math.max(severity, w.contains("ancient sceptre") ? base * 11 / 10 : base);
				}
				if (w.startsWith("trident of the swamp") || w.startsWith("toxic staff of the dead") && l.getSpell() != null)
				{
					venom = serpentine ? 1 : 0.25;
					toxic = true;
				}
				break;
			}
		}
		if (serpentine && !toxic)
		{
			// Wiki: 1/6 with unpoisoned melee weapons, 1/2 with poisoned weapons; emerald bolts do not count.
			venom = poisoned ? 0.5 : cls == CombatClass.MELEE ? 1 / 6.0 : 0;
		}
		double venomChance = accuracy * venom;
		double poisonChance = severity > 0 ? 1 - poisonMiss : 0;

		StatusImmunities.Immunity immunity = StatusImmunities.of(m);
		if (venomChance > 0)
		{
			if (!immunity.isVenomImmune())
			{
				// Venom replaces poison on the shared timer; earlier poison is ignored.
				poisonChance = 0;
				notes.add("venom");
			}
			else if (immunity.isVenomBecomesPoison())
			{
				poisonChance = 1 - (1 - poisonChance) * (1 - venomChance);
				severity = Math.max(severity, VENOM_AS_POISON);
				venomChance = 0;
				notes.add("venom becomes poison");
			}
			else
			{
				venomChance = 0;
			}
		}
		if (poisonChance > 0)
		{
			if (immunity.isPoisonImmune())
			{
				poisonChance = 0;
			}
			else if (!notes.contains("venom becomes poison"))
			{
				notes.add("poison");
			}
		}

		double burnChance = 0;
		double burnFactor = 0;
		if (WeaponRules.isAtlatl(weapon) && cls == CombatClass.RANGED && EquipmentEffects.named(l, Slot.HEAD, "eclipse moon helm")
			&& EquipmentEffects.named(l, Slot.BODY, "eclipse moon chestplate")
			&& EquipmentEffects.named(l, Slot.LEGS, "eclipse moon tassets"))
		{
			// Eclipse set: 20% of successful atlatl attacks inflict a strong burn.
			burnFactor = burnFactor(l, ctx, StatusImmunities.BURN_STRONG);
			if (burnFactor > 0)
			{
				burnChance = 0.2 * accuracy;
				notes.add("burn");
			}
		}
		return new Sources(poisonChance, severity, venomChance, burnChance, burnFactor, notes);
	}

	/**
	 * Fraction of burn damage a target takes: zero when it ignores the burn's severity or ranged damage,
	 * otherwise its ranged mitigation applied to a 10-damage burn.
	 */
	static double burnFactor(Loadout l, CombatContext ctx, int severity)
	{
		Monster m = ctx.getMonster();
		if (CombatRules.burnImmune(m) || StatusImmunities.of(m).getBurnImmunity() >= severity
			|| !EncounterImmunities.classAllowed(m, CombatClass.RANGED))
		{
			return 0;
		}
		return EncounterDamage.rule(m, l, CombatClass.RANGED).mean(BURN_HITS) / BURN_HITS;
	}

	/** Add expected damage over time to a sustained-attack result. */
	static DpsResult apply(Loadout l, CombatContext ctx, DpsResult r)
	{
		Monster m = ctx.getMonster();
		if (ctx.getModifiers().isSpecialAttack() || r.getPrimaryDps() <= 0 || CombatRules.oneHit(m))
		{
			return r;
		}
		Sources s = sources(l, ctx, r.getAccuracy());
		if (!s.any())
		{
			return r;
		}
		double speed = Math.max(1, r.getExpectedSpeedTicks());
		double direct = r.getPrimaryDps() * SECONDS_PER_TICK;
		Fight fight = new Fight(s, speed);
		boolean infinite = m.getId() == 14779 || EncounterDamage.named(m, "gemstone crab");
		int hp = ctx.getModifiers().targetHp(m);
		double extra;
		String when;
		if (infinite || hp <= 0)
		{
			extra = fight.steadyPerTick();
			when = "sustained";
		}
		else
		{
			double ticks = fight.killTime(direct, hp);
			extra = hp / ticks - direct;
			when = String.format(Locale.ROOT, "over a %.0fs kill", ticks * SECONDS_PER_TICK);
		}
		if (extra <= 1e-9)
		{
			return r;
		}
		double extraDps = extra / SECONDS_PER_TICK;
		String note = String.format(Locale.ROOT, "%s +%.2f DPS %s", String.join(" + ", s.getNotes()), extraDps, when);
		return r.withExtraDps(extraDps).withDetail(r.getMaxHitDetail() == null ? note : r.getMaxHitDetail() + "; " + note);
	}

	/** Expected cumulative damage over time for one fight. */
	static final class Fight
	{
		private final Sources s;
		private final double speed;
		private final double refresh;
		private final List<Double> poisonCumulative = new ArrayList<>();
		private double refreshPrefix;
		private double noRefresh = 1;

		Fight(Sources s, double speed)
		{
			this.s = s;
			this.speed = speed;
			// Chance that at least one attack between two poison hits lands a fresh application.
			this.refresh = 1 - Math.pow(1 - s.getPoisonChance(), POISON_INTERVAL / speed);
			poisonCumulative.add(0.0);
		}

		/** Ticks to kill with direct damage per tick plus damage over time. */
		double killTime(double direct, int hp)
		{
			double low = 0;
			double high = hp / direct;
			for (int i = 0; i < 40 && high - low > 1e-3; i++)
			{
				double mid = (low + high) / 2;
				if (direct * mid + damage(mid) >= hp)
				{
					high = mid;
				}
				else
				{
					low = mid;
				}
			}
			return high;
		}

		/** Expected damage-over-time damage dealt by tick t (attacks at 0, speed, 2 speed, ...). */
		double damage(double t)
		{
			double total = 0;
			double venomWeight = s.getVenomChance();
			double poisonWeight = s.getPoisonChance();
			for (int i = 0; ; i++)
			{
				double elapsed = t - i * speed;
				if (elapsed < 0)
				{
					break;
				}
				if (venomWeight > 1e-9)
				{
					total += venomWeight * phaseAverage(elapsed, POISON_INTERVAL, Fight::venomCumulative);
					venomWeight *= 1 - s.getVenomChance();
				}
				if (poisonWeight > 1e-9 && s.getPoisonSeverity() > 0)
				{
					total += poisonWeight * phaseAverage(elapsed, POISON_INTERVAL, this::poisonCumulative);
					poisonWeight *= 1 - s.getPoisonChance();
				}
				if (s.getBurnChance() > 0)
				{
					total += s.getBurnChance() * s.getBurnFactor() * burnCap()
						* phaseAverage(elapsed, BURN_INTERVAL, n -> Math.min(BURN_HITS, n));
				}
			}
			return total;
		}

		/** Long-run damage per tick, for targets whose HP never falls. */
		double steadyPerTick()
		{
			double venom = s.getVenomChance() > 0 ? 20.0 / POISON_INTERVAL : 0;
			double poison = 0;
			if (s.getPoisonChance() > 0)
			{
				// Each poison hit's expected damage once refreshes have reached their stationary pattern.
				double hit = 0;
				for (int k = 0; k <= s.getPoisonSeverity(); k++)
				{
					hit += refresh * Math.pow(1 - refresh, k) * poisonHit(s.getPoisonSeverity() - k);
				}
				poison = hit / POISON_INTERVAL;
			}
			double burn = s.getBurnChance() / speed * BURN_HITS * s.getBurnFactor() * burnCap();
			return venom + poison + burn;
		}

		/** Share of burn damage left after the five-stack limit discards new burns. */
		private double burnCap()
		{
			double mean = s.getBurnChance() / speed * BURN_INTERVAL * BURN_HITS;
			if (mean <= 0)
			{
				return 1;
			}
			double p = Math.exp(-mean);
			double capped = 0;
			double below = 0;
			for (int n = 0; n < BURN_STACKS; n++)
			{
				capped += n * p;
				below += p;
				p *= mean / (n + 1);
			}
			capped += BURN_STACKS * (1 - below);
			return capped / mean;
		}

		/**
		 * Average over the target's timer phase of a per-hit cumulative series: hits come at phase,
		 * phase + interval, ... with the phase uniform over one interval.
		 */
		private static double phaseAverage(double elapsed, int interval, java.util.function.IntToDoubleFunction cumulative)
		{
			int e = (int) elapsed;
			int whole = e / interval;
			int rest = e % interval;
			return (rest * cumulative.applyAsDouble(whole + 1) + (interval - rest) * cumulative.applyAsDouble(whole))
				/ interval;
		}

		/** Venom dealt by its first n hits: 6, 8, ... capped at 20. */
		static double venomCumulative(int n)
		{
			int ramp = Math.min(n, 8);
			double total = ramp * 6 + ramp * (ramp - 1);
			return total + Math.max(0, n - 8) * 20.0;
		}

		/**
		 * Poison dealt by its first n hits after the first application. Before hit j a fresh application
		 * landed with chance r in each interval, resetting the severity.
		 */
		double poisonCumulative(int n)
		{
			int s0 = s.getPoisonSeverity();
			while (poisonCumulative.size() <= n)
			{
				int j = poisonCumulative.size();
				// Hit j: severity s0 - m when the last reset was m intervals ago.
				double expected = refreshPrefix + noRefresh * poisonHit(s0 - (j - 1));
				poisonCumulative.add(poisonCumulative.get(j - 1) + expected);
				refreshPrefix += refresh * noRefresh * poisonHit(s0 - (j - 1));
				noRefresh *= 1 - refresh;
			}
			return poisonCumulative.get(n);
		}

		static int poisonHit(int severity)
		{
			return severity > 0 ? (severity + 4) / 5 : 0;
		}
	}
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.Slot;
import java.util.EnumSet;
import java.util.Set;

/** Spells cast before or beside the attack whose effect a setup's DPS assumes. */
public enum SupportSpell
{
	/** Mark of Darkness, boosting demonbane spells against demons. */
	MARK_OF_DARKNESS,
	/** Charge, boosting a god spell cast with the matching god cape. */
	CHARGE,
	/** The strongest thrall the player can cast, added as flat DPS; last so its Book of the dead follows the runes. */
	THRALL;

	/** The support spells the calculator applies to this loadout in this context. */
	static Set<SupportSpell> assumed(Loadout loadout, CombatContext ctx)
	{
		Set<SupportSpell> spells = EnumSet.noneOf(SupportSpell.class);
		if (markOfDarkness(loadout, ctx))
		{
			spells.add(MARK_OF_DARKNESS);
		}
		if (charge(loadout, ctx))
		{
			spells.add(CHARGE);
		}
		if (thrall(loadout, ctx))
		{
			spells.add(THRALL);
		}
		return spells;
	}

	/** Thralls need the Magic level and can't be cast while autocasting a non-Arceuus spell. */
	static boolean thrall(Loadout loadout, CombatContext ctx)
	{
		boolean usable = loadout.getSpell() == null || "arceuus".equalsIgnoreCase(loadout.getSpell().getSpellbook());
		return ctx.getThrall() != null && usable && !ctx.getMonster().isImmuneThrall();
	}

	static boolean demonbane(Loadout loadout, CombatContext ctx)
	{
		return EncounterDamage.spell(loadout).contains("demonbane") && ctx.getMonster().hasAttribute("demon");
	}

	static boolean markOfDarkness(Loadout loadout, CombatContext ctx)
	{
		return ctx.getModifiers().isMarkOfDarkness() && demonbane(loadout, ctx);
	}

	static boolean charge(Loadout loadout, CombatContext ctx)
	{
		if (!ctx.getModifiers().isCharge())
		{
			return false;
		}
		String spell = EncounterDamage.spell(loadout);
		String god = spell.equals("saradomin strike") ? "saradomin" : spell.equals("claws of guthix") ? "guthix"
			: spell.equals("flames of zamorak") ? "zamorak" : "";
		String cape = EncounterDamage.lower(loadout.get(Slot.CAPE));
		return !god.isEmpty() && (cape.equals(god + " cape") || cape.equals("imbued " + god + " cape")
			|| cape.equals(god + " max cape") || cape.equals("imbued " + god + " max cape"));
	}
}

package com.bestgearsetup.calc;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Arceuus thrall tiers. Thralls always land a successful hit, rolling 0 to their max hit every 4 ticks, so the
 * average damage is half the max hit per 2.4 seconds.
 */
@Getter
@RequiredArgsConstructor
public enum Thrall
{
	LESSER("Lesser thrall", 38, 1),
	SUPERIOR("Superior thrall", 57, 2),
	GREATER("Greater thrall", 76, 3);

	private static final double ATTACK_SECONDS = 2.4;

	private final String displayName;
	private final int magicLevel;
	private final int maxHit;

	/** Flat DPS added to a setup. */
	public double getDps()
	{
		return maxHit / 2.0 / ATTACK_SECONDS;
	}

	/** The strongest thrall this base Magic level can cast, or null below the lesser thrall's level. */
	public static Thrall forLevel(int magic)
	{
		Thrall best = null;
		for (Thrall thrall : values())
		{
			if (magic >= thrall.magicLevel)
			{
				best = thrall;
			}
		}
		return best;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

