package com.bestgearsetup.data;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.IntPredicate;
import java.util.function.IntUnaryOperator;
import java.util.regex.Pattern;
import lombok.Getter;
import net.runelite.api.ItemComposition;
import net.runelite.api.IterableHashTable;
import net.runelite.api.Node;

/**
 * Cache wear parameters plus a curated, source-linked table for legacy equipment. Missing parameters
 * do not establish that an item has no requirements. Neither input models quest or diary access.
 */
public final class EquipmentRequirements
{
	private static final String RESOURCE = "/com/bestgearsetup/equipment-requirements.json";
	private static final int[][] PAIRS = {{434, 436}, {435, 437}, {191, 613}, {579, 614},
		{610, 615}, {611, 616}, {612, 617}};
	private static final Map<Integer, String> SKILLS;
	private static volatile EquipmentRequirements instance;

	static
	{
		Map<Integer, String> skills = new LinkedHashMap<>();
		skills.put(0, "attack");
		skills.put(1, "defence");
		skills.put(2, "strength");
		skills.put(3, "hitpoints");
		skills.put(4, "ranged");
		skills.put(5, "prayer");
		skills.put(6, "magic");
		skills.put(18, "slayer");
		SKILLS = Collections.unmodifiableMap(skills);
	}

	private final List<Rule> rules;

	private EquipmentRequirements(List<Rule> rules)
	{
		this.rules = Collections.unmodifiableList(rules);
	}

	/** Load the bundled rules, without any network or client access. */
	public static EquipmentRequirements get()
	{
		EquipmentRequirements loaded = instance;
		if (loaded == null)
		{
			synchronized (EquipmentRequirements.class)
			{
				loaded = instance;
				if (loaded == null)
				{
					loaded = load();
					instance = loaded;
				}
			}
		}
		return loaded;
	}

	private static EquipmentRequirements load()
	{
		InputStream in = EquipmentRequirements.class.getResourceAsStream(RESOURCE);
		if (in == null)
		{
			throw new IllegalStateException("Bundled equipment requirements are missing");
		}
		List<Rule> rules = new ArrayList<>();
		try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
		{
			JsonObject root = new JsonParser().parse(reader).getAsJsonObject();
			if (root.get("schema").getAsInt() != 1)
			{
				throw new IllegalStateException("Unsupported equipment requirements schema");
			}
			for (JsonElement element : root.getAsJsonArray("rules"))
			{
				JsonObject row = element.getAsJsonObject();
				Rule rule = new Rule();
				rule.label = row.get("label").getAsString();
				rule.source = row.get("source").getAsString();
				rule.pattern = Pattern.compile(row.get("pattern").getAsString());
				rule.combat = row.get("combat").getAsInt();
				rule.reviewRequired = row.get("reviewRequired").getAsBoolean();
				for (JsonElement slot : row.getAsJsonArray("slots"))
				{
					Slot value = Slot.fromApiKey(slot.getAsString());
					if (value == null)
					{
						throw new IllegalStateException("Unknown requirement slot");
					}
					rule.slots.add(value);
				}
				for (JsonElement id : row.getAsJsonArray("ids"))
				{
					rule.ids.add(id.getAsInt());
				}
				for (Map.Entry<String, JsonElement> e : row.getAsJsonObject("requirements").entrySet())
				{
					int level = e.getValue().getAsInt();
					if (!SKILLS.containsValue(e.getKey()) || level < 1 || level > 99)
					{
						throw new IllegalStateException("Invalid requirement for " + rule.label);
					}
					rule.requirements.put(e.getKey(), level);
				}
				rules.add(rule);
			}
		}
		catch (IOException | RuntimeException e)
		{
			throw new IllegalStateException("Bundled equipment requirements are unreadable", e);
		}
		return new EquipmentRequirements(rules);
	}

	/**
	 * Read an item's actual parameter table on the client thread. Testing presence is necessary:
	 * getIntValue returns a param's default for an absent key, which can look like an Attack skill ID.
	 */
	public Resolution resolve(GearItem item, ItemComposition composition)
	{
		IterableHashTable<Node> params = composition.getParams();
		return resolve(item, composition::getIntValue, id -> params != null && params.get(id) != null);
	}

	/** Resolve against a parameter reader; no client objects escape into the result. */
	public Resolution resolve(GearItem item, IntUnaryOperator value, IntPredicate present)
	{
		Map<String, Integer> requirements = new HashMap<>();
		Map<Integer, Integer> unmodelled = new HashMap<>();
		boolean invalid = false;
		for (int[] pair : PAIRS)
		{
			boolean skillPresent = present.test(pair[0]);
			boolean levelPresent = present.test(pair[1]);
			if (!skillPresent && !levelPresent)
			{
				continue;
			}
			if (!skillPresent || !levelPresent)
			{
				invalid = true;
				continue;
			}
			int skill = value.applyAsInt(pair[0]);
			int level = value.applyAsInt(pair[1]);
			if (skill < 0 || level < 1 || level > 99)
			{
				invalid = true;
				continue;
			}
			String key = SKILLS.get(skill);
			if (key == null)
			{
				unmodelled.merge(skill, level, Math::max);
			}
			else
			{
				requirements.merge(key, level, Math::max);
			}
		}
		boolean cache = !requirements.isEmpty();
		Rule rule = match(item);
		if (rule != null)
		{
			for (Map.Entry<String, Integer> e : rule.requirements.entrySet())
			{
				requirements.merge(e.getKey(), e.getValue(), Math::max);
			}
		}
		// Do not silently bless the offline pegasian parameter anomaly before an equip check.
		boolean review = rule != null && rule.reviewRequired;
		if (item.getId() == 13237)
		{
			requirements.remove("attack");
		}
		Source source = invalid || !unmodelled.isEmpty() || review ? Source.REVIEW_REQUIRED
			: rule != null ? cache ? Source.RULE_AND_CACHE : Source.RULE
			: cache ? Source.CACHE : Source.UNRESOLVED;
		return new Resolution(requirements, unmodelled, source, rule == null ? "" : rule.label,
			rule == null ? "" : rule.source, rule == null ? 0 : rule.combat);
	}

	private Rule match(GearItem item)
	{
		Rule matched = null;
		String name = item.getName().toLowerCase(Locale.ROOT).trim();
		for (Rule rule : rules)
		{
			if (rule.slots.contains(item.getSlot()) && (rule.ids.isEmpty()
				? rule.pattern.matcher(name).matches() : rule.ids.contains(item.getId())))
			{
				if (matched != null)
				{
					throw new IllegalStateException("Overlapping wear rules for " + item.getName());
				}
				matched = rule;
			}
		}
		return matched;
	}

	/**
	 * Replace API skill fields only for reviewed families. All other equipment keeps its current
	 * baseline until the local equipment loader is ready. The pegasian exception stays review-only.
	 */
	public boolean applyReviewed(GearItem item)
	{
		Resolution resolution = resolve(item, id -> 0, id -> false);
		return resolution.applyTo(item);
	}

	/** Input provenance, not a certificate of quest access or server-side requirement completeness. */
	public enum Source
	{
		RULE, CACHE, RULE_AND_CACHE, REVIEW_REQUIRED, UNRESOLVED
	}

	@Getter
	public static final class Resolution
	{
		private final Map<String, Integer> requirements;
		private final Map<Integer, Integer> unmodelledSkills;
		private final Source source;
		private final String rule;
		private final String citation;
		private final int combat;

		private Resolution(Map<String, Integer> requirements, Map<Integer, Integer> unmodelledSkills,
			Source source, String rule, String citation, int combat)
		{
			this.requirements = Collections.unmodifiableMap(new HashMap<>(requirements));
			this.unmodelledSkills = Collections.unmodifiableMap(new HashMap<>(unmodelledSkills));
			this.source = source;
			this.rule = rule;
			this.citation = citation;
			this.combat = combat;
		}

		/** Unresolved or review-only items must not become unrestricted in a local catalogue. */
		public boolean isResolved()
		{
			return source != Source.UNRESOLVED && source != Source.REVIEW_REQUIRED;
		}

		/**
		 * Raise the item's levels to any stricter level this resolution states, never lowering one. Used for
		 * the live cache over the bundled snapshot, whose levels already include the reviewed rules.
		 */
		public boolean raise(GearItem item)
		{
			int[] before = levels(item);
			item.setAttackReq(Math.max(item.getAttackReq(), requirements.getOrDefault("attack", 1)));
			item.setDefenceReq(Math.max(item.getDefenceReq(), requirements.getOrDefault("defence", 1)));
			item.setStrengthReq(Math.max(item.getStrengthReq(), requirements.getOrDefault("strength", 1)));
			item.setHitpointsReq(Math.max(item.getHitpointsReq(), requirements.getOrDefault("hitpoints", 1)));
			item.setRangedReq(Math.max(item.getRangedReq(), requirements.getOrDefault("ranged", 1)));
			item.setPrayerReq(Math.max(item.getPrayerReq(), requirements.getOrDefault("prayer", 1)));
			item.setMagicReq(Math.max(item.getMagicReq(), requirements.getOrDefault("magic", 1)));
			item.setSlayerReq(Math.max(item.getSlayerReq(), requirements.getOrDefault("slayer", 1)));
			item.setCombatReq(Math.max(item.getCombatReq(), combat));
			return !java.util.Arrays.equals(before, levels(item));
		}

		private static int[] levels(GearItem item)
		{
			return new int[]{item.getAttackReq(), item.getDefenceReq(), item.getStrengthReq(), item.getHitpointsReq(),
				item.getRangedReq(), item.getPrayerReq(), item.getMagicReq(), item.getSlayerReq(), item.getCombatReq()};
		}

		/** Apply a resolved combat-skill vector, returning false without mutation for a gap. */
		public boolean applyTo(GearItem item)
		{
			if (!isResolved())
			{
				return false;
			}
			item.setAttackReq(requirements.getOrDefault("attack", 1));
			item.setDefenceReq(requirements.getOrDefault("defence", 1));
			item.setStrengthReq(requirements.getOrDefault("strength", 1));
			item.setHitpointsReq(requirements.getOrDefault("hitpoints", 1));
			item.setRangedReq(requirements.getOrDefault("ranged", 1));
			item.setPrayerReq(requirements.getOrDefault("prayer", 1));
			item.setMagicReq(requirements.getOrDefault("magic", 1));
			item.setSlayerReq(requirements.getOrDefault("slayer", 1));
			item.setCombatReq(combat);
			return true;
		}
	}

	private static final class Rule
	{
		private String label;
		private String source;
		private Pattern pattern;
		private int combat;
		private boolean reviewRequired;
		private final List<Slot> slots = new ArrayList<>();
		private final List<Integer> ids = new ArrayList<>();
		private final Map<String, Integer> requirements = new HashMap<>();
	}
}

package com.bestgearsetup.data;

import com.bestgearsetup.OwnershipRules;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.IntFunction;
import java.util.function.IntPredicate;
import lombok.Getter;

/**
 * Immutable snapshot of the reference data (monsters, equipment, spells, prayers, potions).
 */
public class GameData
{
	private static final String[] EXCLUDED_NAME_PARTS = {
		"(fractured archive)", "(uncharged)", "(no burn dmg)", "(unranked)", "(unfrozen target)",
	};

	/** Minigame-only items (Barbarian Assault arrows) that cannot be used elsewhere. */
	private static final java.util.Set<String> EXCLUDED_NAMES = new java.util.HashSet<>(java.util.Arrays.asList(
		"bullet arrow", "field arrow", "blunt arrow", "barbed arrow"));

	private static final String[] EXCLUDED_NAME_PREFIXES = {
		"starter staff",
	};

	@Getter
	private final List<MonsterSummary> monsters;
	private final Map<Slot, List<GearItem>> itemsBySlot = new EnumMap<>(Slot.class);
	private final Map<Slot, Map<Integer, GearItem>> itemsBySlotAndId = new EnumMap<>(Slot.class);
	@Getter
	private final List<Spell> spells;
	private final Map<CombatClass, List<OffensivePrayer>> prayers = new EnumMap<>(CombatClass.class);
	private final Map<Integer, MonsterSummary> monstersById = new HashMap<>();
	/** Variants grouped by base name, in bundle order of each group's first variant. */
	private final List<MonsterGroup> groups = new ArrayList<>();
	/** The same groups holding only their boss variants. */
	private final List<MonsterGroup> bossGroups = new ArrayList<>();
	private final Map<String, List<Potion>> potions = new HashMap<>();

	/**
	 * Wear requirements are taken as given: the bundled Wiki snapshot already combines cache parameters,
	 * Wiki text and the reviewed rule table.
	 */
	public GameData(
		List<MonsterSummary> monsters,
		Map<String, List<GearItem>> equipmentBySlotKey,
		List<GearItem> weapons,
		List<Spell> spells,
		Map<String, List<Prayer>> prayersByCategory,
		Map<String, List<Potion>> potionsBySkill)
	{
		this.monsters = Collections.unmodifiableList(new ArrayList<>(monsters));
		indexMonsters();

		for (Slot slot : Slot.values())
		{
			itemsBySlot.put(slot, new ArrayList<>());
			itemsBySlotAndId.put(slot, new HashMap<>());
		}
		for (Map.Entry<String, List<GearItem>> e : equipmentBySlotKey.entrySet())
		{
			Slot slot = Slot.fromApiKey(e.getKey());
			if (slot == null || slot == Slot.WEAPON)
			{
				continue;
			}
			for (GearItem item : e.getValue())
			{
				addItem(slot, item);
			}
		}
		for (GearItem weapon : weapons)
		{
			addItem(Slot.WEAPON, weapon);
		}

		this.spells = Collections.unmodifiableList(new ArrayList<>(spells));
		buildPrayers(prayersByCategory);
		if (potionsBySkill != null)
		{
			for (Map.Entry<String, List<Potion>> e : potionsBySkill.entrySet())
			{
				List<Potion> list = new ArrayList<>();
				for (Potion p : e.getValue())
				{
					// The dragon battleaxe "boost" depends on levels drained elsewhere; not modelled.
					if (p != null && !p.getName().equalsIgnoreCase("dragon battleaxe"))
					{
						list.add(p);
					}
				}
				potions.put(e.getKey().toLowerCase(Locale.ROOT), Collections.unmodifiableList(list));
			}
		}
	}

	private void indexMonsters()
	{
		for (MonsterSummary m : this.monsters)
		{
			for (int id : m.getIds())
			{
				monstersById.putIfAbsent(id, m);
			}
		}
		Map<String, List<MonsterSummary>> byBase = new LinkedHashMap<>();
		Map<String, List<MonsterSummary>> bossesByBase = new LinkedHashMap<>();
		for (MonsterSummary m : this.monsters)
		{
			String base = MonsterGroup.baseName(m.getName());
			byBase.computeIfAbsent(base, k -> new ArrayList<>()).add(m);
			if (m.isBoss())
			{
				bossesByBase.computeIfAbsent(base, k -> new ArrayList<>()).add(m);
			}
		}
		byBase.forEach((base, variants) -> groups.add(new MonsterGroup(base, variants)));
		bossesByBase.forEach((base, variants) -> bossGroups.add(new MonsterGroup(base, variants)));
	}

	/** @param gson the client's Gson, used to deep-copy the items (plugins may not create their own) */
	private GameData(Gson gson, GameData base, List<MonsterSummary> monsters)
	{
		this.monsters = Collections.unmodifiableList(new ArrayList<>(monsters));
		indexMonsters();
		for (Slot slot : Slot.values())
		{
			itemsBySlot.put(slot, new ArrayList<>());
			itemsBySlotAndId.put(slot, new HashMap<>());
			for (GearItem item : base.itemsBySlot.get(slot))
			{
				addItem(slot, gson.fromJson(gson.toJson(item), GearItem.class));
			}
		}
		spells = base.spells;
		prayers.putAll(base.prayers);
		potions.putAll(base.potions);
	}

	/**
	 * The same equipment, spells, prayers and potions with another monster list.
	 *
	 * @param gson the client's Gson, used to deep-copy the items
	 */
	public GameData withMonsters(Gson gson, List<MonsterSummary> replacement)
	{
		return new GameData(gson, this, replacement);
	}

	private void addItem(Slot slot, GearItem item)
	{
		// The same id can appear in two slots (darts are both blowpipe ammo and thrown weapons). Within a slot
		// one id may name two states with different stats (the keris partisan of amascut inside and outside
		// the Tombs of Amascut); encounter rules pick one, and id lookups return the first.
		Map<Integer, GearItem> byId = itemsBySlotAndId.get(slot);
		GearItem existing = item == null ? null : byId.get(item.getId());
		if (item == null || isExcluded(item) || existing != null && existing.getName().equals(item.getName()))
		{
			return;
		}
		item.setSlot(slot);
		itemsBySlot.get(slot).add(item);
		byId.putIfAbsent(item.getId(), item);
	}

	/**
 * Unsupported custom Leagues items and unusable uncharged weapons. Activity gear is filtered per encounter.
	 * Optional DMM, Bounty Hunter and beta equipment stays in the catalogue for search-time filtering.
	 */
	static boolean isExcluded(GearItem item)
	{
		if (item.isLeagueEquipment())
		{
			return true;
		}
		if (item.getId() <= 0)
		{
			return true;
		}
		String name = item.getName().toLowerCase(Locale.ROOT);
		if (EXCLUDED_NAMES.contains(name))
		{
			return true;
		}
		for (String part : EXCLUDED_NAME_PARTS)
		{
			if (name.contains(part))
			{
				return true;
			}
		}
		for (String prefix : EXCLUDED_NAME_PREFIXES)
		{
			if (name.startsWith(prefix))
			{
				return true;
			}
		}
		return false;
	}

	private void buildPrayers(Map<String, List<Prayer>> byCategory)
	{
		// Melee pairs the attack and strength entries of the same prayer (e.g. piety 20% / 23%).
		Map<String, Prayer> meleeAttack = standardByName(byCategory.get("attack"));
		Map<String, Prayer> meleeStrength = standardByName(byCategory.get("strength"));
		List<OffensivePrayer> melee = new ArrayList<>();
		for (Map.Entry<String, Prayer> e : meleeStrength.entrySet())
		{
			Prayer str = e.getValue();
			Prayer att = meleeAttack.get(e.getKey());
			melee.add(new OffensivePrayer(str.getName(), att == null ? 0 : att.getBoost(), str.getBoost(),
				str.getPrayerLevel(), str.getDefenceLevel()));
		}
		for (Map.Entry<String, Prayer> e : meleeAttack.entrySet())
		{
			if (!meleeStrength.containsKey(e.getKey()))
			{
				Prayer att = e.getValue();
				melee.add(new OffensivePrayer(att.getName(), att.getBoost(), 0, att.getPrayerLevel(), att.getDefenceLevel()));
			}
		}
		prayers.put(CombatClass.MELEE, melee);
		prayers.put(CombatClass.RANGED, toOffensive(byCategory.get("ranged")));
		prayers.put(CombatClass.MAGIC, toOffensive(byCategory.get("magic")));
	}

	private static Map<String, Prayer> standardByName(List<Prayer> list)
	{
		Map<String, Prayer> out = new LinkedHashMap<>();
		if (list != null)
		{
			for (Prayer p : list)
			{
				if (p != null && p.getName() != null && "standard".equalsIgnoreCase(p.getPrayerbook())
					&& isGamePrayer(p.getName()))
				{
					out.put(p.getName(), p);
				}
			}
		}
		return out;
	}

	private static boolean isGamePrayer(String name)
	{
		for (net.runelite.api.Prayer prayer : net.runelite.api.Prayer.values())
		{
			if (prayer.name().replace('_', ' ').equalsIgnoreCase(name))
			{
				return true;
			}
		}
		return false;
	}

	private static List<OffensivePrayer> toOffensive(List<Prayer> list)
	{
		List<OffensivePrayer> out = new ArrayList<>();
		for (Prayer p : standardByName(list).values())
		{
			out.add(new OffensivePrayer(p.getName(), p.getBoost(), p.getStrengthBoost(), p.getPrayerLevel(), p.getDefenceLevel()));
		}
		return out;
	}

	public List<GearItem> getItems(Slot slot)
	{
		return Collections.unmodifiableList(itemsBySlot.get(slot));
	}

	/**
	 * Before publication, expose folded cosmetics as exact items using client-thread cache identities.
	 * They retain the snapshot's identical stats, but have their own name, price and ownership evidence.
	 */
	public void addVariantItems(Gson gson, IntFunction<String> names, IntPredicate tradeable)
	{
		for (Slot slot : Slot.values())
		{
			for (GearItem item : new ArrayList<>(getItems(slot)))
			{
				for (int variant : item.getVariants())
				{
					if (getItem(slot, variant) != null || OwnershipRules.equivalent(item.getId(), variant))
					{
						continue;
					}
					String name = names.apply(variant);
					if (name == null || name.isEmpty() || name.equalsIgnoreCase("null"))
					{
						continue;
					}
					GearItem copy = gson.fromJson(gson.toJson(item), GearItem.class);
					copy.setId(variant);
					copy.setCombatName(item.getCombatName());
					copy.setName(name.toLowerCase(Locale.ROOT));
					if (item.isDmmEquipment() && !copy.isDmmEquipment())
					{
						copy.setName(copy.getName() + " (dmm)");
					}
					if (item.isBountyHunterEquipment() && !copy.isBountyHunterEquipment())
					{
						copy.setName(copy.getName() + " (bh)");
					}
					if (item.isBetaEquipment() && !copy.isBetaEquipment())
					{
						copy.setName(copy.getName() + " (beta)");
					}
					copy.setTradeable(tradeable.test(variant));
					copy.setVariants(Collections.singletonList(variant));
					addItem(slot, copy);
				}
			}
		}
	}

	public GearItem getItem(Slot slot, int id)
	{
		return itemsBySlotAndId.get(slot).get(id);
	}

	/** Potions boosting a skill: attack, strength, defence, ranged or magic. */
	public List<Potion> getPotions(String skill)
	{
		return potions.getOrDefault(skill, Collections.emptyList());
	}

	/** Finds an item in any slot by id. */
	public GearItem findItem(int id)
	{
		for (Slot slot : Slot.values())
		{
			GearItem item = itemsBySlotAndId.get(slot).get(id);
			if (item != null)
			{
				return item;
			}
		}
		return null;
	}

	/**
	 * Entries in the item's slot that share its name once trailing parenthesised suffixes are removed, e.g.
	 * "dragon hunter crossbow" and "dragon hunter crossbow (b)". Includes the item itself. Members can differ
	 * in stats or effects ("ruby bolts (e)"), so excluding the family is offered as a separate choice.
	 */
	public List<GearItem> variantFamily(GearItem item)
	{
		String family = familyName(item.getName());
		List<GearItem> out = new ArrayList<>();
		for (GearItem other : getItems(item.getSlot()))
		{
			if (other.getId() == item.getId() || familyName(other.getName()).equals(family))
			{
				out.add(other);
			}
		}
		return out;
	}

	/** The name without trailing parenthesised suffixes: "dragon hunter crossbow (b)" -> "dragon hunter crossbow". */
	public static String familyName(String name)
	{
		return name.toLowerCase(Locale.ROOT).replaceFirst("(\\s*\\([^()]*\\))+$", "").trim();
	}

	/** Case-insensitive substring search over all equipment names, one entry per item id. */
	public List<GearItem> searchItems(String query, int limit)
	{
		return searchItems(query, limit, null);
	}

	/** As {@link #searchItems(String, int)}, limited to one equipment slot (null for every slot). */
	public List<GearItem> searchItems(String query, int limit, Slot only)
	{
		String q = query == null ? "" : query.toLowerCase(Locale.ROOT).trim();
		List<GearItem> prefix = new ArrayList<>();
		List<GearItem> contains = new ArrayList<>();
		if (q.isEmpty())
		{
			return prefix;
		}
		java.util.Set<Integer> seen = new java.util.HashSet<>();
		for (Slot slot : only == null ? Slot.values() : new Slot[]{only})
		{
			for (GearItem item : itemsBySlot.get(slot))
			{
				String n = item.getName();
				if (!n.contains(q) || !seen.add(item.getId()))
				{
					continue;
				}
				(n.startsWith(q) ? prefix : contains).add(item);
			}
		}
		prefix.sort(java.util.Comparator.comparing(GearItem::getName));
		contains.sort(java.util.Comparator.comparing(GearItem::getName));
		prefix.addAll(contains);
		return prefix.size() > limit ? new ArrayList<>(prefix.subList(0, limit)) : prefix;
	}

	public List<OffensivePrayer> getPrayers(CombatClass combatClass)
	{
		return Collections.unmodifiableList(prayers.getOrDefault(combatClass, Collections.emptyList()));
	}

	/**
	 * Find the monster variant for an in-game NPC: exact NPC id first, then the same name and
	 * combat level, then the same name (variants carry suffixes, e.g. "vorkath (post-quest)").
	 */
	public MonsterSummary matchNpc(int npcId, String npcName, int combatLevel)
	{
		MonsterSummary byId = monstersById.get(npcId);
		if (byId != null)
		{
			return byId;
		}
		if (npcName == null)
		{
			return null;
		}
		String name = npcName.toLowerCase(Locale.ROOT).trim();
		MonsterSummary sameName = null;
		MonsterSummary prefixLevel = null;
		MonsterSummary prefix = null;
		for (MonsterSummary m : monsters)
		{
			String n = m.getName();
			if (n.equals(name))
			{
				if (m.getCombatLevel() == combatLevel)
				{
					return m;
				}
				if (sameName == null)
				{
					sameName = m;
				}
			}
			else if (n.startsWith(name + " ("))
			{
				if (m.getCombatLevel() == combatLevel && prefixLevel == null)
				{
					prefixLevel = m;
				}
				if (prefix == null)
				{
					prefix = m;
				}
			}
		}
		if (prefixLevel != null)
		{
			return prefixLevel;
		}
		return sameName != null ? sameName : prefix;
	}

	/**
	 * Case-insensitive substring search over monster groups, matching the base name or any variant's full
	 * name; exact and prefix matches rank first.
	 *
	 * @param bossesOnly search only bosses, each group holding only its boss variants
	 */
	public List<MonsterGroup> searchMonsterGroups(String query, int limit, boolean bossesOnly)
	{
		String q = query == null ? "" : query.toLowerCase(Locale.ROOT).trim();
		if (q.isEmpty())
		{
			return new ArrayList<>();
		}
		// Exact, prefix and substring matches.
		List<List<MonsterGroup>> ranked = Arrays.asList(new ArrayList<>(), new ArrayList<>(), new ArrayList<>());
		for (MonsterGroup group : bossesOnly ? bossGroups : groups)
		{
			int rank = matchRank(group.getName(), q);
			for (MonsterSummary variant : group.getVariants())
			{
				rank = Math.min(rank, matchRank(variant.getName(), q));
			}
			if (rank < ranked.size())
			{
				ranked.get(rank).add(group);
			}
		}
		List<MonsterGroup> out = new ArrayList<>();
		ranked.forEach(out::addAll);
		return out.size() > limit ? new ArrayList<>(out.subList(0, limit)) : out;
	}

	/** 0 for an exact match, 1 for a prefix, 2 for a substring, 3 for none. */
	private static int matchRank(String name, String q)
	{
		if (name.equals(q))
		{
			return 0;
		}
		if (name.startsWith(q))
		{
			return 1;
		}
		return name.contains(q) ? 2 : 3;
	}

	/**
	 * The group a variant belongs to, restricted to bosses when asked and the variant is one; a target outside
	 * the bundled list forms a group of its own.
	 */
	public MonsterGroup groupOf(MonsterSummary monster, boolean bossesOnly)
	{
		if (bossesOnly)
		{
			for (MonsterGroup group : bossGroups)
			{
				if (group.contains(monster))
				{
					return group;
				}
			}
		}
		for (MonsterGroup group : groups)
		{
			if (group.contains(monster))
			{
				return group;
			}
		}
		return MonsterGroup.single(monster);
	}

	public static String titleCase(String s)
	{
		StringBuilder sb = new StringBuilder(s.length());
		boolean upper = true;
		for (char c : s.toCharArray())
		{
			sb.append(upper ? Character.toUpperCase(c) : c);
			upper = c == ' ' || c == '(' || c == '-';
		}
		return sb.toString();
	}
}

package com.bestgearsetup.data;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.reflect.TypeToken;
import java.util.List;
import java.util.Map;

/**
 * Builds {@link GameData} from JSON in the plugin's catalogue schema (equipment by slot, weapons, spells,
 * prayers and potions), which the bundled Wiki snapshot is written in.
 */
public final class GameDataJson
{
	private GameDataJson()
	{
	}

	static GameData parse(Gson gson, JsonObject monsters, JsonObject equipment, JsonObject weapons,
		JsonObject spells, JsonObject prayers, JsonObject potions)
	{
		TypeToken<List<MonsterSummary>> monsterList = new TypeToken<List<MonsterSummary>>()
		{
		};
		TypeToken<Map<String, List<GearItem>>> equipmentMap = new TypeToken<Map<String, List<GearItem>>>()
		{
		};
		TypeToken<List<GearItem>> gearList = new TypeToken<List<GearItem>>()
		{
		};
		TypeToken<List<Spell>> spellList = new TypeToken<List<Spell>>()
		{
		};
		TypeToken<Map<String, List<Prayer>>> prayerMap = new TypeToken<Map<String, List<Prayer>>>()
		{
		};
		TypeToken<Map<String, List<Potion>>> potionMap = new TypeToken<Map<String, List<Potion>>>()
		{
		};

		return new GameData(
			gson.fromJson(monsters.get("monsters"), monsterList.getType()),
			gson.fromJson(equipment.get("equipment"), equipmentMap.getType()),
			gson.fromJson(weapons.get("weapons"), gearList.getType()),
			gson.fromJson(spells.get("spells"), spellList.getType()),
			gson.fromJson(prayers.get("prayers"), prayerMap.getType()),
			potions == null ? null : gson.fromJson(potions.get("potions"), potionMap.getType()));
	}
}

package com.bestgearsetup.data;

import com.google.gson.Gson;
import java.io.IOException;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Game data from the bundled OSRS Wiki snapshots. Nothing is downloaded; the first call parses the
 * bundles, so call it off the client thread.
 */
@Singleton
public class GameDataLoader
{
	private final Gson gson;

	@Inject
	public GameDataLoader(Gson gson)
	{
		this.gson = gson;
	}

	/** Monsters, equipment, spells, prayers and potions. */
	public GameData loadGameData() throws IOException
	{
		return WikiGameData.get(gson).gameData(gson);
	}

	/** Full stats for the selected variant, as a copy the caller may adjust. */
	public Monster getMonster(MonsterSummary summary) throws IOException
	{
		Monster monster = WikiMonsters.get(gson).monster(summary.getName());
		if (monster == null)
		{
			throw new IOException("No bundled Wiki data for " + summary.getName());
		}
		return monster;
	}

	/** Where the data comes from, for the search notes. */
	public String describeSource()
	{
		try
		{
			return "Game data: bundled OSRS Wiki snapshots (equipment " + WikiGameData.get(gson).getRetrieved()
				+ ", monsters " + WikiMonsters.get(gson).getRetrieved() + ").";
		}
		catch (IOException e)
		{
			return "Game data: bundled OSRS Wiki snapshots.";
		}
	}
}

package com.bestgearsetup.data;

import com.bestgearsetup.ItemCosts;
import com.bestgearsetup.OwnershipRules;
import com.google.gson.annotations.SerializedName;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.stream.Collectors;
import lombok.Data;
import net.runelite.api.gameval.ItemID;

/**
 * A piece of equipment or a weapon from the bundled data. Weapons carry the extra
 * weapon-only fields (speed, styles, ammunition); armour leaves them at their defaults.
 */
@Data
public class GearItem
{
	private int id;
	private String name;
	/** Original snapshot identity for stat-identical cosmetics whose display name has a prefix. */
	private String combatName;
	/** Fixed acquisition price used by offline tests; the plugin prices items from RuneLite at search time. */
	private long price;
	private boolean tradeable;
	private boolean members;

	/** Item ids folded into this entry (ornament kits, charges, recolours). */
	private List<Integer> variants;

	/** Filled in by {@link GameData} from the slot the item was listed under. */
	private transient Slot slot;
	/** Derived from the names and id; cleared by their setters. Transient keeps them out of Gson and equals. */
	private transient String lowerCombatName;
	private transient Boolean dmmEquipment;

	@SerializedName("stab_bonus")
	private int stabBonus;
	@SerializedName("slash_bonus")
	private int slashBonus;
	@SerializedName("crush_bonus")
	private int crushBonus;
