/**
 * Full monster stats from the bundled Wiki snapshot.
 */
@Data
public class Monster
{
	private int id;
	private String name;
	@SerializedName("level_cb")
	private int combatLevel;
	@SerializedName("level_hp")
	private int hitpoints;
	@SerializedName("level_attack")
	private int attackLevel;
	@SerializedName("level_strength")
	private int strengthLevel;
	@SerializedName("level_defence")
	private int defenceLevel;
	/** Specials cannot drain Defence below this level. */
	@SerializedName("defence_floor")
	private int defenceFloor;
	@SerializedName("immune_thrall")
	private boolean immuneThrall;
	@SerializedName("immune_poison")
	private boolean immunePoison;
	@SerializedName("immune_venom")
	private boolean immuneVenom;
	@SerializedName("level_magic")
	private int magicLevel;
	@SerializedName("level_ranged")
	private int rangedLevel;
	@SerializedName("agg_magic")
	private int magicAttackBonus;

	@SerializedName("def_stab")
	private int defStab;
	@SerializedName("def_slash")
	private int defSlash;
	@SerializedName("def_crush")
	private int defCrush;
	@SerializedName("def_magic")
	private int defMagic;
	/** Standard ranged defence (arrows). */
	@SerializedName("def_ranged")
	private int defRanged;
	/** Light ranged defence (darts, knives, thrown). Null when the API has no split value. */
	@SerializedName("def_light")
	private Integer defLight;
	/** Heavy ranged defence (bolts). Null when the API has no split value. */
	@SerializedName("def_heavy")
	private Integer defHeavy;
	@SerializedName("weakness_type")
	private String weaknessType;
	private int weakness;
	@SerializedName(value = "flat", alternate = {"flat_armour"})
	private Integer flatArmour;
	@SerializedName("demonbane_vulnerability")
	private Integer demonbaneVulnerability;

	private int size = 1;
	private boolean task;
	private List<Attribute> attributes;
	/** The monster's own attacks, keyed by name ("slash", "magic", "dragonfire"...). */
	private Map<String, MonsterAttack> attackStyles;

	/** Built on first use; volatile so searches on several threads see the whole set. */
	private transient volatile Set<String> attributeNames;
	/** Derived from the name; cleared by {@link #setName}. */
	private transient String lowerName;
	/** Selected temporary boss state; set by the search, never by the API. */
	private transient EncounterPhase phase = EncounterPhase.STANDARD;
	/** Tombs of Amascut raid level applied to this target's defence roll; zero when unscaled. */
	private transient int toaRaidLevel;

	@Data
	public static class Attribute
	{
		private String name;
	}

	@Data
	public static class MonsterAttack
	{
		@SerializedName("max_hit")
		private int maxHit;
		private double weighting;
		private boolean typeless;
	}

	/** Shallow copy, used to apply stat drains without touching the cached monster. */
	public Monster copy()
	{
		Monster m = new Monster();
		m.id = id;
		m.name = name;
		m.combatLevel = combatLevel;
		m.hitpoints = hitpoints;
		m.attackLevel = attackLevel;
		m.strengthLevel = strengthLevel;
		m.defenceLevel = defenceLevel;
		m.defenceFloor = defenceFloor;
		m.immuneThrall = immuneThrall;
		m.immunePoison = immunePoison;
		m.immuneVenom = immuneVenom;
		m.magicLevel = magicLevel;
		m.rangedLevel = rangedLevel;
		m.magicAttackBonus = magicAttackBonus;
		m.defStab = defStab;
		m.defSlash = defSlash;
		m.defCrush = defCrush;
		m.defMagic = defMagic;
		m.defRanged = defRanged;
		m.defLight = defLight;
		m.defHeavy = defHeavy;
		m.weaknessType = weaknessType;
		m.weakness = weakness;
		m.flatArmour = flatArmour;
		m.demonbaneVulnerability = demonbaneVulnerability;
		m.size = size;
		m.task = task;
		m.attributes = attributes;
		m.attackStyles = attackStyles;
		m.attributeNames = attributeNames;
		m.lowerName = lowerName;
		m.phase = phase;
		m.toaRaidLevel = toaRaidLevel;
		return m;
	}

	public String getName()
	{
		return name == null ? "" : name;
	}

	public void setName(String name)
	{
		this.name = name;
		lowerName = null;
	}

	/** {@link #getName()} in lower case; encounter rules match it for every setup the search scores. */
	public String getLowerName()
	{
		String lower = lowerName;
		if (lower == null)
		{
			lower = getName().toLowerCase(Locale.ROOT);
			lowerName = lower;
		}
		return lower;
	}

	public EncounterPhase getPhase()
	{
		return phase == null ? EncounterPhase.STANDARD : phase;
	}

	public String getDisplayName()
	{
		return GameData.titleCase(getName());
	}

	public boolean hasAttribute(String attribute)
	{
		if (attributeNames == null)
		{
			Set<String> names = new HashSet<>();
			for (Attribute a : attributes == null ? Collections.<Attribute>emptyList() : attributes)
			{
				if (a != null && a.getName() != null)
				{
					names.add(a.getName().toLowerCase(Locale.ROOT));
				}
			}
			attributeNames = names;
		}
		return attributeNames.contains(attribute.toLowerCase(Locale.ROOT));
	}

	/** Invalidate the derived tag cache when reference data is replaced. */
	public void setAttributes(List<Attribute> attributes)
	{
		this.attributes = attributes;
		attributeNames = null;
	}

	public int getDefLightOrStandard()
	{
		return defLight == null ? defRanged : defLight;
	}

	public int getDefHeavyOrStandard()
	{
		return defHeavy == null ? defRanged : defHeavy;
	}
}

package com.bestgearsetup.data;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import lombok.Getter;

/**
 * The bundled variants of one monster ("abyssal sire (phase 1)", "abyssal sire (phase 2)"...), searched as
 * a single entry. Variants share the name left after removing their trailing parenthesised versions.
 */
public final class MonsterGroup
{
	/** Lower-case base name shared by every variant. */
	@Getter
	private final String name;
	/** Variants in natural version order ("delve 2" before "delve 10"). */
	@Getter
	private final List<MonsterSummary> variants;
	/** The variant selected when the group is picked: the first listed default version, a boss when possible. */
	@Getter
	private final MonsterSummary primary;

	MonsterGroup(String name, List<MonsterSummary> bundleOrder)
	{
		this.name = name;
		// The bundle lists Wiki default versions first, so the first boss (or first entry) is a default version.
		this.primary = bundleOrder.stream().filter(MonsterSummary::isBoss).findFirst().orElse(bundleOrder.get(0));
		List<MonsterSummary> sorted = new ArrayList<>(bundleOrder);
		sorted.sort(Comparator.comparing(this::sortKey, MonsterGroup::compareNatural));
		this.variants = Collections.unmodifiableList(sorted);
	}

	/** A group of one, for a target that is not in the bundled list. */
	static MonsterGroup single(MonsterSummary monster)
	{
		return new MonsterGroup(baseName(monster.getName()), Collections.singletonList(monster));
	}

	public String getDisplayName()
	{
		return GameData.titleCase(name);
	}

	public boolean isBoss()
	{
		return variants.stream().anyMatch(MonsterSummary::isBoss);
	}

	public boolean contains(MonsterSummary monster)
	{
		return variants.contains(monster);
	}

	public int getMinCombatLevel()
	{
		return variants.stream().mapToInt(MonsterSummary::getCombatLevel).min().orElse(0);
	}

	public int getMaxCombatLevel()
	{
		return variants.stream().mapToInt(MonsterSummary::getCombatLevel).max().orElse(0);
	}

	/** "Phase 3 (stage 1)", "Delve 1, NPC 14708"; "Standard" for the variant without a version. */
	public String versionLabel(MonsterSummary variant)
	{
		String label = sortKey(variant);
		return label.isEmpty() ? "Standard" : label;
	}

	private String sortKey(MonsterSummary variant)
	{
		String full = variant.getName();
		String rest = full.startsWith(name) ? full.substring(name.length()).trim() : full;
		List<String> parts = new ArrayList<>();
		for (String part : versions(rest))
		{
			parts.add(part.startsWith("npc ") ? "NPC" + part.substring(3)
				: Character.toUpperCase(part.charAt(0)) + part.substring(1));
		}
		return String.join(", ", parts);
	}

	/**
	 * The name without its trailing parenthesised versions: "doom of mokhaiotl (delve 1) (npc 14708)" and
	 * "abyssal sire (phase 3 (stage 1))" become "doom of mokhaiotl" and "abyssal sire".
	 */
	static String baseName(String name)
	{
		String base = name.trim();
		while (base.endsWith(")"))
		{
			int open = matchingOpen(base);
			if (open <= 0)
			{
				break;
			}
			base = base.substring(0, open).trim();
		}
		return base.isEmpty() ? name.trim() : base;
	}

	/** Top-level parenthesised groups, without their outer parentheses. */
	private static List<String> versions(String suffix)
	{
		List<String> out = new ArrayList<>();
		int depth = 0;
		int start = -1;
		for (int i = 0; i < suffix.length(); i++)
		{
			char c = suffix.charAt(i);
			if (c == '(' && depth++ == 0)
			{
				start = i + 1;
			}
			else if (c == ')' && depth > 0 && --depth == 0 && i > start)
			{
				out.add(suffix.substring(start, i).trim());
			}
		}
		out.removeIf(String::isEmpty);
		return out;
	}

	private static int matchingOpen(String s)
	{
		int depth = 0;
		for (int i = s.length() - 1; i >= 0; i--)
		{
			char c = s.charAt(i);
			if (c == ')')
			{
				depth++;
			}
			else if (c == '(' && --depth == 0)
			{
				return i;
			}
		}
		return -1;
	}

	/** Case-insensitive order that compares digit runs by value. */
	static int compareNatural(String a, String b)
	{
		String x = a.toLowerCase(Locale.ROOT);
		String y = b.toLowerCase(Locale.ROOT);
		int i = 0;
		int j = 0;
		while (i < x.length() && j < y.length())
		{
			char cx = x.charAt(i);
			char cy = y.charAt(j);
			if (Character.isDigit(cx) && Character.isDigit(cy))
			{
				int ei = i;
				int ej = j;
				while (ei < x.length() && Character.isDigit(x.charAt(ei)))
				{
					ei++;
				}
				while (ej < y.length() && Character.isDigit(y.charAt(ej)))
				{
					ej++;
				}
				String nx = x.substring(i, ei).replaceFirst("^0+(?=.)", "");
				String ny = y.substring(j, ej).replaceFirst("^0+(?=.)", "");
				int cmp = nx.length() != ny.length() ? Integer.compare(nx.length(), ny.length()) : nx.compareTo(ny);
				if (cmp != 0)
				{
					return cmp;
				}
				i = ei;
				j = ej;
			}
			else
			{
				if (cx != cy)
				{
					return Character.compare(cx, cy);
				}
				i++;
				j++;
			}
		}
		return Integer.compare(x.length() - i, y.length() - j);
	}

	@Override
	public String toString()
	{
		return getDisplayName();
	}
}

