import com.google.gson.annotations.SerializedName;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import lombok.Data;

/**
 * A combat spell. {@code spellWeapons} lists the weapon ids that can autocast it.
 */
@Data
public class Spell
{
	private String name;
	private String spellbook;
	@SerializedName("max")
	private int maxHit;
	private int level;
	@SerializedName("attack_speed")
	private int attackSpeed = 5;
	@SerializedName("spell_weapons")
	private List<String> spellWeapons;

	/** Built on first use; volatile so searches on several threads see the whole set. */
	private transient volatile Set<Integer> weaponIds;

	public boolean castableWith(int weaponId)
	{
		if (weaponIds == null)
		{
			Set<Integer> ids = new HashSet<>();
			for (String s : spellWeapons == null ? Collections.<String>emptyList() : spellWeapons)
			{
				try
				{
					ids.add(Integer.parseInt(s.trim()));
				}
				catch (NumberFormatException ignored)
				{
					// skip malformed ids
				}
			}
			weaponIds = ids;
		}
		return weaponIds.contains(weaponId);
	}

	public String getName()
	{
		return name == null ? "" : name;
	}

	@Override
	public String toString()
	{
		return GameData.titleCase(getName());
	}
}

package com.bestgearsetup.data;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import lombok.Value;

/**
 * Poison, venom, freeze and burn immunities from a bundled snapshot of the OSRS Wiki's monster
 * infoboxes (tools/wiki_status_immunities.py), consulted by NPC id, then by the variant's
 * base name. Target flags supplement the snapshot and serve as a fallback when no Wiki entry exists.
 */
public final class StatusImmunities
{
	/** Burn severities a target can resist: a burn is blocked when its severity is at most the immunity. */
	public static final int BURN_NONE = 0;
	public static final int BURN_WEAK = 1;
	public static final int BURN_NORMAL = 2;
	public static final int BURN_STRONG = 3;

	private static final String RESOURCE = "/com/bestgearsetup/status-immunities.json";
	private static volatile Map<String, int[]> byId;
	private static volatile Map<String, int[]> byName;

	private StatusImmunities()
	{
	}

	@Value
	public static class Immunity
	{
		boolean poisonImmune;
		boolean venomImmune;
		/** Venom applied to this target becomes poison. */
		boolean venomBecomesPoison;
		/** Freeze resistance in percent, or -1 when unknown. */
		int freezeResistance;
		/** Highest burn severity this target ignores (0 = none). */
		int burnImmunity;
		/** Whether Wiki data was found; otherwise only the target's flags were used. */
		boolean known;
	}

	public static Immunity of(Monster m)
	{
		load();
		int[] record = byId.get(Integer.toString(m.getId()));
		if (record == null)
		{
			String name = m.getName().toLowerCase(Locale.ROOT);
			int bracket = name.indexOf(" (");
			record = byName.get(bracket > 0 ? name.substring(0, bracket) : name);
		}
		if (record == null)
		{
			return new Immunity(m.isImmunePoison(), m.isImmuneVenom(), m.isImmuneVenom() && !m.isImmunePoison(),
				-1, BURN_NONE, false);
		}
		boolean poison = record[0] >= 100 || m.isImmunePoison();
		boolean venomPoisons = record[1] == -2;
		boolean venom = venomPoisons || record[1] >= 100 || m.isImmuneVenom();
		return new Immunity(poison, venom, venom && !poison, record[2], Math.max(0, record[3]), true);
	}

	private static void load()
	{
		if (byId != null)
		{
			return;
		}
		synchronized (StatusImmunities.class)
		{
			if (byId != null)
			{
				return;
			}
			Map<String, int[]> ids = new HashMap<>();
			Map<String, int[]> names = new HashMap<>();
			try (InputStream in = StatusImmunities.class.getResourceAsStream(RESOURCE))
			{
				if (in != null)
				{
					try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
					{
						JsonObject root = new JsonParser().parse(reader).getAsJsonObject();
						read(root.getAsJsonObject("ids"), ids);
						read(root.getAsJsonObject("names"), names);
					}
				}
			}
			catch (Exception ex)
			{
				// Fall back to the target's flags alone.
				ids.clear();
				names.clear();
			}
			byName = Collections.unmodifiableMap(names);
			byId = Collections.unmodifiableMap(ids);
		}
	}

	private static void read(JsonObject object, Map<String, int[]> out)
	{
		if (object == null)
		{
			return;
		}
		for (Map.Entry<String, JsonElement> e : object.entrySet())
		{
			JsonArray a = e.getValue().getAsJsonArray();
			int[] values = new int[4];
			for (int i = 0; i < 4 && i < a.size(); i++)
			{
				values[i] = a.get(i).getAsInt();
			}
			out.put(e.getKey(), values);
		}
	}
}

package com.bestgearsetup.data;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPInputStream;

/**
 * Equipment, weapons, spells, prayers and potions from the bundled OSRS Wiki snapshot
 * (tools/wiki_equipment.py), in the plugin's JSON schema. Nothing is downloaded at runtime. Wear
 * requirements are already combined from cache parameters, Wiki text and the reviewed rule table.
 */
public final class WikiGameData
{
	private static final String RESOURCE = "/com/bestgearsetup/wiki-gamedata.json.gz";
	private static volatile WikiGameData instance;

	private final GameData equipment;
	private final String retrieved;

	private WikiGameData(GameData equipment, String retrieved)
	{
		this.equipment = equipment;
		this.retrieved = retrieved;
	}

	/** The catalogue if something has already loaded it, otherwise null; never loads. */
	public static WikiGameData loaded()
	{
		return instance;
	}

	public static WikiGameData get(Gson gson) throws IOException
	{
		WikiGameData loaded = instance;
		if (loaded == null)
		{
			synchronized (WikiGameData.class)
			{
				loaded = instance;
				if (loaded == null)
				{
					loaded = load(gson);
					instance = loaded;
				}
			}
		}
		return loaded;
	}

	private static WikiGameData load(Gson gson) throws IOException
	{
		InputStream in = WikiGameData.class.getResourceAsStream(RESOURCE);
		if (in == null)
		{
			throw new IOException("Bundled Wiki equipment data is missing");
		}
		try (Reader reader = new InputStreamReader(new GZIPInputStream(in), StandardCharsets.UTF_8))
		{
			JsonObject root = new JsonParser().parse(reader).getAsJsonObject();
			String stamp = root.has("retrievedUtc") ? root.get("retrievedUtc").getAsString() : "";
			JsonObject monsters = new JsonObject();
			monsters.add("monsters", new JsonArray());
			GameData data = GameDataJson.parse(gson, monsters, root, root, root, root, root);
			return new WikiGameData(data, stamp.length() >= 10 ? stamp.substring(0, 10) : "unknown date");
		}
		catch (RuntimeException e)
		{
			throw new IOException("Bundled Wiki equipment data is unreadable", e);
		}
	}

	/** The bundled equipment with the bundled Wiki monster list. */
	public GameData gameData(Gson gson) throws IOException
	{
		return equipment.withMonsters(gson, WikiMonsters.get(gson).getSummaries());
	}

	/** The shared bundled equipment catalogue, without monsters; callers must not modify it. */
	public GameData getEquipment()
	{
		return equipment;
	}

	/** Snapshot date (yyyy-mm-dd). */
	public String getRetrieved()
	{
		return retrieved;
	}
}

package com.bestgearsetup.data;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.zip.GZIPInputStream;

/**
 * Monster stats from the bundled OSRS Wiki snapshot (tools/wiki_monsters.py), in the plugin's monster
 * schema. Nothing is downloaded at runtime. Variants are keyed by name because several share an NPC id.
 */
public final class WikiMonsters
{
	private static final String RESOURCE = "/com/bestgearsetup/wiki-monsters.json.gz";
	private static volatile WikiMonsters instance;

	private final List<MonsterSummary> summaries;
	private final Map<String, Monster> byName;
	private final String retrieved;

	private WikiMonsters(List<MonsterSummary> summaries, Map<String, Monster> byName, String retrieved)
	{
		this.summaries = summaries;
		this.byName = byName;
		this.retrieved = retrieved;
	}

	/** Snapshot date (yyyy-mm-dd). */
	public String getRetrieved()
	{
		return retrieved;
	}

	public static WikiMonsters get(Gson gson) throws IOException
	{
		WikiMonsters loaded = instance;
		if (loaded == null)
		{
			synchronized (WikiMonsters.class)
			{
				loaded = instance;
				if (loaded == null)
				{
					loaded = load(gson);
					instance = loaded;
				}
			}
		}
		return loaded;
	}

	private static WikiMonsters load(Gson gson) throws IOException
	{
		InputStream in = WikiMonsters.class.getResourceAsStream(RESOURCE);
		if (in == null)
		{
			throw new IOException("Bundled Wiki monster data is missing");
		}
		List<MonsterSummary> summaries = new ArrayList<>();
		Map<String, Monster> byName = new HashMap<>();
		String retrieved;
		try (Reader reader = new InputStreamReader(new GZIPInputStream(in), StandardCharsets.UTF_8))
		{
			JsonObject root = new JsonParser().parse(reader).getAsJsonObject();
			String stamp = root.has("retrievedUtc") ? root.get("retrievedUtc").getAsString() : "";
			retrieved = stamp.length() >= 10 ? stamp.substring(0, 10) : "unknown date";
			for (JsonElement element : root.getAsJsonArray("monsters"))
			{
				JsonObject record = element.getAsJsonObject();
				Monster monster = gson.fromJson(record, Monster.class);
				MonsterSummary summary = new MonsterSummary();
				summary.setId(monster.getId());
				summary.setName(monster.getName());
				summary.setCombatLevel(monster.getCombatLevel());
				summary.setBoss(record.has("boss") && record.get("boss").getAsBoolean());
				List<Integer> ids = new ArrayList<>();
				for (JsonElement id : record.getAsJsonArray("ids"))
				{
					ids.add(id.getAsInt());
				}
				summary.setIds(ids);
				List<String> attributes = new ArrayList<>();
				JsonArray attrs = record.getAsJsonArray("attributes");
				for (JsonElement a : attrs == null ? new JsonArray() : attrs)
				{
					attributes.add(a.getAsJsonObject().get("name").getAsString());
				}
				summary.setAttributes(attributes);
				summaries.add(summary);
				byName.put(monster.getName(), monster);
			}
		}
		catch (RuntimeException e)
		{
			throw new IOException("Bundled Wiki monster data is unreadable", e);
		}
		return new WikiMonsters(Collections.unmodifiableList(summaries), byName, retrieved);
	}

	public List<MonsterSummary> getSummaries()
	{
		return summaries;
	}

	/** A copy of the variant's stats, or null when the name is not in the snapshot. */
	public Monster monster(String name)
	{
		Monster m = byName.get(name);
		return m == null ? null : m.copy();
	}
}

