	/** Keep wide controls from expanding the view beyond the sidebar's visible width. */
	private static final class SidebarContent extends JPanel implements Scrollable
	{
		private SidebarContent()
		{
			super(new BorderLayout());
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return Math.max(16, visibleRect.height - 16);
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}

	static JPanel left(java.awt.Component c)
	{
		JPanel p = new JPanel(new BorderLayout());
		p.setBackground(ColorScheme.DARK_GRAY_COLOR);
		p.add(c, BorderLayout.CENTER);
		p.setMinimumSize(new Dimension(0, 0));
		p.setAlignmentX(LEFT_ALIGNMENT);
		return p;
	}

	private static JPanel spacer(int height)
	{
		JPanel p = new JPanel();
		p.setBackground(ColorScheme.DARK_GRAY_COLOR);
		p.setPreferredSize(new Dimension(1, height));
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		p.setAlignmentX(LEFT_ALIGNMENT);
		return p;
	}

	static String html(String body)
	{
		return html(body, HTML_WIDTH);
	}

	static String html(String body, int width)
	{
		return "<html><body style='width:" + width + "px'>" + body + "</body></html>";
	}

	static String escape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** A small crossed-swords icon for the sidebar. */
	public static BufferedImage createNavIcon()
	{
		BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(new Color(0xF7, 0x8B, 0x00));
		g.drawLine(3, 3, 12, 12);
		g.drawLine(12, 3, 3, 12);
		g.setColor(new Color(0xD8, 0xD8, 0xD8));
		g.drawLine(2, 10, 5, 13);
		g.drawLine(13, 10, 10, 13);
		g.dispose();
		return img;
	}

	static void setSmall(JLabel label, Color color)
	{
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(color);
		label.setBorder(BorderFactory.createEmptyBorder());
	}
}

package com.bestgearsetup.ui;

import com.bestgearsetup.BestGearSetupPlugin;
import com.bestgearsetup.calc.SlotLock;
import com.bestgearsetup.data.GameData;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Slot;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.components.IconTextField;

/**
 * Flat editor for gear rules and items marked as owned by hand.
 */
class ConstraintsPanel extends JPanel
{
	private final BestGearSetupPlugin plugin;
	private final SidebarSection gearSection;
	private final SidebarSection ownedSection;
	private final JPanel locksList = new JPanel();
	private final JPanel ownedList = new JPanel();
	private final IconTextField ownedSearch = new IconTextField();
	private final JPanel ownedSuggestions = new JPanel();
	private final JComboBox<String> lockSlot = new JComboBox<>();
	private final IconTextField lockSearch = new IconTextField();
	private final JPanel lockSuggestions = new JPanel();

	ConstraintsPanel(BestGearSetupPlugin plugin)
	{
		this(plugin, new SidebarSection.Accordion());
	}

	ConstraintsPanel(BestGearSetupPlugin plugin, SidebarSection.Accordion accordion)
	{
		this.plugin = plugin;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		gearSection = accordion.create("gearRules", "Locks & exclusions");
		JPanel body = gearSection.getContent();
		gearSection.showAsEditor();
		add(BestGearSetupPanel.left(gearSection));
		JLabel lockHint = new JLabel(BestGearSetupPanel.html("Right-click an item in a result to lock its slot, exclude it, or mark it owned."));
		BestGearSetupPanel.setSmall(lockHint, ColorScheme.LIGHT_GRAY_COLOR);
		body.add(BestGearSetupPanel.left(lockHint));
		locksList.setLayout(new BoxLayout(locksList, BoxLayout.Y_AXIS));
		locksList.setBackground(ColorScheme.DARK_GRAY_COLOR);
		body.add(BestGearSetupPanel.left(locksList));
		JLabel lockAny = new JLabel("Lock any item:");
		BestGearSetupPanel.setSmall(lockAny, Color.WHITE);
		lockAny.setBorder(new EmptyBorder(4, 0, 2, 0));
		body.add(BestGearSetupPanel.left(lockAny));
		lockSlot.setName("lockSlot");
		lockSlot.setToolTipText("Slot to search");
		lockSlot.addItem("Any slot");
		for (Slot slot : Slot.values())
		{
			lockSlot.addItem(slot.getDisplayName());
		}
		lockSlot.addActionListener(e -> updateLockSuggestions());
		body.add(BestGearSetupPanel.left(lockSlot));
		styleSearch(lockSearch, "Search an item to lock its slot to");
		lockSearch.setName("lockSearch");
		onTextChange(lockSearch, this::updateLockSuggestions);
		body.add(BestGearSetupPanel.left(lockSearch));
		lockSuggestions.setName("lockSuggestions");
		lockSuggestions.setLayout(new BoxLayout(lockSuggestions, BoxLayout.Y_AXIS));
		lockSuggestions.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		body.add(BestGearSetupPanel.left(lockSuggestions));

		ownedSection = accordion.create("extraOwnedItems", "Extra owned items");
		body = ownedSection.getContent();
		ownedSection.showAsEditor();
		add(BestGearSetupPanel.left(ownedSection));
		JLabel ownedHint = new JLabel(BestGearSetupPanel.html("For items the bank scan can't see, e.g. the POH costume room."));
		BestGearSetupPanel.setSmall(ownedHint, ColorScheme.LIGHT_GRAY_COLOR);
		body.add(BestGearSetupPanel.left(ownedHint));
		styleSearch(ownedSearch, "Search an item to mark as owned");
		onTextChange(ownedSearch, this::updateOwnedSuggestions);
		body.add(BestGearSetupPanel.left(ownedSearch));
		ownedSuggestions.setLayout(new BoxLayout(ownedSuggestions, BoxLayout.Y_AXIS));
		ownedSuggestions.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		body.add(BestGearSetupPanel.left(ownedSuggestions));
		ownedList.setLayout(new BoxLayout(ownedList, BoxLayout.Y_AXIS));
		ownedList.setBackground(ColorScheme.DARK_GRAY_COLOR);
		body.add(BestGearSetupPanel.left(ownedList));

		JLabel more = new JLabel(BestGearSetupPanel.html("Persistent preferences (equipment, styles, experience and fill slots) are in "
			+ "RuneLite's settings under <b>Best Gear Setup</b>."));
		BestGearSetupPanel.setSmall(more, ColorScheme.LIGHT_GRAY_COLOR);
		more.setBorder(new EmptyBorder(6, 0, 0, 0));
		gearSection.getContent().add(BestGearSetupPanel.left(more));
	}

	/** Limit the lock search to a slot (null for any) and put the cursor in it. */
	void startLockSearch(Slot slot)
	{
		lockSlot.setSelectedIndex(slot == null ? 0 : slot.ordinal() + 1);
		lockSearch.setText("");
		lockSearch.requestFocusInWindow();
	}

	private Slot selectedLockSlot()
	{
		int index = lockSlot.getSelectedIndex();
		return index <= 0 ? null : Slot.values()[index - 1];
	}

	private void updateLockSuggestions()
	{
		lockSuggestions.removeAll();
		GameData data = plugin.getGameData();
		if (data != null)
		{
			Slot only = selectedLockSlot();
			for (GearItem item : data.searchItems(lockSearch.getText(), 8, only))
			{
				String name = GameData.titleCase(item.getName());
				String slotName = item.getSlot().getDisplayName();
				lockSuggestions.add(itemButton(item, only == null ? name + " (" + slotName + ")" : name,
					"Lock " + slotName.toLowerCase(Locale.ROOT) + " slot to " + name, () ->
					{
						plugin.lockItem(item);
						lockSearch.setText("");
					}));
			}
		}
		lockSuggestions.revalidate();
		lockSuggestions.repaint();
	}

	/** Rebuild from the plugin's current state (after data load or config change). */
	void refresh()
	{
		GameData data = plugin.getGameData();
		rebuildLocks(data);
		rebuildOwned(data);
		gearSection.setSummary(plugin.getLocks().size() + plugin.getExcluded().size());
	}

	private void rebuildLocks(GameData data)
	{
		locksList.removeAll();
		Map<Slot, SlotLock> locks = plugin.getLocks();
		Set<Integer> excluded = plugin.getExcluded();
		for (Map.Entry<Slot, SlotLock> e : locks.entrySet())
		{
			Slot slot = e.getKey();
			SlotLock lock = e.getValue();
			String what;
			switch (lock.getKind())
			{
				case EMPTY:
					what = "empty";
					break;
				case FILL:
					what = "always fill";
					break;
				default:
					GearItem item = data == null ? null : data.getItem(slot, lock.getItemId());
					what = item == null ? "item " + lock.getItemId() : GameData.titleCase(item.getName());
					break;
			}
			locksList.add(removableRow("Lock " + slot.getDisplayName() + ": " + what, () -> plugin.setLock(slot, null)));
		}
		for (int id : excluded)
		{
			GearItem item = data == null ? null : data.findItem(id);
			String name = item == null ? "item " + id : GameData.titleCase(item.getName());
			locksList.add(removableRow("Excluded: " + name, () -> plugin.setExcluded(id, false)));
		}
		if (!locks.isEmpty() || !excluded.isEmpty())
		{
			JButton clear = new JButton("Clear all");
			clear.addActionListener(e -> plugin.clearLocksAndExclusions());
			locksList.add(BestGearSetupPanel.left(clear));
		}
		else
		{
			JLabel none = new JLabel("None");
			BestGearSetupPanel.setSmall(none, ColorScheme.LIGHT_GRAY_COLOR);
			locksList.add(BestGearSetupPanel.left(none));
		}
		locksList.revalidate();
		locksList.repaint();
	}

	/** Rebuild the "Marked as owned" list after the manual list changed. */
	void refreshOwned()
	{
		rebuildOwned(plugin.getGameData());
	}

	private void rebuildOwned(GameData data)
	{
		ownedSection.setSummary(plugin.getOwnedItems().getManual().size());
		ownedList.removeAll();
		for (int id : plugin.getOwnedItems().getManual())
		{
			GearItem item = data == null ? null : data.findItem(id);
			String name = item == null ? "item " + id : GameData.titleCase(item.getName());
			ownedList.add(removableRow(name, () -> plugin.setManualOwned(id, false)));
		}
		ownedList.revalidate();
		ownedList.repaint();
	}

	private void updateOwnedSuggestions()
	{
		ownedSuggestions.removeAll();
		GameData data = plugin.getGameData();
		if (data != null)
		{
			List<GearItem> matches = data.searchItems(ownedSearch.getText(), 8);
			for (GearItem item : matches)
			{
				ownedSuggestions.add(itemButton(item, GameData.titleCase(item.getName()), "Mark as owned", () ->
				{
					plugin.setManualOwned(item.getId(), true);
					ownedSearch.setText("");
				}));
			}
		}
		ownedSuggestions.revalidate();
		ownedSuggestions.repaint();
	}

	/** A search suggestion; items you own are green. */
	private JPanel itemButton(GearItem item, String text, String tooltip, Runnable onClick)
	{
		JButton row = new JButton(text);
		row.setFont(FontManager.getRunescapeSmallFont());
		row.setForeground(plugin.owns(item) ? new Color(0x6BD56B) : Color.WHITE);
		row.setHorizontalAlignment(javax.swing.SwingConstants.LEFT);
		row.setBorder(new EmptyBorder(3, 6, 3, 6));
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		row.setToolTipText(tooltip);
		row.addActionListener(e -> onClick.run());
		return BestGearSetupPanel.left(row);
	}

	private static void styleSearch(IconTextField field, String tooltip)
	{
		field.setIcon(IconTextField.Icon.SEARCH);
		field.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		field.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		field.setToolTipText(tooltip);
	}

	private static void onTextChange(IconTextField field, Runnable action)
	{
		field.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				action.run();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				action.run();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				action.run();
			}
		});
	}

	private static JPanel removableRow(String text, Runnable onRemove)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(2, 6, 2, 4));
		JLabel label = new JLabel(text);
		BestGearSetupPanel.setSmall(label, Color.WHITE);
		label.setToolTipText(text);
		row.add(label, BorderLayout.CENTER);
		JButton remove = new JButton("x");
		remove.setFont(FontManager.getRunescapeSmallFont());
		remove.setForeground(new Color(0xFF6B6B));
		remove.setMargin(new java.awt.Insets(0, 3, 0, 3));
		remove.getAccessibleContext().setAccessibleName("Remove " + text);
		remove.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		remove.setToolTipText("Remove");
		remove.addActionListener(e -> onRemove.run());
		row.add(remove, BorderLayout.EAST);
		JPanel wrap = BestGearSetupPanel.left(row);
		wrap.setBorder(new EmptyBorder(1, 0, 1, 0));
		return wrap;
	}

}

package com.bestgearsetup.ui;

import com.bestgearsetup.Budget;
import com.bestgearsetup.BestGearSetupPlugin;
import com.bestgearsetup.ItemCosts;
import com.bestgearsetup.OwnedItems;
import com.bestgearsetup.calc.LockStatus;
import com.bestgearsetup.calc.Loadout;
import com.bestgearsetup.calc.SetupResult;
import com.bestgearsetup.calc.WeaponRules;
import com.bestgearsetup.data.GameData;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Slot;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.RenderingHints;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.Set;
import javax.swing.JComponent;
import javax.swing.JPanel;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * The worn-equipment layout from the game:
 * <pre>
 *        head
 *  cape  neck  ammo
 *  weapon body shield
 *        legs
 *  hands feet  ring
 * </pre>
 * Slots filled for defence / prayer are highlighted blue, locked slots get an orange frame and padlock
 * (red when the lock could not be applied, with the locked item shown faded), and a corner marker shows
 * whether the item is owned (green), to buy (yellow) or untradeable (orange). A tick in the top-right corner
 * marks items currently worn, so a missing piece stands out; it is read when painted and follows the worn
 * equipment live.
 */
class EquipmentGrid extends JPanel
{
	static final int SLOT_SIZE = 44;
	private static final Color TILE = new Color(0x3E, 0x35, 0x29);
	private static final Color TILE_EDGE = new Color(0x5A, 0x4D, 0x3B);
	private static final Color FILLED = new Color(0x3D, 0x6F, 0xC4);
	private static final Color LOCKED = new Color(0xFF, 0x98, 0x1F);
	private static final Color BLOCKED = new Color(0xFF, 0x4D, 0x4D);
	private static final Color OWNED = new Color(0x6B, 0xD5, 0x6B);
	private static final Color BUY = new Color(0xFF, 0xD2, 0x4D);
	private static final Color UNTRADEABLE = new Color(0xFF, 0x9F, 0x40);
	private static final Color WORN = new Color(0x7C, 0xF0, 0x7C);
	private static final String TIP_FOOTER = "<br><i>Right-click for options</i></html>";

	private static final Slot[] LAYOUT = {
		null, Slot.HEAD, null,
		Slot.CAPE, Slot.NECK, Slot.AMMO,
		Slot.WEAPON, Slot.BODY, Slot.SHIELD,
		null, Slot.LEGS, null,
		Slot.HANDS, Slot.FEET, Slot.RING,
	};

	/** @param locks how each locked slot affected the search that found this setup */
	EquipmentGrid(SetupResult result, Map<Slot, LockStatus> locks, BestGearSetupPlugin plugin, ItemManager itemManager,
		SpriteCache sprites, int ammoCount)
	{
		super(new GridLayout(5, 3, 6, 4));
		setOpaque(false);
		Loadout l = result.getLoadout();
		Set<Slot> filled = result.getFilledSlots();
		for (Slot slot : LAYOUT)
		{
			if (slot == null)
			{
				JPanel empty = new JPanel();
				empty.setOpaque(false);
				add(empty);
				continue;
			}
			GearItem item = l.get(slot);
			boolean darts = false;
			if (slot == Slot.AMMO && item == null && l.getLoadedAmmo() != null)
			{
				// Blowpipe darts are shown in the ammo slot.
				item = l.getLoadedAmmo();
				darts = true;
			}
			add(new SlotBox(slot, item, darts, filled.contains(slot), locks.get(slot), plugin, itemManager, sprites,
				ammoCount));
		}
		setMaximumSize(getPreferredSize());
	}

	private static int placeholderSprite(Slot slot)
	{
		switch (slot)
		{
			case HEAD:
				return SpriteID.Wornicons.HEAD;
			case CAPE:
				return SpriteID.Wornicons.CAPE;
			case NECK:
				return SpriteID.Wornicons.NECK;
			case AMMO:
				return SpriteID.Wornicons.AMMUNITION;
			case WEAPON:
				return SpriteID.Wornicons.WEAPON;
			case BODY:
				return SpriteID.Wornicons.TORSO;
			case SHIELD:
				return SpriteID.Wornicons.SHIELD;
			case LEGS:
				return SpriteID.Wornicons.LEGS;
			case HANDS:
				return SpriteID.Wornicons.HANDS;
			case FEET:
				return SpriteID.Wornicons.FEET;
			default:
				return SpriteID.Wornicons.RING;
		}
	}

	private static final class SlotBox extends JComponent
	{
		private final Slot slot;
		private final GearItem item;
		private final boolean filled;
		private final LockStatus lock;
		private final SpriteCache sprites;
		private final AsyncBufferedImage icon;
		/** The locked item that could not be used, drawn faded in its empty slot. */
		private final AsyncBufferedImage ghost;
		private final Color marker;
		private final BestGearSetupPlugin plugin;
		/** False for blowpipe darts, which are loaded rather than worn. */
		private final boolean wearable;
		/** The item tooltip without its footer; the worn status is added when it is shown. */
		private String itemTip;

		SlotBox(Slot slot, GearItem item, boolean darts, boolean filled, LockStatus lock, BestGearSetupPlugin plugin,
			ItemManager itemManager, SpriteCache sprites, int ammoCount)
		{
			this.slot = slot;
			this.item = item;
			this.filled = filled;
			this.lock = lock;
			this.sprites = sprites;
			this.plugin = plugin;
			this.wearable = item != null && !darts;
			setPreferredSize(new Dimension(SLOT_SIZE, SLOT_SIZE));
			boolean locked = lock != null;
			GearItem lockedItem = locked ? lock.getItem() : null;

			if (item == null && lockedItem != null && lock.isBlocking())
			{
				icon = null;
				marker = null;
				ghost = itemManager.getImage(lockedItem.getId());
				ghost.onLoaded(this::repaint);
				setToolTipText("<html><b>Locked to " + BestGearSetupPanel.escape(GameData.titleCase(lockedItem.getName()))
					+ "</b><br>Can't be used: " + BestGearSetupPanel.escape(lock.getProblem()) + ".<br>"
					+ BestGearSetupPanel.escape(lock.getEffect()) + "<br><i>Right-click to unlock</i></html>");
				setComponentPopupMenu(ItemMenus.create(lockedItem, slot, true, plugin));
				return;
			}
			ghost = null;
			if (item == null)
			{
				icon = null;
				marker = null;
				setToolTipText(slot.getDisplayName() + (lockDescription(lock).isEmpty() ? " (empty)" : " - " + lockDescription(lock))
					+ (locked && lock.isBlocking() ? ". Can't be used: " + lock.getProblem() : "")
					+ " - right-click for options");
			}
			else
			{
				icon = itemManager.getImage(item.getId());
				icon.onLoaded(this::repaint);
				boolean owned = plugin.owns(item);
				marker = owned ? OWNED : !item.isTradeable() ? UNTRADEABLE : BUY;
				StringBuilder tip = new StringBuilder("<html><b>").append(BestGearSetupPanel.escape(GameData.titleCase(item.getName())))
					.append("</b>");
				if (darts)
				{
					tip.append(" (loaded in blowpipe)");
				}
				tip.append("<br>");
				boolean countedAmmo = WeaponRules.consumedPerAttack(item) && ammoCount > 0;
				long held = countedAmmo && owned ? plugin.heldQuantity(item) : 0;
				if (owned && countedAmmo && held < ammoCount)
				{
					long cost = plugin.price(item);
					tip.append("Owned: ").append(held).append(" of ").append(ammoCount).append("<br>Buy ")
						.append(ammoCount - held).append(": ")
						.append(ItemCosts.isKnown(cost) ? Budget.format(cost * (ammoCount - held)) + " gp" : "no current price");
				}
				else if (owned)
				{
					tip.append(countedAmmo && held != OwnedItems.UNLIMITED ? "Owned: " + held : "Owned");
				}
				else if (!item.isTradeable())
				{
					tip.append("Untradeable");
					long cost = plugin.price(item);
					if (!ItemCosts.isKnown(cost))
					{
						tip.append("<br>Components: no current price");
					}
					else if (cost > 0)
					{
						tip.append("<br>Components: ").append(Budget.format(cost)).append(" gp");
					}
				}
				else
				{
					boolean ammo = WeaponRules.consumedPerAttack(item);
					long cost = plugin.price(item);
					tip.append("Buy: ").append(ItemCosts.isKnown(cost) ? Budget.format(cost) + " gp" : "no current price");
					if (ammo && ItemCosts.isKnown(cost))
					{
						tip.append(" each").append(ammoCount > 0 ? " (x" + ammoCount + ")" : "");
					}
				}
				if (filled)
				{
					tip.append("<br>Filled for defence / prayer (no DPS)");
				}
				if (variantOfExcluded(item, plugin))
				{
					tip.append("<br>A variant of an item you excluded; right-click to exclude all variants");
				}
				if (locked)
				{
					tip.append("<br>").append(BestGearSetupPanel.escape(lockDescription(lock)));
				}
				itemTip = tip.toString();
				setToolTipText(itemTip + TIP_FOOTER);
			}
			setComponentPopupMenu(ItemMenus.create(item, darts ? null : slot, locked, plugin));
		}

		private boolean worn()
		{
			return wearable && plugin.wears(item);
		}

		@Override
		public String getToolTipText(MouseEvent event)
		{
			if (itemTip == null)
			{
				return super.getToolTipText(event);
			}
			return itemTip + (wearable ? (worn() ? "<br>Equipped" : "<br>Not equipped") : "") + TIP_FOOTER;
		}

		private static boolean variantOfExcluded(GearItem item, BestGearSetupPlugin plugin)
		{
			GameData data = plugin.getGameData();
			Set<Integer> excluded = plugin.getExcluded();
			return data != null && !excluded.isEmpty() && !excluded.contains(item.getId())
				&& data.variantFamily(item).stream().anyMatch(v -> excluded.contains(v.getId()));
		}

		private static String lockDescription(LockStatus lock)
		{
			if (lock == null)
			{
				return "";
			}
			switch (lock.getLock().getKind())
			{
				case EMPTY:
					return "Locked empty";
				case FILL:
					return "Locked: always filled for defence / prayer";
				default:
					return lock.getItem() == null ? "Locked to item " + lock.getLock().getItemId()
						: "Locked to " + GameData.titleCase(lock.getItem().getName());
			}
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			int w = getWidth();
			int h = getHeight();

			BufferedImage tile = sprites.get(SpriteID.Miscgraphics.EQUIPMENT_SLOT_TILE, this::repaint);
			if (tile != null)
			{
				g2.drawImage(tile, 0, 0, w, h, null);
			}
			else
			{
				g2.setColor(TILE);
				g2.fillRoundRect(0, 0, w - 1, h - 1, 8, 8);
				g2.setColor(TILE_EDGE);
				g2.drawRoundRect(0, 0, w - 1, h - 1, 8, 8);
			}
			if (filled)
			{
				g2.setColor(new Color(FILLED.getRed(), FILLED.getGreen(), FILLED.getBlue(), 150));
				g2.fillRoundRect(2, 2, w - 4, h - 4, 8, 8);
			}

			if (icon != null)
			{
				g2.drawImage(icon, (w - icon.getWidth()) / 2, (h - icon.getHeight()) / 2, null);
			}
			else if (ghost != null)
			{
				Graphics2D faded = (Graphics2D) g2.create();
				faded.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.35f));
				faded.drawImage(ghost, (w - ghost.getWidth()) / 2, (h - ghost.getHeight()) / 2, null);
				faded.dispose();
				g2.setColor(BLOCKED);
				g2.setStroke(new BasicStroke(2f));
				g2.drawLine(8, h - 8, w - 8, 8);
			}
			else
			{
				BufferedImage ph = sprites.get(placeholderSprite(slot), this::repaint);
				if (ph != null)
				{
					g2.drawImage(ph, (w - ph.getWidth()) / 2, (h - ph.getHeight()) / 2, null);
				}
			}

			if (marker != null)
			{
				g2.setColor(marker);
				g2.fillPolygon(new int[]{w - 9, w - 2, w - 2}, new int[]{h - 2, h - 2, h - 9}, 3);
			}
			if (worn())
			{
				// Tick in the top-right corner, outlined so it reads over the item icon.
				int[] xs = {w - 12, w - 9, w - 4};
				int[] ys = {7, 10, 3};
				g2.setStroke(new BasicStroke(3.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.setColor(Color.BLACK);
				g2.drawPolyline(xs, ys, 3);
				g2.setStroke(new BasicStroke(1.75f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g2.setColor(WORN);
				g2.drawPolyline(xs, ys, 3);
			}
			if (lock != null)
			{
				Color frame = lock.isBlocking() ? BLOCKED : LOCKED;
				g2.setColor(frame);
				g2.setStroke(new BasicStroke(2f));
				g2.drawRoundRect(1, 1, w - 3, h - 3, 8, 8);
				// Padlock in the top-left corner.
				g2.setStroke(new BasicStroke(1.5f));
				g2.drawArc(5, 3, 6, 7, 0, 180);
				g2.fillRect(4, 7, 8, 6);
			}
			g2.dispose();
		}
	}
}

package com.bestgearsetup.ui;

import com.bestgearsetup.BestGearSetupConfig;
import com.bestgearsetup.BestGearSetupPlugin;
