		PRAYER_SPRITES.put("mystic might", SpriteID.Prayeron.MYSTIC_MIGHT);
		PRAYER_SPRITES.put("mystic lore", SpriteID.Prayeron.MYSTIC_LORE);
		PRAYER_SPRITES.put("mystic will", SpriteID.Prayeron.MYSTIC_WILL);
