		GETTERS.put("potionMelee", BestGearSetupConfig::potionMelee);
		GETTERS.put("potionRanged", BestGearSetupConfig::potionRanged);
		GETTERS.put("potionMagic", BestGearSetupConfig::potionMagic);
		GETTERS.put("locks", BestGearSetupConfig::locks);
		GETTERS.put("excluded", BestGearSetupConfig::excluded);
	}

	/** Config keys that differ from their method name, which is what overrides are keyed by. */
	private static final Map<String, String> METHOD_BY_KEY = new HashMap<>();

	static
	{
		METHOD_BY_KEY.put("meleePotionChoice", "meleePotion");
		METHOD_BY_KEY.put("rangedPotionChoice", "rangedPotion");
		METHOD_BY_KEY.put("magicPotionChoice", "magicPotion");
		METHOD_BY_KEY.put(BestGearSetupConfig.POTION_KEY_PREFIX + "MELEE", "potionMelee");
		METHOD_BY_KEY.put(BestGearSetupConfig.POTION_KEY_PREFIX + "RANGED", "potionRanged");
		METHOD_BY_KEY.put(BestGearSetupConfig.POTION_KEY_PREFIX + "MAGIC", "potionMagic");
	}

	@Test public void getterTableCoversEveryConfigItem()
	{
		Set<String> methods = new TreeSet<>();
		for (ConfigItemDescriptor item : ConfigItemsForTests.items())
		{
			String key = item.getItem().keyName();
			methods.add(METHOD_BY_KEY.getOrDefault(key, key));
		}
		assertEquals(methods, new TreeSet<>(GETTERS.keySet()));
	}

	/** A new config item that the snapshot forgets would silently fall back to its default during searches. */
	@Test public void everyConfigItemIsCopiedAndCanBeOverridden()
	{
		BestGearSetupConfig defaults = new BestGearSetupConfig() { };
		Map<String, Object> changed = new LinkedHashMap<>();
		for (Map.Entry<String, Function<BestGearSetupConfig, Object>> e : GETTERS.entrySet())
		{
			changed.put(e.getKey(), different(e.getValue().apply(defaults)));
		}
		// Overriding every key at once gives a source whose every value differs from the default.
		BestGearSetupConfig source = SearchAssumptions.capture(defaults, changed);
		BestGearSetupConfig copied = SearchAssumptions.capture(source, Collections.emptyMap());
		for (Map.Entry<String, Object> e : changed.entrySet())
		{
			Function<BestGearSetupConfig, Object> getter = GETTERS.get(e.getKey());
			assertEquals(e.getKey(), e.getValue(), getter.apply(source));
			assertEquals(e.getKey(), e.getValue(), getter.apply(copied));
			BestGearSetupConfig overridden = SearchAssumptions.capture(defaults, Collections.singletonMap(e.getKey(), e.getValue()));
			assertEquals(e.getKey(), e.getValue(), getter.apply(overridden));
		}
	}

	@Test(expected = IllegalArgumentException.class) public void unknownOverrideIsRejected()
	{
		SearchAssumptions.capture(new BestGearSetupConfig() { }, Collections.singletonMap("noSuchSetting", true));
	}

	private static Object different(Object value)
	{
		if (value instanceof Boolean) { return !(Boolean) value; }
		if (value instanceof Integer) { return (Integer) value + 1; }
		if (value instanceof Double) { return (Double) value + 0.5; }
		if (value instanceof String) { return value + "-changed"; }
		if (value instanceof Color) { return new Color(1, 2, 3); }
		if (value instanceof Enum)
		{
			return next((Enum<?>) value);
		}
		throw new AssertionError("Add a changed value for " + value);
	}

	@SuppressWarnings({"unchecked", "rawtypes"})
	private static Object next(Enum<?> value)
	{
		List<Enum<?>> constants = new ArrayList<>(EnumSet.allOf((Class) value.getDeclaringClass()));
		return constants.get((value.ordinal() + 1) % constants.size());
	}

	@Test public void automaticUnknownAndExplicitOverridesAreDifferent()
	{
		assertFalse(AutoState.AUTO.resolve(null, false));
		assertTrue(AutoState.AUTO.resolve(true, false));
		assertFalse(AutoState.AUTO.resolve(false, true));
		assertTrue(AutoState.ON.resolve(false, false));
		assertFalse(AutoState.OFF.resolve(true, true));
	}
}

package com.bestgearsetup;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.data.MonsterSummary;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.atomic.AtomicInteger;
import javax.swing.SwingUtilities;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.BeforeClass;
import org.junit.Test;

public class SearchInvalidationTest
{
	/** Main code gets the client's Gson in startUp; tests use the same instance. */
	@BeforeClass
	public static void ownershipRules()
	{
		OwnershipRules.init(RuneLiteAPI.GSON);
	}

	private static Set<Integer> ids(Integer... ids)
	{
		return new HashSet<>(Arrays.asList(ids));
	}

	@Test
	public void gainingOrLosingEquipmentInvalidatesResults()
	{
		Set<Integer> gear = ids(100, 200, 201);
		assertTrue(BestGearSetupPlugin.gearOwnershipDiffers(ids(100, 200), ids(100), gear));
		assertTrue(BestGearSetupPlugin.gearOwnershipDiffers(ids(100), ids(100, 201), gear));
	}

	@Test
	public void consumablesAndUnchangedGearDoNotInvalidateResults()
	{
		Set<Integer> gear = ids(100, 200);
		// e.g. a potion dose changing id, or food running out.
		assertFalse(BestGearSetupPlugin.gearOwnershipDiffers(ids(100, 2434), ids(100, 139), gear));
		assertFalse(BestGearSetupPlugin.gearOwnershipDiffers(ids(100, 200), ids(200, 100), gear));
	}

	@Test
	public void onlyStackChangesWithinTheRequestedQuantityMatter()
	{
		Set<Integer> bolts = ids(9242);
		Map<Integer, Long> held = Collections.singletonMap(9242, 159L);
		assertTrue(BestGearSetupPlugin.supplyDiffers(held, Collections.singletonMap(9242, 158L), bolts, 100_000));
		assertTrue(BestGearSetupPlugin.supplyDiffers(held, Collections.emptyMap(), bolts, 100_000));
		// Firing from a stack that still covers the requested quantity changes nothing.
		assertFalse(BestGearSetupPlugin.supplyDiffers(held, Collections.singletonMap(9242, 150L), bolts, 100));
		assertTrue(BestGearSetupPlugin.supplyDiffers(held, Collections.singletonMap(9242, 99L), bolts, 100));
		// Uncounted ammunition and non-supply items never trigger a refresh.
		assertFalse(BestGearSetupPlugin.supplyDiffers(held, Collections.singletonMap(9242, 1L), bolts, 0));
		assertFalse(BestGearSetupPlugin.supplyDiffers(held, Collections.singletonMap(9242, 1L), ids(868), 100_000));
	}

	private final AtomicInteger reruns = new AtomicInteger();
	/** Times the settle timer was (re)started; each restart pushes the refresh back. */
	private final AtomicInteger schedules = new AtomicInteger();
	private OwnedItems owned;
	private BestGearSetupPlugin plugin;

	/** A search captured with 159 Ruby bolts (e) held and 100,000 requested. */
	private void searchedWithBolts()
	{
		owned = new OwnedItems(null, null);
		owned.bank = Collections.singletonMap(9242, 159L);
		owned.rebuild(true);
		plugin = new BestGearSetupPlugin()
		{
			@Override
			public void rerun()
			{
				reruns.incrementAndGet();
			}

			@Override
			void scheduleSupplyRefresh()
			{
				schedules.incrementAndGet();
			}
		};
		plugin.ownedItems = owned;
		plugin.searchOwned = owned.snapshot();
		plugin.searchQuantities = owned.quantitySnapshot();
		plugin.searchAmmoCount = 100_000;
		plugin.lastSearched = new MonsterSummary();
		plugin.gearIds = ids(9242);
		plugin.consumableIds = ids(9242);
	}

	/** A container event: the bank holds this many bolts and the inventory this many lobsters. */
	private void containers(long bolts, long lobsters) throws Exception
	{
		Map<Integer, Long> bank = new HashMap<>();
		bank.put(9242, bolts);
		owned.bank = bank;
		owned.inventory = Collections.singletonMap(379, lobsters);
		owned.rebuild(false);
		plugin.invalidateIfOwnershipChanged();
		// Scheduling is queued on the Swing thread.
		SwingUtilities.invokeAndWait(() ->
		{
		});
	}

	/** The settle timer fires. */
	private void settle() throws Exception
	{
		SwingUtilities.invokeAndWait(plugin::refreshSupply);
	}

	/** The evaluator's scenario: one stack-only change to a quantity-dependent search reruns it once settled. */
	@Test
	public void changingOnlyStackQuantityRefreshesSearchOnceSettled() throws Exception
	{
		searchedWithBolts();
		// Three shots in quick succession restart one settle timer rather than starting three refreshes.
		for (long left : new long[]{158, 157, 156})
		{
			containers(left, 0);
		}
		assertEquals(3, schedules.get());
		assertEquals("No rerun before the stack settles", 0, reruns.get());
		settle();
		assertEquals(1, reruns.get());
		// The refresh records the stack it searched with, so the same stack doesn't schedule again.
		containers(156, 0);
		assertEquals(3, schedules.get());
		assertEquals(1, reruns.get());
	}

	/** Food and potion updates after the ammunition has settled must not keep postponing the refresh. */
	@Test
	public void unrelatedContainerEventsDoNotPostponeASettledSupplyRefresh() throws Exception
	{
		searchedWithBolts();
		containers(158, 0);
		for (long lobsters = 1; lobsters <= 16; lobsters++)
		{
			containers(158, lobsters);
		}
		assertEquals("Lobster changes must not restart the settle timer", 1, schedules.get());
		settle();
		assertEquals(1, reruns.get());
	}

	/** A stack that returns to the searched size before settling needs no refresh. */
	@Test
	public void aStackRestoredBeforeSettlingDoesNotRerun() throws Exception
	{
		searchedWithBolts();
		containers(158, 0);
		containers(159, 0);
		settle();
		assertEquals(0, reruns.get());
	}

}

package com.bestgearsetup;

import static org.junit.Assert.assertEquals;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Test;

public class SearchProgressTest
{
	private final AtomicLong now = new AtomicLong();
	private final List<Integer> published = new ArrayList<>();

	@Test
	public void averagesTheTabs()
	{
		SearchProgress progress = new SearchProgress(3, published::add, now::get);
		progress.update(0, 1);
		progress.update(1, 0.5);
		assertEquals(50, progress.percent());
		progress.update(2, 0.25);
		assertEquals(58, progress.percent());
	}

	@Test
	public void publishesAtMostOncePerInterval()
	{
		SearchProgress progress = new SearchProgress(1, published::add, now::get);
		progress.update(0, 0.1);
		progress.update(0, 0.2);
		now.addAndGet(SearchProgress.INTERVAL_NANOS - 1);
		progress.update(0, 0.3);
		now.addAndGet(1);
		progress.update(0, 0.4);
		assertEquals(Arrays.asList(10, 40), published);
	}

	@Test
	public void neverPublishesTheSameOrALowerPercentage()
	{
		SearchProgress progress = new SearchProgress(2, published::add, now::get);
		progress.update(0, 0.8);
		now.addAndGet(SearchProgress.INTERVAL_NANOS);
		progress.update(0, 0.8);
		now.addAndGet(SearchProgress.INTERVAL_NANOS);
		progress.update(1, 0);
		assertEquals(Collections.singletonList(40), published);
	}

	@Test
	public void completionIsPublishedImmediatelyOnce()
	{
		SearchProgress progress = new SearchProgress(2, published::add, now::get);
		progress.update(0, 0.5);
		progress.complete();
		progress.complete();
		assertEquals(Arrays.asList(25, 100), published);
	}
}

