package com.bestgearsetup;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.calc.Loadout;
import com.bestgearsetup.calc.SetupResult;
import com.bestgearsetup.calc.SupportSpell;
import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Potion;
import com.bestgearsetup.data.Slot;
import com.bestgearsetup.data.Spell;
import com.bestgearsetup.data.WikiGameData;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.gameval.ItemID;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.Test;

public class SpellRunesTest
{
	@Test
	public void everyBundledSpellHasItsRunes() throws Exception
	{
		Gson gson = RuneLiteAPI.GSON;
		for (Spell spell : WikiGameData.get(gson).gameData(gson).getSpells())
		{
			Loadout loadout = new Loadout();
			loadout.setSpell(spell);
			assertFalse(spell.getName(), required(loadout).isEmpty());
		}
	}

	@Test
	public void runesTheStaffOrTomeSuppliesAreLeftOut()
	{
		assertEquals(Arrays.asList(ItemID.AIRRUNE, ItemID.FIRERUNE, ItemID.WRATHRUNE),
			required(loadout("fire surge", "kodai wand", null)));
		assertEquals(Collections.singletonList(ItemID.WRATHRUNE),
			required(loadout("fire surge", "smoke battlestaff", null)));
		assertEquals(Collections.singletonList(ItemID.WRATHRUNE),
			required(loadout("fire surge", "staff of air", "tome of fire")));
		assertEquals(Arrays.asList(ItemID.FIRERUNE, ItemID.WRATHRUNE),
			required(loadout("fire surge", "mystic air staff", "tome of fire (empty)")));
		assertEquals(Arrays.asList(ItemID.DEATHRUNE, ItemID.BLOODRUNE),
			required(loadout("ice barrage", "kodai wand", null)));
		assertEquals(Arrays.asList(ItemID.WATERRUNE, ItemID.DEATHRUNE, ItemID.BLOODRUNE),
			required(loadout("ice barrage", "smoke ancient sceptre", null)));
		assertTrue(required(loadout(null, "trident of the swamp", null)).isEmpty());
		assertTrue(SpellRunes.substitutes(ItemID.FIRERUNE).contains(ItemID.SUNFIRERUNE));
	}

	@Test
	public void supportSpellsAddTheirRunesOnceAndThrallsAddTheBook()
	{
		// Dark Demonbane (fire, soul) + Mark of Darkness (cosmic, soul) + thrall (fire, blood, cosmic, book).
		assertEquals(Arrays.asList(ItemID.FIRERUNE, ItemID.SOULRUNE, ItemID.COSMICRUNE, ItemID.BLOODRUNE,
			ItemID.BOOK_OF_THE_DEAD), required(loadout("dark demonbane", "magic staff", null),
			EnumSet.of(SupportSpell.MARK_OF_DARKNESS, SupportSpell.THRALL)));
		// A melee setup with a thrall still brings the thrall's runes; a fire staff covers its fire.
		assertEquals(Arrays.asList(ItemID.BLOODRUNE, ItemID.COSMICRUNE, ItemID.BOOK_OF_THE_DEAD),
			required(loadout(null, "staff of fire", null), EnumSet.of(SupportSpell.THRALL)));
		assertEquals(Arrays.asList(ItemID.AIRRUNE, ItemID.FIRERUNE, ItemID.BLOODRUNE),
			required(loadout("flames of zamorak", "zamorak staff", null), EnumSet.of(SupportSpell.CHARGE)));
	}

	@Test
	public void bankLayoutWrapsSpellItemsOntoTheSecondRow()
	{
		Loadout loadout = loadout("dark demonbane", "magic staff", null);
		Map<Integer, Integer> cells = BestGearSetupBankView.cellsFor(new SetupResult(CombatClass.MAGIC, loadout, null,
			0, 0, Collections.emptySet(), EnumSet.of(SupportSpell.MARK_OF_DARKNESS, SupportSpell.THRALL)));
		assertEquals(Integer.valueOf(7), cells.get(ItemID.BLOODRUNE));
		assertEquals(Integer.valueOf(12), cells.get(ItemID.BOOK_OF_THE_DEAD));
		// Aether replaces soul and cosmic; it sits with the first of those (soul).
		assertEquals(Integer.valueOf(5), cells.get(ItemID.AETHERRUNE));
		Map<Integer, Integer> thrall = BestGearSetupBankView.cellsFor(new SetupResult(CombatClass.MELEE,
			loadout(null, "abyssal whip", null), null, 0, 0, Collections.emptySet(), EnumSet.of(SupportSpell.THRALL)));
		assertEquals(thrall.get(ItemID.COSMICRUNE), thrall.get(ItemID.AETHERRUNE));
	}

	@Test
	public void bankLayoutPlacesRunesBesideTheHeadSlotAfterEquipment()
	{
		Loadout loadout = loadout("fire surge", "staff of earth", null);
		loadout.set(Slot.HEAD, gear(ItemID.WRATHRUNE, "test helm"));
		Map<Integer, Integer> cells = BestGearSetupBankView.cellsFor(
			new SetupResult(CombatClass.MAGIC, loadout, null, 0));
		// Equipment keeps its silhouette cell; runes follow on the top row in spellbook order.
		assertEquals(Integer.valueOf(1), cells.get(ItemID.WRATHRUNE));
		assertEquals(Integer.valueOf(4), cells.get(ItemID.AIRRUNE));
		// A combination rune sits with the first rune it replaces.
		assertEquals(Integer.valueOf(4), cells.get(ItemID.SMOKERUNE));
		assertEquals(Integer.valueOf(5), cells.get(ItemID.FIRERUNE));
		assertEquals(Integer.valueOf(5), cells.get(ItemID.SUNFIRERUNE));
		assertEquals(Integer.valueOf(5), cells.get(ItemID.LAVARUNE));
		assertFalse(cells.containsKey(ItemID.EARTHRUNE));
	}

	@Test
	public void bankLayoutPlacesBoostsBelowTheSpellRunesWithEveryDose()
	{
		Potion combat = new Potion();
		combat.setId(ItemID._4DOSE2COMBAT);
		Potion heart = new Potion();
		heart.setId(ItemID.SATURATED_HEART);
		Map<Integer, Integer> cells = BestGearSetupBankView.cellsFor(new SetupResult(CombatClass.MELEE,
			loadout(null, "abyssal whip", null), null, 0), Arrays.asList(combat, heart));
		assertEquals(Integer.valueOf(20), cells.get(ItemID._4DOSE2COMBAT));
		assertEquals(Integer.valueOf(20), cells.get(ItemID._2DOSE2COMBAT));
		assertEquals(Integer.valueOf(20), cells.get(ItemID._3DOSEDIVINECOMBAT));
		assertEquals(Integer.valueOf(21), cells.get(ItemID.SATURATED_HEART));
		Potion attack = new Potion();
		attack.setId(ItemID._4DOSE2ATTACK);
		Potion strength = new Potion();
		strength.setId(ItemID._4DOSE2STRENGTH);
		Map<Integer, Integer> split = BestGearSetupBankView.cellsFor(new SetupResult(CombatClass.MELEE,
			loadout(null, "abyssal whip", null), null, 0), Arrays.asList(attack, strength));
		// A super combat covers both and sits with the first; each keeps its own cell.
		assertEquals(Integer.valueOf(20), split.get(ItemID._4DOSE2ATTACK));
		assertEquals(Integer.valueOf(20), split.get(ItemID._3DOSE2COMBAT));
		assertEquals(Integer.valueOf(21), split.get(ItemID._4DOSE2STRENGTH));
		BestGearSetupPlugin plugin = new BestGearSetupPlugin();
		plugin.setBankHighlightedSetup(new SetupResult(CombatClass.MELEE, loadout(null, "abyssal whip", null), null, 0),
			Collections.singletonList(combat));
		assertTrue(plugin.getBankHighlightIds().containsAll(Arrays.asList(ItemID._1DOSE2COMBAT,
			ItemID._1DOSEDIVINECOMBAT)));
	}

	@Test
	public void bankHighlightsIncludeSpellRunes()
	{
		BestGearSetupPlugin plugin = new BestGearSetupPlugin();
		plugin.setBankHighlightedSetup(new SetupResult(CombatClass.MAGIC,
			loadout("blood barrage", "kodai wand", null), null, 0));
		assertTrue(plugin.getBankHighlightIds().containsAll(Arrays.asList(ItemID.DEATHRUNE, ItemID.BLOODRUNE,
			ItemID.SOULRUNE, ItemID.AETHERRUNE)));
		plugin.setBankHighlightedSetup(new SetupResult(CombatClass.MELEE, loadout(null, "abyssal whip", null), null,
			0, 0, Collections.emptySet(), EnumSet.of(SupportSpell.THRALL)));
		assertTrue(plugin.getBankHighlightIds().containsAll(Arrays.asList(ItemID.FIRERUNE, ItemID.BLOODRUNE,
			ItemID.COSMICRUNE, ItemID.BOOK_OF_THE_DEAD)));
	}

	private static List<Integer> required(Loadout loadout)
	{
		return required(loadout, EnumSet.noneOf(SupportSpell.class));
	}

	private static List<Integer> required(Loadout loadout, Set<SupportSpell> support)
	{
		return SpellRunes.required(loadout, support);
	}

	private static Loadout loadout(String spell, String weapon, String shield)
	{
		Loadout loadout = new Loadout();
		if (spell != null)
		{
			Spell s = new Spell();
			s.setName(spell);
			loadout.setSpell(s);
		}
		loadout.set(Slot.WEAPON, gear(1, weapon));
		if (shield != null)
		{
			loadout.set(Slot.SHIELD, gear(2, shield));
		}
		return loadout;
	}

	private static GearItem gear(int id, String name)
	{
		GearItem item = new GearItem();
		item.setId(id);
		item.setName(name);
		return item;
	}
}

package com.bestgearsetup;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.calc.OptimizerSettings;
import java.util.Collections;
import org.junit.Test;

public class WildernessSettingsTest
{
	private OptimizerSettings settings(BestGearSetupConfig config)
	{
		BestGearSetupPlugin plugin = new BestGearSetupPlugin();
		plugin.config = config;
		return plugin.buildSettings(config);
	}

	@Test
	public void savedLimitActivatesOnlyInWildernessAndAcceptsGpSuffixes() throws Exception
	{
		BestGearSetupConfig planning = new BestGearSetupConfig()
		{
			@Override public boolean limitWildernessRisk() { return true; }
			@Override public int maxExpensiveItems() { return 0; }
			@Override public String expensiveItemThreshold() { return "500k"; }
		};
		assertFalse(settings(planning).isWildernessRiskLimited());
		// Live fight detection overrides only the location; saved risk choices still apply.
		BestGearSetupConfig live = SearchAssumptions.capture(planning, Collections.singletonMap("wilderness", true));
		OptimizerSettings result = settings(live);
		assertTrue(result.isWildernessRiskLimited());
		assertEquals(0, result.getMaxExpensiveItems());
		assertEquals(500_000, result.getExpensiveItemThreshold());
		assertFalse(planning.wilderness());
		assertFalse(settings(new BestGearSetupConfig() { @Override public boolean wilderness() { return true; } })
			.isWildernessRiskLimited());
	}

	@Test
	public void invalidThresholdNeverSilentlyRemovesTheLimit() throws Exception
	{
		OptimizerSettings result = settings(new BestGearSetupConfig()
		{
			@Override public boolean wilderness() { return true; }
			@Override public boolean limitWildernessRisk() { return true; }
			@Override public String expensiveItemThreshold() { return "bad value"; }
		});
		assertTrue(result.isWildernessRiskLimited());
		assertEquals(0, result.getExpensiveItemThreshold());
	}
}

package com.bestgearsetup;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.data.GearItem;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.BeforeClass;
import org.junit.Test;

public class WornItemsTest
{
	/** Main code gets the client's Gson in startUp; tests use the same instance. */
	@BeforeClass
	public static void ownershipRules()
	{
		OwnershipRules.init(RuneLiteAPI.GSON);
	}

	private static BestGearSetupPlugin wearing(int... ids) throws Exception
	{
		return plugin(equippedNow(ids));
	}

	private static OwnedItems equippedNow(int... ids) throws Exception
	{
		OwnedItems owned = new OwnedItems(null, null);
		Set<Integer> equipped = new HashSet<>();
		for (int id : ids)
		{
			equipped.add(id);
		}
		owned.equipped = equipped;
		// Held in the bank only: owned but not worn.
		owned.bank = Collections.singletonMap(4151, 1L);
		return owned;
	}

	private static BestGearSetupPlugin plugin(OwnedItems owned) throws Exception
	{
		BestGearSetupPlugin plugin = new BestGearSetupPlugin();
		plugin.ownedItems = owned;
		return plugin;
	}

	private static GearItem item(int id, Integer... variants)
	{
		GearItem item = new GearItem();
		item.setId(id);
		item.setVariants(Arrays.asList(variants));
		return item;
	}

	@Test
	public void wornItemsAndTheirChargeStatesCountAsEquipped() throws Exception
	{
		BestGearSetupPlugin plugin = wearing(1704);
		assertTrue(plugin.wears(item(1704)));
		// An amulet of glory (4) is equipped when the uncharged glory is worn.
		assertTrue(plugin.wears(item(1712, 1704, 1712)));
	}

	@Test
	public void itemsOnlyInTheBankAreNotEquipped() throws Exception
	{
		BestGearSetupPlugin plugin = wearing(1704);
		assertFalse(plugin.wears(item(4151)));
		assertFalse(wearing().wears(item(1704)));
	}

	@Test
	public void rememberedEquipmentIsNotEquippedWhileLoggedOut() throws Exception
	{
		// Equipment saved from an earlier session still counts as owned, but nothing is equipped until the
		// live worn container is seen.
		OwnedItems owned = new OwnedItems(null, null);
		Map<Integer, Long> remembered = new HashMap<>();
		remembered.put(1704, 1L);
		owned.worn = remembered;
		assertFalse(plugin(owned).wears(item(1704)));
	}

	@Test
	public void loggingOutClearsEquippedItems() throws Exception
	{
		OwnedItems owned = equippedNow(1704);
		BestGearSetupPlugin plugin = plugin(owned);
		assertTrue(plugin.wears(item(1704)));
		owned.clearEquipped();
		assertFalse(plugin.wears(item(1704)));
	}

}

package com.bestgearsetup.calc;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.ItemCosts;
import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.GameData;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Slot;
import com.bestgearsetup.data.WikiGameData;
import java.util.Arrays;
import java.util.Collections;
import java.util.function.IntPredicate;
import java.util.function.IntToLongFunction;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.BeforeClass;
import org.junit.Test;

/** Exercise the real bundled ammo and reward IDs through the optimizer. */
public class AmmunitionOwnershipTest
{
	private static GameData data;
	private static GearItem atlatl;
	private static GearItem dart;
	private static CombatContext context;

	@BeforeClass
	public static void load() throws Exception
	{
		data = WikiGameData.get(RuneLiteAPI.GSON).gameData(RuneLiteAPI.GSON);
		atlatl = data.getItem(Slot.WEAPON, 29000);
		dart = data.getItem(Slot.AMMO, 28991);
		context = new CombatContext(TestData.monster(100, 20), PlayerLevels.maxed(), false, true, null);
	}

	@Test
	public void ownedAtlatlNeedsOwnedDartsAndCannotUseABlessingInstead()
	{
		OptimizerSettings settings = OptimizerSettings.builder().mode(SearchMode.OWNED_ONLY)
			.spellbooks(Collections.emptySet()).build();
		assertTrue(new Optimizer(data, context, settings, id -> id == atlatl.getId() || id == 22947, GearItem::getPrice)
			.optimize(CombatClass.RANGED, () -> false).isEmpty());
		SetupResult result = new Optimizer(data, context, settings,
			id -> id == atlatl.getId() || id == dart.getId() || id == 22947, GearItem::getPrice)
			.optimize(CombatClass.RANGED, () -> false).get(0);
		assertEquals(dart, result.getLoadout().get(Slot.AMMO));
		assertTrue(WeaponRules.firesAmmoSlot(atlatl));
		assertFalse(WeaponRules.loadsAmmo(atlatl));
	}

	@Test
	public void zeroBonusAtlatlDartsArePricedByQuantity()
	{
		GameData small = TestData.gameData(Arrays.asList(atlatl, dart), Collections.emptyList());
		OptimizerSettings settings = OptimizerSettings.builder().mode(SearchMode.BUDGET).budget(7000)
			.ammoCount(1000).spellbooks(Collections.emptySet()).build();
		SetupResult result = new Optimizer(small, context, settings, id -> id == atlatl.getId(), item -> 7)
			.optimize(CombatClass.RANGED, () -> false).get(0);
		assertEquals(7000, result.getBuyCost());
		assertTrue(new Optimizer(small, context, settings.toBuilder().budget(6999).build(),
			id -> id == atlatl.getId(), item -> 7).optimize(CombatClass.RANGED, () -> false).isEmpty());
	}

	/** Owning part of the requested stack prices only the shortfall; it never makes the whole stack free. */
	@Test
	public void ownedAmmunitionCoversOnlyTheStackHeld()
	{
		GameData small = TestData.gameData(Arrays.asList(atlatl, dart), Collections.emptyList());
		IntPredicate owned = id -> id == atlatl.getId() || id == dart.getId();
		IntToLongFunction held = id -> id == atlatl.getId() ? 1 : id == dart.getId() ? 159 : 0;
		OptimizerSettings budget = OptimizerSettings.builder().mode(SearchMode.BUDGET).budget(0)
			.ammoCount(100_000).spellbooks(Collections.emptySet()).build();
		assertTrue("A zero budget can't buy the 99,841 missing darts",
			new Optimizer(small, context, budget, owned, held, item -> 7).optimize(CombatClass.RANGED, () -> false).isEmpty());

		long shortfall = (100_000 - 159) * 7L;
		SetupResult bought = new Optimizer(small, context, budget.toBuilder().budget(shortfall).build(), owned, held,
			item -> 7).optimize(CombatClass.RANGED, () -> false).get(0);
		assertEquals(shortfall, bought.getBuyCost());
		assertTrue(new Optimizer(small, context, budget.toBuilder().budget(shortfall - 1).build(), owned, held,
			item -> 7).optimize(CombatClass.RANGED, () -> false).isEmpty());

		SetupResult unlimited = new Optimizer(small, context, budget.toBuilder().mode(SearchMode.UNLIMITED).build(),
			owned, held, item -> 7).optimize(CombatClass.RANGED, () -> false).get(0);
		assertEquals(shortfall, unlimited.getBuyCost());

		OptimizerSettings ownedOnly = budget.toBuilder().mode(SearchMode.OWNED_ONLY).build();
		Optimizer tooFew = new Optimizer(small, context, ownedOnly, owned, held, item -> 7);
		assertTrue(tooFew.optimize(CombatClass.RANGED, () -> false).isEmpty());
		assertTrue(tooFew.unusableReason(dart).contains("159 of the 100000"));
		SetupResult enough = new Optimizer(small, context, ownedOnly.toBuilder().ammoCount(159).build(), owned, held,
			item -> 7).optimize(CombatClass.RANGED, () -> false).get(0);
		assertEquals(0, enough.getBuyCost());

		// Unpriced darts: the shortfall can't be priced, so it is reported rather than counted as free.
		SetupResult unpriced = new Optimizer(small, context, budget.toBuilder().mode(SearchMode.UNLIMITED).build(),
			owned, held, item -> item == dart ? ItemCosts.UNKNOWN : 7).optimize(CombatClass.RANGED, () -> false).get(0);
		assertEquals(1, unpriced.getUnpricedItems());
		SetupResult covered = new Optimizer(small, context, budget.toBuilder().mode(SearchMode.UNLIMITED).ammoCount(100)
			.build(), owned, held, item -> item == dart ? ItemCosts.UNKNOWN : 7).optimize(CombatClass.RANGED, () -> false)
			.get(0);
		assertEquals(0, covered.getUnpricedItems());
	}

	/** Knives, darts and chinchompas are used up from the weapon slot, so the same supply rules apply. */
	@Test
	public void thrownWeaponsArePricedAndOwnedByTheRequestedQuantity()
	{
		GearItem knife = data.getItem(Slot.WEAPON, 868);
		assertEquals("rune knife", knife.getName());
		GameData small = TestData.gameData(Collections.singletonList(knife), Collections.emptyList());
		IntPredicate owned = id -> id == knife.getId();
		IntToLongFunction held = id -> id == knife.getId() ? 6 : 0;
		OptimizerSettings budget = OptimizerSettings.builder().mode(SearchMode.BUDGET).budget(0)
			.ammoCount(100_000).spellbooks(Collections.emptySet()).build();
		assertTrue("Six knives can't supply 100,000 throws on a zero budget",
			new Optimizer(small, context, budget, owned, held, item -> 50).optimize(CombatClass.RANGED, () -> false).isEmpty());
		OptimizerSettings ownedOnly = budget.toBuilder().mode(SearchMode.OWNED_ONLY).build();
		assertTrue(new Optimizer(small, context, ownedOnly, owned, held, item -> 50)
			.optimize(CombatClass.RANGED, () -> false).isEmpty());

		long shortfall = (100_000 - 6) * 50L;
		assertEquals(shortfall, new Optimizer(small, context, budget.toBuilder().budget(shortfall).build(), owned, held,
			item -> 50).optimize(CombatClass.RANGED, () -> false).get(0).getBuyCost());
		assertEquals(shortfall, new Optimizer(small, context, budget.toBuilder().mode(SearchMode.UNLIMITED).build(),
			owned, held, item -> 50).optimize(CombatClass.RANGED, () -> false).get(0).getBuyCost());
		assertEquals(0, new Optimizer(small, context, ownedOnly.toBuilder().ammoCount(6).build(), owned, held,
			item -> 50).optimize(CombatClass.RANGED, () -> false).get(0).getBuyCost());
		assertEquals(1, new Optimizer(small, context, budget.toBuilder().mode(SearchMode.UNLIMITED).build(), owned, held,
			item -> ItemCosts.UNKNOWN).optimize(CombatClass.RANGED, () -> false).get(0).getUnpricedItems());
	}

	@Test
	public void onlyWeaponsUsedUpPerAttackCountAsSupplies()
	{
		for (int id : new int[]{868, 811, 805, 11959, 6522, 33716})
		{
			assertTrue(data.getItem(Slot.WEAPON, id).getName(), WeaponRules.consumedPerAttack(data.getItem(Slot.WEAPON, id)));
		}
		// Blowpipes, Tonalztics of Ralos, the Hunter's spear and the atlatl are thrown-style or ranged but kept.
		for (int id : new int[]{12926, 28922, 29305, atlatl.getId(), 21012})
		{
			assertFalse(data.getItem(Slot.WEAPON, id).getName(), WeaponRules.consumedPerAttack(data.getItem(Slot.WEAPON, id)));
		}
		assertTrue(WeaponRules.consumedPerAttack(dart));
		assertFalse(WeaponRules.consumedPerAttack(data.getItem(Slot.AMMO, 22947)));
	}

	@Test
	public void onlyBestInSlotAssumesAnUnownedDiaryTier()
	{
		GearItem elite = data.getItem(Slot.AMMO, 22947);
		for (SearchMode mode : SearchMode.values())
		{
			OptimizerSettings settings = OptimizerSettings.builder().mode(mode).budget(Long.MAX_VALUE)
				.spellbooks(Collections.emptySet()).build();
			// Best in slot has no limit, so every diary tier is assumed.
			assertEquals(mode == SearchMode.UNLIMITED,
				new Optimizer(data, context, settings, id -> id == 22943, GearItem::getPrice).available(elite));
			assertTrue(new Optimizer(data, context, settings, id -> id == 22947, GearItem::getPrice).available(elite));
		}
	}
}

package com.bestgearsetup.calc;

import static com.bestgearsetup.calc.TestData.monster;
import static com.bestgearsetup.calc.TestData.piety;
import static com.bestgearsetup.calc.TestData.weapon;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.Slot;
import com.bestgearsetup.data.Spell;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

public class AreaDamageTest
{
	private static Loadout loadout(GearItem weapon, String style)
	{
		Loadout l = new Loadout();
		l.set(Slot.WEAPON, weapon);
		l.setStyle(AttackStyle.parse(style));
		return l;
	}

	private static CombatContext context(Monster target, int targets)
	{
		return new CombatContext(target, PlayerLevels.maxed(), false, true, piety()).withFightOptions(targets, 0);
	}

	@Test
	public void allScytheVariantsUseMonsterSizeAndOnlyUnusedHitsSplash()
	{
		for (String name : new String[]{"scythe of vitur", "holy scythe of vitur", "sanguine scythe of vitur"})
		{
			GearItem w = weapon(22325, name, "scythe", 5, "chop,slash,aggressive");
			w.setMeleeStr(130);
			Loadout l = loadout(w, "chop,slash,aggressive");
			for (int size = 1; size <= 4; size++)
			{
				Monster m = monster(1, 0);
				m.setSize(size);
				DpsResult single = DpsCalculator.calculate(l, context(m, 1));
				int hits = Math.min(3, size);
				int max = 0;
				for (int hit = 0; hit < hits; hit++)
				{
					max += 47 >> hit;
				}
				assertEquals(max, single.getMaxHit());
				double mean = 0;
				for (int hit = 0; hit < hits; hit++)
				{
					int bound = 47 >> hit;
					mean += bound / 2.0 + 1.0 / (bound + 1);
				}
				assertEquals(single.getAccuracy() * mean, single.getAverageHit(), 1e-10);
				DpsResult group = DpsCalculator.calculate(l, context(m, 9));
				assertEquals(single.getPrimaryDps(), group.getPrimaryDps(), 1e-10);
				assertEquals(4 - hits, group.getTargetsHit());
				assertEquals(group.getAccuracy() * (81 / 2.0 + 1.0 / 48 + 1.0 / 24 + 1.0 / 12) / 3,
					group.getDps(), 1e-10);
			}
		}
	}

	@Test
	public void hallowfellCleavesTwoUniqueTargetsAtHalfMaxRegardlessOfMonsterSize()
	{
		GearItem sword = weapon(34027, "hallowfell", "2h sword", 6, "slash,slash,aggressive", "smash,crush,aggressive");
		sword.setMeleeStr(130);
		sword.setTwoHanded(true);
		for (String style : sword.getStyles())
		{
			Loadout l = loadout(sword, style);
			for (int size : new int[]{1, 2, 3, 5})
			{
				Monster m = monster(100, 0);
				m.setSize(size);
				DpsResult single = DpsCalculator.calculate(l, context(m, 1));
				assertEquals(47, single.getMaxHit());
				assertEquals(1, single.getTargetsHit());
				assertEquals(single.getDps(), single.getPrimaryDps(), 1e-10);
				for (int targets : new int[]{2, 3, 9})
				{
					DpsResult group = DpsCalculator.calculate(l, context(m, targets));
					int hits = Math.min(3, targets);
					double secondary = single.getAccuracy() * (23 / 2.0 + 1.0 / 24);
					assertEquals(hits, group.getTargetsHit());
					assertEquals(single.getAverageHit() + secondary * (hits - 1), group.getAverageHit(), 1e-10);
					assertEquals(group.getAverageHit() / 3.6, group.getDps(), 1e-10);
					assertEquals(single.getPrimaryDps(), group.getPrimaryDps(), 1e-10);
					assertEquals(single.getMaxHit(), group.getMaxHit());
				}
			}
		}
	}

	@Test
	public void hallowfellAppliesEncounterCapsToEachCleaveAfterHalvingRawMax()
	{
		GearItem sword = weapon(34027, "hallowfell", "2h sword", 6, "slash,slash,aggressive");
		sword.setMeleeStr(130);
		Loadout l = loadout(sword, "slash,slash,aggressive");
		Monster regular = monster(1, 0);
		int raw = DpsCalculator.calculate(l, context(regular, 1)).getMaxHit();
		Monster verzik = regular.copy();
		verzik.setId(8369);
		verzik.setName("verzik vitur (phase 1)");
		EncounterDamage.Rule rule = EncounterDamage.rule(verzik, l);
		DpsResult area = DpsCalculator.calculate(l, context(verzik, 3));
		assertEquals(area.getAccuracy() * (rule.average(0, raw) + rule.mean(1) / (raw + 1.0)
			+ 2 * (rule.average(0, raw / 2) + rule.mean(1) / (raw / 2 + 1.0))),
			area.getAverageHit(), 1e-10);
		assertEquals(rule.maximum(raw), area.getMaxHit());
		assertEquals(DpsCalculator.calculate(l, context(verzik, 1)).getDps(), area.getPrimaryDps(), 1e-10);
	}

	@Test
	public void hallowfellThrallIsNotMultipliedByCleaveTargets()
	{
		GearItem sword = weapon(34027, "hallowfell", "2h sword", 6, "slash,slash,aggressive");
		sword.setMeleeStr(110);
		Loadout l = loadout(sword, "slash,slash,aggressive");
		Monster m = monster(1, 0);
		CombatContext base = context(m, 3);
		CombatContext thrall = new CombatContext(m, PlayerLevels.maxed(), false, base.getAttack(), base.getStrength(),
			base.getRanged(), base.getMagic(), piety(), true).withFightOptions(3, 0);
		DpsResult before = DpsCalculator.calculate(l, base);
		DpsResult after = DpsCalculator.calculate(l, thrall);
		assertEquals(Thrall.GREATER.getDps(), after.getDps() - before.getDps(), 1e-10);
		assertEquals(Thrall.GREATER.getDps(), after.getPrimaryDps() - before.getPrimaryDps(), 1e-10);
	}

	@Test
	public void optimizerChoosesHallowfellForCleaveButFasterSwordWithAoeOff()
	{
		GearItem hallowfell = weapon(34027, "hallowfell", "2h sword", 6, "slash,slash,aggressive");
		hallowfell.setMeleeStr(110);
		hallowfell.setSlashBonus(117);
		hallowfell.setTwoHanded(true);
		GearItem fast = weapon(1, "fast sword", "slash sword", 4, "slash,slash,aggressive");
		fast.setMeleeStr(110);
		fast.setSlashBonus(117);
		OptimizerSettings settings = OptimizerSettings.builder().mode(SearchMode.UNLIMITED)
			.spellbooks(Collections.emptySet()).build();
		for (int targets : new int[]{1, 3})
		{
			Optimizer optimizer = new Optimizer(TestData.gameData(Arrays.asList(hallowfell, fast), Collections.emptyList()),
				context(monster(100, 0), targets), settings, id -> false, GearItem::getPrice);
			SetupResult best = optimizer.optimize(CombatClass.MELEE, () -> false).get(0);
			assertEquals(targets == 1 ? fast : hallowfell, best.getLoadout().getWeapon());
		}
	}

	@Test
	public void venatorUsesTwoReducedBouncesAndReturnsLastBounceWithTwoEnemies()
	{
		GearItem bow = weapon(27655, "venator bow", "bow", 5, "rapid,ranged,rapid");
		bow.setRangedStr(130);
		Loadout l = loadout(bow, "rapid,ranged,rapid");
		Monster m = monster(1, 0);
		DpsResult single = DpsCalculator.calculate(l, context(m, 1));
		int bounceMax = single.getMaxHit() * 2 / 3;
		double bounce = single.getAccuracy() * (bounceMax / 2.0 + 1.0 / (bounceMax + 1)) / 2.4;
		for (int targets : new int[]{2, 3, 9})
		{
			DpsResult area = DpsCalculator.calculate(l, context(m, targets));
			assertEquals(single.getDps() + bounce * 2, area.getDps(), 1e-10);
			assertEquals(single.getDps() + (targets == 2 ? bounce : 0), area.getPrimaryDps(), 1e-10);
			assertEquals(Math.min(3, targets), area.getTargetsHit());
			assertEquals(single.getMaxHit() + (targets == 2 ? single.getMaxHit() * 2 / 3 : 0), area.getMaxHit());
		}
	}

	@Test
	public void venatorBouncesApplyCapsAfterScalingRawHit()
	{
		GearItem bow = weapon(27655, "venator bow", "bow", 5, "rapid,ranged,rapid");
		bow.setRangedStr(650);
		Loadout l = loadout(bow, "rapid,ranged,rapid");
		Monster regular = monster(1, 0);
		int raw = DpsCalculator.calculate(l, context(regular, 1)).getMaxHit();
		Monster zulrah = regular.copy();
		zulrah.setId(2042);
		EncounterDamage.Rule rule = EncounterDamage.rule(zulrah, l);
		DpsResult area = DpsCalculator.calculate(l, context(zulrah, 3));
		double expected = area.getAccuracy() * (rule.average(0, raw) + rule.mean(1) / (raw + 1.0)
			+ 2 * (rule.average(0, raw * 2 / 3) + rule.mean(1) / (raw * 2 / 3 + 1.0)));
		assertEquals(expected, area.getAverageHit(), 1e-10);
	}

	@Test
	public void chinchompasUseHeavyDefenceDistanceAndTheirOwnTargetLimit()
	{
		GearItem chin = weapon(10034, "red chinchompa", "chinchompa", 4, "medium fuse,ranged,rapid");
		chin.setRangedStr(15);
		chin.setRangedBonus(70);
		Loadout l = loadout(chin, "medium fuse,ranged,rapid");
		Monster m = monster(100, 0);
		m.setDefHeavy(200);
		m.setDefLight(0);
		CombatContext ctx = context(m, 1);
		DpsResult near = DpsCalculator.calculate(l, ctx.withFightOptions(1, 1));
		DpsResult middle = DpsCalculator.calculate(l, ctx.withFightOptions(1, 5));
		DpsResult far = DpsCalculator.calculate(l, ctx.withFightOptions(1, 8));
		assertTrue(middle.getAccuracy() > near.getAccuracy());
		assertEquals(near.getAccuracy(), far.getAccuracy(), 1e-10);
		DpsResult area = DpsCalculator.calculate(l, ctx.withFightOptions(12, 5));
		assertEquals(11, area.getTargetsHit());
		assertEquals(middle.getDps() * 11, area.getDps(), 1e-10);
		assertEquals(middle.getDps(), area.getPrimaryDps(), 1e-10);
		chin.setName("black chinchompa");
		assertEquals(12, DpsCalculator.calculate(l, ctx.withFightOptions(12, 5)).getTargetsHit());
		m.setDefHeavy(0);
		assertTrue(DpsCalculator.calculate(l, ctx.withFightOptions(1, 5)).getAccuracy() > middle.getAccuracy());
	}

	@Test
	public void ancientBurstAndBarrageSplashButBlitzDoesNot()
	{
		GearItem staff = weapon(4675, "ancient staff", "staff", 5, "spell,magic,magic");
		Loadout l = loadout(staff, "spell,magic,magic");
		Monster m = monster(1, 0);
		for (String name : new String[]{"ice burst", "ice barrage", "blood barrage", "ice blitz"})
		{
			Spell spell = new Spell();
			spell.setName(name);
			spell.setSpellbook("ancient");
			spell.setMaxHit(30);
			l.setSpell(spell);
			DpsResult single = DpsCalculator.calculate(l, context(m, 1));
			DpsResult area = DpsCalculator.calculate(l, context(m, 12));
			int hits = name.endsWith("blitz") ? 1 : 9;
			assertEquals(hits, area.getTargetsHit());
			assertEquals(single.getDps() * hits, area.getDps(), 1e-10);
			assertEquals(single.getDps(), area.getPrimaryDps(), 1e-10);
		}
	}

	@Test
	public void thrallIsAddedOnceAndOrdinaryWeaponsNeverGainAreaDamage()
	{
		Monster m = monster(1, 0);
		GearItem bow = weapon(27655, "venator bow", "bow", 5, "rapid,ranged,rapid");
		bow.setRangedStr(80);
		Loadout l = loadout(bow, "rapid,ranged,rapid");
		CombatContext base = context(m, 3);
		CombatContext thrall = new CombatContext(m, PlayerLevels.maxed(), false, base.getAttack(), base.getStrength(),
			base.getRanged(), base.getMagic(), piety(), true).withFightOptions(3, 0);
		DpsResult before = DpsCalculator.calculate(l, base);
		DpsResult after = DpsCalculator.calculate(l, thrall);
		assertEquals(Thrall.GREATER.getDps(), after.getDps() - before.getDps(), 1e-10);
		assertEquals(Thrall.GREATER.getDps(), after.getPrimaryDps() - before.getPrimaryDps(), 1e-10);
		bow.setName("magic shortbow");
		assertEquals(DpsCalculator.calculate(l, context(m, 1)).getDps(), DpsCalculator.calculate(l, base).getDps(), 1e-10);
		assertEquals(1, DpsCalculator.calculate(l, base).getTargetsHit());
	}

	@Test
	public void optimizerCanChooseLowerSingleTargetSpellForGreaterTotalDamage()
	{
		GearItem staff = weapon(4675, "ancient staff", "staff", 5, "spell,magic,magic");
		Spell burst = new Spell();
		burst.setName("ice burst");
		burst.setSpellbook("ancient");
		burst.setMaxHit(22);
		burst.setSpellWeapons(Collections.singletonList("4675"));
		Spell blitz = new Spell();
		blitz.setName("ice blitz");
		blitz.setSpellbook("ancient");
		blitz.setMaxHit(26);
		blitz.setSpellWeapons(Collections.singletonList("4675"));
		OptimizerSettings settings = OptimizerSettings.builder().mode(SearchMode.UNLIMITED)
			.spellbooks(Collections.singleton("ancient")).build();
		for (int targets : new int[]{1, 9})
		{
			Optimizer optimizer = new Optimizer(TestData.gameData(Collections.singletonList(staff), Arrays.asList(burst, blitz)),
				context(monster(1, 0), targets), settings, id -> false, GearItem::getPrice);
			SetupResult best = optimizer.optimize(CombatClass.MAGIC, () -> false).get(0);
			assertEquals(targets == 1 ? blitz : burst, best.getLoadout().getSpell());
		}
	}
}

package com.bestgearsetup.calc;

import static com.bestgearsetup.calc.TestData.item;
import static com.bestgearsetup.calc.TestData.monster;
import static com.bestgearsetup.calc.TestData.piety;
import static com.bestgearsetup.calc.TestData.weapon;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.BestGearSetupConfig;
import com.bestgearsetup.OwnershipRules;
import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.GameData;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Slot;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.function.IntPredicate;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.Before;
import org.junit.BeforeClass;
import org.junit.Test;

public class AtlatlAmmoRecoveryTest
{
	private GearItem atlatl;
	private GearItem darts;
	private GearItem fireCape;
	private GearItem accumulator;
	private GameData data;
	private final CombatContext ctx = new CombatContext(monster(100, 20), PlayerLevels.maxed(), false, true, piety());

	@BeforeClass
	public static void ownershipRules()
	{
		OwnershipRules.init(RuneLiteAPI.GSON);
	}

	@Before
	public void setUp()
	{
		atlatl = weapon(29000, "eclipse atlatl", "bow", 4, "rapid,ranged,rapid");
		atlatl.setRangedBonus(87);
		atlatl.setMeleeStr(40);
		atlatl.setTwoHanded(true);
		atlatl.setAmmunition(Collections.singletonList(29001));
		darts = item(29001, "atlatl dart", Slot.AMMO);
		fireCape = item(6570, "fire cape", Slot.CAPE);
		fireCape.setMeleeStr(30);
		fireCape.setRangedBonus(30);
		fireCape.setPrayerBonus(10);
		accumulator = item(10499, "ava's accumulator", Slot.CAPE);
		accumulator.setTradeable(false);
		data = TestData.gameData(Arrays.asList(atlatl, darts, fireCape, accumulator), Collections.emptyList());
	}

	private OptimizerSettings.OptimizerSettingsBuilder settings()
	{
		return OptimizerSettings.builder().mode(SearchMode.UNLIMITED).requireAtlatlAmmoRecovery(true)
			.spellbooks(Collections.emptySet()).styles(EnumSet.of(AttackStyle.Type.ATLATL));
	}

	private Optimizer optimizer(OptimizerSettings settings, IntPredicate owned)
	{
		return new Optimizer(data, ctx, settings, owned, GearItem::getPrice);
	}

	private List<SetupResult> run(OptimizerSettings.OptimizerSettingsBuilder settings)
	{
		return optimizer(settings.build(), id -> true).optimize(CombatClass.RANGED, () -> false);
	}

	@Test
	public void optionalSettingPreservesUnrestrictedAtlatlResults()
	{
		assertFalse(new BestGearSetupConfig() { }.requireAtlatlAmmoRecovery());
		assertFalse(OptimizerSettings.builder().build().isRequireAtlatlAmmoRecovery());
		assertEquals(fireCape, run(settings().requireAtlatlAmmoRecovery(false)).get(0).getLoadout().get(Slot.CAPE));
	}

	@Test
	public void zeroDamageDeviceSurvivesPruningAndEverySearchDepth()
	{
		assertTrue(optimizer(settings().build(), id -> true).candidates(CombatClass.RANGED).get(Slot.CAPE).contains(accumulator));
		for (SearchDepth depth : SearchDepth.values())
		{
			List<SetupResult> results = run(settings().depth(depth));
			assertEquals(depth.toString(), 1, results.size());
			assertEquals(accumulator, results.get(0).getLoadout().get(Slot.CAPE));
			assertTrue(results.get(0).getDps().getDps() > 0);
		}
	}

	@Test
	public void supportsDevicesAssemblerVariantsAndQuivers()
	{
		String[] names = {"ava's attractor", "ava's accumulator", "ava's assembler", "assembler max cape",
			"masori assembler", "masori assembler max cape", "dizana's quiver", "blessed dizana's quiver"};
		for (String name : names)
		{
			GearItem cape = item(900, name, Slot.CAPE);
			data = TestData.gameData(Arrays.asList(atlatl, darts, fireCape, cape), Collections.emptyList());
			assertEquals(name, cape, run(settings()).get(0).getLoadout().get(Slot.CAPE));
		}
	}

	@Test
	public void ownershipAndExclusionsCanRemoveAllAtlatlResults()
	{
		for (SearchMode mode : Arrays.asList(SearchMode.OWNED_ONLY, SearchMode.BUDGET))
		{
			assertTrue(optimizer(settings().mode(mode).budget(1_000_000).build(), id -> id != accumulator.getId())
				.optimize(CombatClass.RANGED, () -> false).isEmpty());
		}
		assertTrue(run(settings().excluded(Collections.singleton(accumulator.getId()))).isEmpty());
		accumulator.setRangedReq(100);
		assertTrue(run(settings()).isEmpty());
	}

	@Test
	public void cheaperDeviceFitsWhenQuiverExceedsCombinedBudget()
	{
		accumulator.setTradeable(true);
		accumulator.setPrice(100);
		atlatl.setPrice(200);
		GearItem quiver = item(28951, "dizana's quiver", Slot.CAPE);
		quiver.setPrice(250);
		quiver.setRangedBonus(20);
		data = TestData.gameData(Arrays.asList(atlatl, darts, accumulator, quiver), Collections.emptyList());
		OptimizerSettings budget = settings().mode(SearchMode.BUDGET).budget(300).build();
		List<SetupResult> results = optimizer(budget, id -> false).optimize(CombatClass.RANGED, () -> false);
		assertEquals(accumulator, results.get(0).getLoadout().get(Slot.CAPE));
		assertEquals(300, results.get(0).getBuyCost());
		assertTrue(optimizer(budget.toBuilder().budget(299).build(), id -> false)
			.optimize(CombatClass.RANGED, () -> false).isEmpty());
	}

	@Test
	public void capeLocksRespectTheRequirementAndExplainWeaponConflicts()
	{
		for (SlotLock lock : Arrays.asList(SlotLock.empty(), SlotLock.item(fireCape.getId())))
		{
			OptimizerSettings locked = settings().locks(Collections.singletonMap(Slot.CAPE, lock)).build();
			Optimizer optimizer = optimizer(locked, id -> true);
			assertTrue(optimizer.optimize(CombatClass.RANGED, () -> false).isEmpty());
			assertTrue(optimizer.weaponLockReason(atlatl).contains("Ava's"));
		}
		for (SlotLock lock : Arrays.asList(SlotLock.fill(), SlotLock.item(accumulator.getId())))
		{
			assertEquals(accumulator, run(settings().locks(Collections.singletonMap(Slot.CAPE, lock)))
				.get(0).getLoadout().get(Slot.CAPE));
		}
	}

	@Test
	public void slotFillingCannotReplaceTheRecoveryCape()
	{
		for (FillMode fill : FillMode.values())
		{
			assertEquals(accumulator, run(settings().fillMode(fill).fillMarginPercent(100))
				.get(0).getLoadout().get(Slot.CAPE));
		}
	}

	@Test
	public void wildernessRiskStillCountsRequiredCapes()
	{
		accumulator.setPrice(1_000_000);
		assertTrue(run(settings().wildernessRiskLimited(true).maxExpensiveItems(0)).isEmpty());
		assertEquals(accumulator, run(settings().wildernessRiskLimited(true).maxExpensiveItems(1))
			.get(0).getLoadout().get(Slot.CAPE));
	}

	@Test
	public void otherRangedWeaponsKeepTheirUnrestrictedCapes()
	{
		GearItem bow = weapon(900, "bow", "bow", 4, "rapid,ranged,rapid");
		bow.setRangedBonus(60);
		fireCape.setRangedStr(30);
		data = TestData.gameData(Arrays.asList(bow, fireCape), Collections.emptyList());
		assertEquals(fireCape, run(settings().styles(EnumSet.of(AttackStyle.Type.RANGED)))
			.get(0).getLoadout().get(Slot.CAPE));
	}
}

package com.bestgearsetup.calc;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.GameData;
import com.bestgearsetup.data.Slot;
import com.bestgearsetup.data.WikiGameData;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.BeforeClass;
import org.junit.Test;

/** Salve damage and ownership rules for Strength-scaling ranged attacks against undead. */
public class AtlatlSalveTest
{
	private static GameData data;
	private static final CombatContext CONTEXT = new CombatContext(TestData.monster(30, 0, "undead"),
		new PlayerLevels(82, 87, 80, 81, 76, 76, 87, 68), true, false, null);
	private static final OptimizerSettings SETTINGS = OptimizerSettings.builder()
		.mode(SearchMode.OWNED_ONLY)
		.depth(SearchDepth.BEST)
		.styles(Collections.singleton(AttackStyle.Type.ATLATL))
		.spellbooks(Collections.singleton("standard"))
		.build();

	@BeforeClass
	public static void load() throws Exception
	{
		Gson gson = RuneLiteAPI.GSON;
		data = WikiGameData.get(gson).gameData(gson);
	}

	@Test
	public void enchantedSalvesShareAtlatlDamageButOnlyImbuedGrantsAccuracy()
	{
		Loadout loadout = new Loadout();
		loadout.set(Slot.WEAPON, data.getItem(Slot.WEAPON, 29000));
		loadout.set(Slot.AMMO, data.getItem(Slot.AMMO, 28991));
		loadout.setStyle(AttackStyle.parse("rapid,ranged,rapid"));
		DpsResult baseline = DpsCalculator.calculate(loadout, CONTEXT);
		loadout.set(Slot.NECK, data.getItem(Slot.NECK, 10588));
		DpsResult regular = DpsCalculator.calculate(loadout, CONTEXT);
		loadout.set(Slot.NECK, data.getItem(Slot.NECK, 12018));
		DpsResult imbued = DpsCalculator.calculate(loadout, CONTEXT);

		assertEquals(baseline.getMaxHit() * 6 / 5, regular.getMaxHit());
		assertEquals(baseline.getAccuracy(), regular.getAccuracy(), 1e-12);
		assertEquals(regular.getMaxHit(), imbued.getMaxHit());
		assertTrue(imbued.getAccuracy() > regular.getAccuracy());
		assertTrue(imbued.getDps() > regular.getDps());
	}

	@Test
	public void ownedOnlySelectsImbuedWhenAvailableAndRegularOtherwise()
	{
		Set<Integer> owned = new HashSet<>(Arrays.asList(29000, 28991, 10588));
		SetupResult regular = new Optimizer(data, CONTEXT, SETTINGS, owned::contains, item -> 0)
			.optimize(CombatClass.RANGED, () -> false).get(0);
		assertEquals(10588, regular.getLoadout().get(Slot.NECK).getId());

		owned.add(12018);
		SetupResult imbued = new Optimizer(data, CONTEXT, SETTINGS, owned::contains, item -> 0)
			.optimize(CombatClass.RANGED, () -> false).get(0);
		assertEquals(12018, imbued.getLoadout().get(Slot.NECK).getId());
		assertTrue(imbued.getDps().getDps() > regular.getDps().getDps());
	}
}

package com.bestgearsetup.calc;

