		assertEquals(1, new WorldArea(105, 102, 1, 1, 0).distanceTo(target));
		assertEquals(2, new WorldArea(106, 106, 1, 1, 0).distanceTo(target));
		assertEquals(Integer.MAX_VALUE, new WorldArea(105, 102, 1, 1, 1).distanceTo(target));
	}
}

package com.bestgearsetup.calc;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.GameData;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.Slot;
import com.bestgearsetup.data.WikiGameData;
import com.bestgearsetup.data.WikiMonsters;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.BeforeClass;
import org.junit.Test;

/** Owned blue-dragon setups whose stat upgrades cross a max-hit breakpoint together. */
public class BlueDragonOptimizerTest
{
	private static GameData data;
	private static CombatContext ctx;
	private static final OptimizerSettings SETTINGS = OptimizerSettings.builder()
		.mode(SearchMode.OWNED_ONLY)
		.depth(SearchDepth.BEST)
		.antifire(Antifire.REGULAR)
		.protectMagic(false)
		.spellbooks(Collections.singleton("standard"))
		.build();

	@BeforeClass
	public static void load() throws Exception
	{
		Gson gson = RuneLiteAPI.GSON;
		data = WikiGameData.get(gson).gameData(gson);
		Monster monster = WikiMonsters.get(gson).monster(data.matchNpc(265, null, 0).getName());
		ctx = new CombatContext(monster, new PlayerLevels(82, 87, 80, 81, 76, 76, 87, 67), true, false, null);
	}

	private static Set<Integer> meleeOwned()
	{
		return new HashSet<>(Arrays.asList(11864, 13121, 10354, 6585, 6570, 26219, 29280, 1540,
			29283, 7462, 13239, 11773));
	}

	private static SetupResult best(Set<Integer> owned, CombatClass cls)
	{
		List<SetupResult> results = new Optimizer(data, ctx, SETTINGS, owned::contains, item -> 1_000)
			.optimize(cls, () -> false);
		return results.get(0);
	}

	@Test
	public void furyAndFireCapeTogetherEscapeTheStabPlateau()
	{
		Set<Integer> owned = meleeOwned();
		owned.remove(6585);
		owned.remove(6570);
		Loadout baseline = best(owned, CombatClass.MELEE).getLoadout();
		DpsResult before = DpsCalculator.calculate(baseline, ctx);
		Loadout furyOnly = baseline.copy();
		furyOnly.set(Slot.NECK, data.getItem(Slot.NECK, 6585));
		assertEquals(before.getDps(), DpsCalculator.calculate(furyOnly, ctx).getDps(), 1e-9);
		Loadout capeOnly = baseline.copy();
		capeOnly.set(Slot.CAPE, data.getItem(Slot.CAPE, 6570));
		assertTrue(DpsCalculator.calculate(capeOnly, ctx).getDps() < before.getDps());

		SetupResult result = best(meleeOwned(), CombatClass.MELEE);
		assertEquals(6585, result.getLoadout().get(Slot.NECK).getId());
		assertEquals(6570, result.getLoadout().get(Slot.CAPE).getId());
		assertEquals(32, result.getDps().getMaxHit());
		assertEquals(5.96212946154077, result.getDps().getDps(), 1e-9);
		assertEquals(0, result.getBuyCost());
	}

	@Test
	public void bloodMoonArmourTogetherEscapesTheEmptyCrushSlots()
	{
		Set<Integer> owned = new HashSet<>(Arrays.asList(11865, 6570, 6585, 28810, 1540, 7462, 13239, 11773));
		OptimizerSettings crush = SETTINGS.toBuilder().styles(Collections.singleton(AttackStyle.Type.CRUSH)).build();
		Loadout baseline = new Optimizer(data, ctx, crush, owned::contains, item -> 1_000)
			.optimize(CombatClass.MELEE, () -> false).get(0).getLoadout();
		double before = DpsCalculator.calculate(baseline, ctx).getDps();
		for (Slot slot : Arrays.asList(Slot.BODY, Slot.LEGS))
		{
			Loadout single = baseline.copy();
			single.set(slot, data.getItem(slot, slot == Slot.BODY ? 29022 : 29025));
			assertEquals(before, DpsCalculator.calculate(single, ctx).getDps(), 1e-9);
		}
		owned.add(29022);
		owned.add(29025);
		SetupResult result = new Optimizer(data, ctx, crush, owned::contains, item -> 1_000)
			.optimize(CombatClass.MELEE, () -> false).get(0);
		assertEquals(29022, result.getLoadout().get(Slot.BODY).getId());
		assertEquals(29025, result.getLoadout().get(Slot.LEGS).getId());
		assertEquals(38, result.getDps().getMaxHit());
		assertEquals(3.990498978687955, result.getDps().getDps(), 1e-9);
		assertEquals(0, result.getBuyCost());
	}

	@Test
	public void rangedAccuracyTieRetainsFurysDefenceAndPrayer()
	{
		Set<Integer> owned = new HashSet<>(Arrays.asList(11865, 27374, 10354, 6585, 9243, 9185,
			29004, 1540, 2497, 7462, 22951));
		SetupResult result = best(owned, CombatClass.RANGED);
		assertEquals(6585, result.getLoadout().get(Slot.NECK).getId());
		Loadout glory = result.getLoadout().copy();
		GearItem amulet = data.getItem(Slot.NECK, 10354);
		glory.set(Slot.NECK, amulet);
		assertEquals(result.getDps().getDps(), DpsCalculator.calculate(glory, ctx).getDps(), 1e-9);
		assertEquals(0, result.getBuyCost());
	}

	@Test
	public void superAntifireStabFindsTwoIndividuallyWorseStrengthTrades()
	{
		Set<Integer> owned = meleeOwned();
		owned.addAll(Arrays.asList(11865, 12954, 29025));
		OptimizerSettings settings = SETTINGS.toBuilder().antifire(Antifire.SUPER)
			.styles(Collections.singleton(AttackStyle.Type.STAB)).build();
		Loadout baseline = new Optimizer(data, ctx, settings.toBuilder().depth(SearchDepth.NORMAL).build(),
			owned::contains, item -> 1_000).optimize(CombatClass.MELEE, () -> false).get(0).getLoadout();
		double before = DpsCalculator.calculate(baseline, ctx).getDps();
		for (Slot slot : Arrays.asList(Slot.CAPE, Slot.LEGS))
		{
			Loadout single = baseline.copy();
			single.set(slot, data.getItem(slot, slot == Slot.CAPE ? 6570 : 29025));
			assertTrue(DpsCalculator.calculate(single, ctx).getDps() < before);
		}
		SetupResult result = new Optimizer(data, ctx, settings, owned::contains, item -> 1_000)
			.optimize(CombatClass.MELEE, () -> false).get(0);
		assertEquals(6570, result.getLoadout().get(Slot.CAPE).getId());
		assertEquals(29025, result.getLoadout().get(Slot.LEGS).getId());
		assertEquals(33, result.getDps().getMaxHit());
		assertEquals(6.162669837023042, result.getDps().getDps(), 1e-9);
		assertEquals(0, result.getBuyCost());

		OptimizerSettings locked = settings.toBuilder().locks(SlotLock.parse("CAPE:13121,LEGS:29283")).build();
		SetupResult constrained = new Optimizer(data, ctx, locked, owned::contains, item -> 1_000)
			.optimize(CombatClass.MELEE, () -> false).get(0);
		assertEquals(13121, constrained.getLoadout().get(Slot.CAPE).getId());
		assertEquals(29283, constrained.getLoadout().get(Slot.LEGS).getId());
		assertTrue(constrained.getDps().getDps() < result.getDps().getDps());

		owned.removeAll(Arrays.asList(6570, 29025));
		OptimizerSettings noSpend = settings.toBuilder().mode(SearchMode.BUDGET).budget(0).build();
		SetupResult affordable = new Optimizer(data, ctx, noSpend, owned::contains, item -> 1_000)
			.optimize(CombatClass.MELEE, () -> false).get(0);
		assertEquals(0, affordable.getBuyCost());
		assertTrue(affordable.getDps().getDps() < result.getDps().getDps());
	}

	@Test
	public void diamondBeatsRubyAcrossTheFightDespiteRubysHigherStartingDps()
	{
		Set<Integer> owned = new HashSet<>(Arrays.asList(11865, 27374, 6585, 9242, 9243, 9185,
			29004, 1540, 2497, 7462, 22951));
		SetupResult result = best(owned, CombatClass.RANGED);
		assertEquals(9243, result.getLoadout().get(Slot.AMMO).getId());
		Loadout ruby = result.getLoadout().copy();
		ruby.set(Slot.AMMO, data.getItem(Slot.AMMO, 9242));
		assertTrue(DpsCalculator.snapshot(ruby, ctx).getDps() > result.getDps().getDps());
		assertEquals(3.996653853236797, DpsCalculator.snapshot(ruby, ctx).getDps(), 1e-9);
		double seconds = 0;
		for (int hp = ctx.getMonster().getHitpoints(); hp >= 1; hp--)
		{
			seconds += 1 / DpsCalculator.snapshot(ruby, ctx.atTargetHp(hp)).getPrimaryDps();
		}
		double averaged = ctx.getMonster().getHitpoints() / seconds;
		assertTrue(averaged < result.getDps().getDps());
		assertEquals(averaged, DpsCalculator.calculate(ruby, ctx).getDps(), averaged * 0.002);
		assertEquals(3.942164150262182, result.getDps().getDps(), 1e-9);
	}

	@Test
	public void shortAtlatlFightFavoursSlayerHelmetOverTheFullBurnSet()
	{
		GearItem eclipseHelm = data.getItems(Slot.HEAD).stream()
			.filter(i -> i.getName().equals("eclipse moon helm")).findFirst().get();
		GearItem mixedBoots = data.getItems(Slot.FEET).stream()
			.filter(i -> i.getName().equals("mixed hide boots")).findFirst().get();
		Set<Integer> owned = new HashSet<>(Arrays.asList(11865, 6570, 6585, 29000, 28991, 29004,
			29007, 7462, 13239, 11773, eclipseHelm.getId(), mixedBoots.getId()));
		OptimizerSettings settings = SETTINGS.toBuilder().antifire(Antifire.SUPER)
			.styles(Collections.singleton(AttackStyle.Type.ATLATL)).build();
		SetupResult result = new Optimizer(data, ctx, settings, owned::contains, item -> 1_000)
			.optimize(CombatClass.RANGED, () -> false).get(0);
		assertEquals(11865, result.getLoadout().get(Slot.HEAD).getId());
		assertEquals(13239, result.getLoadout().get(Slot.FEET).getId());
		assertEquals(5.16442935381305, result.getDps().getDps(), 1e-9);

		Loadout fullSet = result.getLoadout().copy();
		fullSet.set(Slot.HEAD, eclipseHelm);
		fullSet.set(Slot.FEET, mixedBoots);
		DpsResult direct = DpsCalculator.snapshot(fullSet, ctx);
		// Crediting all ten future burn hits per proc reproduces GearScape's sustained result.
		double allBurnHits = direct.getDps() + direct.getAccuracy() * 0.2 * 10 / 1.8;
		assertEquals(5.19227, allBurnHits, 1e-5);
		assertTrue(allBurnHits > result.getDps().getDps());
		assertEquals(4.773570288705978, DpsCalculator.calculate(fullSet, ctx).getDps(), 1e-9);
		assertTrue(DpsCalculator.calculate(fullSet, ctx).getDps() < result.getDps().getDps());
	}

	@Test
	public void superAntifireRangedFavoursKnivesOverWholeFightRubyDamage()
	{
		Set<Integer> owned = new HashSet<>(Arrays.asList(11865, 27374, 6585, 868, 9242, 9243, 9185,
			29004, 22275, 2497, 7462, 22951));
		OptimizerSettings settings = SETTINGS.toBuilder().antifire(Antifire.SUPER)
			.styles(Collections.singleton(AttackStyle.Type.RANGED)).build();
		SetupResult result = new Optimizer(data, ctx, settings, owned::contains, item -> 1_000)
			.optimize(CombatClass.RANGED, () -> false).get(0);
		assertEquals(868, result.getLoadout().getWeapon().getId());
		assertEquals(3.9831401730861367, result.getDps().getDps(), 1e-9);
		Loadout crossbow = result.getLoadout().copy();
		crossbow.set(Slot.WEAPON, data.getItem(Slot.WEAPON, 9185));
		crossbow.set(Slot.AMMO, data.getItem(Slot.AMMO, 9242));
		assertEquals(4.00754, DpsCalculator.snapshot(crossbow, ctx).getDps(), 1e-5);
		assertTrue(DpsCalculator.snapshot(crossbow, ctx).getDps() > result.getDps().getDps());
		assertTrue(DpsCalculator.calculate(crossbow, ctx).getDps() < result.getDps().getDps());
		crossbow.set(Slot.AMMO, data.getItem(Slot.AMMO, 9243));
		assertEquals(3.9525841756379023, DpsCalculator.calculate(crossbow, ctx).getDps(), 1e-9);
	}

	@Test
	public void ownedOnlyDoesNotSubstituteUnownedDragonDarts()
	{
		Set<Integer> owned = new HashSet<>(Arrays.asList(11865, 27374, 6585, 9243, 9185, 29004,
			1540, 2497, 7462, 22951));
		assertEquals(9185, best(owned, CombatClass.RANGED).getLoadout().getWeapon().getId());
		owned.add(11230);
		SetupResult darts = best(owned, CombatClass.RANGED);
		assertEquals(11230, darts.getLoadout().getWeapon().getId());
		assertEquals(4.12223197101416, darts.getDps().getDps(), 1e-9);
	}
}

package com.bestgearsetup.calc;

import static com.bestgearsetup.calc.TestData.item;
import static com.bestgearsetup.calc.TestData.monster;
import static com.bestgearsetup.calc.TestData.weapon;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.OwnershipRules;
import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Slot;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.BeforeClass;
import org.junit.Test;

/** Candidate pruning and trial evaluation on synthetic gear. */
public class CandidateSearchTest
{
	@BeforeClass
	public static void ownershipRules()
	{
		OwnershipRules.init(RuneLiteAPI.GSON);
	}

	private static GearItem stabSword()
	{
		GearItem sword = weapon(100, "sword", "stab sword", 4, "stab,stab,accurate", "lunge,stab,aggressive");
		sword.setStabBonus(60);
		sword.setMeleeStr(40);
		return sword;
	}

	private static OptimizerSettings.OptimizerSettingsBuilder settings()
	{
		return OptimizerSettings.builder().mode(SearchMode.UNLIMITED).depth(SearchDepth.BEST)
			.spellbooks(new HashSet<>());
	}

	private static double dps(GearItem sword, GearItem head, CombatContext ctx, String style)
	{
		Loadout l = new Loadout();
		l.set(Slot.WEAPON, sword);
		l.set(Slot.HEAD, head);
		l.setStyle(AttackStyle.parse(style));
		return DpsCalculator.calculate(l, ctx).getDps();
	}

	private static double best(GearItem sword, GearItem head, CombatContext ctx)
	{
		return Math.max(dps(sword, head, ctx, "stab,stab,accurate"), dps(sword, head, ctx, "lunge,stab,aggressive"));
	}

	/**
	 * +1 attack and +1 strength reach the same max hit as +3 strength while keeping some accuracy, so they beat
	 * both +3 attack and +3 strength, though each single-stat ranking puts them last.
	 */
	@Test
	public void balancedItemSurvivesPruning()
	{
		GearItem sword = stabSword();
		GearItem attack = item(201, "attack helm", Slot.HEAD);
		attack.setStabBonus(3);
		GearItem strength = item(202, "strength helm", Slot.HEAD);
		strength.setMeleeStr(3);
		GearItem balanced = item(203, "balanced helm", Slot.HEAD);
		balanced.setStabBonus(1);
		balanced.setMeleeStr(1);
		CombatContext ctx = new CombatContext(monster(100, 60), PlayerLevels.maxed(), false, false, null);
		double best = best(sword, balanced, ctx);
		assertTrue(best > best(sword, strength, ctx));
		assertTrue(best > best(sword, attack, ctx));

		Optimizer optimizer = new Optimizer(TestData.gameData(Arrays.asList(sword, attack, strength, balanced),
			Collections.emptyList()), ctx, settings().build(), id -> true, i -> 0);
		assertTrue(optimizer.candidates(CombatClass.MELEE).get(Slot.HEAD).contains(balanced));
		SetupResult result = optimizer.optimize(CombatClass.MELEE, () -> false).get(0);
		assertEquals(balanced, result.getLoadout().get(Slot.HEAD));
		assertEquals(best, result.getDps().getDps(), 1e-12);
	}

	/** A dominated item (no better stat, no cheaper, no less risky) is pruned; a cheaper equal one is not. */
	@Test
	public void dominatedItemsArePruned()
	{
		GearItem sword = stabSword();
		GearItem good = item(201, "good helm", Slot.HEAD);
		good.setStabBonus(5);
		good.setMeleeStr(2);
		good.setPrice(1_000);
		GearItem worse = item(202, "worse helm", Slot.HEAD);
		worse.setStabBonus(4);
		worse.setMeleeStr(2);
		worse.setPrice(1_000);
		GearItem cheaper = item(203, "cheaper helm", Slot.HEAD);
		cheaper.setStabBonus(4);
		cheaper.setMeleeStr(2);
		cheaper.setPrice(10);
		CombatContext ctx = new CombatContext(monster(100, 60), PlayerLevels.maxed(), false, false, null);
		Optimizer optimizer = new Optimizer(TestData.gameData(Arrays.asList(sword, good, worse, cheaper),
			Collections.emptyList()), ctx, settings().mode(SearchMode.BUDGET).budget(10_000).build(), id -> false,
			GearItem::getPrice);
		assertEquals(Arrays.asList(good, cheaper), optimizer.candidates(CombatClass.MELEE).get(Slot.HEAD));
	}

	/** The trial evaluation only ever chooses a stance the experience filter allows, even when another scores more. */
	@Test
	public void trialOptionsFollowTheExperienceFilter()
	{
		GearItem sword = stabSword();
		CombatContext ctx = new CombatContext(monster(300, 300), PlayerLevels.maxed(), false, false, null);
		Loadout l = new Loadout();
		l.set(Slot.WEAPON, sword);
		double accurate = dps(sword, null, ctx, "stab,stab,accurate");
		double aggressive = dps(sword, null, ctx, "lunge,stab,aggressive");
		boolean accurateWins = accurate > aggressive;
		assertTrue(accurate != aggressive);

		Optimizer free = new Optimizer(TestData.gameData(Collections.singletonList(sword), Collections.emptyList()), ctx,
			settings().build(), id -> true, i -> 0);
		l.setStyle(AttackStyle.parse(accurateWins ? "lunge,stab,aggressive" : "stab,stab,accurate"));
		assertEquals(Math.max(accurate, aggressive), free.scoreWithBestOption(l, CombatClass.MELEE), 1e-12);
		assertEquals(accurateWins ? "accurate" : "aggressive", l.getStyle().getStance());

		// Forbid the winning stance's experience: the other one is chosen although it scores less.
		Optimizer filtered = new Optimizer(TestData.gameData(Collections.singletonList(sword), Collections.emptyList()),
			ctx, settings().attackXp(!accurateWins).strengthXp(accurateWins).build(), id -> true, i -> 0);
		assertEquals(Math.min(accurate, aggressive), filtered.scoreWithBestOption(l, CombatClass.MELEE), 1e-12);
		assertEquals(accurateWins ? "aggressive" : "accurate", l.getStyle().getStance());
	}

	/** A trial over the expensive-item cap is worth nothing, whatever its option. */
	@Test
	public void trialOverTheCapScoresNothing()
	{
		GearItem sword = stabSword();
		sword.setPrice(5_000_000);
		CombatContext ctx = new CombatContext(monster(100, 60), PlayerLevels.maxed(), false, false, null);
		Optimizer optimizer = new Optimizer(TestData.gameData(Collections.singletonList(sword), Collections.emptyList()),
			ctx, settings().wildernessRiskLimited(true).maxExpensiveItems(0).build(), id -> true, GearItem::getPrice);
		Loadout l = new Loadout();
		l.set(Slot.WEAPON, sword);
		l.setStyle(AttackStyle.parse("lunge,stab,aggressive"));
		assertEquals(0, optimizer.scoreWithBestOption(l, CombatClass.MELEE), 0);
	}
}

package com.bestgearsetup.calc;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.OwnershipRules;
import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.GameData;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.Slot;
import com.bestgearsetup.data.WikiGameData;
import com.bestgearsetup.data.WikiMonsters;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.BeforeClass;
import org.junit.Test;

/** A capped atlatl search must be able to leave the full Eclipse set for stronger mixed equipment. */
public class ChaosDwarfOptimizerTest
{
	private static GameData data;
	private static CombatContext context;
	private static final Set<Integer> OWNED = new HashSet<>(Arrays.asList(
		10828, 6570, 1725, 29280, 2497, 7462, 29286, 11773, 29000, 28991,
		29035, 29031, 29033, 29047, 29043, 29045, 776, 22114, 13239, 6585, 1704, 3105));

	@BeforeClass
	public static void load() throws Exception
	{
		Gson gson = RuneLiteAPI.GSON;
		OwnershipRules.init(gson);
		data = WikiGameData.get(gson).gameData(gson);
		// The live client adds charged/degraded entries with their own identities and prices.
		data.addVariantItems(gson, id ->
		{
			switch (id)
			{
				case 29035: return "Eclipse moon helm";
				case 29031: return "Eclipse moon chestplate";
				case 29033: return "Eclipse moon tassets";
				case 29047: return "Blood moon helm";
				case 29043: return "Blood moon chestplate";
				case 29045: return "Blood moon tassets";
				default: return null;
			}
		}, id -> false);
		Monster monster = WikiMonsters.get(gson).monster(data.matchNpc(291, null, 0).getName());
		context = new CombatContext(monster, new PlayerLevels(82, 87, 80, 81, 76, 76, 87, 68),
			false, false, null).withModifiers(CombatModifiers.builder().wilderness(true).build());
	}

	private static long price(GearItem item)
	{
		String name = item.getName();
		if (name.equals("barrows gloves"))
		{
			return 130_000;
		}
		return name.startsWith("eclipse moon") || name.startsWith("blood moon")
			|| name.equals("eclipse atlatl") || name.equals("berserker ring (i)")
			|| name.equals("primordial boots") || name.equals("amulet of fury") ? 1_000_000 : 1_000;
	}

	private static OptimizerSettings settings()
	{
		return OptimizerSettings.builder().mode(SearchMode.OWNED_ONLY).depth(SearchDepth.BEST)
			.styles(Collections.singleton(AttackStyle.Type.ATLATL)).spellbooks(Collections.emptySet())
			.wildernessRiskLimited(true).maxExpensiveItems(4).expensiveItemThreshold(100_000).build();
	}

	@Test
	public void mixedEquipmentBeatsTheEclipseSetWithinFourExpensiveItems()
	{
		Optimizer optimizer = new Optimizer(data, context, settings(), OWNED::contains, ChaosDwarfOptimizerTest::price);
		SetupResult result = optimizer.optimize(CombatClass.RANGED, () -> false).get(0);
		assertEquals(5.542224536007131, result.getDps().getDps(), 1e-9);
		assertEquals(22, result.getDps().getMaxHit());
		assertEquals(0.9033389604375305, result.getDps().getAccuracy(), 1e-8);
		assertEquals(10828, result.getLoadout().get(Slot.HEAD).getId());
		assertEquals(29280, result.getLoadout().get(Slot.BODY).getId());
		assertEquals(2497, result.getLoadout().get(Slot.LEGS).getId());
		assertEquals(11773, result.getLoadout().get(Slot.RING).getId());
		assertEquals(4, optimizer.expensiveItemCount(result.getLoadout()));
		assertEquals(0, result.getBuyCost());
	}

	/** Owned melee gear with fixed acquisition values; repair fees come from the normal cost rules. */
	private static final Map<Integer, Long> CRUSH_BANK = new HashMap<>();

	static
	{
		long[][] bank = {
			{10828, 43_682}, {22114, 0}, {1704, 12_103}, {1725, 734}, {28997, 5_178_308}, {29280, 17_253},
			{29283, 26_090}, {29286, 16_306}, {8850, 0}, {12954, 0}, {7462, 130_000}, {13239, 18_895_384},
			{11773, 3_259_456}, {776, 0}, {3105, 754}, {29047, 926_239}, {29043, 3_786_296}, {29045, 8_700_432},
			{28810, 1_628_575}, {1434, 29_900}, {1495, 0}, {6570, 0},
		};
		for (long[] entry : bank)
		{
			CRUSH_BANK.put((int) entry[0], entry[1]);
		}
	}

	private static CombatContext crushContext()
	{
		return context.withModifiers(CombatModifiers.builder().wilderness(true).markOfDarkness(true).miningLevel(70).build());
	}

	private static OptimizerSettings crushSettings()
	{
		return settings().toBuilder().styles(Collections.singleton(AttackStyle.Type.CRUSH)).build();
	}

	/**
	 * With the owned degraded Blood Moon set, the Strength amulet and the aggressive stance are each worse alone
	 * than the Glory on accurate, but better together; the search must change them together.
	 */
	@Test
	public void stanceAndNecklaceChangeTogether()
	{
		Optimizer optimizer = new Optimizer(data, crushContext(), crushSettings(), CRUSH_BANK::containsKey,
			item -> CRUSH_BANK.getOrDefault(item.getId(), 1_000L));
		SetupResult result = optimizer.optimize(CombatClass.MELEE, () -> false).get(0);
		Loadout l = result.getLoadout();
		assertEquals(28997, l.getWeapon().getId());
		assertEquals(1725, l.get(Slot.NECK).getId());
		assertEquals("aggressive", l.getStyle().getStance());
		assertEquals(5.365411110567, result.getDps().getDps(), 1e-9);
		for (Slot slot : Slot.values())
		{
			assertTrue(l.get(slot) == null || CRUSH_BANK.containsKey(l.get(slot).getId()));
		}
		assertEquals(0, result.getBuyCost());
		assertEquals(4, optimizer.expensiveItemCount(l));

		// The trap itself: every single change from accurate + Glory loses DPS.
		double both = DpsCalculator.calculate(l, crushContext()).getDps();
		Loadout glory = l.copy();
		glory.set(Slot.NECK, data.getItem(Slot.NECK, 1704));
		Loadout accurate = l.copy();
		Loadout trapped = glory.copy();
		for (String raw : l.getWeapon().getStyles())
		{
			AttackStyle style = AttackStyle.parse(raw);
			if (style.getType() == AttackStyle.Type.CRUSH && style.getStance().equals("accurate"))
			{
				accurate.setStyle(style);
				trapped.setStyle(style);
			}
		}
		double trap = DpsCalculator.calculate(trapped, crushContext()).getDps();
		assertTrue(DpsCalculator.calculate(glory, crushContext()).getDps() < trap);
		assertTrue(DpsCalculator.calculate(accurate, crushContext()).getDps() < trap);
		assertTrue(both > trap);
	}

	@Test
	public void damageSeedHonoursLockedSlotsAndZeroPurchaseBudget()
	{
		Map<Slot, SlotLock> locks = new EnumMap<>(Slot.class);
		locks.put(Slot.HEAD, SlotLock.item(29035));
		locks.put(Slot.CAPE, SlotLock.item(22114));
		OptimizerSettings locked = settings().toBuilder().mode(SearchMode.BUDGET).budget(0)
			.locks(locks).build();
		Optimizer optimizer = new Optimizer(data, context, locked, OWNED::contains, ChaosDwarfOptimizerTest::price);
		SetupResult result = optimizer.optimize(CombatClass.RANGED, () -> false).get(0);
		assertEquals(29035, result.getLoadout().get(Slot.HEAD).getId());
		assertEquals(22114, result.getLoadout().get(Slot.CAPE).getId());
		assertEquals(0, result.getBuyCost());
		assertTrue(optimizer.expensiveItemCount(result.getLoadout()) <= 4);
	}
}

package com.bestgearsetup.calc;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.GameData;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.MonsterSummary;
import com.bestgearsetup.data.Slot;
import com.bestgearsetup.data.Spell;
import com.bestgearsetup.data.WikiGameData;
import com.bestgearsetup.data.WikiMonsters;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.function.ToLongFunction;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.BeforeClass;
import org.junit.Test;

/** Sweeps over the bundled Wiki catalogue; these supplement, rather than replace, exact mechanic vectors. */
public class CombatCatalogTest
{
	private static final Gson GSON = RuneLiteAPI.GSON;
	/** Offline stand-in for live prices: every tradeable item costs 1m. */
	private static final ToLongFunction<GearItem> PRICE = item -> item.isTradeable() ? 1_000_000L : 0;
	private static GameData data;
	private static WikiMonsters monsters;

	@BeforeClass
	public static void loadSnapshot() throws Exception
	{
		data = WikiGameData.get(GSON).gameData(GSON);
		monsters = WikiMonsters.get(GSON);
	}

	private static Monster target(int npcId)
	{
		MonsterSummary summary = data.matchNpc(npcId, null, 0);
		assertNotNull("Missing bundled monster " + npcId, summary);
		return monsters.monster(summary.getName());
	}

	private static GearItem weapon(String name)
	{
		for (GearItem w : data.getItems(Slot.WEAPON))
		{
			if (w.getName().equals(name))
			{
				return w;
			}
		}
		throw new AssertionError("Missing bundled weapon " + name);
	}

	private static void sane(DpsResult result)
	{
		assertTrue(Double.isFinite(result.getDps()));
		assertTrue(Double.isFinite(result.getAverageHit()));
		assertTrue(result.getDps() >= 0);
		assertTrue(result.getAverageHit() >= 0);
		assertTrue(result.getMaxHit() >= 0);
		assertTrue(result.getAccuracy() >= 0 && result.getAccuracy() <= 1);
		assertTrue(result.getAverageHit() <= result.getMaxHit() + 1e-8);
	}

	private static Loadout loadout(GearItem weapon, AttackStyle style)
	{
		Loadout l = new Loadout();
		l.set(Slot.WEAPON, weapon);
		l.setStyle(style);
		for (int id : weapon.getAmmunition())
		{
			GearItem ammo = data.getItem(Slot.AMMO, id);
			if (ammo != null)
			{
				if (WeaponRules.loadsAmmo(weapon))
				{
					l.setLoadedAmmo(ammo);
				}
				else
				{
					l.set(Slot.AMMO, ammo);
				}
				break;
			}
		}
		if (style.isAutocast() && !weapon.getSubcategory().equals("salamander"))
		{
			for (Spell spell : data.getSpells())
			{
				if (spell.getMaxHit() > 0 && spell.castableWith(weapon.getId()))
				{
					l.setSpell(spell);
					break;
				}
			}
		}
		return l;
	}

	private static OptimizerSettings budget(long gp, int results)
	{
		return OptimizerSettings.builder().mode(SearchMode.BUDGET).budget(gp)
			.depth(SearchDepth.FAST).resultsPerClass(results)
			.spellbooks(new HashSet<>(Arrays.asList("standard", "ancient", "arceuus"))).build();
	}

	@Test
	public void everyWeaponStyleScoresAcrossRepresentativeTargets()
	{
		List<GearItem> weapons = data.getItems(Slot.WEAPON);
		assertTrue(weapons.size() > 600);
		int calculations = 0;
		for (GearItem weapon : weapons)
		{
			for (String raw : weapon.getStyles())
			{
				AttackStyle style = AttackStyle.parse(raw);
				if (style == null)
				{
					// Only the bulwark's block stance has no attack.
					assertTrue(raw, raw.startsWith("block,"));
					continue;
				}
				Loadout l = loadout(weapon, style);
				for (int id : new int[]{13011, 13012, 13013, 11753, 11755, 7223, 7550, 7584, 12223})
				{
					CombatContext ctx = new CombatContext(target(id), PlayerLevels.maxed(), false, false, null);
					sane(DpsCalculator.calculate(l, ctx));
					calculations++;
				}
			}
		}
		assertTrue(calculations > 15_000);
	}

	@Test
	public void everyMonsterVariantProducesFiniteBoundedResults()
	{
		List<MonsterSummary> all = data.getMonsters();
		assertTrue(all.size() > 3000);
		GearItem[] weapons = {weapon("abyssal whip"), weapon("rune crossbow"), weapon("trident of the seas"),
			weapon("magic shortbow"), weapon("osmumten's fang")};
		for (MonsterSummary summary : all)
		{
			Monster monster = monsters.monster(summary.getName());
			assertNotNull(summary.getName(), monster);
			CombatContext ctx = new CombatContext(monster, PlayerLevels.maxed(), false, false, null);
			for (GearItem weapon : weapons)
			{
				AttackStyle style = AttackStyle.parse(weapon.getStyles().get(0));
				sane(DpsCalculator.calculate(loadout(weapon, style), ctx));
			}
		}
	}

	@Test
	public void budgetSearchesRespectBudgetAndActivityAccess()
	{
		for (int id : new int[]{13011, 11753, 7223})
		{
			Monster monster = target(id);
			CombatContext ctx = new CombatContext(monster, PlayerLevels.maxed(), false, true, null);
			for (CombatClass cls : CombatClass.values())
			{
				List<SetupResult> results = new Optimizer(data, ctx, budget(20_000_000, 1), itemId -> false, PRICE)
					.optimize(cls, () -> false);
				for (SetupResult result : results)
				{
					sane(result.getDps());
					assertTrue(result.getBuyCost() <= 20_000_000);
					for (Slot slot : Slot.values())
					{
						GearItem item = result.getLoadout().get(slot);
						if (item != null)
						{
							assertTrue(CombatRules.equipmentAllowed(monster, item));
							assertFalse(item.isDmmEquipment());
							assertFalse(item.isBetaEquipment());
							assertFalse(item.isBountyHunterEquipment());
						}
					}
				}
			}
		}
	}

	@Test
	public void healthDependentAndRaidScaledSearchesStaySane()
	{
		Monster vardorvis = target(12223);
		Monster akkha = RaidScaling.apply(target(11789),
			RaidScaling.Settings.builder().partySize(3).toaRaidLevel(300).toaPathLevel(2).build());
		assertTrue(akkha.getHitpoints() > 400);
		for (Monster monster : new Monster[]{vardorvis, akkha})
		{
			CombatContext ctx = new CombatContext(monster, PlayerLevels.maxed(), false, true, null)
				.withHealthStates(hp -> MonsterStates.atHealth(monster, hp));
			for (CombatClass cls : CombatClass.values())
			{
				for (SetupResult result : new Optimizer(data, ctx, budget(50_000_000, 1), itemId -> false, PRICE)
					.optimize(cls, () -> false))
				{
					sane(result.getDps());
					assertTrue(result.getBuyCost() <= 50_000_000);
				}
			}
		}
	}

	@Test
	public void specialAttackModeIsSaneForEveryWeaponAndSearchesOnlySpecWeapons()
	{
		CombatModifiers spec = CombatModifiers.builder().specialAttack(true).soulreaperStacks(5).build();
		java.util.Set<String> scored = new java.util.TreeSet<>();
		for (GearItem weapon : data.getItems(Slot.WEAPON))
		{
			for (String raw : weapon.getStyles())
			{
				AttackStyle style = AttackStyle.parse(raw);
				if (style == null)
				{
					continue;
				}
				Loadout l = loadout(weapon, style);
				for (int id : new int[]{13011, 11753, 7584, 12223, 7550})
				{
					CombatContext ctx = new CombatContext(target(id), PlayerLevels.maxed(), false, true, null)
						.withModifiers(spec);
					DpsResult r = DpsCalculator.calculate(l, ctx);
					sane(r);
					if (r.getDps() > 0)
					{
						scored.add(weapon.getName());
					}
				}
			}
		}
		assertTrue(scored.contains("dragon claws"));
		assertTrue(scored.contains("armadyl godsword"));
		assertTrue(scored.contains("dark bow"));
		assertFalse(scored.contains("scythe of vitur"));

		CombatContext ctx = new CombatContext(target(12223), PlayerLevels.maxed(), false, true, null).withModifiers(spec);
		for (CombatClass cls : CombatClass.values())
		{
			for (SetupResult result : new Optimizer(data, ctx, budget(200_000_000, 3), itemId -> false, PRICE)
				.optimize(cls, () -> false))
			{
				sane(result.getDps());
				assertNotNull(result.getLoadout().getWeapon().getName(), SpecialAttack.of(result.getLoadout(), ctx));
			}
		}
	}

	@Test
	public void damageOverTimeSearchesStaySane()
	{
		CombatModifiers poison = CombatModifiers.builder().weaponPoison(WeaponPoison.POISON_PLUS_PLUS).build();
		for (int id : new int[]{415, 2267, 12223})
		{
			CombatContext ctx = new CombatContext(target(id), PlayerLevels.maxed(), false, true, null).withModifiers(poison);
			for (CombatClass cls : CombatClass.values())
			{
				for (SetupResult result : new Optimizer(data, ctx, budget(100_000_000, 1), itemId -> false, PRICE)
					.optimize(cls, () -> false))
				{
					sane(result.getDps());
				}
			}
		}
	}
}

package com.bestgearsetup.calc;

import static com.bestgearsetup.calc.TestData.item;
import static com.bestgearsetup.calc.TestData.monster;
import static com.bestgearsetup.calc.TestData.weapon;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.Slot;
import com.bestgearsetup.data.Spell;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.Test;

/** Boundary cases that must survive changes to modifier order and catalog identity. */
public class CombatEdgeCasesTest
{
	private static final double EPS = 1e-10;

	private static Loadout loadout(String name, String category, String style)
	{
		GearItem w = weapon(50000, name, category, 5, style);
		w.setMeleeStr(100);
		w.setRangedStr(100);
		w.setStabBonus(100);
		w.setSlashBonus(100);
		w.setCrushBonus(100);
		w.setRangedBonus(100);
		w.setMagicBonus(100);
		Loadout l = new Loadout();
		l.set(Slot.WEAPON, w);
		l.setStyle(AttackStyle.parse(style));
		return l;
	}

	private static CombatContext context(Monster m)
	{
		return new CombatContext(m, PlayerLevels.maxed(), false, false, null);
	}

	private static Loadout crossbow(String ammo)
	{
		Loadout l = loadout("rune crossbow", "crossbow", "rapid,ranged,rapid");
		l.set(Slot.AMMO, item(50001, ammo, Slot.AMMO));
		return l;
	}

	private static double ordinary(int max)
	{
		return max / 2.0 + 1.0 / (max + 1);
	}

	@Test
	public void diamondProcsOnMissesAndDiaryScalesProcProbability()
	{
		Loadout l = crossbow("diamond bolts (e)");
		CombatContext ctx = context(monster(100, 50));
		EnchantedBolts.Result result = EnchantedBolts.calculate(l, ctx, EncounterDamage.unmitigated(), 0.25, 0, 20);
		assertEquals(0.9 * 0.25 * ordinary(20) + 0.1 * ordinary(23), result.getAverage(), EPS);
		assertEquals(0.325, result.getAccuracy(), EPS);
		assertEquals(23, result.getMaximum());
		ctx = ctx.withModifiers(CombatModifiers.builder().kandarinDiary(true).build());
		result = EnchantedBolts.calculate(l, ctx, EncounterDamage.unmitigated(), 0.25, 0, 20);
		assertEquals(0.89 * 0.25 * ordinary(20) + 0.11 * ordinary(23), result.getAverage(), EPS);
	}

	@Test
	public void opalAddsDamageEvenOnMissesWithoutTurningMissesAccurate()
	{
		Loadout l = crossbow("opal bolts (e)");
		EnchantedBolts.Result result = EnchantedBolts.calculate(l, context(monster(100, 50)),
			EncounterDamage.unmitigated(), 0.25, 0, 20);
		assertEquals(0.95 * 0.25 * ordinary(20) + 0.05 * (0.25 * 19 + 0.75 * 9), result.getAverage(), EPS);
		assertEquals(0.25, result.getAccuracy(), EPS);
		assertEquals(29, result.getMaximum());
	}

	@Test
	public void opalRetainsBoundedWardenDamageRolls()
	{
		EnchantedBolts.Result result = EnchantedBolts.calculate(crossbow("opal bolts (e)"), context(monster(100, 50)),
			EncounterDamage.unmitigated(), 1, 6, 11);
		assertEquals(0.95 * 8.5 + 0.05 * 17.5, result.getAverage(), EPS);
	}

	@Test
	public void rubyUsesHealthSnapshotAndRequiresAtLeastTenPlayerHp()
	{
		Monster m = monster(100, 50);
		m.setHitpoints(1000);
		Loadout l = crossbow("ruby bolts (e)");
		CombatContext ctx = context(m);
		EnchantedBolts.Result result = EnchantedBolts.calculate(l, ctx, EncounterDamage.unmitigated(), 0, 0, 20);
		assertEquals(6, result.getAverage(), EPS);
		assertEquals(0.06, result.getAccuracy(), EPS);
		assertEquals(100, result.getMaximum());
		ctx = ctx.withModifiers(CombatModifiers.builder().monsterHitpoints(100).currentHitpoints(10).build());
		result = EnchantedBolts.calculate(l, ctx, EncounterDamage.unmitigated(), 0, 0, 20);
