		target.setId(7550);
		DpsResult reduced = calculate(scythe, "reap,slash,aggressive", target, false);
		int maximum = 0;
		double mean = 0;
		for (String component : base.getMaxHitDetail().split(" \\+ "))
		{
			int raw = Integer.parseInt(component);
			maximum += raw / 3;
			int sum = 0;
			for (int hit = 0; hit <= raw; hit++)
