		int minimum = Integer.parseInt(base.getMaxHitDetail().split("-")[0]);
		int sum = 0;
		for (int hit = minimum; hit <= base.getMaxHit(); hit++)
		{
			sum += hit / 3;
		}
		target.setId(7550);
		DpsResult reduced = calculate(fang, "stab,stab,aggressive", target, false);
