		Loadout pickaxe = loadout("dragon pickaxe", "pickaxe", "smash,crush,aggressive");
		assertFalse(EncounterImmunities.attackAllowed(guardian, sword));
		assertTrue(EncounterImmunities.attackAllowed(guardian, pickaxe));
		assertEquals(0, calculate(sword.getWeapon(), "lash,slash,aggressive", guardian, true).getDps(), 0);
		OptimizerSettings settings = OptimizerSettings.builder().mode(SearchMode.UNLIMITED)
			.locks(Collections.singletonMap(Slot.WEAPON, SlotLock.item(sword.getWeapon().getId()))).build();
		assertTrue(new Optimizer(TestData.gameData(Arrays.asList(sword.getWeapon()), Collections.emptyList()),
			new CombatContext(guardian, PlayerLevels.maxed(), false, true, piety()), settings, id -> true,
			GearItem::getPrice).optimize(CombatClass.MELEE, () -> false).isEmpty());
		Monster leafy = monster(100, 20, "leafy");
		assertFalse(EncounterImmunities.attackAllowed(leafy, sword));
		assertTrue(EncounterImmunities.attackAllowed(leafy, loadout("leaf-bladed sword", "stab sword", "stab,stab,accurate")));
		Loadout crossbow = loadout("rune crossbow", "crossbow", "rapid,ranged,rapid");
		crossbow.getWeapon().setAmmunition(Collections.singletonList(13280));
		crossbow.set(Slot.AMMO, item(13280, "amethyst broad bolts", Slot.AMMO));
		assertTrue(EncounterImmunities.attackAllowed(leafy, crossbow));
		Loadout trident = loadout("trident of the seas", "powered staff", "accurate,magic,accurate");
		trident.set(Slot.AMMO, item(13280, "amethyst broad bolts", Slot.AMMO));
		assertFalse(EncounterImmunities.attackAllowed(leafy, trident));
		assertFalse(Optimizer.classAllowed(monster(100, 20, "magic only", "magic immune"), CombatClass.MAGIC));
	}

	@Test
	public void tierTwoAndThreeVampyresHaveDifferentWeaponRequirementsAndCaps()
	{
		Monster tierTwo = monster(100, 20, "vampyre (t2)");
		Loadout sword = loadout("abyssal whip", "whip", "lash,slash,aggressive");
		assertFalse(EncounterImmunities.attackAllowed(tierTwo, sword));
		sword.set(Slot.RING, item(21140, "efaritay's aid", Slot.RING));
		assertTrue(EncounterImmunities.attackAllowed(tierTwo, sword));
		assertEquals(15, EncounterDamage.rule(tierTwo, sword).maximum(30));
		Loadout silver = loadout("silverlight", "slash sword", "chop,slash,aggressive");
		assertTrue(EncounterImmunities.attackAllowed(tierTwo, silver));
		assertEquals(10, EncounterDamage.rule(tierTwo, silver).maximum(30));
		assertEquals(5, EncounterDamage.rule(tierTwo, silver).maximum(5));
		Monster tierThree = monster(100, 20, "vampyre (t3)");
		assertFalse(EncounterImmunities.attackAllowed(tierThree, sword));
		assertFalse(EncounterImmunities.attackAllowed(tierThree, silver));
		assertTrue(EncounterImmunities.attackAllowed(tierThree, loadout("blisterwood flail", "flail", "reap,crush,aggressive")));
	}

	@Test
	public void immunityTagsExcludeMagicRatherThanTreatingDefenceAsImmunity()
	{
		assertFalse(Optimizer.classAllowed(monster(1, 0, "magic immune"), CombatClass.MAGIC));
		assertTrue(Optimizer.classAllowed(monster(999, 999), CombatClass.MAGIC));
		assertTrue(Optimizer.classAllowed(monster(1, 0, "magic immune"), CombatClass.MELEE));
	}
}

package com.bestgearsetup.calc;

import static com.bestgearsetup.calc.TestData.monster;
import static com.bestgearsetup.calc.TestData.weapon;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.data.EncounterPhase;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.Slot;
import org.junit.Test;

/** Temporary boss states from the Wiki calculator that have no separate monster variant. */
public class EncounterPhaseTest
{
	private static final double EPS = 1e-10;

	private static Loadout loadout(String name, String subcategory, String style)
	{
		GearItem w = weapon(50000, name, subcategory, 4, style);
		w.setStabBonus(100);
		w.setSlashBonus(100);
		w.setCrushBonus(100);
		w.setRangedBonus(100);
		w.setMeleeStr(80);
		w.setRangedStr(80);
		Loadout l = new Loadout();
		l.set(Slot.WEAPON, w);
		l.setStyle(AttackStyle.parse(style));
		return l;
	}

	private static Monster target(int id, String name, EncounterPhase phase, String... attributes)
	{
		Monster m = monster(100, 50, attributes);
		m.setId(id);
		m.setName(name);
		m.setHitpoints(1000);
		m.setPhase(phase);
		return m;
	}

	private static DpsResult calculate(Loadout l, Monster m)
	{
		return DpsCalculator.calculate(l, new CombatContext(m, PlayerLevels.maxed(), false, false, null));
	}

	@Test
	public void hueycoatlPillarMultipliesEachCappedTailOutcome()
	{
		Loadout crush = loadout("test maul", "blunt", "pound,crush,aggressive");
		crush.getWeapon().setCrushBonus(101);
		Monster tail = target(14014, "the hueycoatl (tail)", EncounterPhase.HUEYCOATL_PILLAR, "dragon");
		EncounterDamage.Rule rule = EncounterDamage.rule(tail, crush);
		// Caps 0-9 give max(1, trunc(cap * 1.3)): 1,1,2,3,5,6,7,9,10,11.
		assertEquals(5.5, rule.mean(20), EPS);
		assertEquals(11, rule.maximum(20));
		assertEquals(1, rule.missDamage(), EPS);
		tail.setPhase(EncounterPhase.STANDARD);
		assertEquals(4.6, EncounterDamage.rule(tail, crush).mean(20), EPS);
	}

	@Test
	public void hueycoatlPillarAppliesToTheHeadButNotTheBody()
	{
		Loadout slash = loadout("test sword", "slash sword", "slash,slash,aggressive");
		Monster head = target(14009, "the hueycoatl (head)", EncounterPhase.HUEYCOATL_PILLAR, "dragon");
		assertEquals(13, EncounterDamage.rule(head, slash).mean(10), EPS);
		Monster body = target(14017, "the hueycoatl", EncounterPhase.HUEYCOATL_PILLAR, "dragon");
		assertEquals(10, EncounterDamage.rule(body, slash).mean(10), EPS);
		assertTrue(EncounterPhases.describe(body).contains("ignored"));
	}

	@Test
	public void sireTransitionHalvesEachHit()
	{
		Loadout slash = loadout("test sword", "slash sword", "slash,slash,aggressive");
		Monster sire = target(5886, "abyssal sire (phase 1)", EncounterPhase.ABYSSAL_SIRE_TRANSITION, "demon");
		assertEquals(5, EncounterDamage.rule(sire, slash).mean(11), EPS);
		DpsResult halved = calculate(slash, sire);
		sire.setPhase(EncounterPhase.STANDARD);
		DpsResult normal = calculate(slash, sire);
		assertTrue(halved.getAverageHit() < normal.getAverageHit() * 0.55);
	}

	@Test
	public void royalTitansOutOfMeleeMultiplyOnlyTheRangedAttackRoll()
	{
		Loadout bow = loadout("test bow", "bow", "rapid,ranged,rapid");
		Monster titan = target(12596, "branda the fire queen", EncounterPhase.ROYAL_TITANS_OUT_OF_MELEE, "fiery");
		long attack = 107L * 164;
		long defence = 109L * 114;
		assertEquals(HitChance.single(attack * 6, defence), calculate(bow, titan).getAccuracy(), EPS);
		titan.setPhase(EncounterPhase.STANDARD);
		assertEquals(HitChance.single(attack, defence), calculate(bow, titan).getAccuracy(), EPS);
		Loadout sword = loadout("test sword", "slash sword", "slash,slash,accurate");
		titan.setPhase(EncounterPhase.ROYAL_TITANS_OUT_OF_MELEE);
		assertEquals(HitChance.single(110L * 164, defence), calculate(sword, titan).getAccuracy(), EPS);
	}

	@Test
	public void titanElementalMagicAccuracyComesFromTheMagicBonus()
	{
		Monster elemental = target(14150, "fire elemental (royal titans)", EncounterPhase.STANDARD);
		GearItem staff = weapon(11907, "trident of the seas", "powered staff", 4, "accurate,magic,accurate");
		staff.setMagicBonus(20);
		Loadout l = new Loadout();
		l.set(Slot.WEAPON, staff);
		l.setStyle(AttackStyle.parse("accurate,magic,accurate"));
		DpsResult r = calculate(l, elemental);
		assertEquals(0.5, r.getAccuracy(), EPS);
		assertEquals(r.getMaxHit() * 0.5, r.getAverageHit(), EPS);
		staff.setMagicBonus(90);
		assertEquals(1.0, calculate(l, elemental).getAccuracy(), EPS);
	}

	@Test
	public void mokhaiotlShieldAllowsOnlyDemonbaneAndEveryNonNormalStateHits()
	{
		Monster doom = target(14707, "doom of mokhaiotl", EncounterPhase.MOKHAIOTL_SHIELDED, "demon");
		Loadout whip = loadout("abyssal whip", "whip", "lash,slash,controlled");
		Loadout arclight = loadout("arclight", "slash sword", "slash,slash,aggressive");
		assertFalse(EncounterImmunities.attackAllowed(doom, whip));
		assertEquals(0, calculate(whip, doom).getDps(), EPS);
		assertTrue(EncounterImmunities.attackAllowed(doom, arclight));
		assertEquals(1.0, calculate(arclight, doom).getAccuracy(), EPS);
		doom.setPhase(EncounterPhase.MOKHAIOTL_BURROWING);
		assertEquals(1.0, calculate(whip, doom).getAccuracy(), EPS);
		doom.setPhase(EncounterPhase.STANDARD);
		assertTrue(calculate(whip, doom).getAccuracy() < 1.0);
		assertNull(EncounterPhases.describe(doom));
	}

	@Test
	public void guaranteedAccuracyVariantsAlwaysHit()
	{
		Monster variant = target(14708, "doom of mokhaiotl (100% accuracy)", EncounterPhase.STANDARD, "demon");
		assertEquals(1.0, calculate(loadout("abyssal whip", "whip", "lash,slash,controlled"), variant).getAccuracy(), EPS);
	}

	@Test
	public void phasesNeverChangeOtherTargets()
	{
		Monster ordinary = target(1, "test monster", EncounterPhase.MOKHAIOTL_SHIELDED);
		Loadout whip = loadout("abyssal whip", "whip", "lash,slash,controlled");
		assertTrue(EncounterImmunities.attackAllowed(ordinary, whip));
		assertTrue(calculate(whip, ordinary).getAccuracy() < 1.0);
		for (EncounterPhase phase : EncounterPhase.values())
		{
			assertFalse(phase.name(), phase != EncounterPhase.STANDARD && EncounterPhases.applies(ordinary, phase));
		}
	}
}

package com.bestgearsetup.calc;

import static com.bestgearsetup.calc.TestData.item;
import static com.bestgearsetup.calc.TestData.monster;
import static com.bestgearsetup.calc.TestData.piety;
import static com.bestgearsetup.calc.TestData.weapon;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.OwnershipRules;
import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.EquipmentRequirements;
import com.bestgearsetup.data.GameData;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Slot;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.BeforeClass;
import org.junit.Test;

public class EquipmentFiltersTest
{
	/** Main code gets the client's Gson in startUp; tests use the same instance. */
	@BeforeClass
	public static void ownershipRules()
	{
		OwnershipRules.init(RuneLiteAPI.GSON);
	}

	private final GearItem sword = weapon(4151, "sword", "slash sword", 4, "slash,slash,aggressive");

	public EquipmentFiltersTest()
	{
		sword.setSlashBonus(80);
		sword.setMeleeStr(80);
	}

	private List<SetupResult> run(OptimizerSettings.OptimizerSettingsBuilder builder, GearItem... gear)
	{
		GameData data = TestData.gameData(Arrays.asList(gear), Collections.emptyList());
		CombatContext ctx = new CombatContext(monster(100, 20), PlayerLevels.maxed(), false, true, piety());
		OptimizerSettings settings = builder.mode(SearchMode.UNLIMITED)
			.spellbooks(Collections.singleton("standard")).resultsPerClass(1).build();
		// Even owned equipment must obey category filters.
		return new Optimizer(data, ctx, settings, id -> true, GearItem::getPrice)
			.optimize(CombatClass.MELEE, () -> false);
	}

	@Test
	public void bountyHunterIsExcludedByDefaultAndCanBeEnabled()
	{
		GearItem bh = weapon(24617, "vesta's blighted longsword", "slash sword", 4, "slash,slash,aggressive");
		bh.setSlashBonus(150);
		bh.setMeleeStr(150);
		assertEquals(sword, run(OptimizerSettings.builder(), sword, bh).get(0).getLoadout().getWeapon());
		assertEquals(bh, run(OptimizerSettings.builder().bountyHunterItems(true), sword, bh)
			.get(0).getLoadout().getWeapon());
	}

	@Test
	public void dmmBetaAndMembersFiltersAreIndependent()
	{
		GearItem dmm = item(22616, "vesta's chainbody (dmm)", Slot.BODY);
		GearItem beta = item(99901, "test helm (beta)", Slot.HEAD);
		GearItem members = item(6737, "berserker ring", Slot.RING);
		dmm.setMeleeStr(10);
		beta.setMeleeStr(10);
		members.setMeleeStr(10);
		members.setMembers(true);
		SetupResult defaults = run(OptimizerSettings.builder(), sword, dmm, beta, members).get(0);
		assertNull(defaults.getLoadout().get(Slot.BODY));
		assertNull(defaults.getLoadout().get(Slot.HEAD));
		assertEquals(members, defaults.getLoadout().get(Slot.RING));
		SetupResult enabled = run(OptimizerSettings.builder().dmmItems(true).betaItems(true).membersItems(false),
			sword, dmm, beta, members).get(0);
		assertEquals(dmm, enabled.getLoadout().get(Slot.BODY));
		assertEquals(beta, enabled.getLoadout().get(Slot.HEAD));
		assertNull(enabled.getLoadout().get(Slot.RING));
	}

	@Test
	public void disabledCategoryCannotBypassFiltersThroughWeaponLock()
	{
		GearItem bh = weapon(24617, "vesta's blighted longsword", "slash sword", 4, "slash,slash,aggressive");
		Map<Slot, SlotLock> locks = Collections.singletonMap(Slot.WEAPON, SlotLock.item(bh.getId()));
		assertTrue(run(OptimizerSettings.builder().locks(locks), sword, bh).isEmpty());
		assertEquals(bh, run(OptimizerSettings.builder().bountyHunterItems(true).locks(locks), sword, bh)
			.get(0).getLoadout().getWeapon());
	}

	@Test
	public void disabledCategoryCannotBypassFiltersThroughArmourLock()
	{
		GearItem dmm = item(22616, "vesta's chainbody (dmm)", Slot.BODY);
		dmm.setMeleeStr(10);
		Map<Slot, SlotLock> locks = new EnumMap<>(Slot.class);
		locks.put(Slot.BODY, SlotLock.item(dmm.getId()));
		assertNull(run(OptimizerSettings.builder().locks(locks), sword, dmm).get(0).getLoadout().get(Slot.BODY));
		assertEquals(dmm, run(OptimizerSettings.builder().dmmItems(true).locks(locks), sword, dmm)
			.get(0).getLoadout().get(Slot.BODY));
	}

	@Test
	public void ownedAndLockedBlackMaskCannotBypassBaseCombatLevel()
	{
		GearItem mask = item(8921, "black mask", Slot.HEAD);
		mask.setMeleeStr(50);
		// As in the bundled snapshot: 10 Defence, 20 Strength and 40 combat.
		EquipmentRequirements.get().applyReviewed(mask);
		GameData data = TestData.gameData(Arrays.asList(sword, mask), Collections.emptyList());
		PlayerLevels levels = new PlayerLevels(1, 20, 10, 1, 1, 1, 10, 1);
		// Large boosts may change damage, but must not grant permission to equip the mask.
		CombatContext ctx = new CombatContext(monster(1, 0), levels, false, 99, 99, 99, 99, piety(), false);
		OptimizerSettings settings = OptimizerSettings.builder().mode(SearchMode.UNLIMITED)
			.build();
		List<SetupResult> results = new Optimizer(data, ctx, settings, id -> true, GearItem::getPrice)
			.optimize(CombatClass.MELEE, () -> false);
		assertFalse(results.isEmpty());
		assertNull(results.get(0).getLoadout().get(Slot.HEAD));
		OptimizerSettings locked = settings.toBuilder()
			.locks(Collections.singletonMap(Slot.HEAD, SlotLock.item(mask.getId()))).build();
		List<SetupResult> lockedResults = new Optimizer(data, ctx, locked, id -> true, GearItem::getPrice)
			.optimize(CombatClass.MELEE, () -> false);
		assertFalse(lockedResults.isEmpty());
		assertNull(lockedResults.get(0).getLoadout().get(Slot.HEAD));
	}

	@Test
	public void weaponLockCannotBypassWearOwnershipOrUntradeableRules()
	{
		sword.setAttackReq(70);
		sword.setPrice(1000);
		GameData data = TestData.gameData(Collections.singletonList(sword), Collections.emptyList());
		OptimizerSettings settings = OptimizerSettings.builder().mode(SearchMode.OWNED_ONLY)
			.locks(Collections.singletonMap(Slot.WEAPON, SlotLock.item(sword.getId()))).build();
		PlayerLevels low = new PlayerLevels(1, 99, 99, 99, 99, 99, 99, 99);
		CombatContext lowContext = new CombatContext(monster(100, 20), low, false, true, piety());
		CombatContext maxed = new CombatContext(monster(100, 20), PlayerLevels.maxed(), false, true, piety());
		assertTrue(new Optimizer(data, lowContext, settings, id -> true, GearItem::getPrice)
			.optimize(CombatClass.MELEE, () -> false).isEmpty());
		assertTrue(new Optimizer(data, maxed, settings, id -> false, GearItem::getPrice)
			.optimize(CombatClass.MELEE, () -> false).isEmpty());
		assertEquals(sword, new Optimizer(data, maxed, settings, id -> true, GearItem::getPrice)
			.optimize(CombatClass.MELEE, () -> false).get(0).getLoadout().getWeapon());
		assertTrue(new Optimizer(data, maxed, settings.toBuilder().mode(SearchMode.BUDGET).budget(999).build(),
			id -> false, GearItem::getPrice).optimize(CombatClass.MELEE, () -> false).isEmpty());
		sword.setTradeable(false);
		assertTrue(new Optimizer(data, maxed, settings.toBuilder().mode(SearchMode.BUDGET).budget(Long.MAX_VALUE).build(),
			id -> false, GearItem::getPrice).optimize(CombatClass.MELEE, () -> false).isEmpty());
		// Best in slot has no limit: an unowned untradeable is still used.
		assertEquals(sword, new Optimizer(data, maxed, settings.toBuilder().mode(SearchMode.UNLIMITED).build(),
			id -> false, GearItem::getPrice).optimize(CombatClass.MELEE, () -> false).get(0).getLoadout().getWeapon());
	}

	@Test
	public void ammunitionLockCannotBypassWearOwnershipOrUntradeableRules()
	{
		GearItem bow = weapon(600, "bow", "bow", 5, "rapid,ranged,rapid");
		bow.setRangedBonus(60);
		bow.setAmmunition(Collections.singletonList(700));
		GearItem arrow = item(700, "arrow", Slot.AMMO);
		arrow.setRangedStr(60);
		arrow.setRangedReq(90);
		arrow.setPrice(1000);
		GameData data = TestData.gameData(Arrays.asList(bow, arrow), Collections.emptyList());
		OptimizerSettings settings = OptimizerSettings.builder().mode(SearchMode.OWNED_ONLY)
			.locks(Collections.singletonMap(Slot.AMMO, SlotLock.item(arrow.getId()))).build();
		PlayerLevels low = new PlayerLevels(99, 99, 99, 1, 99, 99, 99, 99);
		CombatContext lowContext = new CombatContext(monster(100, 20), low, false, true, piety());
		CombatContext maxed = new CombatContext(monster(100, 20), PlayerLevels.maxed(), false, true, piety());
		assertTrue(new Optimizer(data, lowContext, settings, id -> true, GearItem::getPrice)
			.optimize(CombatClass.RANGED, () -> false).isEmpty());
		assertTrue(new Optimizer(data, maxed, settings, id -> id == bow.getId(), GearItem::getPrice)
			.optimize(CombatClass.RANGED, () -> false).isEmpty());
		assertEquals(arrow, new Optimizer(data, maxed, settings, id -> true, GearItem::getPrice)
			.optimize(CombatClass.RANGED, () -> false).get(0).getLoadout().get(Slot.AMMO));
		assertTrue(new Optimizer(data, maxed, settings.toBuilder().mode(SearchMode.BUDGET).budget(999).build(),
			id -> id == bow.getId(), GearItem::getPrice).optimize(CombatClass.RANGED, () -> false).isEmpty());
		arrow.setTradeable(false);
		assertTrue(new Optimizer(data, maxed, settings.toBuilder().mode(SearchMode.BUDGET).budget(Long.MAX_VALUE).build(),
			id -> id == bow.getId(), GearItem::getPrice).optimize(CombatClass.RANGED, () -> false).isEmpty());
		assertEquals(arrow, new Optimizer(data, maxed, settings.toBuilder().mode(SearchMode.UNLIMITED).build(),
			id -> id == bow.getId(), GearItem::getPrice).optimize(CombatClass.RANGED, () -> false).get(0)
			.getLoadout().get(Slot.AMMO));
	}
}

package com.bestgearsetup.calc;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.GameData;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.MonsterGroup;
import com.bestgearsetup.data.Slot;
import com.bestgearsetup.data.WikiGameData;
import com.bestgearsetup.data.WikiMonsters;
import com.google.gson.Gson;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.BeforeClass;
import org.junit.Test;

/** Variants catalogued as separate entries, such as "dragon hunter crossbow (b)", can be excluded together. */
public class ExclusionFamilyTest
{
	private static final Gson GSON = RuneLiteAPI.GSON;
	private static GameData data;
	private static GearItem crossbow;
	private static GearItem crossbowB;

	@BeforeClass
	public static void load() throws Exception
	{
		data = WikiGameData.get(GSON).gameData(GSON);
		crossbow = data.getItem(Slot.WEAPON, 21012);
		crossbowB = data.getItem(Slot.WEAPON, 25918);
		assertNotNull(crossbow);
		assertNotNull(crossbowB);
	}

	@Test
	public void familyNamesDropTrailingVariantSuffixes()
	{
		assertEquals("dragon hunter crossbow", GameData.familyName("Dragon hunter crossbow (b)"));
		assertEquals("dragon hunter crossbow", GameData.familyName("dragon hunter crossbow"));
		assertEquals("dharok's helm", GameData.familyName("dharok's helm (100) (or)"));
		assertEquals("osmumten's fang", GameData.familyName("osmumten's fang"));
	}

	@Test
	public void crossbowFamilyHoldsBothEntriesWhicheverIsExcluded()
	{
		Set<Integer> family = ids(data.variantFamily(crossbow));
		assertTrue(family.contains(crossbow.getId()));
		assertTrue(family.contains(crossbowB.getId()));
		assertEquals(family, ids(data.variantFamily(crossbowB)));
		for (int id : family)
		{
			assertEquals(Slot.WEAPON, data.getItem(Slot.WEAPON, id).getSlot());
		}
	}

	@Test
	public void excludingTheFamilyRemovesTheEquivalentCrossbowFromVorkathResults() throws Exception
	{
		List<MonsterGroup> groups = data.searchMonsterGroups("vorkath", 1, true);
		assertFalse(groups.isEmpty());
		Monster vorkath = WikiMonsters.get(GSON).monster(groups.get(0).getPrimary().getName());
		CombatContext ctx = new CombatContext(vorkath, PlayerLevels.maxed(), false, true, TestData.piety());
		OptimizerSettings base = OptimizerSettings.builder().mode(SearchMode.UNLIMITED).depth(SearchDepth.FAST)
			.resultsPerClass(40).antifire(Antifire.SUPER).protectMagic(false).spellbooks(Collections.emptySet()).build();

		Optimizer onlyBase = new Optimizer(data, ctx, base.toBuilder().excluded(Collections.singleton(crossbow.getId()))
			.build(), id -> false, item -> 1L);
		assertNull(onlyBase.unusableReason(crossbowB));

		Set<Integer> family = ids(data.variantFamily(crossbow));
		Optimizer whole = new Optimizer(data, ctx, base.toBuilder().excluded(family).build(), id -> false, item -> 1L);
		assertEquals("you excluded it", whole.unusableReason(crossbowB));
		for (SetupResult r : whole.optimize(CombatClass.RANGED, () -> false))
		{
			assertFalse(r.getLoadout().getWeapon().getName(), family.contains(r.getLoadout().getWeapon().getId()));
		}
	}

	private static Set<Integer> ids(List<GearItem> items)
	{
		return items.stream().map(GearItem::getId).collect(Collectors.toCollection(HashSet::new));
	}
}

package com.bestgearsetup.calc;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class HitChanceTest
{
	private static final double EPS = 1e-12;

	/** The rolls a maximum gives: 0..max, or max + 2..0 when the maximum is negative. */
	private static long[] range(long max)
	{
		return max >= 0 ? new long[]{0, max} : new long[]{Math.min(0, max + 2), 0};
	}

	/** Enumerate every equally likely combination of rolls. */
	private static double brute(long maxAttack, long maxDefence, int attackRolls)
	{
		long[] a = range(maxAttack);
		long[] d = range(maxDefence);
		long hits = 0;
		long total = 0;
		for (long x = a[0]; x <= a[1]; x++)
		{
			for (long y = attackRolls == 2 ? a[0] : 0; y <= (attackRolls == 2 ? a[1] : 0); y++)
			{
				long best = attackRolls == 2 ? Math.max(x, y) : x;
				for (long z = d[0]; z <= d[1]; z++)
				{
					total++;
					hits += best > z ? 1 : 0;
				}
			}
		}
		return hits / (double) total;
	}

	@Test
	public void matchesEnumerationIncludingNegativeRolls()
	{
		for (long a = -12; a <= 40; a++)
		{
			for (long d = -12; d <= 40; d++)
			{
				assertEquals(a + "/" + d, brute(a, d, 1), HitChance.single(a, d), EPS);
				assertEquals(a + "/" + d, brute(a, d, 2), HitChance.twoAttackRolls(a, d), EPS);
			}
		}
	}

	@Test
	public void matchesTheWikiFormulasForLargeRolls()
	{
		// Damage per second/Melee: 1 - (d + 2) / (2(a + 1)) if a > d, else a / (2(d + 1)).
		assertEquals(1 - 1002.0 / (2 * 2001), HitChance.single(2000, 1000), EPS);
		assertEquals(1000.0 / (2 * 2001), HitChance.single(1000, 2000), EPS);
		// Osmumten's fang, outside the Tombs of Amascut.
		double a = 30_000;
		double d = 20_000;
		assertEquals(1 - (d + 2) * (2 * d + 3) / (6 * (a + 1) * (a + 1)), HitChance.twoAttackRolls(30_000, 20_000), 1e-9);
		assertEquals(d * (4 * d + 5) / (6 * (d + 1) * (a + 1)), HitChance.twoAttackRolls(20_000, 30_000), 1e-9);
	}

	@Test
	public void retryAfterMissMatchesTheLongRunRate()
	{
		double normal = 0.4;
		double retry = 0.64;
		// Iterate the two-state chain until it settles.
		double pRetry = 0;
		for (int i = 0; i < 1000; i++)
		{
			pRetry = (1 - pRetry) * (1 - normal) + pRetry * (1 - retry);
		}
		double expected = (1 - pRetry) * normal + pRetry * retry;
		assertEquals(expected, HitChance.withRetryAfterMiss(normal, retry), EPS);
		assertEquals(1.0, HitChance.withRetryAfterMiss(1, 1), EPS);
		assertEquals(0.0, HitChance.withRetryAfterMiss(0, 0), EPS);
	}
}

