	private static final String[][] MELEE_SETS = {
		{"void melee helm", "void knight top", "void knight robe", "void knight gloves"},
		{"obsidian helmet", "obsidian platebody", "obsidian platelegs", "toktz-xil-ak", "berserker necklace"},
