		0, 500, 12_000, 99_999, 100_000, 100_001, 900_000, 4_000_000, ItemCosts.UNKNOWN,
	};
	private static final int[] DEGRADED = {29047, 29043, 29045, 29035, 29031, 29033};

	private static GameData catalogue;
	private static WikiMonsters monsters;

	@BeforeClass
	public static void load() throws Exception
	{
		Gson gson = RuneLiteAPI.GSON;
		OwnershipRules.init(gson);
		catalogue = WikiGameData.get(gson).gameData(gson);
		catalogue.addVariantItems(gson, id ->
		{
			switch (id)
			{
				case 29035: return "Eclipse moon helm";
				case 29031: return "Eclipse moon chestplate";
				case 29033: return "Eclipse moon tassets";
				case 29047: return "Blood moon helm";
				case 29043: return "Blood moon chestplate";
				case 29045: return "Blood moon tassets";
				default: return null;
			}
		}, id -> false);
		monsters = WikiMonsters.get(gson);
	}

	@Test
	public void bestDepthMatchesExhaustiveSearch()
	{
		// Optional: ./gradlew test -Dbgs.oracle.cases=N -Dbgs.oracle.from=SEED -Dbgs.oracle.verbose=true
		int cases = Integer.getInteger("bgs.oracle.cases", 1500);
		int first = Integer.getInteger("bgs.oracle.from", 1);
		boolean verbose = Boolean.getBoolean("bgs.oracle.verbose");
		List<String> errors = new ArrayList<>();
		List<String> misses = new ArrayList<>();
		Set<Integer> missedBanks = new HashSet<>();
		double worstGap = 0;
		long evaluations = 0;
		for (int seed = first; seed < first + cases; seed++)
		{
			Case c = generate(seed);
			Oracle oracle = new Oracle(c);
			Oracle.Best best = oracle.search();
			evaluations += oracle.evaluations;
			if (verbose)
			{
				System.out.println("seed " + seed + " " + c + " evaluations " + oracle.evaluations + " best " + best.score
					+ "\n    " + describe(best.loadout));
			}
			for (int order = 0; order < 2; order++)
			{
				List<GearItem> items = new ArrayList<>(c.pool);
				if (order > 0)
				{
					Collections.shuffle(items, new Random(seed * 31L + order));
				}
				GameData data = TestData.gameData(items, catalogue.getSpells());
				Optimizer optimizer = new Optimizer(data, c.ctx, c.settings, c.owned::contains,
					id -> c.owned.contains(id) ? c.quantities.getOrDefault(id, Long.MAX_VALUE) : 0, c::price);
				String label = "seed " + seed + " order " + order + " " + c + ": ";
				if (order == 0)
				{
					// Pruning must keep an optimum: compare the optimum over the kept candidates.
					Oracle pruned = new Oracle(c);
					pruned.restrict(optimizer.candidates(c.cls));
					Oracle.Best kept = pruned.search();
					if (kept.score < best.score - EPS)
					{
						errors.add(label + String.format(Locale.ROOT, "pruning lost the optimum: %.9f of %.9f",
							kept.score, best.score) + "\n    oracle " + describe(best.loadout));
					}
				}
				List<SetupResult> results = optimizer.optimize(c.cls, () -> false);
				if (results.isEmpty())
				{
					if (best.loadout != null)
					{
						errors.add(label + "no result, oracle " + best.score + "\n    oracle " + describe(best.loadout));
					}
					continue;
				}
				Loadout found = results.get(0).getLoadout();
				double score = oracle.metric(DpsCalculator.calculate(found, c.ctx));
				String detail = "\n    found  " + describe(found) + "\n    oracle " + describe(best.loadout);
				String illegal = oracle.illegal(found);
				if (illegal != null)
				{
					errors.add(label + "illegal result (" + illegal + ")" + detail);
				}
				else if (best.loadout == null || score > best.score + EPS)
				{
					errors.add(label + String.format(Locale.ROOT, "score %.9f above oracle %.9f (oracle incomplete)",
						score, best.score) + detail);
				}
				else if (score < best.score - EPS)
				{
					double gap = 1 - dps(found, c) / dps(best.loadout, c);
					worstGap = Math.max(worstGap, gap);
					missedBanks.add(seed);
					misses.add(label + String.format(Locale.ROOT, "score %.9f below oracle %.9f (DPS %.4f%% lower)",
						score, best.score, 100 * gap) + detail);
				}
			}
		}
		System.out.println("oracle cases=" + cases + " evaluations=" + evaluations + " errors=" + errors.size()
			+ " missed banks=" + missedBanks.size() + String.format(Locale.ROOT, " worst DPS gap=%.4f%%", 100 * worstGap));
		errors.forEach(System.out::println);
		misses.forEach(System.out::println);
		assertTrue(String.join("\n", errors), errors.isEmpty());
		assertTrue(missedBanks.size() + " of " + cases + " banks ended below the exhaustive optimum:\n"
			+ String.join("\n", misses), missedBanks.size() <= MAX_MISS_RATE * cases);
		assertTrue(String.format(Locale.ROOT, "a search ended %.2f%% below the optimum DPS:%n", 100 * worstGap)
			+ String.join("\n", misses), worstGap <= MAX_MISS_GAP);
	}

	private static double dps(Loadout l, Case c)
	{
		return DpsCalculator.calculate(l, c.ctx).getDps();
	}

	private static String describe(Loadout l)
	{
		if (l == null)
		{
			return "none";
		}
		StringBuilder sb = new StringBuilder();
		sb.append(l.getStyle()).append(l.getSpell() == null ? "" : " " + l.getSpell().getName());
		for (Slot s : Slot.values())
		{
			if (l.get(s) != null)
			{
				sb.append(", ").append(s).append('=').append(l.get(s).getName()).append(" #").append(l.get(s).getId());
			}
		}
		if (l.getLoadedAmmo() != null)
		{
			sb.append(", loaded=").append(l.getLoadedAmmo().getName());
		}
		return sb.toString();
	}

	// ------------------------------------------------------------ generated cases

	private static final class Case
	{
		AttackStyle.Type tab;
		CombatClass cls;
		CombatContext ctx;
		PlayerLevels levels;
		OptimizerSettings settings;
		final List<GearItem> pool = new ArrayList<>();
		final Set<Integer> owned = new HashSet<>();
		final Map<Integer, Long> quantities = new HashMap<>();
		final Map<Integer, Long> prices = new HashMap<>();
		String monster;

		long price(GearItem item)
		{
			return prices.getOrDefault(item.getId(), ItemCosts.UNKNOWN);
		}

		@Override
		public String toString()
		{
			return tab + " vs " + monster + " " + settings.getMode() + (settings.getMode() == SearchMode.BUDGET
				? " " + settings.getBudget() : "") + (settings.isWildernessRiskLimited()
				? " cap " + settings.getMaxExpensiveItems() : "") + " calc " + settings.getCalcMode()
				+ (settings.getLocks().isEmpty() ? "" : " locks " + settings.getLocks().keySet())
				+ (settings.getExcluded().isEmpty() ? "" : " excl " + settings.getExcluded())
				+ (settings.getAmmoCount() > 0 ? " ammo " + settings.getAmmoCount() : "")
				+ " xp " + (settings.isAttackXp() ? "A" : "") + (settings.isStrengthXp() ? "S" : "")
				+ (settings.isDefenceXp() ? "D" : "") + " pool " + pool.size();
		}
	}

	private static Case generate(int seed)
	{
		Random r = new Random(seed);
		Case c = new Case();
		c.tab = TABS[(seed - 1) % TABS.length];
		c.cls = c.tab == AttackStyle.Type.MAGIC ? CombatClass.MAGIC
			: c.tab == AttackStyle.Type.RANGED || c.tab == AttackStyle.Type.ATLATL ? CombatClass.RANGED : CombatClass.MELEE;
		c.monster = MONSTERS[r.nextInt(MONSTERS.length)];
		Monster monster = monsters.monster(c.monster);
		c.levels = new PlayerLevels(level(r), level(r), level(r), level(r), level(r), level(r), level(r), level(r));
		boolean wilderness = c.monster.equals("chaos dwarf") || r.nextInt(4) == 0;
		c.ctx = new CombatContext(monster, c.levels, false, r.nextBoolean(), r.nextBoolean() ? TestData.piety() : null)
			.withModifiers(CombatModifiers.builder().wilderness(wilderness).build());

		// Weapons for the tab, then 4-6 armour slots of relevant items; magic keeps its spell lists small.
		Set<GearItem> pool = new LinkedHashSet<>();
		List<GearItem> weapons = new ArrayList<>();
		for (GearItem w : catalogue.getItems(Slot.WEAPON))
		{
			// Mostly wearable picks; a few unwearable ones exercise the requirement filter.
			if (plain(w) && servesTab(w, c.tab) && (c.levels.canEquip(w) || r.nextInt(8) == 0))
			{
				weapons.add(w);
			}
		}
		if (weapons.isEmpty())
		{
			for (GearItem w : catalogue.getItems(Slot.WEAPON))
			{
				if (plain(w) && servesTab(w, c.tab))
				{
					weapons.add(w);
				}
			}
		}
		int weaponCount = 2 + r.nextInt(c.cls == CombatClass.MAGIC ? 2 : 3);
		for (int i = 0; i < weaponCount; i++)
		{
			pool.add(weapons.get(r.nextInt(weapons.size())));
		}
		String[][] sets = c.tab == AttackStyle.Type.MAGIC ? MAGIC_SETS : c.tab == AttackStyle.Type.RANGED ? RANGED_SETS
			: c.tab == AttackStyle.Type.ATLATL ? ATLATL_SETS : MELEE_SETS;
		if (r.nextInt(5) < 3)
		{
			for (String name : sets[r.nextInt(sets.length)])
			{
				GearItem item = named(name, r);
				if (item != null && (item.getSlot() != Slot.WEAPON || servesTab(item, c.tab)))
				{
					pool.add(item);
				}
			}
		}
		List<Slot> slots = new ArrayList<>(Arrays.asList(ARMOUR));
		Collections.shuffle(slots, r);
		int active = (c.cls == CombatClass.MAGIC ? 4 : 5) + r.nextInt(3);
		for (Slot slot : slots.subList(0, active))
		{
			List<GearItem> relevant = new ArrayList<>();
			for (GearItem item : catalogue.getItems(slot))
			{
				if (plain(item) && relevant(item, c.tab) && (c.levels.canEquip(item) || r.nextInt(8) == 0))
				{
					relevant.add(item);
				}
			}
			int n = 1 + r.nextInt(slot == Slot.SHIELD || c.cls == CombatClass.MAGIC ? 2 : 3);
			for (int i = 0; i < n && !relevant.isEmpty(); i++)
			{
				pool.add(relevant.get(r.nextInt(relevant.size())));
			}
		}
		// Ammunition for every weapon that needs it.
		for (GearItem w : new ArrayList<>(pool))
		{
			if (w.getSlot() == Slot.WEAPON && !w.getAmmunition().isEmpty())
			{
				List<Integer> ids = new ArrayList<>(w.getAmmunition());
				Collections.shuffle(ids, r);
				int added = 0;
				for (int id : ids)
				{
					GearItem a = catalogue.getItem(Slot.AMMO, id);
					if (a != null && plain(a) && added < 2)
					{
						pool.add(a);
						added++;
					}
				}
			}
		}
		trim(pool, c, r);
		c.pool.addAll(pool);

		for (GearItem item : c.pool)
		{
			c.prices.put(item.getId(), PRICES[r.nextInt(PRICES.length)]);
			if (r.nextInt(10) < 7)
			{
				c.owned.add(item.getId());
				if (WeaponRules.consumedPerAttack(item))
				{
					c.quantities.put(item.getId(), r.nextBoolean() ? 50L : 5_000L);
				}
			}
		}

		OptimizerSettings.OptimizerSettingsBuilder s = OptimizerSettings.builder().depth(SearchDepth.BEST)
			.styles(EnumSet.of(c.tab)).spellbooks(new HashSet<>(Arrays.asList("standard", "ancient", "arceuus")))
			.resultsPerClass(1);
		switch (r.nextInt(4))
		{
			case 0:
				s.mode(SearchMode.OWNED_ONLY);
				break;
			case 1:
				s.mode(SearchMode.BUDGET).budget(0);
				break;
			case 2:
				s.mode(SearchMode.BUDGET).budget(r.nextBoolean() ? 100_000 : 5_000_000);
				break;
			default:
				s.mode(SearchMode.UNLIMITED);
				break;
		}
		if (wilderness || r.nextInt(3) == 0)
		{
			s.wildernessRiskLimited(true).maxExpensiveItems(r.nextInt(6) == 0 ? 0 : 1 + r.nextInt(4))
				.expensiveItemThreshold(100_000);
		}
		int calc = r.nextInt(8);
		s.calcMode(calc == 0 ? CalcMode.MAX_HIT : calc == 1 ? CalcMode.ACCURACY : CalcMode.DPS);
		s.attackXp(r.nextInt(5) > 0).strengthXp(r.nextInt(5) > 0).defenceXp(r.nextInt(5) > 0);
		if (r.nextInt(4) == 0)
		{
			s.ammoCount(r.nextBoolean() ? 100 : 1_000);
		}
		if (r.nextInt(4) == 0)
		{
			Map<Slot, SlotLock> locks = new EnumMap<>(Slot.class);
			GearItem item = c.pool.get(r.nextInt(c.pool.size()));
			if (item.getSlot() != Slot.WEAPON && item.getSlot() != Slot.AMMO)
			{
				locks.put(item.getSlot(), r.nextBoolean() ? SlotLock.item(item.getId()) : SlotLock.empty());
			}
			s.locks(locks);
		}
		if (r.nextInt(4) == 0)
		{
			s.excluded(Collections.singleton(c.pool.get(r.nextInt(c.pool.size())).getId()));
		}
		c.settings = s.build();
		return c;
	}

	private static int level(Random r)
	{
		return 60 + r.nextInt(40);
	}

	/** Bound the exhaustive search: drop armour from the largest slot until the enumeration is small. */
	private static void trim(Set<GearItem> pool, Case c, Random r)
	{
		while (true)
		{
			Map<Slot, Integer> counts = new EnumMap<>(Slot.class);
			int options = 0;
			for (GearItem item : pool)
			{
				if (item.getSlot() == Slot.WEAPON)
				{
					options += c.cls == CombatClass.MAGIC ? 40 : 4;
				}
				else if (item.getSlot() != Slot.AMMO)
				{
					counts.merge(item.getSlot(), 1, Integer::sum);
				}
			}
			long product = 1;
			Slot largest = null;
			for (Map.Entry<Slot, Integer> e : counts.entrySet())
			{
				product *= e.getValue() + 1;
				if (largest == null || e.getValue() > counts.get(largest))
				{
					largest = e.getKey();
				}
			}
			if (product * options <= 150_000 || largest == null)
			{
				return;
			}
			List<GearItem> inSlot = new ArrayList<>();
			for (GearItem item : pool)
			{
				if (item.getSlot() == largest)
				{
					inSlot.add(item);
				}
			}
			pool.remove(inSlot.get(r.nextInt(inSlot.size())));
		}
	}

	/** Ordinary equipment whose availability follows the plain ownership / purchase rules. */
	private static boolean plain(GearItem item)
	{
		return !item.isDmmEquipment() && !item.isBetaEquipment() && !item.isBountyHunterEquipment()
			&& !item.isLeagueEquipment() && !DiaryRewards.isReward(item.getId())
			&& !OwnershipRules.requiresOwnership(item.getId()) && item.isTradeable();
	}

	private static GearItem named(String name, Random r)
	{
		List<GearItem> matches = new ArrayList<>();
		for (Slot slot : Slot.values())
		{
			for (GearItem item : catalogue.getItems(slot))
			{
				if (item.getName().equalsIgnoreCase(name) && !item.isDmmEquipment() && !item.isBetaEquipment()
					&& !item.isBountyHunterEquipment() && !item.isLeagueEquipment() && !DiaryRewards.isReward(item.getId()))
				{
					matches.add(item);
				}
			}
		}
		if (matches.isEmpty())
		{
			return null;
		}
		// Prefer the degraded identities when they exist, so ownership of exactly that variant is exercised.
		for (GearItem item : matches)
		{
			if (Arrays.stream(DEGRADED).anyMatch(id -> id == item.getId()) && r.nextBoolean())
			{
				return item;
			}
		}
		return matches.get(r.nextInt(matches.size()));
	}

	private static boolean servesTab(GearItem weapon, AttackStyle.Type tab)
	{
		if (weapon.getSubcategory().equals("salamander"))
		{
			return false;
		}
		for (String raw : weapon.getStyles())
		{
			AttackStyle s = AttackStyle.parse(raw);
			if (s != null && WeaponRules.tabType(weapon, s) == tab)
			{
				return tab != AttackStyle.Type.MAGIC || s.isAutocast() || WeaponRules.isPoweredStaff(weapon);
			}
		}
		return false;
	}

	private static boolean relevant(GearItem item, AttackStyle.Type tab)
	{
		switch (tab)
		{
			case STAB:
				return item.getStabBonus() > 0 || item.getMeleeStr() > 0;
			case SLASH:
				return item.getSlashBonus() > 0 || item.getMeleeStr() > 0;
			case CRUSH:
				return item.getCrushBonus() > 0 || item.getMeleeStr() > 0;
			case RANGED:
				return item.getRangedBonus() > 0 || item.getRangedStr() > 0;
			case ATLATL:
				return item.getRangedBonus() > 0 || item.getMeleeStr() > 0;
			default:
				return item.getMagicBonus() > 0 || item.getMagicStr() > 0;
		}
	}

	// ------------------------------------------------------------ the oracle

	private static final class Oracle
	{
		private final Case c;
		private final OptimizerSettings s;
		private Map<Slot, List<GearItem>> kept;
		long evaluations;

		/** Only enumerate these armour candidates (weapons and ammunition stay unrestricted). */
		void restrict(Map<Slot, List<GearItem>> candidates)
		{
			kept = candidates;
		}

		Oracle(Case c)
		{
			this.c = c;
			this.s = c.settings;
		}

		static final class Best
		{
			Loadout loadout;
			double score = Double.NEGATIVE_INFINITY;
			long cost = Long.MAX_VALUE;
		}

		double metric(DpsResult r)
		{
			switch (s.getCalcMode())
			{
				case ACCURACY:
					return r.getDps() <= 0 ? 0 : r.getAccuracy() * 1e6 + r.getDps();
				case MAX_HIT:
					return r.getMaxHit() * 1e6 + r.getDps();
				default:
					return r.getDps();
			}
		}

		private boolean owns(GearItem item)
		{
			if (c.owned.contains(item.getId()))
			{
				return true;
			}
			for (int variant : item.getOwnershipVariants())
			{
				if (c.owned.contains(variant))
				{
					return true;
				}
			}
			return false;
		}

		/** Units held of the item and its equivalent variants. */
		private long held(GearItem item)
		{
			Set<Integer> ids = new LinkedHashSet<>(item.getOwnershipVariants());
			ids.add(item.getId());
			long held = 0;
			for (int id : ids)
			{
				long more = c.owned.contains(id) ? c.quantities.getOrDefault(id, Long.MAX_VALUE) : 0;
				held = held > Long.MAX_VALUE - more ? Long.MAX_VALUE : held + more;
			}
			return held;
		}

		/** Units of the requested ammunition still to buy. */
		private long shortfall(GearItem item)
		{
			if (s.getAmmoCount() <= 0 || !WeaponRules.consumedPerAttack(item))
			{
				return 0;
			}
			return Math.max(0, s.getAmmoCount() - held(item));
		}

		/** Excluded, unwearable, or not obtainable alone under the search mode. */
		boolean usable(GearItem item)
		{
			if (s.getExcluded().contains(item.getId()) || !c.levels.canEquip(item)
				|| !CombatRules.equipmentAllowed(c.ctx.getMonster(), item))
			{
				return false;
			}
			if (s.getMode() == SearchMode.UNLIMITED || owns(item) && shortfall(item) == 0)
			{
				return true;
			}
			if (s.getMode() == SearchMode.OWNED_ONLY || OwnershipRules.requiresOwnership(item.getId())
				|| !item.isTradeable() && !ItemCosts.hasTradableComponents(item.getId()))
			{
				return false;
			}
			long price = c.price(item);
			if (price < 0)
			{
				return s.getAmmoCount() <= 0 && WeaponRules.consumedPerAttack(item);
			}
			return price <= s.getBudget();
		}

		long cost(GearItem item)
		{
			if (item == null)
			{
				return 0;
			}
			long price = Math.max(0, c.price(item));
			if (WeaponRules.consumedPerAttack(item))
			{
				return price * shortfall(item);
			}
			return owns(item) ? 0 : price;
		}

		boolean expensive(GearItem item)
		{
			if (item == null)
			{
				return false;
			}
			long price = c.price(item);
			return price < 0 || price + ItemCosts.pvpRepairCost(item) >= s.getExpensiveItemThreshold();
		}

		/** Why the loadout breaks a rule, or null if it is a legal answer. */
		String illegal(Loadout l)
		{
			GearItem weapon = l.getWeapon();
			if (weapon == null || !options(weapon).contains(new Option(l.getStyle(), l.getSpell())))
			{
				return "option " + l.getStyle() + " / " + l.getSpell();
			}
			long cost = cost(l.getLoadedAmmo());
			int expensive = 0;
			for (Slot slot : Slot.values())
			{
				GearItem item = l.get(slot);
				SlotLock lock = s.getLocks().get(slot);
				if (lock != null && !(slot == Slot.SHIELD && weapon.isTwoHanded()))
				{
					// An unusable locked item leaves the slot empty.
					GearItem locked = lock.getKind() == SlotLock.Kind.ITEM ? find(slot, lock.getItemId()) : null;
					if (item != (locked != null && usable(locked) ? locked : null))
					{
						return "lock " + slot;
					}
				}
				if (item == null)
				{
					continue;
				}
				if (!usable(item))
				{
					return "unusable " + item.getName();
				}
				cost += cost(item);
				expensive += expensive(item) ? 1 : 0;
			}
			if (weapon.isTwoHanded() && l.get(Slot.SHIELD) != null)
			{
				return "shield with two-handed weapon";
			}
			GearItem ammo = WeaponRules.loadsAmmo(weapon) ? l.getLoadedAmmo() : l.get(Slot.AMMO);
			boolean needsAmmo = !weapon.getAmmunition().isEmpty();
			if (needsAmmo && (ammo == null || !weapon.getAmmunition().contains(ammo.getId()) || !usable(ammo)))
			{
				return "ammunition";
			}
			if (s.getMode() == SearchMode.BUDGET && cost > s.getBudget())
			{
				return "cost " + cost;
			}
			if (s.isWildernessRiskLimited() && expensive > s.getMaxExpensiveItems())
			{
				return "expensive " + expensive;
			}
			return null;
		}

		List<Option> options(GearItem weapon)
		{
			List<Option> out = new ArrayList<>();
			Set<String> seen = new HashSet<>();
			for (String raw : weapon.getStyles())
			{
				AttackStyle style = AttackStyle.parse(raw);
				if (style == null || WeaponRules.classOf(style) != c.cls || !seen.add(style.getType() + "/" + style.getStance())
					|| !s.getStyles().contains(WeaponRules.tabType(weapon, style))
					|| !AttackReach.canReach(c.ctx.getMonster(), weapon, style, s.getTargetDistance()))
				{
					continue;
				}
				String stance = style.getStance();
				boolean controlled = style.isMelee() && stance.equals("controlled");
				if (!s.isAttackXp() && style.isMelee() && (stance.equals("accurate") || controlled)
					|| !s.isStrengthXp() && style.isMelee() && (stance.equals("aggressive") || controlled)
					|| !s.isDefenceXp() && (style.isMelee() && (stance.equals("defensive") || controlled)
						|| stance.equals("longrange")))
				{
					continue;
				}
				if (c.cls != CombatClass.MAGIC)
				{
					out.add(new Option(style, null));
				}
				else if (style.isAutocast())
				{
					for (Spell spell : catalogue.getSpells())
					{
						String name = spell.getName().toLowerCase(Locale.ROOT);
						String book = spell.getSpellbook() == null ? "" : spell.getSpellbook().toLowerCase(Locale.ROOT);
						if (spell.getMaxHit() > 0 && spell.getLevel() <= c.ctx.getMagic() && s.getSpellbooks().contains(book)
							&& spell.castableWith(weapon.getId())
							&& (!name.contains("demonbane") || c.ctx.getMonster().hasAttribute("demon"))
							&& (!name.equals("crumble undead") || c.ctx.getMonster().hasAttribute("undead")))
						{
							out.add(new Option(style, spell));
						}
					}
				}
				else if (WeaponRules.isPoweredStaff(weapon) && WeaponRules.poweredStaffMaxHit(weapon, c.ctx.getMagic()) > 0)
				{
					out.add(new Option(style, null));
				}
			}
			return out;
		}

		Best search()
		{
			Best best = new Best();
			if (!Optimizer.classAllowed(c.ctx.getMonster(), c.cls))
			{
				return best;
			}
			SlotLock weaponLock = s.getLocks().get(Slot.WEAPON);
			for (GearItem weapon : c.pool)
			{
				if (weapon.getSlot() != Slot.WEAPON || !usable(weapon)
					|| weaponLock != null && weaponLock.getItemId() != weapon.getId())
				{
					continue;
				}
				SlotLock shieldLock = s.getLocks().get(Slot.SHIELD);
				if (weapon.isTwoHanded() && shieldLock != null && shieldLock.getKind() != SlotLock.Kind.EMPTY)
				{
					continue;
				}
				List<Option> options = options(weapon);
				if (options.isEmpty())
				{
					continue;
				}
				List<GearItem> ammo = new ArrayList<>();
				if (weapon.getAmmunition().isEmpty())
				{
					ammo.add(null);
				}
				else
				{
					for (GearItem a : c.pool)
					{
						if (a.getSlot() == Slot.AMMO && weapon.getAmmunition().contains(a.getId()) && usable(a))
						{
							ammo.add(a);
						}
					}
				}
				List<List<GearItem>> choices = new ArrayList<>();
				List<Slot> slots = new ArrayList<>();
				for (Slot slot : ARMOUR)
				{
					List<GearItem> list = new ArrayList<>();
					SlotLock lock = s.getLocks().get(slot);
					if (slot == Slot.SHIELD && weapon.isTwoHanded())
					{
						list.add(null);
					}
					else if (lock != null)
					{
						GearItem locked = lock.getKind() == SlotLock.Kind.ITEM ? find(slot, lock.getItemId()) : null;
						list.add(locked != null && usable(locked) ? locked : null);
					}
					else
					{
						list.add(null);
						for (GearItem item : c.pool)
						{
							if (item.getSlot() == slot && usable(item)
								&& (kept == null || kept.getOrDefault(slot, Collections.emptyList()).contains(item)))
							{
								list.add(item);
							}
						}
					}
					slots.add(slot);
					choices.add(list);
				}
				for (GearItem a : ammo)
				{
					Loadout l = new Loadout();
					l.set(Slot.WEAPON, weapon);
					if (WeaponRules.loadsAmmo(weapon))
					{
						l.setLoadedAmmo(a);
					}
					else
					{
						l.set(Slot.AMMO, a);
					}
					long cost = cost(weapon) + cost(a);
					int expensive = (expensive(weapon) ? 1 : 0) + (a != null && !WeaponRules.loadsAmmo(weapon) && expensive(a) ? 1 : 0);
					enumerate(l, slots, choices, 0, cost, expensive, options, best);
				}
			}
			return best;
		}

		private GearItem find(Slot slot, int id)
		{
			for (GearItem item : c.pool)
			{
				if (item.getSlot() == slot && item.getId() == id)
				{
					return item;
				}
			}
			return null;
		}

		private void enumerate(Loadout l, List<Slot> slots, List<List<GearItem>> choices, int index, long cost,
			int expensive, List<Option> options, Best best)
		{
			if (s.getMode() == SearchMode.BUDGET && cost > s.getBudget()
				|| s.isWildernessRiskLimited() && expensive > s.getMaxExpensiveItems())
			{
				return;
			}
			if (index == slots.size())
			{
				for (Option o : options)
				{
					l.setStyle(o.getStyle());
					l.setSpell(o.getSpell());
					evaluations++;
					DpsResult r = DpsCalculator.calculate(l, c.ctx);
					if (r.getDps() <= 0)
					{
						continue;
					}
					double score = metric(r);
					if (score > best.score + EPS
						|| Math.abs(score - best.score) <= EPS && cost < best.cost)
					{
						best.score = score;
						best.cost = cost;
						best.loadout = l.copy();
					}
				}
				return;
			}
			Slot slot = slots.get(index);
			for (GearItem item : choices.get(index))
			{
				l.set(slot, item);
				enumerate(l, slots, choices, index + 1, cost + cost(item), expensive + (expensive(item) ? 1 : 0),
					options, best);
			}
			l.set(slot, null);
		}
	}

	private static final class Option
	{
		final AttackStyle style;
		final Spell spell;

		Option(AttackStyle style, Spell spell)
		{
			this.style = style;
			this.spell = spell;
		}

		AttackStyle getStyle()
		{
			return style;
		}

		Spell getSpell()
		{
			return spell;
		}

		@Override
		public boolean equals(Object o)
		{
			return o instanceof Option && java.util.Objects.equals(style, ((Option) o).style) && spell == ((Option) o).spell;
		}

		@Override
		public int hashCode()
		{
			return java.util.Objects.hashCode(style);
		}
	}
}

package com.bestgearsetup.calc;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.GameData;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.WikiGameData;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.BeforeClass;
import org.junit.Test;

public class OptimizerProgressTest
{
	private static GameData data;
	private static CombatContext context;

	@BeforeClass
	public static void load() throws Exception
	{
		data = WikiGameData.get(RuneLiteAPI.GSON).gameData(RuneLiteAPI.GSON);
		context = new CombatContext(TestData.monster(100, 20), PlayerLevels.maxed(), false, true, null);
	}

	private static List<Double> progress(SearchDepth depth)
	{
		OptimizerSettings settings = OptimizerSettings.builder().mode(SearchMode.UNLIMITED).depth(depth)
			.spellbooks(Collections.emptySet()).build();
		List<Double> seen = new ArrayList<>();
		List<SetupResult> results = new Optimizer(data, context, settings, id -> false, GearItem::getPrice)
			.optimize(CombatClass.MELEE, () -> false, seen::add);
		assertFalse(results.isEmpty());
		return seen;
	}

	@Test
	public void progressRisesToCompletionAtEveryDepth()
	{
		for (SearchDepth depth : SearchDepth.values())
		{
			List<Double> seen = progress(depth);
			assertTrue(depth + ": reports more than start and end", seen.size() > 2);
			assertEquals(depth + ": starts at zero", 0, seen.get(0), 0);
			for (int i = 1; i < seen.size(); i++)
			{
				assertTrue(depth + ": never falls", seen.get(i) >= seen.get(i - 1));
			}
			assertEquals(depth + ": ends complete", 1, seen.get(seen.size() - 1), 1e-9);
		}
	}

	@Test
	public void aClassTheTargetIgnoresIsCompleteAtOnce()
	{
		List<Double> seen = new ArrayList<>();
		// Dusk takes melee damage only.
		Monster dusk = TestData.monster(100, 20);
		dusk.setId(7851);
		CombatContext meleeOnly = new CombatContext(dusk, PlayerLevels.maxed(), false, true, null);
		assertTrue(new Optimizer(data, meleeOnly, OptimizerSettings.builder().build(), id -> false, GearItem::getPrice)
			.optimize(CombatClass.RANGED, () -> false, seen::add).isEmpty());
		assertEquals(Collections.singletonList(1.0), seen);
	}
}

package com.bestgearsetup.calc;

import static com.bestgearsetup.calc.TestData.item;
import static com.bestgearsetup.calc.TestData.monster;
import static com.bestgearsetup.calc.TestData.piety;
import static com.bestgearsetup.calc.TestData.weapon;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.ItemCosts;
import com.bestgearsetup.OwnershipRules;
import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.GameData;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Slot;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.ToLongFunction;
import net.runelite.api.gameval.ItemID;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.BeforeClass;
import org.junit.Test;

public class OptimizerTest
{
	/** Main code gets the client's Gson in startUp; tests use the same instance. */
	@BeforeClass
	public static void ownershipRules()
	{
		OwnershipRules.init(RuneLiteAPI.GSON);
	}

	private final GearItem sword = weapon(100, "sword", "slash sword", 4, "chop,slash,aggressive", "slash,slash,accurate");
	private final GearItem cheapHelm = item(200, "cheap helm", Slot.HEAD);
	private final GearItem pricyHelm = item(201, "pricy helm", Slot.HEAD);
	private final GearItem uselessRing = item(300, "useless ring", Slot.RING);
	private final GearItem voidHelm = item(11665, "void melee helm", Slot.HEAD);
	private final GearItem voidTop = item(8839, "void knight top", Slot.BODY);
	private final GearItem voidRobe = item(8840, "void knight robe", Slot.LEGS);
	private final GearItem voidGloves = item(8842, "void knight gloves", Slot.HANDS);
	private final GearItem body = item(400, "strong body", Slot.BODY);

	public OptimizerTest()
	{
		sword.setMeleeStr(80);
		sword.setSlashBonus(80);
		sword.setPrice(1_000_000);
		cheapHelm.setMeleeStr(2);
		cheapHelm.setPrice(1_000);
		pricyHelm.setMeleeStr(10);
		pricyHelm.setSlashBonus(10);
		pricyHelm.setPrice(50_000_000);
		uselessRing.setPrice(5_000);
		body.setMeleeStr(1);
		body.setSlashBonus(1);
		body.setPrice(10_000);
		for (GearItem v : Arrays.asList(voidHelm, voidTop, voidRobe, voidGloves))
		{
			v.setTradeable(false);
		}
	}

	private List<SetupResult> run(SearchMode mode, long budget, Set<Integer> owned, GearItem... items)
	{
		return run(mode, budget, owned, GearItem::getPrice, items);
	}

	private List<SetupResult> run(SearchMode mode, long budget, Set<Integer> owned,
		ToLongFunction<GearItem> prices, GearItem... items)
	{
		GameData data = TestData.gameData(Arrays.asList(items), Collections.emptyList());
		CombatContext ctx = new CombatContext(monster(100, 20), PlayerLevels.maxed(), false, true, piety());
		OptimizerSettings settings = OptimizerSettings.builder()
			.mode(mode)
			.budget(budget)
			.spellbooks(new HashSet<>(Collections.singletonList("standard")))
			.build();
		return new Optimizer(data, ctx, settings, owned::contains, prices).optimize(CombatClass.MELEE, () -> false);
	}

	@Test
	public void unpricedPurchasesAreExcludedFromBudgetSearches()
	{
		ToLongFunction<GearItem> noQuoteForPricyHelm = i -> i == pricyHelm ? ItemCosts.UNKNOWN : i.getPrice();
		Set<Integer> owned = new HashSet<>(Collections.singletonList(100));
		SetupResult budget = run(SearchMode.BUDGET, 2_000_000_000L, owned, noQuoteForPricyHelm,
			sword, cheapHelm, pricyHelm).get(0);
		assertEquals(cheapHelm, budget.getLoadout().get(Slot.HEAD));
		assertEquals(1_000, budget.getBuyCost());
		assertEquals(0, budget.getUnpricedItems());

		SetupResult unlimited = run(SearchMode.UNLIMITED, 0, owned, noQuoteForPricyHelm,
			sword, cheapHelm, pricyHelm).get(0);
		assertEquals(pricyHelm, unlimited.getLoadout().get(Slot.HEAD));
		assertEquals(0, unlimited.getBuyCost());
		assertEquals(1, unlimited.getUnpricedItems());

		owned.add(pricyHelm.getId());
		SetupResult alreadyOwned = run(SearchMode.BUDGET, 0, owned, noQuoteForPricyHelm,
			sword, cheapHelm, pricyHelm).get(0);
		assertEquals(pricyHelm, alreadyOwned.getLoadout().get(Slot.HEAD));
		assertEquals(0, alreadyOwned.getUnpricedItems());
	}

	@Test
	public void unpricedGearWithRangedBonusesIsNotTreatedAsUncountedAmmo()
	{
		// Only ammo-slot ammunition may stay unpriced; a helm with a ranged bonus is still bought once.
		pricyHelm.setRangedBonus(5);
		ToLongFunction<GearItem> noQuoteForPricyHelm = i -> i == pricyHelm ? ItemCosts.UNKNOWN : i.getPrice();
		Set<Integer> owned = new HashSet<>(Collections.singletonList(100));
		SetupResult budget = run(SearchMode.BUDGET, 2_000_000_000L, owned, noQuoteForPricyHelm,
			sword, cheapHelm, pricyHelm).get(0);
		assertEquals(cheapHelm, budget.getLoadout().get(Slot.HEAD));
		assertEquals(0, budget.getUnpricedItems());
	}

	@Test
	public void untradeablesWithTradableComponentsCanBeBought()
	{
		GearItem chargedHelm = item(ItemID.SERPENTINE_HELM_CHARGED, "charged helm", Slot.HEAD);
		chargedHelm.setTradeable(false);
		chargedHelm.setMeleeStr(10);
		chargedHelm.setPrice(5_000);
		Set<Integer> owned = new HashSet<>(Collections.singletonList(100));
		SetupResult r = run(SearchMode.BUDGET, 10_000, owned, sword, cheapHelm, chargedHelm).get(0);
		assertEquals(chargedHelm, r.getLoadout().get(Slot.HEAD));
		assertEquals(5_000, r.getBuyCost());

		SetupResult tooDear = run(SearchMode.BUDGET, 4_000, owned, sword, cheapHelm, chargedHelm).get(0);
		assertEquals(cheapHelm, tooDear.getLoadout().get(Slot.HEAD));
	}

	@Test
	public void budgetLimitsPurchases()
	{
		Set<Integer> owned = new HashSet<>(Collections.singletonList(100));
		SetupResult r = run(SearchMode.BUDGET, 10_000, owned, sword, cheapHelm, pricyHelm).get(0);
		assertEquals(cheapHelm, r.getLoadout().get(Slot.HEAD));
		assertEquals(1_000, r.getBuyCost());

		SetupResult unlimited = run(SearchMode.UNLIMITED, 0, owned, sword, cheapHelm, pricyHelm).get(0);
		assertEquals(pricyHelm, unlimited.getLoadout().get(Slot.HEAD));
	}

	@Test
	public void ownedOnlyUsesNothingElse()
	{
		assertTrue(run(SearchMode.OWNED_ONLY, 0, Collections.emptySet(), sword, cheapHelm).isEmpty());

		Set<Integer> owned = new HashSet<>(Arrays.asList(100, 200));
		SetupResult r = run(SearchMode.OWNED_ONLY, 0, owned, sword, cheapHelm, pricyHelm).get(0);
		assertEquals(cheapHelm, r.getLoadout().get(Slot.HEAD));
		assertEquals(0, r.getBuyCost());
	}

	@Test
	public void itemsThatAddNoDpsAreLeftOff()
	{
		Set<Integer> owned = new HashSet<>(Collections.singletonList(100));
		SetupResult r = run(SearchMode.UNLIMITED, 0, owned, sword, uselessRing).get(0);
		assertNull(r.getLoadout().get(Slot.RING));
	}

	@Test
	public void findsVoidSetBonusThatGreedySearchWouldMiss()
	{
		Set<Integer> owned = new HashSet<>(Arrays.asList(100, 11665, 8839, 8840, 8842, 400));
		SetupResult r = run(SearchMode.OWNED_ONLY, 0, owned,
			sword, voidHelm, voidTop, voidRobe, voidGloves, body).get(0);
		assertEquals(voidHelm, r.getLoadout().get(Slot.HEAD));
		assertEquals(voidTop, r.getLoadout().get(Slot.BODY));
		assertEquals(voidGloves, r.getLoadout().get(Slot.HANDS));
	}

	@Test
	public void unownedUntradeablesAreOnlyUsedInBestInSlot()
	{
		Set<Integer> owned = new HashSet<>(Arrays.asList(100, 400));
		SetupResult budget = run(SearchMode.BUDGET, Long.MAX_VALUE, owned,
			sword, voidHelm, voidTop, voidRobe, voidGloves, body).get(0);
		assertEquals(body, budget.getLoadout().get(Slot.BODY));

		SetupResult bis = run(SearchMode.UNLIMITED, 0, owned,
			sword, voidHelm, voidTop, voidRobe, voidGloves, body).get(0);
		assertEquals(voidTop, bis.getLoadout().get(Slot.BODY));
	}

	@Test
	public void untradeableComponentsRespectTheBudgetAndOwnership()
	{
		// A charged serpentine helm: untradeable, bought as its tradable uncharged base.
		pricyHelm.setId(ItemID.SERPENTINE_HELM_CHARGED);
		pricyHelm.setTradeable(false);
		Set<Integer> owned = new HashSet<>(Collections.singletonList(100));
		SetupResult cheap = run(SearchMode.BUDGET, 10_000, owned, sword, cheapHelm, pricyHelm).get(0);
		assertEquals(cheapHelm, cheap.getLoadout().get(Slot.HEAD));
		assertEquals(1_000, cheap.getBuyCost());

		SetupResult enough = run(SearchMode.BUDGET, 50_000_000, owned, sword, cheapHelm, pricyHelm).get(0);
		assertEquals(pricyHelm, enough.getLoadout().get(Slot.HEAD));
		assertEquals(50_000_000, enough.getBuyCost());

		owned.add(pricyHelm.getId());
		SetupResult alreadyOwned = run(SearchMode.BUDGET, 0, owned, sword, cheapHelm, pricyHelm).get(0);
		assertEquals(pricyHelm, alreadyOwned.getLoadout().get(Slot.HEAD));
		assertEquals(0, alreadyOwned.getBuyCost());
	}

	@Test
	public void untradeableComponentsCountTowardTheCombinedBudget()
	{
		cheapHelm.setId(ItemID.SERPENTINE_HELM_CHARGED);
		cheapHelm.setTradeable(false);
		body.setId(ItemID.SANGUINESTI_STAFF);
		body.setTradeable(false);
		Set<Integer> owned = new HashSet<>(Collections.singletonList(100));
		SetupResult result = run(SearchMode.BUDGET, 10_000, owned, sword, cheapHelm, body).get(0);
		assertTrue(result.getBuyCost() <= 10_000);
		assertFalse(result.getLoadout().get(Slot.HEAD) != null && result.getLoadout().get(Slot.BODY) != null);
	}

	@Test
	public void respectsMonsterImmunity()
	{
		GameData data = TestData.gameData(Collections.singletonList(sword), Collections.emptyList());
		CombatContext ctx = new CombatContext(monster(1, 0, "melee immune"), PlayerLevels.maxed(), false, true, piety());
		OptimizerSettings settings = OptimizerSettings.builder().mode(SearchMode.UNLIMITED)
			.spellbooks(Collections.singleton("standard")).build();
		assertTrue(new Optimizer(data, ctx, settings, id -> true, GearItem::getPrice)
			.optimize(CombatClass.MELEE, () -> false).isEmpty());
	}
}

package com.bestgearsetup.calc;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.OwnershipRules;
import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.GameData;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Slot;
import com.bestgearsetup.data.WikiGameData;
import com.bestgearsetup.data.WikiMonsters;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * Small banks (found by the exhaustive comparison in {@link OptimizerOracleTest}) where the best stance or spell
 * only wins together with an equipment change, and neither wins alone. Each expected score is that bank's
 * exhaustive optimum.
 */
public class OptionCouplingTest
{
	private static GameData catalogue;
	private static WikiMonsters monsters;

	@BeforeClass
	public static void load() throws Exception
	{
		Gson gson = RuneLiteAPI.GSON;
		OwnershipRules.init(gson);
		catalogue = WikiGameData.get(gson).gameData(gson);
		monsters = WikiMonsters.get(gson);
	}

	/** One bank: {item id, acquisition price, owned (1) or not (0)} per row. */
	private static SetupResult best(String monster, PlayerLevels levels, boolean potions, boolean prayers,
		boolean wilderness, OptimizerSettings settings, CombatClass cls, long[][] bank)
	{
		List<GearItem> items = new ArrayList<>();
		Map<Integer, Long> prices = new HashMap<>();
		HashSet<Integer> owned = new HashSet<>();
		for (long[] row : bank)
		{
			int id = (int) row[0];
			GearItem item = null;
			for (Slot slot : Slot.values())
			{
				item = item != null ? item : catalogue.getItem(slot, id);
			}
			items.add(item);
			prices.put(id, row[1]);
			if (row[2] != 0)
			{
				owned.add(id);
			}
		}
		GameData data = TestData.gameData(items, catalogue.getSpells());
		CombatContext ctx = new CombatContext(monsters.monster(monster), levels, false, potions,
			prayers ? TestData.piety() : null).withModifiers(CombatModifiers.builder().wilderness(wilderness).build());
		Optimizer optimizer = new Optimizer(data, ctx, settings, owned::contains, item -> prices.get(item.getId()));
		SetupResult result = optimizer.optimize(cls, () -> false).get(0);
		assertTrue(optimizer.expensiveItemCount(result.getLoadout()) <= settings.getMaxExpensiveItems()
			|| !settings.isWildernessRiskLimited());
		assertTrue(settings.getMode() != SearchMode.BUDGET || result.getBuyCost() <= settings.getBudget());
		return result;
	}

	private static OptimizerSettings.OptimizerSettingsBuilder settings(AttackStyle.Type tab)
	{
		return OptimizerSettings.builder().depth(SearchDepth.BEST).styles(Collections.singleton(tab))
			.spellbooks(new HashSet<>(Arrays.asList("standard", "ancient", "arceuus")));
	}

	@Test
	public void stanceChangesWithTwoSlots()
	{
		// Aggressive only beats accurate once the cape comes off and Glory replaces Strength.
		SetupResult r = best("fire giant (level 86)", new PlayerLevels(71, 77, 69, 72, 95, 97, 89, 92), true, false,
			false, settings(AttackStyle.Type.CRUSH).mode(SearchMode.BUDGET).budget(5_000_000).build(), CombatClass.MELEE,
			new long[][]{
				{6760, 100_001, 1}, {4153, 99_999, 1}, {4081, 100_000, 1}, {10588, 12_000, 1}, {1725, 100_001, 1},
				{1704, 99_999, 1}, {21298, 500, 1}, {6524, 900_000, 0}, {31081, 99_999, 0}, {24420, 900_000, 1},
				{11832, 900_000, 0}, {4131, 12_000, 1}, {11966, 500, 0}, {29289, 100_001, 1},
			});
		assertEquals(2.6369662078521534, r.getDps().getDps(), 1e-9);
		assertEquals("aggressive", r.getLoadout().getStyle().getStance());
		assertEquals(1704, r.getLoadout().get(Slot.NECK).getId());
	}

	@Test
	public void spellChangesWithTwoSlots()
	{
		// Fire Wave needs the Tome of fire, which takes the one expensive allowance and the legs' place.
		SetupResult r = best("chaos dwarf", new PlayerLevels(90, 64, 82, 74, 71, 94, 75, 60), true, true, true,
			settings(AttackStyle.Type.MAGIC).mode(SearchMode.BUDGET).budget(5_000_000).wildernessRiskLimited(true)
				.maxExpensiveItems(1).expensiveItemThreshold(100_000).excluded(Collections.singleton(4675)).build(),
			CombatClass.MAGIC, new long[][]{
				{30634, 12_000, 1}, {1405, 12_000, 0}, {4675, 100_001, 1}, {20714, 900_000, 0}, {1387, 12_000, 1},
				{12002, 500, 0}, {21791, 100_000, 0}, {10446, 500, 0}, {25576, -1, 1}, {22975, 0, 0},
				{23053, 100_000, 1},
			});
		assertEquals(4.236583326045129, r.getDps().getDps(), 1e-9);
		assertEquals("fire wave", r.getLoadout().getSpell().getName().toLowerCase(java.util.Locale.ROOT));
		assertEquals(20714, r.getLoadout().get(Slot.SHIELD).getId());
	}

	/** The trial evaluation alone: each equipment state gets the best of every allowed spell, and keeps it set. */
	@Test
	public void trialTakesItsBestSpell()
	{
		CombatContext ctx = new CombatContext(monsters.monster("chaos dwarf"), new PlayerLevels(69, 73, 81, 64, 60, 67, 88, 61),
			false, false, null).withModifiers(CombatModifiers.builder().wilderness(true).build());
		OptimizerSettings settings = settings(AttackStyle.Type.MAGIC).mode(SearchMode.UNLIMITED).build();
		GearItem staff = catalogue.getItem(Slot.WEAPON, 6563);
		Optimizer optimizer = new Optimizer(catalogue, ctx, settings, id -> true, item -> 0);
		Map<String, String> best = new HashMap<>();
		for (int shield : new int[]{20714, 11924})
		{
			Loadout l = new Loadout();
			l.set(Slot.WEAPON, staff);
			l.set(Slot.SHIELD, catalogue.getItem(Slot.SHIELD, shield));
			AttackStyle autocast = null;
			for (String raw : staff.getStyles())
			{
				AttackStyle style = AttackStyle.parse(raw);
				autocast = style != null && style.isAutocast() ? style : autocast;
			}
			// Independently: every spell this staff can autocast at this Magic level.
			double expected = 0;
			String expectedSpell = null;
			for (com.bestgearsetup.data.Spell spell : catalogue.getSpells())
			{
				String book = spell.getSpellbook() == null ? "" : spell.getSpellbook().toLowerCase(java.util.Locale.ROOT);
				if (spell.getMaxHit() > 0 && spell.getLevel() <= ctx.getMagic() && spell.castableWith(staff.getId())
					&& settings.getSpellbooks().contains(book))
				{
					l.setStyle(autocast);
					l.setSpell(spell);
					double dps = DpsCalculator.calculate(l, ctx).getDps();
					if (dps > expected)
					{
						expected = dps;
						expectedSpell = spell.getName();
					}
				}
			}
			l.setSpell(catalogue.getSpells().get(0));
			double score = optimizer.scoreWithBestOption(l, CombatClass.MAGIC);
			assertEquals(expected, score, 1e-12);
			assertEquals(expectedSpell, l.getSpell().getName());
			assertEquals(score, DpsCalculator.calculate(l, ctx).getDps(), 1e-12);
			best.put(shield == 20714 ? "tome" : "ward", expectedSpell);
		}
		// The best spell depends on the shield, so neither can be chosen before the other.
		assertEquals("fire blast", best.get("tome").toLowerCase(java.util.Locale.ROOT));
		assertTrue(!best.get("ward").equalsIgnoreCase("fire blast"));
	}

	@Test
	public void spellChangesWithOneSlot()
	{
		// Fire Blast loses with the Malediction ward and the Tome of fire loses with Wind Blast; together they win.
		Map<Slot, SlotLock> locks = new EnumMap<>(Slot.class);
		locks.put(Slot.NECK, SlotLock.empty());
		SetupResult r = best("chaos dwarf", new PlayerLevels(69, 73, 81, 64, 60, 67, 88, 61), false, false, true,
			settings(AttackStyle.Type.MAGIC).mode(SearchMode.UNLIMITED).wildernessRiskLimited(true).maxExpensiveItems(2)
				.expensiveItemThreshold(100_000).attackXp(false).ammoCount(1_000).locks(locks).build(),
			CombatClass.MAGIC, new long[][]{
				{6563, 99_999, 1}, {6910, 99_999, 1}, {20714, 100_000, 1}, {1387, 900_000, 0}, {12002, 12_000, 0},
				{21791, 500, 1}, {12267, 0, 1}, {6141, 99_999, 1}, {1724, 100_000, 1}, {28313, -1, 1},
				{11924, 12_000, 1}, {30066, 900_000, 0}, {581, 500, 1},
			});
		assertEquals(2.7124713964392533, r.getDps().getDps(), 1e-9);
		assertEquals("fire blast", r.getLoadout().getSpell().getName().toLowerCase(java.util.Locale.ROOT));
		assertEquals(20714, r.getLoadout().get(Slot.SHIELD).getId());
	}
}

package com.bestgearsetup.calc;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.GameData;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.MonsterSummary;
import com.bestgearsetup.data.Potion;
import com.bestgearsetup.data.Prayer;
import com.bestgearsetup.data.Slot;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class PotionChoiceTest
{
	private static Potion potion(String name, int base, int pct, String... attributes)
	{
		Potion p = new Potion();
		p.setName(name);
		p.setBaseIncrease(base);
		p.setPercentageIncrease(pct);
		p.setAttributes(Arrays.asList(attributes));
		return p;
	}

	private static GameData data()
	{
		Map<String, List<Potion>> potions = new HashMap<>();
		potions.put("ranged", Arrays.asList(
			potion("ranging potion", 4, 10),
			potion("overload (+)", 6, 16, "xerician"),
			potion("smelling salts", 11, 16, "tombs of amascut")));
		potions.put("strength", Collections.singletonList(potion("dragon battleaxe", 10, 0)));
		return new GameData(Collections.<MonsterSummary>emptyList(), Collections.<String, List<GearItem>>emptyMap(),
			Collections.<GearItem>emptyList(), Collections.emptyList(), Collections.<String, List<Prayer>>emptyMap(), potions);
	}

	@Test
	public void bestSkipsRaidOnlyPotions()
	{
		// 99 + 4 + 9 = 112 (overloads and smelling salts are raid-only)
		assertEquals(112, PotionChoice.boostedLevel(data(), "ranged", 99, PotionChoice.BEST));
		assertEquals("Ranging Potion", PotionChoice.describe(data(), "ranged", 99, PotionChoice.BEST));
	}

	@Test
	public void bestUsesRaidSuppliesInsideTheirRaid()
	{
		Monster vorkath = TestData.monster(214, 26);
		Monster zebak = TestData.monster(70, 0, "tombs of amascut");
		Monster olm = TestData.monster(150, 0, "xerician");
		// Owning nothing: raid supplies are handed out in the raid, so ownership doesn't apply to them.
		java.util.function.Predicate<Potion> none = p -> p.isRaidSupply();
		// 99 + 11 + 15 = 125
		assertEquals(125, PotionChoice.boostedLevel(data(), "ranged", 99, PotionChoice.BEST, none, zebak));
		// 99 + 6 + 15 = 120; smelling salts don't work in the Chambers of Xeric
		assertEquals(120, PotionChoice.boostedLevel(data(), "ranged", 99, PotionChoice.BEST, none, olm));
		assertEquals(112, PotionChoice.boostedLevel(data(), "ranged", 99, PotionChoice.BEST, p -> true, vorkath));
		assertNull(PotionChoice.resolve(data(), "ranged", 99, PotionChoice.BEST, none, vorkath));
	}

	@Test
	public void namedAndNoneChoices()
	{
		// 99 + 11 + 15 = 125
		assertEquals(125, PotionChoice.boostedLevel(data(), "ranged", 99, "smelling salts"));
		assertEquals(99, PotionChoice.boostedLevel(data(), "ranged", 99, PotionChoice.NONE));
		assertTrue(PotionChoice.namesFor(data(), CombatClass.RANGED).contains("overload (+)"));
	}

	@Test
	public void dragonBattleaxeIsNotOffered()
	{
		assertTrue(PotionChoice.namesFor(data(), CombatClass.MELEE).isEmpty());
	}

	@Test
	public void slotLocksRoundTrip()
	{
		Map<Slot, SlotLock> locks = SlotLock.parse("WEAPON:4151,SHIELD:empty,BODY:fill,bogus,HEAD:x");
		assertEquals(SlotLock.item(4151), locks.get(Slot.WEAPON));
		assertEquals(SlotLock.empty(), locks.get(Slot.SHIELD));
		assertEquals(SlotLock.fill(), locks.get(Slot.BODY));
		assertEquals(3, locks.size());
		assertEquals(locks, SlotLock.parse(SlotLock.format(locks)));
	}

	@Test
	public void namedRaidPotionsReportWhereTheyApply()
	{
		Monster vorkath = TestData.monster(214, 26);
		vorkath.setName("vorkath (post-quest)");
		Monster zebak = TestData.monster(70, 0, "tombs of amascut");
		zebak.setName("zebak");
		Monster olm = TestData.monster(150, 0, "xerician");
		Potion salts = potion("smelling salts", 11, 16, "tombs of amascut");
		Potion overload = potion("overload (+)", 6, 16, "xerician");
		assertEquals("only usable in the Tombs of Amascut", PotionChoice.restriction(salts, vorkath));
		assertNull(PotionChoice.restriction(salts, zebak));
		assertEquals("only usable in the Chambers of Xeric", PotionChoice.restriction(overload, vorkath));
		assertNull(PotionChoice.restriction(overload, olm));
		assertNull(PotionChoice.restriction(potion("ranging potion", 4, 10), vorkath));
		assertEquals("only usable in Nightmare Zone", PotionChoice.restriction(potion("super ranging", 5, 15, "nmz"), olm));
		assertTrue(PotionChoice.isExplicit("smelling salts"));
		assertFalse(PotionChoice.isExplicit(PotionChoice.BEST));
		assertFalse(PotionChoice.isExplicit(PotionChoice.NONE));
		assertFalse(PotionChoice.isExplicit(null));
	}
}

package com.bestgearsetup.calc;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.GameData;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.Slot;
import com.bestgearsetup.data.WikiGameData;
import com.bestgearsetup.data.WikiMonsters;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.BeforeClass;
import org.junit.Test;

/** Pyrefiend comparisons where several strength bonuses cross a max-hit breakpoint together. */
public class PyrefiendOptimizerTest
{
	private static GameData data;
	private static CombatContext ctx;
	private static final OptimizerSettings SETTINGS = OptimizerSettings.builder()
		.mode(SearchMode.OWNED_ONLY)
		.depth(SearchDepth.BEST)
		.spellbooks(Collections.singleton("standard"))
		.excluded(new HashSet<>(Arrays.asList(11230, 12006, 12926)))
		.build();

	@BeforeClass
	public static void load() throws Exception
	{
		Gson gson = RuneLiteAPI.GSON;
		data = WikiGameData.get(gson).gameData(gson);
		Monster monster = WikiMonsters.get(gson).monster(data.matchNpc(433, null, 0).getName());
		ctx = new CombatContext(monster, new PlayerLevels(82, 87, 80, 81, 76, 76, 87, 67), true, false, null);
	}

	private static Set<Integer> meleeOwned()
	{
		return new HashSet<>(Arrays.asList(11865, 29028, 6570, 13121, 6585, 1725, 29280, 29022,
			29283, 29025, 12954, 7462, 13239, 11773, 26219, 28997, 28810, 4587, 31248));
	}

	private static SetupResult best(AttackStyle.Type type, Set<Integer> owned, OptimizerSettings settings)
	{
		return new Optimizer(data, ctx, settings.toBuilder().styles(Collections.singleton(type)).build(),
			owned::contains, item -> 1_000).optimize(type == AttackStyle.Type.RANGED ? CombatClass.RANGED
				: CombatClass.MELEE, () -> false).get(0);
	}

	@Test
	public void threeStrengthTradesMakeDualMacuahuitlBeatFang()
	{
		SetupResult result = best(AttackStyle.Type.STAB, meleeOwned(), SETTINGS);
		assertEquals(28997, result.getLoadout().getWeapon().getId());
		assertEquals(1725, result.getLoadout().get(Slot.NECK).getId());
		assertEquals(29022, result.getLoadout().get(Slot.BODY).getId());
		assertEquals(29025, result.getLoadout().get(Slot.LEGS).getId());
		assertEquals(11865, result.getLoadout().get(Slot.HEAD).getId());
		assertEquals(33, result.getDps().getMaxHit());
		assertEquals(6.349199525945838, result.getDps().getDps(), 1e-9);
	}

	@Test
	public void strengthAmuletAndAggressiveStanceMakeScimitarBeatZombieAxe()
	{
		SetupResult result = best(AttackStyle.Type.SLASH, meleeOwned(), SETTINGS);
		assertEquals(4587, result.getLoadout().getWeapon().getId());
		assertEquals(1725, result.getLoadout().get(Slot.NECK).getId());
		assertEquals("aggressive", result.getLoadout().getStyle().getStance());
		assertEquals(32, result.getDps().getMaxHit());
		assertEquals(6.2497467815797325, result.getDps().getDps(), 1e-9);
	}

	@Test
	public void matchingExclusionsSelectRuneKnives()
	{
		Set<Integer> owned = new HashSet<>(Arrays.asList(11865, 27374, 6585, 868, 811, 810, 12926,
			11230, 29004, 22275, 2497, 7462, 22951));
		SetupResult result = best(AttackStyle.Type.RANGED, owned, SETTINGS);
		assertEquals(868, result.getLoadout().getWeapon().getId());
		assertEquals(14, result.getDps().getMaxHit());
		assertEquals(5.519889137541012, result.getDps().getDps(), 1e-9);
		owned.remove(11230);
		OptimizerSettings knivesExcluded = SETTINGS.toBuilder()
			.excluded(new HashSet<>(Arrays.asList(868, 12006, 12926))).build();
		assertEquals(811, best(AttackStyle.Type.RANGED, owned, knivesExcluded).getLoadout().getWeapon().getId());
	}

	@Test
	public void strengthSeedRespectsLocksOwnershipAndZeroBudget()
	{
		Set<Integer> owned = meleeOwned();
		OptimizerSettings locked = SETTINGS.toBuilder().locks(SlotLock.parse("NECK:6585")).build();
		assertEquals(6585, best(AttackStyle.Type.STAB, owned, locked).getLoadout().get(Slot.NECK).getId());
		owned.remove(1725);
		OptimizerSettings noSpend = SETTINGS.toBuilder().mode(SearchMode.BUDGET).budget(0).build();
		SetupResult affordable = best(AttackStyle.Type.STAB, owned, noSpend);
		assertEquals(0, affordable.getBuyCost());
		assertTrue(affordable.getLoadout().get(Slot.NECK).getId() != 1725);
		assertTrue(affordable.getDps().getDps() < 6.349199525945838);
	}
}

package com.bestgearsetup.calc;

import static com.bestgearsetup.calc.TestData.monster;
import static com.bestgearsetup.calc.TestData.weapon;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.Slot;
import org.junit.Test;

/**
 * Vectors computed by hand from the Wiki calculator's lib/scaling modules (revision 89c3e25),
 * using solo, unscaled raid records as the base stats.
 */
public class RaidScalingTest
{
	private static Monster raidMonster(int id, String name, String attribute, int hp, int def, int magic,
		int attack, int strength, int ranged)
	{
		Monster m = monster(def, 50, attribute);
		m.setId(id);
		m.setName(name);
		m.setHitpoints(hp);
		m.setMagicLevel(magic);
		m.setAttackLevel(attack);
		m.setStrengthLevel(strength);
		m.setRangedLevel(ranged);
		return m;
	}

	private static RaidScaling.Settings.SettingsBuilder party(int size)
	{
		return RaidScaling.Settings.builder().partySize(size);
	}

	@Test
	public void toaScalesPathBossHpWithRaidPathAndPartyThenRounds()
	{
		Monster akkha = raidMonster(11789, "akkha", "tombs of amascut", 400, 80, 100, 100, 140, 100);
		Monster scaled = RaidScaling.apply(akkha, party(4).toaRaidLevel(300).toaPathLevel(3).build());
		// 400 + 120% = 880; path 3: x118% = 1038; party 4: x34/10 = 3529; rounded to 10.
		assertEquals(3530, scaled.getHitpoints());
		assertEquals(300, scaled.getToaRaidLevel());
		assertEquals(400, akkha.getHitpoints());
		assertEquals(0, akkha.getToaRaidLevel());
	}

	@Test
	public void toaCoreUsesFixedHpAndReducedInvocationFactor()
	{
		Monster core = raidMonster(11758, "tumeken's warden (core-ejected)", "tombs of amascut", 4500, 100, 190, 1, 1, 1);
		assertEquals(5850, RaidScaling.apply(core, party(1).toaRaidLevel(300).build()).getHitpoints());
	}

	@Test
	public void toaSmallTargetsRoundToFiveAndOverlordsKeepUnscaledDefenceRolls()
	{
		Monster kephri = raidMonster(11721, "kephri", "tombs of amascut", 80, 80, 125, 1, 1, 1);
		// 80 * 19/10 = 152, rounded to the nearest 5.
		assertEquals(150, RaidScaling.apply(kephri, party(2).build()).getHitpoints());
		Monster scarab = raidMonster(11724, "soldier scarab", "tombs of amascut", 40, 80, 1, 1, 1, 1);
		assertEquals(0, RaidScaling.apply(scarab, party(1).toaRaidLevel(300).build()).getToaRaidLevel());
		Monster baboon = raidMonster(11709, "baboon brawler", "tombs of amascut", 10, 10, 1, 1, 1, 1);
		Monster unscaled = RaidScaling.apply(baboon, party(8).toaRaidLevel(500).build());
		assertEquals(10, unscaled.getHitpoints());
		assertEquals(0, unscaled.getToaRaidLevel());
	}

	@Test
	public void toaRaidLevelMultipliesTheDefenceRollBeforeAccuracy()
	{
		Monster target = monster(80, 120);
		target.setToaRaidLevel(300);
		Loadout l = new Loadout();
		l.set(Slot.WEAPON, weapon(50000, "test sword", "stab sword", 4, "lunge,stab,accurate"));
		l.getWeapon().setStabBonus(100);
		l.getWeapon().setMeleeStr(50);
		l.setStyle(AttackStyle.parse("lunge,stab,accurate"));
		DpsResult r = DpsCalculator.calculate(l, new CombatContext(target, PlayerLevels.maxed(), false, false, null));
		long defence = 89L * 184 * 550 / 250;
		assertEquals(36027, defence);
		assertEquals(HitChance.single(110L * 164, defence), r.getAccuracy(), 1e-12);
	}

	@Test
	public void tobNormalClampsSmallPartiesAndEntryModeUsesItsTable()
	{
		Monster maiden = raidMonster(8360, "the maiden of sugadinti (normal)", "theatre of blood", 3500, 200, 350, 350, 350, 1);
		assertEquals(3062, RaidScaling.apply(maiden, party(4).build()).getHitpoints());
		assertEquals(2625, RaidScaling.apply(maiden, party(1).build()).getHitpoints());
		assertEquals(3500, RaidScaling.apply(maiden, party(5).build()).getHitpoints());
		Monster entry = raidMonster(10814, "the maiden of sugadinti (entry mode)", "theatre of blood", 2000, 80, 140, 1, 1, 1);
		assertEquals(950, RaidScaling.apply(entry, party(2).build()).getHitpoints());
		assertEquals(500, RaidScaling.apply(entry, party(1).build()).getHitpoints());
		// The variant name decides the mode, whatever the NPC id.
		Monster named = raidMonster(10821, "blood spawn (normal)", "theatre of blood", 120, 0, 0, 1, 1, 1);
		assertEquals(RaidScaling.Raid.TOB, RaidScaling.raid(named));
	}

	@Test
	public void coxMultiScalingUsesPartySizeAndChallengeMode()
	{
		Monster tekton = raidMonster(7540, "tekton (normal)", "xerician", 300, 205, 205, 390, 390, 1);
		Monster normal = RaidScaling.apply(tekton, party(3).build());
		assertEquals(600, normal.getHitpoints());
		assertEquals(209, normal.getDefenceLevel());
		// Tekton's Magic is a defensive skill.
		assertEquals(209, normal.getMagicLevel());
		assertEquals(425, normal.getAttackLevel());
		assertEquals(1, normal.getRangedLevel());
		Monster cm = RaidScaling.apply(tekton, party(3).coxChallengeMode(true).build());
		assertEquals(900, cm.getHitpoints());
		assertEquals(250, cm.getDefenceLevel());
		assertEquals(637, cm.getStrengthLevel());
	}

	@Test
	public void coxSoloAtMaximumLevelsKeepsBaseStats()
	{
		Monster tekton = raidMonster(7540, "tekton (normal)", "xerician", 300, 205, 205, 390, 390, 1);
		Monster solo = RaidScaling.apply(tekton, RaidScaling.Settings.SOLO);
		assertEquals(300, solo.getHitpoints());
		assertEquals(205, solo.getDefenceLevel());
		assertEquals(390, solo.getAttackLevel());
	}

	@Test
	public void coxLowerPartyLevelsReduceStatsAndGuardianHpUsesMining()
	{
		Monster guardian = raidMonster(7569, "guardian", "xerician", 151, 100, 1, 140, 140, 1);
		Monster maxed = RaidScaling.apply(guardian, party(1).partyAverageMining(85).build());
		assertEquals(236, maxed.getHitpoints());
		Monster low = RaidScaling.apply(guardian, party(1).partyAverageMining(85).partyMaxCombat(100)
			.partyMaxHitpoints(80).build());
		assertEquals(187, low.getHitpoints());
		assertEquals(90, low.getDefenceLevel());
		assertEquals(127, low.getAttackLevel());
		assertEquals(1, low.getMagicLevel());
	}

	@Test
	public void olmReplacesHpByPartyPhasesAndHalvesMageHandMagic()
	{
		Monster head = raidMonster(7551, "great olm (head)", "xerician", 400, 150, 250, 250, 250, 250);
		Monster scaled = RaidScaling.apply(head, party(9).build());
		assertEquals(2800, scaled.getHitpoints());
		assertEquals(160, scaled.getDefenceLevel());
		assertEquals(305, scaled.getMagicLevel());
		// The base record already halves the mage hand's Magic; scaling uses the linked Defence and halves once.
		Monster mage = raidMonster(7550, "great olm (mage hand)", "xerician", 300, 175, 87, 250, 250, 250);
		Monster hand = RaidScaling.apply(mage, party(1).build());
		assertEquals(600, hand.getHitpoints());
		assertEquals(175, hand.getDefenceLevel());
		assertEquals(87, hand.getMagicLevel());
	}

	@Test
	public void coxSinglesScaleOnlyByHighestLevels()
	{
		Monster beast = raidMonster(7548, "scavenger beast (normal)", "xerician", 40, 50, 1, 75, 75, 1);
		RaidScaling.Settings levels = party(8).partyMaxCombat(100).partyMaxHitpoints(80).build();
		Monster scaled = RaidScaling.apply(beast, levels);
		assertEquals(31, scaled.getHitpoints());
		assertEquals(40, scaled.getDefenceLevel());
		assertEquals(60, scaled.getAttackLevel());
		Monster cm = RaidScaling.apply(beast, levels.toBuilder().coxChallengeMode(true).build());
		assertEquals(47, cm.getHitpoints());
		assertEquals(60, cm.getDefenceLevel());
		assertEquals(90, cm.getAttackLevel());
	}

	@Test
	public void ordinaryTargetsAreCopiedUnchanged()
	{
		Monster ordinary = monster(100, 50);
		ordinary.setHitpoints(250);
		Monster copy = RaidScaling.apply(ordinary, party(5).toaRaidLevel(500).build());
		assertEquals(250, copy.getHitpoints());
		assertEquals(RaidScaling.Raid.NONE, RaidScaling.raid(ordinary));
		assertNull(RaidScaling.describe(ordinary, copy, RaidScaling.Settings.SOLO));
		assertSame(ordinary.getAttributes(), copy.getAttributes());
	}

	@Test
	public void maxedCombatLevelIs126()
	{
		assertEquals(126, PlayerLevels.maxed().combatLevel());
		assertEquals(3, new PlayerLevels(1, 1, 1, 1, 1, 1, 10, 1).combatLevel());
	}
}

package com.bestgearsetup.calc;

import static com.bestgearsetup.calc.TestData.item;
import static com.bestgearsetup.calc.TestData.monster;
import static com.bestgearsetup.calc.TestData.weapon;
import static org.junit.Assert.assertEquals;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.Slot;
import org.junit.Test;

/** Cases found by diffing every named special case in the Wiki calculator against this implementation. */
public class ReferenceParityTest
{
	private static final double EPS = 1e-10;

	private static CombatContext context(Monster m, CombatModifiers modifiers)
	{
		return new CombatContext(m, PlayerLevels.maxed(), false, false, null).withModifiers(modifiers);
	}

	@Test
	public void huntersSpearScalesWithStrengthAndMeleeStrengthBonus()
	{
		GearItem spear = weapon(29305, "hunter's spear", "thrown", 6, "accurate,ranged,accurate", "rapid,ranged,rapid");
		spear.setRangedBonus(73);
		spear.setMeleeStr(48);
		Loadout l = new Loadout();
		l.set(Slot.WEAPON, spear);
		l.setStyle(AttackStyle.parse("rapid,ranged,rapid"));
		CombatContext ctx = new CombatContext(monster(1, 0), PlayerLevels.maxed(), false, 99, 70, 99, 99, null, false);
		// Visible Strength 70 + 8, melee strength 48: (78 * 112 + 320) / 640 = 14.
		assertEquals(14, DpsCalculator.calculate(l, ctx).getMaxHit());
		// Melee slayer helmet damage applies on task, as for the atlatl.
		l.set(Slot.HEAD, item(11864, "slayer helmet", Slot.HEAD));
		ctx = new CombatContext(monster(1, 0), PlayerLevels.maxed(), true, 99, 70, 99, 99, null, false);
		assertEquals(16, DpsCalculator.calculate(l, ctx).getMaxHit());
		assertEquals(AttackStyle.Type.RANGED, WeaponRules.tabType(spear, l.getStyle()));
	}

	@Test
	public void forinthrySurgeRaisesAvariceAgainstRevenantsOnly()
	{
		GearItem sword = weapon(50000, "test sword", "slash sword", 4, "slash,slash,aggressive");
		sword.setMeleeStr(100);
		Loadout l = new Loadout();
		l.set(Slot.WEAPON, sword);
		l.set(Slot.NECK, item(22557, "amulet of avarice", Slot.NECK));
		l.setStyle(AttackStyle.parse("slash,slash,aggressive"));
		Monster revenant = monster(1, 0);
		revenant.setName("revenant knight");
		// Effective strength 110; base max (110 * 164 + 320) / 640 = 28.
		assertEquals(33, DpsCalculator.calculate(l, context(revenant, CombatModifiers.NONE)).getMaxHit());
		CombatModifiers surge = CombatModifiers.builder().forinthrySurge(true).build();
		assertEquals(37, DpsCalculator.calculate(l, context(revenant, surge)).getMaxHit());
		assertEquals(28, DpsCalculator.calculate(l, context(monster(1, 0), surge)).getMaxHit());
	}
}

package com.bestgearsetup.calc;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.GameData;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.Slot;
import com.bestgearsetup.data.WikiGameData;
import com.bestgearsetup.data.WikiMonsters;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.function.ToLongFunction;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.BeforeClass;
import org.junit.Test;

/** Slayer monsters with mandatory protective equipment: every returned setup must wear it, on or off task. */
public class SlayerEquipmentTest
{
	private static final Gson GSON = RuneLiteAPI.GSON;
	private static final ToLongFunction<GearItem> PRICE = item -> 100_000L;
	private static final OptimizerSettings DEFAULTS = OptimizerSettings.builder().build();
	private static GameData data;
	private static WikiMonsters monsters;

	@BeforeClass
	public static void load() throws Exception
	{
		data = WikiGameData.get(GSON).gameData(GSON);
		monsters = WikiMonsters.get(GSON);
	}

	private static Monster bundled(String name)
	{
		Monster m = monsters.monster(name);
		assertNotNull(name, m);
		return m;
	}

	private static Monster named(String name)
	{
		Monster m = TestData.monster(1, 0);
		m.setName(name);
		return m;
	}

	private static GearItem item(Slot slot, String name)
	{
		for (GearItem item : data.getItems(slot))
		{
			if (item.getName().equalsIgnoreCase(name))
			{
				return item;
			}
		}
		throw new AssertionError(name + " is not in the bundled data");
	}

	private static Loadout wearing(GearItem... items)
	{
		Loadout l = new Loadout();
		l.set(Slot.WEAPON, item(Slot.WEAPON, "abyssal whip"));
		for (GearItem i : items)
		{
			l.set(i.getSlot(), i);
		}
		return l;
	}

	@Test
	public void eachTargetAcceptsOnlyItsProtection()
	{
		GearItem slayerHelm = item(Slot.HEAD, "slayer helmet (i)");
		Object[][] cases = {
			{"dust devil (smoke dungeon)", item(Slot.HEAD, "facemask")},
			{"choke devil", item(Slot.HEAD, "facemask")},
			{"thermonuclear smoke devil", item(Slot.HEAD, "facemask")},
			{"banshee", item(Slot.HEAD, "earmuffs")},
			{"twisted banshee", item(Slot.HEAD, "earmuffs")},
			{"screaming banshee", item(Slot.HEAD, "earmuffs")},
			{"aberrant spectre", item(Slot.HEAD, "nose peg")},
			{"repugnant spectre", item(Slot.HEAD, "nose peg")},
			{"sourhog", item(Slot.HEAD, "reinforced goggles")},
			{"basilisk knight", item(Slot.SHIELD, "mirror shield")},
			{"cockathrice", item(Slot.SHIELD, "v's shield")},
			{"basilisk youngling", item(Slot.SHIELD, "mirror shield")},
			{"harpie bug swarm", item(Slot.SHIELD, "lit bug lantern")},
			{"hydra", item(Slot.FEET, "boots of stone")},
			{"alchemical hydra (fire)", item(Slot.FEET, "granite boots")},
			{"drake", item(Slot.FEET, "boots of brimstone")},
		};
		for (Object[] c : cases)
		{
			Monster target = bundled((String) c[0]);
			GearItem protection = (GearItem) c[1];
			assertTrue(target.getName(), SlayerEquipment.applies(target, DEFAULTS));
			assertFalse(target.getName() + " unprotected", SlayerEquipment.allowed(target, DEFAULTS, wearing()));
			assertTrue(target.getName() + " with " + protection.getName(),
				SlayerEquipment.allowed(target, DEFAULTS, wearing(protection)));
			if (protection.getSlot() == Slot.HEAD)
			{
				assertTrue(target.getName() + " with a slayer helmet", SlayerEquipment.allowed(target, DEFAULTS,
					wearing(slayerHelm)));
			}
		}
		// The quest's sourhog is fought before slayer helmets gain the goggles' protection.
		Monster questHog = bundled("sourhog (a porcine of interest)");
		assertFalse(SlayerEquipment.allowed(questHog, DEFAULTS, wearing()));
		assertFalse(SlayerEquipment.allowed(questHog, DEFAULTS, wearing(slayerHelm)));
		assertTrue(SlayerEquipment.allowed(questHog, DEFAULTS, wearing(item(Slot.HEAD, "reinforced goggles"))));
		// Each head item covers only its own monsters: earmuffs don't stop dust devils.
		assertFalse(SlayerEquipment.allowed(bundled("choke devil"), DEFAULTS, wearing(item(Slot.HEAD, "earmuffs"))));
		// The Wiki names only the mirror shield for younglings.
		assertFalse(SlayerEquipment.allowed(bundled("basilisk youngling"), DEFAULTS, wearing(item(Slot.SHIELD, "v's shield"))));
	}

	@Test
	public void unrelatedVariantsAndRecommendationsAreNotEnforced()
	{
		for (String name : new String[]{"moonlight cockatrice", "wall beast (beast)",
			"wyrm (attacking)", "killerwatt", "fever spider", "cave horror", "vorkath (post-quest)", "zulrah (serpentine)"})
		{
			assertFalse(name, SlayerEquipment.applies(named(name), DEFAULTS));
		}
		assertTrue(SlayerEquipment.notes(named("wall beast (beast)"), DEFAULTS).get(0).contains("start the fight"));
		assertTrue(SlayerEquipment.notes(named("wyrm (attacking)"), DEFAULTS).get(0).contains("Wyrmscraig"));
	}

	@Test
	public void eliteKourendDiaryWaivesOnlyTheKaruulmBoots()
	{
		OptimizerSettings diary = DEFAULTS.toBuilder().kourendEliteDiary(true).build();
		Monster hydra = bundled("hydra");
		assertTrue(SlayerEquipment.inKaruulm(hydra));
		assertFalse(SlayerEquipment.applies(hydra, diary));
		assertTrue(SlayerEquipment.allowed(hydra, diary, wearing()));
		assertTrue(SlayerEquipment.notes(hydra, diary).get(0).contains("Diary complete"));
		assertTrue(SlayerEquipment.applies(bundled("banshee"), diary));
	}

	@Test
	public void karuulmWyrmsRequireBootsUnlessEliteDiaryIsComplete()
	{
		OptimizerSettings karuulm = DEFAULTS.toBuilder().karuulmDungeon(true).build();
		OptimizerSettings elite = karuulm.toBuilder().kourendEliteDiary(true).build();
		for (String name : new String[]{"wyrm (attacking)", "wyrm (idle)", "shadow wyrm"})
		{
			Monster wyrm = named(name);
			assertTrue(SlayerEquipment.inKaruulm(wyrm, karuulm));
			assertTrue(SlayerEquipment.applies(wyrm, karuulm));
			assertFalse(SlayerEquipment.allowed(wyrm, karuulm, wearing()));
			GearItem ordinaryBoots = item(Slot.FEET, "primordial boots");
			assertFalse(SlayerEquipment.allowed(wyrm, karuulm, wearing(ordinaryBoots)));
			assertNotNull(SlayerEquipment.lockConflict(wyrm, karuulm, Slot.FEET, ordinaryBoots));
			for (String boots : new String[]{"boots of stone", "boots of brimstone", "granite boots"})
			{
				GearItem protection = item(Slot.FEET, boots);
				assertTrue(SlayerEquipment.isRequired(wyrm, karuulm, protection));
				assertTrue(SlayerEquipment.allowed(wyrm, karuulm, wearing(protection)));
			}
			assertTrue(SlayerEquipment.notes(wyrm, karuulm).get(0).contains("Required equipment"));
			assertFalse(SlayerEquipment.notes(wyrm, karuulm).stream().anyMatch(n -> n.contains("not enforced")));
			assertFalse(SlayerEquipment.applies(wyrm, elite));
			assertTrue(SlayerEquipment.allowed(wyrm, elite, wearing(ordinaryBoots)));
			assertTrue(SlayerEquipment.notes(wyrm, elite).get(0).contains("Diary complete"));
			assertFalse(SlayerEquipment.applies(wyrm, DEFAULTS));
			assertTrue(SlayerEquipment.allowed(wyrm, DEFAULTS, wearing(ordinaryBoots)));
		}
		assertFalse(SlayerEquipment.applies(named("wyrmling"), karuulm));
	}

	@Test
	public void karuulmWyrmSearchesEnforceBootsForEveryModeAndCombatStyle()
	{
		Monster wyrm = bundled("wyrm (attacking)");
		Set<Integer> owned = new HashSet<>(Arrays.asList(4587, 1704, 23037));
		for (SearchMode mode : SearchMode.values())
		{
			OptimizerSettings settings = OptimizerSettings.builder().mode(mode).budget(10_000_000L)
				.depth(SearchDepth.FAST).resultsPerClass(2).karuulmDungeon(true)
				.spellbooks(Collections.singleton("standard")).build();
			for (boolean onTask : new boolean[]{false, true})
			{
				CombatContext ctx = new CombatContext(wyrm, PlayerLevels.maxed(), onTask, true, TestData.piety());
				Optimizer optimizer = new Optimizer(data, ctx, settings, owned::contains, PRICE);
				int found = 0;
				for (CombatClass cls : CombatClass.values())
				{
					List<SetupResult> results = optimizer.optimize(cls, () -> false);
					if (mode != SearchMode.OWNED_ONLY) { assertFalse(mode + " " + cls, results.isEmpty()); }
					for (SetupResult result : results)
					{
						found++;
						assertTrue(mode + " " + cls + " task=" + onTask,
							SlayerEquipment.allowed(wyrm, settings, result.getLoadout()));
					}
				}
				assertTrue(mode + " task=" + onTask, found > 0);
			}
		}
		OptimizerSettings noBoots = OptimizerSettings.builder().mode(SearchMode.OWNED_ONLY)
			.depth(SearchDepth.FAST).karuulmDungeon(true).spellbooks(Collections.singleton("standard")).build();
		CombatContext ctx = new CombatContext(wyrm, PlayerLevels.maxed(), false, true, TestData.piety());
		assertTrue(new Optimizer(data, ctx, noBoots, id -> id == 4587 || id == 1704, PRICE)
			.optimize(CombatClass.MELEE, () -> false).isEmpty());
	}

	@Test
	public void twoHandedWeaponsCannotHoldARequiredShield()
	{
		Monster knight = bundled("basilisk knight");
		Loadout l = wearing(item(Slot.SHIELD, "mirror shield"));
		assertTrue(SlayerEquipment.allowed(knight, DEFAULTS, l));
		GearItem twoHanded = TestData.weapon(1, "test greatsword", "2h sword", 6, "chop,slash,accurate");
		twoHanded.setTwoHanded(true);
		l.set(Slot.WEAPON, twoHanded);
		assertFalse(SlayerEquipment.allowed(knight, DEFAULTS, l));
	}

	@Test
	public void everySearchModeStyleAndAoeResultWearsProtectionOffTask()
	{
