	@Test
	public void ownedOnlyWithoutProtectionFindsNothingAndOnTaskUsesASlayerHelmet()
	{
		Monster dustDevil = bundled("dust devil (smoke dungeon)");
		OptimizerSettings owned = OptimizerSettings.builder().mode(SearchMode.OWNED_ONLY).depth(SearchDepth.FAST)
			.spellbooks(Collections.singleton("standard")).build();
		CombatContext offTask = new CombatContext(dustDevil, PlayerLevels.maxed(), false, true, TestData.piety());
		Set<Integer> noMask = new HashSet<>(Arrays.asList(4587, 1704));
		assertTrue(new Optimizer(data, offTask, owned, noMask::contains, PRICE).optimize(CombatClass.MELEE, () -> false)
			.isEmpty());

		CombatContext onTask = new CombatContext(dustDevil, PlayerLevels.maxed(), true, true, TestData.piety());
		OptimizerSettings unlimited = owned.toBuilder().mode(SearchMode.UNLIMITED).build();
		GearItem head = new Optimizer(data, onTask, unlimited, id -> false, PRICE).optimize(CombatClass.MELEE, () -> false)
			.get(0).getLoadout().get(Slot.HEAD);
		assertTrue(head.getName().toLowerCase(Locale.ROOT).contains("slayer helmet"));
	}

	@Test
	public void locksWithoutTheRequiredItemAreReportedAsBlocking()
	{
		Object[][] cases = {
			{"dust devil (smoke dungeon)", Slot.HEAD, "eclipse moon helm", "facemask"},
			{"basilisk knight", Slot.SHIELD, "dragon defender", "mirror shield"},
			{"hydra", Slot.FEET, "primordial boots", "boots of stone"},
		};
		for (Object[] c : cases)
		{
			Monster target = bundled((String) c[0]);
			Slot slot = (Slot) c[1];
			GearItem wrong = item(slot, (String) c[2]);
			GearItem right = item(slot, (String) c[3]);
			CombatContext ctx = new CombatContext(target, PlayerLevels.maxed(), false, true, TestData.piety());
			for (SlotLock lock : new SlotLock[]{SlotLock.item(wrong.getId()), SlotLock.empty(), SlotLock.fill()})
			{
				OptimizerSettings settings = OptimizerSettings.builder().mode(SearchMode.UNLIMITED).depth(SearchDepth.FAST)
					.spellbooks(Collections.singleton("standard")).locks(Collections.singletonMap(slot, lock)).build();
				Optimizer optimizer = new Optimizer(data, ctx, settings, id -> false, PRICE);
				assertTrue(target.getName() + " " + lock, optimizer.optimize(CombatClass.RANGED, () -> false).isEmpty());
				List<LockStatus> status = LockStatus.check(data, optimizer, settings.getLocks());
				assertTrue(status.get(0).isBlocking());
				assertTrue(status.get(0).getProblem().contains("requires"));
			}
			OptimizerSettings good = OptimizerSettings.builder().mode(SearchMode.UNLIMITED).depth(SearchDepth.FAST)
				.spellbooks(Collections.singleton("standard"))
				.locks(Collections.singletonMap(slot, SlotLock.item(right.getId()))).build();
			Optimizer optimizer = new Optimizer(data, ctx, good, id -> false, PRICE);
			assertFalse(LockStatus.check(data, optimizer, good.getLocks()).get(0).isBlocking());
			assertEquals(right, optimizer.optimize(CombatClass.RANGED, () -> false).get(0).getLoadout().get(slot));
		}
	}
}

package com.bestgearsetup.calc;

import static com.bestgearsetup.calc.TestData.item;
import static com.bestgearsetup.calc.TestData.monster;
import static com.bestgearsetup.calc.TestData.weapon;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.Slot;
import java.util.Arrays;
import org.junit.Test;

/** Special attack scoring (used for specs within a kill): vectors derived from the Wiki calculator's spec formulas. */
public class SpecialAttackTest
{
	private static final double EPS = 1e-10;
	private static final CombatModifiers SPEC = CombatModifiers.builder().specialAttack(true).build();

	/** Mean of a uniform 0..max roll with a successful zero raised to one. */
	private static double ordinary(long max)
	{
		return max / 2.0 + 1.0 / (max + 1);
	}

	private static Loadout loadout(GearItem weapon, String style)
	{
		Loadout l = new Loadout();
		l.set(Slot.WEAPON, weapon);
		l.setStyle(AttackStyle.parse(style));
		return l;
	}

	private static CombatContext context(Monster m, CombatModifiers modifiers)
	{
		return new CombatContext(m, PlayerLevels.maxed(), false, false, null).withModifiers(modifiers);
	}

	private static GearItem melee(String name, int bonus, int strength, int speed)
	{
		GearItem w = weapon(50000, name, "slash sword", speed, "slash,slash,aggressive", "lunge,stab,aggressive");
		w.setStabBonus(bonus);
		w.setSlashBonus(bonus);
		w.setCrushBonus(bonus);
		w.setMeleeStr(strength);
		return w;
	}

	@Test
	public void armadylGodswordAppliesGodswordThenOwnMultiplierWithDoubleAccuracy()
	{
		Loadout l = loadout(melee("armadyl godsword", 132, 132, 6), "slash,slash,aggressive");
		DpsResult r = DpsCalculator.calculate(l, context(monster(100, 50), SPEC));
		// Max (110 * 196 + 320) / 640 = 34; x 11/10 = 37; x 5/4 = 46. Attack roll 107 * 196, doubled.
		assertEquals(46, r.getMaxHit());
		double acc = HitChance.single(2L * 107 * 196, 109L * 114);
		assertEquals(acc, r.getAccuracy(), EPS);
		assertEquals(acc * ordinary(46), r.getAverageHit(), EPS);
		assertEquals(6, r.getAttackSpeedTicks());
		assertTrue(r.getMaxHitDetail().contains("50% energy"));
	}

	@Test
	public void specDefenceStyleOverridesTheSelectedStance()
	{
		Monster target = monster(100, 0);
		target.setDefStab(300);
		target.setDefSlash(-20);
		// Dragon dagger rolls against slash even from a stab stance, and hits twice.
		GearItem dds = melee("dragon dagger(p++)", 40, 40, 4);
		DpsResult r = DpsCalculator.calculate(loadout(dds, "lunge,stab,aggressive"), context(target, SPEC));
		long attack = 107L * 104 * 23 / 20;
		double acc = HitChance.single(attack, 109L * 44);
		long max = (110L * 104 + 320) / 640 * 23 / 20;
		assertEquals(acc, r.getAccuracy(), EPS);
		assertEquals(2 * acc * ordinary(max), r.getAverageHit(), EPS);
		assertEquals(2 * max, r.getMaxHit());
	}

	@Test
	public void dragonClawsFollowTheCascadeDistribution()
	{
		Loadout l = loadout(melee("dragon claws", 57, 56, 4), "slash,slash,aggressive");
		Monster target = monster(150, 80);
		DpsResult r = DpsCalculator.calculate(l, context(target, SPEC));
		long max = (110L * 120 + 320) / 640;
		double acc = HitChance.single(107L * 121, 159L * 144);
		double expected = 0;
		for (int k = 0; k < 4; k++)
		{
			long low = max * (4 - k) / 4;
			long high = max + low - 1;
			for (long d = low; d <= high; d++)
			{
				long sum = k == 0 ? d / 2 + d / 4 + d / 8 + d / 8 + 1 : k == 1 ? d / 2 + d / 4 + d / 4 + 1
					: k == 2 ? d / 2 + d / 2 + 1 : d + 1;
				expected += Math.pow(1 - acc, k) * acc / (high - low + 1) * sum;
			}
		}
		expected += Math.pow(1 - acc, 4) * 2.0 / 3 * 2;
		assertEquals(expected, r.getAverageHit(), 1e-9);
		assertEquals(1 - Math.pow(1 - acc, 4), r.getAccuracy(), EPS);
	}

	@Test
	public void voidwakerAlwaysHitsFor50To150PercentAsMagic()
	{
		GearItem voidwaker = melee("voidwaker", 70, 80, 4);
		Loadout l = loadout(voidwaker, "slash,slash,aggressive");
		Monster target = monster(300, 300);
		DpsResult r = DpsCalculator.calculate(l, context(target, SPEC));
		long max = (110L * 144 + 320) / 640;
		assertEquals(1.0, r.getAccuracy(), EPS);
		assertEquals(max + max / 2, r.getMaxHit());
		assertEquals((max / 2 + max + max / 2) / 2.0, r.getAverageHit(), EPS);
		// Mitigated as Magic: Tekton divides Magic by five, with positive hits kept at one.
		target.setId(7540);
		target.setName("tekton (normal)");
		target.setDefMagic(0);
		assertTrue(DpsCalculator.calculate(l, context(target, SPEC)).getAverageHit() < max * 0.31);
	}

	@Test
	public void darkBowMissesStillDealTheArrowMinimumAndHitsCapAt48()
	{
		GearItem bow = weapon(11235, "dark bow", "bow", 9, "rapid,ranged,rapid");
		bow.setAmmunition(Arrays.asList(11212, 882));
		bow.setRangedBonus(95);
		Loadout l = loadout(bow, "rapid,ranged,rapid");
		GearItem dragon = item(11212, "dragon arrow", Slot.AMMO);
		dragon.setRangedStr(60);
		l.set(Slot.AMMO, dragon);
		Monster target = monster(200, 200);
		DpsResult r = DpsCalculator.calculate(l, context(target, SPEC));
		long max = (107L * 124 + 320) / 640 * 15 / 10;
		double acc = HitChance.single(107L * 159, 209L * 264);
		double hit = 0;
		for (long h = 8; h <= max; h++)
		{
			hit += Math.max(8, Math.min(48, h));
		}
		hit /= max - 8 + 1;
		assertEquals(2 * (acc * hit + (1 - acc) * 8), r.getAverageHit(), 1e-9);
		assertEquals(2 * Math.min(48, max), r.getMaxHit());
	}

	@Test
	public void zarytCrossbowSpecGuaranteesBoltEffectsOnAccurateHits()
	{
		GearItem zcb = weapon(26374, "zaryte crossbow", "crossbow", 5, "rapid,ranged,rapid");
		zcb.setAmmunition(Arrays.asList(9243));
		zcb.setRangedBonus(110);
		GearItem diamond = item(9243, "diamond bolts (e)", Slot.AMMO);
		diamond.setRangedStr(105);
		Loadout l = loadout(zcb, "rapid,ranged,rapid");
		l.set(Slot.AMMO, diamond);
		Monster target = monster(150, 80);
		CombatContext ctx = context(target, SPEC);
		long max = (107L * 169 + 320) / 640;
		long effect = max * 126 / 100;
		double acc = HitChance.single(2L * 107 * 174, 159L * 144);
		DpsResult r = DpsCalculator.calculate(l, ctx);
		assertEquals(acc * ordinary(effect) + (1 - acc) * 0.1 * ordinary(effect), r.getAverageHit(), EPS);
		assertTrue(r.getMaxHitDetail().contains("guaranteed on hit"));
	}

	@Test
	public void accursedSceptreAutocastSpecUsesItsBuiltInSpell()
	{
		GearItem sceptre = weapon(27679, "accursed sceptre (a)", "staff", 5, "bash,crush,accurate", "spell,magic,magic");
		sceptre.setMagicBonus(22);
		Loadout l = loadout(sceptre, "spell,magic,magic");
		DpsResult r = DpsCalculator.calculate(l, context(monster(100, 50), SPEC));
		// Built-in max 99 / 3 - 6 = 27, x 3/2 = 40; accurate stance +2 and spec accuracy x 3/2.
		assertEquals(40, r.getMaxHit());
		assertEquals(HitChance.single((99L + 2 + 9) * 86 * 3 / 2, 109L * 114), r.getAccuracy(), EPS);
		// The staff's bash has no melee special.
		assertNull(SpecialAttack.of(loadout(sceptre, "bash,crush,accurate"), context(monster(100, 50), SPEC)));
	}

	@Test
	public void unsupportedWeaponsScoreNothing()
	{
		CombatContext ctx = context(monster(100, 50), SPEC);
		GearItem scythe = melee("scythe of vitur", 125, 75, 5);
		assertEquals(0, DpsCalculator.calculate(loadout(scythe, "slash,slash,aggressive"), ctx).getDps(), EPS);
		GearItem other = weapon(11785, "unlisted crossbow", "crossbow", 6, "rapid,ranged,rapid");
		assertNull(SpecialAttack.of(loadout(other, "rapid,ranged,rapid"), ctx));
		// Ordinary attacks are unchanged when the mode is off.
		assertFalse(CombatModifiers.NONE.isSpecialAttack());
	}

	@Test
	public void specialsFollowTheirWikiPages()
	{
		CombatContext ctx = context(monster(100, 50), SPEC);
		// Armadyl Eye doubles accuracy.
		SpecialAttack acb = SpecialAttack.of(loadout(weapon(11785, "armadyl crossbow", "crossbow", 6,
			"rapid,ranged,rapid"), "rapid,ranged,rapid"), ctx);
		assertEquals(400, acb.scaleAccuracy(200));
		// Binding Tentacle has no accuracy bonus.
		SpecialAttack tentacle = SpecialAttack.of(loadout(melee("abyssal tentacle", 82, 86, 4), "slash,slash,aggressive"), ctx);
		assertEquals(200, tentacle.scaleAccuracy(200));
		assertEquals(40, tentacle.scaleMax(40));
		// Smash: 25-125% of the maximum.
		SpecialAttack smash = SpecialAttack.of(loadout(melee("statius's warhammer (bh)", 0, 114, 6),
			"slash,slash,aggressive"), ctx);
		assertEquals(50, smash.scaleMax(40));
		assertEquals(10, smash.minimum(40));
		// Impale: +10% damage and one tick slower.
		SpecialAttack impale = SpecialAttack.of(loadout(melee("rune claws", 38, 39, 4), "slash,slash,aggressive"), ctx);
		assertEquals(44, impale.scaleMax(40));
		assertEquals(1, impale.getExtraTicks());
		assertEquals(5, DpsCalculator.calculate(loadout(melee("rune claws", 38, 39, 4), "slash,slash,aggressive"), ctx)
			.getExpectedSpeedTicks(), EPS);
	}

	@Test
	public void burningClawDotMatchesTheReferenceBurnTable()
	{
		// The roll that succeeds sets a 15/30/45% burn chance per splat; overlapping first two burns lose 1.
		assertEquals(expected(0.15), SpecialDamage.burningClawDot(1), EPS);
		assertEquals(0.5 * expected(0.15) + 0.25 * expected(0.30) + 0.125 * expected(0.45),
			SpecialDamage.burningClawDot(0.5), EPS);
		assertEquals(0, SpecialDamage.burningClawDot(0), EPS);
	}

	private static double expected(double chance)
	{
		double total = 0;
		for (int row = 0; row < 8; row++)
		{
			int burns = Integer.bitCount(row);
			total += Math.pow(chance, burns) * Math.pow(1 - chance, 3 - burns) * (10 * burns - ((row & 6) == 6 ? 1 : 0));
		}
		return total;
	}

	@Test
	public void seekingBroadArrowsRaiseSuccessfulHitsToThree()
	{
		GearItem bow = weapon(50010, "test bow", "bow", 4, "rapid,ranged,rapid");
		bow.setAmmunition(Arrays.asList(50011));
		bow.setRangedBonus(50);
		GearItem arrows = item(50011, "seeking broad arrows", Slot.AMMO);
		arrows.setRangedStr(-40);
		Loadout l = loadout(bow, "rapid,ranged,rapid");
		l.set(Slot.AMMO, arrows);
		DpsResult r = DpsCalculator.calculate(l, context(monster(1, 0), CombatModifiers.NONE));
		long max = (107L * 24 + 320) / 640;
		double acc = HitChance.single(107L * 114, 10L * 64);
		double mean = 0;
		for (long h = 0; h <= max; h++)
		{
			mean += Math.max(3, h);
		}
		assertEquals(acc * mean / (max + 1), r.getAverageHit(), EPS);
	}
}

package com.bestgearsetup.calc;

import static com.bestgearsetup.calc.TestData.monster;
import static org.junit.Assert.assertEquals;
import com.bestgearsetup.data.Monster;
import org.junit.Test;

public class SpecialAttacksTest
{
	private static Monster target(int defence, int magic, String... attributes)
	{
		Monster m = monster(defence, 0, attributes);
		m.setMagicLevel(magic);
		m.setAttackLevel(200);
		m.setStrengthLevel(200);
		return m;
	}

	@Test
	public void warhammerAndMaulAreMultiplicative()
	{
		// 200 -> 140 -> 98
		assertEquals(98, SpecialAttacks.builder().dragonWarhammer(2).build().apply(target(200, 100)).getDefenceLevel());
		// 200 -> 130
		assertEquals(130, SpecialAttacks.builder().elderMaul(1).build().apply(target(200, 100)).getDefenceLevel());
		// vulnerability first: 200 -> 180 -> 126
		assertEquals(126, SpecialAttacks.builder().vulnerability(true).dragonWarhammer(1).build()
			.apply(target(200, 100)).getDefenceLevel());
	}

	@Test
	public void arclightIsAdditiveAndStrongerOnDemons()
	{
		// 5% of 200 + 1 = 11 per hit
		assertEquals(178, SpecialAttacks.builder().arclight(2).build().apply(target(200, 100)).getDefenceLevel());
		// 10% vs demons
		assertEquals(158, SpecialAttacks.builder().arclight(2).build().apply(target(200, 100, "demon")).getDefenceLevel());
		// emberlight: 5% + 1
		assertEquals(189, SpecialAttacks.builder().emberlight(1).build().apply(target(200, 100)).getDefenceLevel());
	}

	@Test
	public void tonalzticsUsesTargetMagic()
	{
		// 1/8 of 160 magic = 20 per hit
		assertEquals(160, SpecialAttacks.builder().tonalztics(2).build().apply(target(200, 160)).getDefenceLevel());
	}

	@Test
	public void godswordDrainsDefenceThenOtherStats()
	{
		Monster m = target(50, 100);
		Monster drained = SpecialAttacks.builder().bandosGodswordDamage(460).build().apply(m);
		assertEquals(0, drained.getDefenceLevel());
		assertEquals(0, drained.getStrengthLevel());
		assertEquals(0, drained.getAttackLevel());
		// 460 - 50 def - 200 str - 200 att = 10 left for magic
		assertEquals(90, drained.getMagicLevel());
	}

	@Test
	public void defenceFloorIsRespected()
	{
		Monster m = target(200, 100);
		m.setDefenceFloor(150);
		assertEquals(150, SpecialAttacks.builder().dragonWarhammer(3).build().apply(m).getDefenceLevel());
	}

	@Test
	public void magicDrains()
	{
		Monster m = target(200, 100);
		m.setDefMagic(50);
		Monster drained = SpecialAttacks.builder().seercullDamage(30).ayakDamage(20).build().apply(m);
		assertEquals(70, drained.getMagicLevel());
		assertEquals(30, drained.getDefMagic());
		// the cached monster is untouched
		assertEquals(100, m.getMagicLevel());
	}
}

package com.bestgearsetup.calc;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class SpecialRotationTest
{
	private static final double EPS = 1e-9;
	// 5 DPS ordinary attacks, and a 10 DPS spec on the same 4-tick (2.4s) weapon.
	private static final DpsResult ORDINARY = new DpsResult(5, 30, 0.8, 4, 12, null);
	private static final DpsResult SPEC = new DpsResult(10, 60, 0.9, 4, 24, null);

	@Test
	public void regeneratedEnergySpecsForItsShareOfTheFight()
	{
		SpecialRotation.Blend b = SpecialRotation.blend(ORDINARY, SPEC, 50, 500, SpecEnergy.REGENERATION);
		// 1/3% per second for 2.4s per spec at 50% each: 1.6% of the fight is spent speccing.
		double share = 2.4 / 3 / 50;
		double rate = share * 10 + (1 - share) * 5;
		assertEquals(rate, b.getResult().getPrimaryDps(), EPS);
		assertEquals(rate, b.getResult().getDps(), EPS);
		assertEquals(share * (500 / rate) / 2.4, b.getSpecsPerKill(), EPS);
		// The ordinary attack's own stats are kept.
		assertEquals(30, b.getResult().getMaxHit());
		assertEquals(12, b.getResult().getAverageHit(), EPS);
	}

	@Test
	public void fullBarOpensWithEveryWholeSpecItHolds()
	{
		SpecialRotation.Blend b = SpecialRotation.blend(ORDINARY, SPEC, 40, 500, SpecEnergy.FULL_BAR);
		// Two 40% specs (24 damage each, 4.8s); the 20% remainder is not carried over.
		double share = 2.4 / 3 / 40;
		double rate = share * 10 + (1 - share) * 5;
		double seconds = 4.8 + (500 - 48) / rate;
		assertEquals(500 / seconds, b.getResult().getPrimaryDps(), EPS);
		assertEquals(2 + share * (seconds - 4.8) / 2.4, b.getSpecsPerKill(), EPS);
	}

	@Test
	public void openingSpecsAloneCanKill()
	{
		SpecialRotation.Blend b = SpecialRotation.blend(ORDINARY, SPEC, 25, 30, SpecEnergy.FULL_BAR);
		assertEquals(10, b.getResult().getPrimaryDps(), EPS);
		assertEquals(30 / 24.0, b.getSpecsPerKill(), EPS);
	}

	@Test
	public void specsThatDoNotOutDamageOrdinaryAttacksAreNotUsed()
	{
		assertNull(SpecialRotation.blend(SPEC, ORDINARY, 50, 500, SpecEnergy.FULL_BAR));
		assertNull(SpecialRotation.blend(ORDINARY, SPEC, 0, 500, SpecEnergy.FULL_BAR));
		assertNull(SpecialRotation.blend(ORDINARY, DpsResult.ZERO, 50, 500, SpecEnergy.FULL_BAR));
	}

	@Test
	public void areaDamageBlendsTotalAndPrimaryRatesSeparately()
	{
		DpsResult area = new DpsResult(15, 30, 0.8, 4, 12, null, 5, 3);
		SpecialRotation.Blend b = SpecialRotation.blend(area, SPEC, 50, 500, SpecEnergy.REGENERATION);
		double share = 2.4 / 3 / 50;
		assertEquals(share * 10 + (1 - share) * 15, b.getResult().getDps(), EPS);
		assertEquals(3, b.getResult().getTargetsHit());
	}

	/** Ordinary attacks rise with each landed warhammer; the 50%-accurate spec itself averages 12 a hit. */
	private static final SpecialRotation.Fight WARHAMMER = new SpecialRotation.Fight()
	{
		@Override
		public DpsResult ordinary(SpecialAttacks drains)
		{
			int dps = new int[]{5, 8, 10}[drains.getDragonWarhammer()];
			return new DpsResult(dps, 30, 0.8, 4, dps * 2.4, null);
		}

		@Override
		public DpsResult spec(SpecialAttacks drains)
		{
			return new DpsResult(5, 50, 0.5, 4, 12, null);
		}
	};

	@Test
	public void fullBarDrainsOpenTheKillAndEachOutcomeFinishesAtItsStats()
	{
		SpecialRotation.Blend b = SpecialRotation.draining(WARHAMMER, SpecialAttack.Drain.DRAGON_WARHAMMER, 50, 500,
			SpecEnergy.FULL_BAR, SpecialRotation.REGEN_PER_SECOND);
		// A landed spec deals 24. Two hits: 4.8s + 452/10; one: 4.8s + 476/8 (either order); none: 4.8s + 500/5.
		double seconds = 4.8 + 0.25 * 45.2 + 0.5 * 59.5 + 0.25 * 100;
		assertEquals(500 / seconds, b.getResult().getPrimaryDps(), EPS);
		assertEquals(2, b.getSpecsPerKill(), EPS);
		// The undrained attack's stats are kept.
		assertEquals(30, b.getResult().getMaxHit());
	}

	@Test
	public void worstCaseDrainsAllMissAndOnlyCostTheirAttacks()
	{
		SpecialRotation.Blend b = SpecialRotation.draining(WARHAMMER, SpecialAttack.Drain.DRAGON_WARHAMMER, 50, 500,
			SpecEnergy.FULL_BAR, SpecialRotation.REGEN_PER_SECOND, true);
		// Two missed specs (4.8s), then the whole 500 HP at the undrained 5 DPS.
		assertEquals(500 / 104.8, b.getResult().getPrimaryDps(), EPS);
		assertEquals(2, b.getSpecsPerKill(), EPS);
	}

	@Test
	public void worstCaseWithRegeneratedEnergyOpensWithOneKillsEnergy()
	{
		SpecialRotation.Blend b = SpecialRotation.draining(WARHAMMER, SpecialAttack.Drain.DRAGON_WARHAMMER, 50, 500,
			SpecEnergy.REGENERATION, SpecialRotation.REGEN_PER_SECOND, true);
		double seconds = 500 / b.getResult().getPrimaryDps();
		double m = b.getSpecsPerKill();
		// Fewer specs than a full bar's two, each a 2.4s miss before the undrained 100s.
		assertTrue(m > 0 && m < 1);
		assertEquals(SpecialRotation.REGEN_PER_SECOND * seconds / 50, m, 1e-4);
		assertEquals(100 + m * 2.4, seconds, 1e-6);
	}

	@Test
	public void longKillsSpendRegenerationBeyondAFullBarDuringTheKill()
	{
		// A spec (12 DPS) that still beats the twice-drained ordinary attacks (10 DPS).
		SpecialRotation.Fight strong = new SpecialRotation.Fight()
		{
			@Override
			public DpsResult ordinary(SpecialAttacks drains)
			{
				return WARHAMMER.ordinary(drains);
			}

			@Override
			public DpsResult spec(SpecialAttacks drains)
			{
				return new DpsResult(12, 50, 0.5, 4, 28.8, null);
			}
		};
		SpecialRotation.Blend b = SpecialRotation.draining(strong, SpecialAttack.Drain.DRAGON_WARHAMMER, 50, 5000,
			SpecEnergy.REGENERATION, SpecialRotation.REGEN_PER_SECOND);
		double seconds = 5000 / b.getResult().getPrimaryDps();
		// Over 300s regenerates more than a full bar: two opening specs, then the rest during the kill, so all of
		// one kill's regenerated energy is spent.
		assertTrue(b.getSpecsPerKill() > 2);
		assertEquals(SpecialRotation.REGEN_PER_SECOND * seconds / 50, b.getSpecsPerKill(), 1e-3);
	}

	@Test
	public void regeneratedDrainsOpenEachKillWithTheEnergyOfOneKill()
	{
		SpecialRotation.Blend b = SpecialRotation.draining(WARHAMMER, SpecialAttack.Drain.DRAGON_WARHAMMER, 50, 500,
			SpecEnergy.REGENERATION, SpecialRotation.REGEN_PER_SECOND);
		double seconds = 500 / b.getResult().getPrimaryDps();
		// Self-consistent: the specs opening a kill are what one kill regenerates.
		assertEquals(SpecialRotation.REGEN_PER_SECOND * seconds / 50, b.getSpecsPerKill(), 1e-4);
		// Between no spec (100s) and one spec every kill (82.15s).
		double m = b.getSpecsPerKill();
		assertTrue(m > 0 && m < 1);
		assertEquals(100 + m * (82.15 - 100), seconds, 1e-3);
	}

	@Test
	public void lightbearerDoublesRegeneratedSpecs()
	{
		SpecialRotation.Blend plain = SpecialRotation.blend(ORDINARY, SPEC, 50, 500, SpecEnergy.REGENERATION);
		SpecialRotation.Blend lit = SpecialRotation.blend(ORDINARY, SPEC, 50, 500, SpecEnergy.REGENERATION,
			2 * SpecialRotation.REGEN_PER_SECOND);
		double share = 2 * 2.4 / 3 / 50;
		assertEquals(share * 10 + (1 - share) * 5, lit.getResult().getPrimaryDps(), EPS);
		assertTrue(lit.getSpecsPerKill() > 1.9 * plain.getSpecsPerKill());
	}
}

package com.bestgearsetup.calc;

import static com.bestgearsetup.calc.TestData.item;
import static com.bestgearsetup.calc.TestData.monster;
import static com.bestgearsetup.calc.TestData.weapon;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.Slot;
import com.bestgearsetup.data.Spell;
import com.bestgearsetup.data.StatusImmunities;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

/** Poison, venom and burn mechanics from the OSRS Wiki status-effect pages. */
public class StatusEffectsTest
{
	private static final double EPS = 1e-9;

	private static StatusEffects.Sources sources(double poison, int severity, double venom, double burn)
	{
		return new StatusEffects.Sources(poison, severity, venom, burn, 1, Collections.emptyList());
	}

	private static Monster target(int id, String name, int hp)
	{
		Monster m = monster(100, 50);
		m.setId(id);
		m.setName(name);
		m.setHitpoints(hp);
		return m;
	}

	private static Loadout loadout(GearItem weapon, String style)
	{
		Loadout l = new Loadout();
		l.set(Slot.WEAPON, weapon);
		l.setStyle(AttackStyle.parse(style));
		return l;
	}

	private static CombatContext context(Monster m, CombatModifiers modifiers)
	{
		return new CombatContext(m, PlayerLevels.maxed(), false, false, null).withModifiers(modifiers);
	}

	@Test
	public void venomMatchesTheWikiDamageTable()
	{
		double[] totals = {0, 6, 14, 24, 36, 50, 66, 84, 104, 124};
		for (int n = 0; n < totals.length; n++)
		{
			assertEquals(totals[n], StatusEffects.Fight.venomCumulative(n), EPS);
		}
	}

	@Test
	public void unrefreshedPoisonTotalsMatchTheWiki()
	{
		// Severity 30 (p++ melee) 105, ranged (p) severity 6 deals 7, emerald bolts 75 or 87 with the Zaryte.
		int[][] cases = {{30, 105}, {20, 50}, {6, 7}, {25, 75}, {27, 87}, {26, 81}};
		for (int[] c : cases)
		{
			StatusEffects.Fight fight = new StatusEffects.Fight(sources(1e-15, c[0], 0, 0), 4);
			assertEquals("severity " + c[0], c[1], fight.poisonCumulative(200), 1e-6);
		}
		assertEquals(6, StatusEffects.Fight.poisonHit(30));
		assertEquals(5, StatusEffects.Fight.poisonHit(22));
	}

	@Test
	public void frequentReapplicationKeepsPoisonAtItsStartingDamage()
	{
		StatusEffects.Fight fight = new StatusEffects.Fight(sources(1, 30, 0, 0), 4);
		assertEquals(6.0 / 30, fight.steadyPerTick(), EPS);
		assertEquals(60, fight.poisonCumulative(10), EPS);
	}

	@Test
	public void killTimeIncludesDamageOverTimeButShortKillsGainLittle()
	{
		StatusEffects.Fight fight = new StatusEffects.Fight(sources(0, 0, 1, 0), 4);
		double longKill = fight.killTime(0.5, 20_000);
		double rate = 20_000 / longKill;
		// Long fights approach the 20-per-30-ticks venom cap.
		assertTrue(rate > 0.5 + 20.0 / 30 - 0.02);
		// 10 HP at 0.5 per tick takes 20 ticks; the first 6-damage venom hit lands within 30 ticks.
		double shortKill = fight.killTime(0.5, 10);
		assertTrue(shortKill > 13 && shortKill < 20);
		assertTrue(fight.damage(0) == 0);
	}

	@Test
	public void bundledImmunitiesOverrideMissingMonsterFlags()
	{
		StatusImmunities.Immunity vorkath = StatusImmunities.of(target(8061, "vorkath", 750));
		assertTrue(vorkath.isPoisonImmune());
		assertTrue(vorkath.isVenomImmune());
		StatusImmunities.Immunity rex = StatusImmunities.of(target(2267, "dagannoth rex", 255));
		assertFalse(rex.isPoisonImmune());
		assertTrue(rex.isVenomBecomesPoison());
		StatusImmunities.Immunity demon = StatusImmunities.of(target(415, "abyssal demon (standard)", 150));
		assertFalse(demon.isVenomImmune());
		assertEquals(StatusImmunities.BURN_NORMAL, StatusImmunities.of(target(5862, "cerberus", 600)).getBurnImmunity());
		assertEquals(StatusImmunities.BURN_STRONG, StatusImmunities.of(target(7706, "tzkal-zuk", 1200)).getBurnImmunity());
		// Unknown ids fall back to the variant's base name.
		assertTrue(StatusImmunities.of(target(999_999, "vorkath (test variant)", 750)).isVenomImmune());
	}

	@Test
	public void venomChancesFollowTheSerpentineHelmRules()
	{
		Monster demon = target(415, "abyssal demon (standard)", 150);
		GearItem whip = weapon(4151, "abyssal whip", "whip", 4, "lash,slash,controlled");
		Loadout l = loadout(whip, "lash,slash,controlled");
		CombatContext ctx = context(demon, CombatModifiers.NONE);
		assertFalse(StatusEffects.sources(l, ctx, 0.8).any());
		l.set(Slot.HEAD, item(12931, "serpentine helm", Slot.HEAD));
		assertEquals(0.8 / 6, StatusEffects.sources(l, ctx, 0.8).getVenomChance(), EPS);
		Loadout dagger = loadout(weapon(1215, "dragon dagger", "stab sword", 4, "lunge,stab,aggressive"), "lunge,stab,aggressive");
		dagger.set(Slot.HEAD, item(12931, "serpentine helm", Slot.HEAD));
		CombatContext poisoned = context(demon, CombatModifiers.builder().weaponPoison(WeaponPoison.POISON_PLUS_PLUS).build());
		assertEquals(0.4, StatusEffects.sources(dagger, poisoned, 0.8).getVenomChance(), EPS);
		GearItem pipe = weapon(12926, "toxic blowpipe", "thrown", 3, "rapid,ranged,rapid");
		Loadout blowpipe = loadout(pipe, "rapid,ranged,rapid");
		assertEquals(0.25 * 0.7, StatusEffects.sources(blowpipe, ctx, 0.7).getVenomChance(), EPS);
		blowpipe.set(Slot.HEAD, item(12931, "serpentine helm", Slot.HEAD));
		assertEquals(0.7, StatusEffects.sources(blowpipe, ctx, 0.7).getVenomChance(), EPS);
	}

	@Test
	public void poisonSourcesUseTheirChanceAndSeverity()
	{
		Monster demon = target(415, "abyssal demon (standard)", 150);
		CombatContext ctx = context(demon, CombatModifiers.builder().weaponPoison(WeaponPoison.POISON_PLUS_PLUS).build());
		StatusEffects.Sources dagger = StatusEffects.sources(
			loadout(weapon(1215, "dragon dagger", "stab sword", 4, "lunge,stab,aggressive"), "lunge,stab,aggressive"), ctx, 0.8);
		assertEquals(0.2, dagger.getPoisonChance(), EPS);
		assertEquals(30, dagger.getPoisonSeverity());
		// Poisoned ranged ammunition: 1/8 per successful hit, severity lowered by 14.
		GearItem bow = weapon(861, "magic shortbow", "bow", 4, "rapid,ranged,rapid");
		bow.setAmmunition(Arrays.asList(892));
		Loadout ranged = loadout(bow, "rapid,ranged,rapid");
		ranged.set(Slot.AMMO, item(892, "rune arrow", Slot.AMMO));
		StatusEffects.Sources arrows = StatusEffects.sources(ranged, ctx, 0.8);
		assertEquals(0.1, arrows.getPoisonChance(), EPS);
		assertEquals(16, arrows.getPoisonSeverity());
		// Emerald bolts: 55% of successful hits, severity 25 (27 with the Zaryte crossbow), never lowered.
		GearItem zcb = weapon(26374, "zaryte crossbow", "crossbow", 5, "rapid,ranged,rapid");
		zcb.setAmmunition(Arrays.asList(9241));
		Loadout bolts = loadout(zcb, "rapid,ranged,rapid");
		bolts.set(Slot.AMMO, item(9241, "emerald bolts (e)", Slot.AMMO));
		StatusEffects.Sources emerald = StatusEffects.sources(bolts, context(demon, CombatModifiers.NONE), 0.5);
		assertEquals(0.275, emerald.getPoisonChance(), EPS);
		assertEquals(27, emerald.getPoisonSeverity());
		// Smoke Barrage with an ancient sceptre: 1/8, severity 22.
		GearItem sceptre = weapon(28264, "smoke ancient sceptre", "staff", 4, "spell,magic,magic");
		Loadout smoke = loadout(sceptre, "spell,magic,magic");
		Spell barrage = new Spell();
		barrage.setName("smoke barrage");
		barrage.setSpellbook("ancient");
		smoke.setSpell(barrage);
		StatusEffects.Sources magic = StatusEffects.sources(smoke, context(demon, CombatModifiers.NONE), 0.8);
		assertEquals(0.1, magic.getPoisonChance(), EPS);
		assertEquals(22, magic.getPoisonSeverity());
	}

	@Test
	public void immuneTargetsTakeNoPoisonOrVenomAndVenomBecomesPoisonWhereListed()
	{
		GearItem pipe = weapon(12926, "toxic blowpipe", "thrown", 3, "rapid,ranged,rapid");
		Loadout blowpipe = loadout(pipe, "rapid,ranged,rapid");
		assertFalse(StatusEffects.sources(blowpipe, context(target(8061, "vorkath", 750), CombatModifiers.NONE), 0.7).any());
		StatusEffects.Sources rex = StatusEffects.sources(blowpipe,
			context(target(2267, "dagannoth rex", 255), CombatModifiers.NONE), 0.8);
		assertEquals(0, rex.getVenomChance(), EPS);
		assertEquals(0.2, rex.getPoisonChance(), EPS);
		assertEquals(26, rex.getPoisonSeverity());
	}

	@Test
	public void burnsRespectSeverityImmunityAndRangedImmunity()
	{
		Loadout atlatl = loadout(weapon(29000, "eclipse atlatl", "bow", 4, "rapid,ranged,rapid"), "rapid,ranged,rapid");
		atlatl.set(Slot.HEAD, item(29010, "eclipse moon helm", Slot.HEAD));
		atlatl.set(Slot.BODY, item(29004, "eclipse moon chestplate", Slot.BODY));
		atlatl.set(Slot.LEGS, item(29007, "eclipse moon tassets", Slot.LEGS));
		// Cerberus resists normal burns only; the Eclipse burn is strong.
		assertTrue(StatusEffects.sources(atlatl, context(target(5862, "cerberus", 600), CombatModifiers.NONE), 0.8).any());
		assertFalse(StatusEffects.sources(atlatl, context(target(7706, "tzkal-zuk", 1200), CombatModifiers.NONE), 0.8).any());
		Monster tekton = target(7540, "tekton (normal)", 300);
		assertEquals(0, StatusEffects.burnFactor(atlatl, context(tekton, CombatModifiers.NONE), StatusImmunities.BURN_STRONG), EPS);
		// Burning claws' special burn is normal severity, so Cerberus takes none of it.
		assertEquals(0, StatusEffects.burnFactor(atlatl, context(target(5862, "cerberus", 600), CombatModifiers.NONE),
			StatusImmunities.BURN_NORMAL), EPS);
	}

	@Test
	public void venomRaisesWholeFightDpsOnSusceptibleTargetsOnly()
	{
		GearItem pipe = weapon(12926, "toxic blowpipe", "thrown", 3, "rapid,ranged,rapid");
		pipe.setRangedBonus(30);
		pipe.setRangedStr(40);
		Loadout l = loadout(pipe, "rapid,ranged,rapid");
		l.set(Slot.HEAD, item(12931, "serpentine helm", Slot.HEAD));
		Monster demon = target(415, "abyssal demon (standard)", 150);
		DpsResult withVenom = DpsCalculator.calculate(l, context(demon, CombatModifiers.NONE));
		DpsResult direct = DpsCalculator.snapshot(l, context(demon, CombatModifiers.NONE));
		assertTrue(withVenom.getDps() > direct.getDps());
		assertTrue(withVenom.getMaxHitDetail().contains("venom"));
		Monster vorkath = target(8061, "vorkath", 750);
		assertEquals(DpsCalculator.snapshot(l, context(vorkath, CombatModifiers.NONE)).getDps(),
			DpsCalculator.calculate(l, context(vorkath, CombatModifiers.NONE)).getDps(), EPS);
	}

	@Test
	public void iceAncientSceptreGainsAccuracyOnlyAgainstFreezableTargets()
	{
		GearItem sceptre = weapon(28262, "ice ancient sceptre", "staff", 4, "spell,magic,magic");
		sceptre.setMagicBonus(20);
		Loadout l = loadout(sceptre, "spell,magic,magic");
		Spell barrage = new Spell();
		barrage.setName("ice barrage");
		barrage.setSpellbook("ancient");
		barrage.setMaxHit(30);
		barrage.setLevel(94);
		l.setSpell(barrage);
		Monster ordinary = target(415, "abyssal demon (standard)", 150);
		double plain = DpsCalculator.snapshot(l.copy(), context(ordinary, CombatModifiers.NONE)).getAccuracy();
		GearItem other = weapon(27624, "ancient sceptre", "staff", 4, "spell,magic,magic");
		other.setMagicBonus(20);
		Loadout baseline = l.copy();
		baseline.set(Slot.WEAPON, other);
		assertTrue(plain > DpsCalculator.snapshot(baseline, context(ordinary, CombatModifiers.NONE)).getAccuracy());
		Monster boss = target(8061, "vorkath", 750);
		boss.setAttributes(Collections.singletonList(attribute("boss")));
		assertEquals(DpsCalculator.snapshot(baseline, context(boss, CombatModifiers.NONE)).getAccuracy(),
			DpsCalculator.snapshot(l, context(boss, CombatModifiers.NONE)).getAccuracy(), EPS);
	}

	private static Monster.Attribute attribute(String name)
	{
		Monster.Attribute a = new Monster.Attribute();
		a.setName(name);
		return a;
	}
}

package com.bestgearsetup.calc;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.Slot;
import com.bestgearsetup.data.Spell;
import java.util.Collections;
import java.util.EnumSet;
import org.junit.Test;

public class SupportSpellTest
{
	private static final CombatModifiers ALL = CombatModifiers.builder().markOfDarkness(true).charge(true).build();

	@Test
	public void thrallIsAssumedUnlessANonArceuusSpellIsAutocastOrTheTargetIsImmune()
	{
		Monster target = monster(false, false);
		assertEquals(EnumSet.of(SupportSpell.THRALL), SupportSpell.assumed(new Loadout(), context(target, true)));
		assertEquals(EnumSet.noneOf(SupportSpell.class),
			SupportSpell.assumed(loadout("ice barrage", "ancient", null), context(target, true)));
		assertEquals(EnumSet.of(SupportSpell.THRALL),
			SupportSpell.assumed(loadout("undead grasp", "arceuus", null), context(target, true)));
		assertEquals(EnumSet.noneOf(SupportSpell.class), SupportSpell.assumed(new Loadout(), context(target, false)));
		assertEquals(EnumSet.noneOf(SupportSpell.class),
			SupportSpell.assumed(new Loadout(), context(monster(false, true), true)));
	}

	@Test
	public void thrallTierFollowsBaseMagicLevel()
	{
		Monster target = monster(false, false);
		assertEquals(EnumSet.noneOf(SupportSpell.class), SupportSpell.assumed(new Loadout(), context(target, true, 37)));
		assertEquals(Thrall.LESSER, context(target, true, 38).getThrall());
		assertEquals(Thrall.SUPERIOR, context(target, true, 75).getThrall());
		assertEquals(Thrall.GREATER, context(target, true, 76).getThrall());
		assertEquals(EnumSet.of(SupportSpell.THRALL), SupportSpell.assumed(new Loadout(), context(target, true, 38)));
		assertNull(context(target, false, 99).getThrall());
		assertEquals(0.625, Thrall.GREATER.getDps(), 1e-9);
		assertEquals(2 / 2.0 / 2.4, Thrall.SUPERIOR.getDps(), 1e-9);
		assertEquals(1 / 2.0 / 2.4, Thrall.LESSER.getDps(), 1e-9);
	}

	@Test
	public void markOfDarknessNeedsADemonbaneSpellAgainstADemon()
	{
		Loadout demonbane = loadout("dark demonbane", "arceuus", null);
		assertEquals(EnumSet.of(SupportSpell.MARK_OF_DARKNESS),
			SupportSpell.assumed(demonbane, context(monster(true, false), false)));
		assertEquals(EnumSet.noneOf(SupportSpell.class),
			SupportSpell.assumed(demonbane, context(monster(false, false), false)));
		assertEquals(EnumSet.noneOf(SupportSpell.class), SupportSpell.assumed(demonbane,
			context(monster(true, false), false).withModifiers(CombatModifiers.NONE)));
	}

	@Test
	public void chargeNeedsAGodSpellWithItsGodCape()
	{
		Monster target = monster(false, false);
		assertEquals(EnumSet.of(SupportSpell.CHARGE),
			SupportSpell.assumed(loadout("flames of zamorak", "standard", "imbued zamorak cape"), context(target, false)));
		assertEquals(EnumSet.noneOf(SupportSpell.class),
			SupportSpell.assumed(loadout("flames of zamorak", "standard", "saradomin cape"), context(target, false)));
		assertEquals(EnumSet.noneOf(SupportSpell.class),
			SupportSpell.assumed(loadout("fire surge", "standard", "zamorak cape"), context(target, false)));
	}

	private static CombatContext context(Monster target, boolean thrall)
	{
		return context(target, thrall, 99);
	}

	private static CombatContext context(Monster target, boolean thrall, int magic)
	{
		PlayerLevels levels = new PlayerLevels(99, 99, 99, 99, magic, 99, 99, 99);
		return new CombatContext(target, levels, false, 99, 99, 99, magic, null, thrall).withModifiers(ALL);
	}

	private static Monster monster(boolean demon, boolean immuneThrall)
	{
		Monster m = new Monster();
		Monster.Attribute attribute = new Monster.Attribute();
		attribute.setName("demon");
		m.setAttributes(demon ? Collections.singletonList(attribute) : Collections.emptyList());
		m.setImmuneThrall(immuneThrall);
		return m;
	}

	private static Loadout loadout(String spell, String spellbook, String cape)
	{
		Loadout l = new Loadout();
		Spell s = new Spell();
		s.setName(spell);
		s.setSpellbook(spellbook);
		l.setSpell(s);
		if (cape != null)
		{
			GearItem item = new GearItem();
			item.setName(cape);
			l.set(Slot.CAPE, item);
		}
		return l;
	}
}

package com.bestgearsetup.calc;

import com.bestgearsetup.data.CombatClass;
import com.bestgearsetup.data.GameData;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.MonsterSummary;
import com.bestgearsetup.data.OffensivePrayer;
import com.bestgearsetup.data.Prayer;
import com.bestgearsetup.data.Slot;
import com.bestgearsetup.data.Spell;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/** Builders for synthetic items and monsters. */
final class TestData
{
	private TestData()
	{
	}

	static GearItem item(int id, String name, Slot slot)
	{
		GearItem i = new GearItem();
		i.setId(id);
		i.setName(name);
		i.setSlot(slot);
		i.setTradeable(true);
		return i;
	}

	static GearItem weapon(int id, String name, String subcategory, int speed, String... styles)
	{
		GearItem w = item(id, name, Slot.WEAPON);
		w.setSubcategory(subcategory);
		w.setAttackSpeed(speed);
		w.setStyles(Arrays.asList(styles));
		return w;
	}

	static Monster monster(int defence, int defBonus, String... attributes)
	{
		Monster m = new Monster();
		m.setId(1);
		m.setName("test monster");
		m.setDefenceLevel(defence);
		m.setMagicLevel(defence);
		m.setDefStab(defBonus);
		m.setDefSlash(defBonus);
		m.setDefCrush(defBonus);
		m.setDefRanged(defBonus);
		m.setDefMagic(defBonus);
		List<Monster.Attribute> attrs = new ArrayList<>();
		for (String a : attributes)
		{
			Monster.Attribute attr = new Monster.Attribute();
			attr.setName(a);
			attrs.add(attr);
		}
		m.setAttributes(attrs);
		return m;
	}

	static Map<CombatClass, OffensivePrayer> piety()
	{
		Map<CombatClass, OffensivePrayer> p = new EnumMap<>(CombatClass.class);
		p.put(CombatClass.MELEE, new OffensivePrayer("piety", 20, 23, 70, 70));
		p.put(CombatClass.RANGED, new OffensivePrayer("rigour", 20, 23, 74, 70));
		p.put(CombatClass.MAGIC, new OffensivePrayer("augury", 25, 4, 77, 70));
		return p;
	}

	static GameData gameData(List<GearItem> items, List<Spell> spells)
	{
		Map<String, List<GearItem>> bySlot = new HashMap<>();
		List<GearItem> weapons = new ArrayList<>();
		for (GearItem i : items)
		{
			if (i.getSlot() == Slot.WEAPON)
			{
				weapons.add(i);
			}
			else
			{
				bySlot.computeIfAbsent(i.getSlot().getApiKey(), k -> new ArrayList<>()).add(i);
			}
		}
		return new GameData(Collections.<MonsterSummary>emptyList(), bySlot, weapons, spells,
			Collections.<String, List<Prayer>>emptyMap(), null);
	}
}

package com.bestgearsetup.calc;

import static com.bestgearsetup.calc.TestData.item;
import static com.bestgearsetup.calc.TestData.monster;
import static com.bestgearsetup.calc.TestData.weapon;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.bestgearsetup.data.GearItem;
import com.bestgearsetup.data.Monster;
import com.bestgearsetup.data.Slot;
import org.junit.Test;

/** Kill time integrated over the target's HP for attacks that change as it falls. */
public class WholeFightTest
{
	private static Loadout rubyCrossbow()
	{
		GearItem bow = weapon(9185, "rune crossbow", "crossbow", 5, "rapid,ranged,rapid");
		bow.setRangedBonus(90);
		bow.setAmmunition(java.util.Arrays.asList(9242, 9243));
		GearItem bolts = item(9242, "ruby bolts (e)", Slot.AMMO);
		bolts.setRangedStr(103);
		Loadout l = new Loadout();
		l.set(Slot.WEAPON, bow);
		l.set(Slot.AMMO, bolts);
		l.setStyle(AttackStyle.parse("rapid,ranged,rapid"));
		return l;
	}

	private static CombatContext context(Monster m)
	{
		return new CombatContext(m, PlayerLevels.maxed(), false, true, null);
	}

	/** Sum of 1/DPS over every integer HP from the start down to 1: the exact fluid kill time. */
	private static double bruteForceDps(Loadout l, CombatContext ctx, int startHp)
	{
		double seconds = 0;
		for (int hp = startHp; hp >= 1; hp--)
		{
			seconds += 1 / DpsCalculator.snapshot(l, ctx.atTargetHp(hp)).getPrimaryDps();
		}
		return startHp / seconds;
	}

	@Test
	public void rubyBoltsAreAveragedAsTheirEffectFallsWithTargetHp()
	{
		Monster target = monster(150, 80);
		target.setHitpoints(900);
		Loadout l = rubyCrossbow();
		CombatContext ctx = context(target);
		DpsResult start = DpsCalculator.snapshot(l, ctx);
		DpsResult fight = DpsCalculator.calculate(l, ctx);
		assertTrue(fight.getDps() < start.getDps());
		assertEquals(bruteForceDps(l, ctx, 900), fight.getPrimaryDps(), fight.getPrimaryDps() * 0.002);
		assertEquals(start.getMaxHit(), fight.getMaxHit());
		assertTrue(fight.getMaxHitDetail(), fight.getMaxHitDetail().contains("whole-fight average from 900 HP"));
	}

	@Test
	public void startingHpSelectsTheRemainingFight()
	{
		Monster target = monster(150, 80);
		target.setHitpoints(900);
		Loadout l = rubyCrossbow();
		CombatContext ctx = context(target).withModifiers(CombatModifiers.builder().monsterHitpoints(300).build());
		assertEquals(bruteForceDps(l, ctx, 300), DpsCalculator.calculate(l, ctx).getPrimaryDps(), 0.002);
	}

	@Test
	public void sunKerisIsExactAcrossItsQuarterHealthBreakpoint()
	{
		Monster akkha = monster(80, 60, "tombs of amascut");
		akkha.setId(11789);
		akkha.setName("akkha");
		akkha.setHitpoints(1000);
		GearItem keris = weapon(27291, "keris partisan of the sun", "spear", 4, "lunge,stab,accurate");
		keris.setStabBonus(58);
		keris.setMeleeStr(75);
		Loadout l = new Loadout();
		l.set(Slot.WEAPON, keris);
		l.setStyle(AttackStyle.parse("lunge,stab,accurate"));
		CombatContext ctx = context(akkha);
		double high = DpsCalculator.snapshot(l, ctx).getPrimaryDps();
		double low = DpsCalculator.snapshot(l, ctx.atTargetHp(249)).getPrimaryDps();
		assertTrue(low > high);
		double expected = 1000 / (750 / high + 250 / low);
		assertEquals(expected, DpsCalculator.calculate(l, ctx).getPrimaryDps(), 1e-9);
	}

	@Test
	public void vardorvisDefenceFollowsHisHealthWhenStatesAreSupplied()
	{
		Monster vardorvis = monster(215, 85);
		vardorvis.setId(12223);
		vardorvis.setName("vardorvis");
		vardorvis.setHitpoints(700);
		vardorvis.setStrengthLevel(270);
		GearItem sword = weapon(50000, "test sword", "slash sword", 4, "slash,slash,aggressive");
		sword.setSlashBonus(120);
		sword.setMeleeStr(110);
		Loadout l = new Loadout();
		l.set(Slot.WEAPON, sword);
		l.setStyle(AttackStyle.parse("slash,slash,aggressive"));
		CombatContext plain = context(MonsterStates.atHealth(vardorvis, 0));
		assertNull(DpsCalculator.hpBreakpoints(l, plain));
		CombatContext ctx = plain.withHealthStates(hp -> MonsterStates.atHealth(vardorvis, hp));
		DpsResult fight = DpsCalculator.calculate(l, ctx);
		assertTrue(fight.getDps() > DpsCalculator.snapshot(l, ctx).getDps());
		assertEquals(bruteForceDps(l, ctx, 700), fight.getPrimaryDps(), fight.getPrimaryDps() * 0.002);
	}

	@Test
	public void ordinaryAttacksKeepTheirSnapshot()
	{
		Monster target = monster(150, 80);
		target.setHitpoints(900);
		Loadout l = rubyCrossbow();
		l.set(Slot.AMMO, item(9243, "diamond bolts (e)", Slot.AMMO));
		l.get(Slot.AMMO).setRangedStr(105);
		CombatContext ctx = context(target);
		assertNull(DpsCalculator.hpBreakpoints(l, ctx));
		assertEquals(DpsCalculator.snapshot(l, ctx), DpsCalculator.calculate(l, ctx));
	}
}

